		public void TestShipmentCommodities_ThereIsNoExceptionWhenRefreshInvoceLinesOnPartChange()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.UnitedStates))
			{
				var supplier = Factory.NewWithValidTestData<OrgHeader>();
				supplier.OH_Code = Guid.NewGuid().ToString().Replace("-", "").Substring(0, 12);
				var importer = Factory.NewWithValidTestData<OrgHeader>();
				importer.OH_Code = Guid.NewGuid().ToString().Replace("-", "").Substring(0, 12);
				var shipment = Factory.New<ForwardingShipment>();
				var declaration = Factory.New<US.IJobDeclaration>();
				declaration.JE_JS = shipment.PK;
				declaration.JE_OH_Importer = importer.PK;
				declaration.JE_OH_Supplier = supplier.PK;
				declaration.JE_MessageType = "IMP";
				var invoice = declaration.Invoices.AddNew();
				invoice.JZ_OH_Buyer = importer.PK;
				invoice.JZ_OH_Supplier = supplier.PK;
				var invoiceLine1 = invoice.AddNewInvoiceLine();
				invoiceLine1.JI_PartNo = "HXUTEST";
				var invoiceLine2 = invoice.AddNewInvoiceLine();
				invoiceLine2.JI_ParentID = invoiceLine1.PK;
				var invoiceLine3 = invoice.AddNewInvoiceLine();
				invoiceLine3.JI_ParentID = invoiceLine1.PK;
				invoiceLine3.JI_Tariff = "33333333";
				Factory.Save();

				var factory1 = new BusinessObjectFactory();
				var product = factory1.New<OrgSupplierPart>();
				product.OP_PartNum = "HXUTEST";
				var relation = product.RelatedOrganisations.AddOrganisationIfNotExist(importer.PK, OrgPartRelation.RelationshipTypes.Both);
				var cusClassPartPivot = (BusinessObject)factory1.New<IBaseCusClassPartPivot>();
				cusClassPartPivot[CusClassPartPivotSchema.Constants.CI_OP] = product.PK;
				cusClassPartPivot[CusClassPartPivotSchema.Constants.CI_OH] = relation.OU_OH;
				cusClassPartPivot[CusClassPartPivotSchema.Constants.CI_ChildType] = "HTI";
				cusClassPartPivot[CusClassPartPivotSchema.Constants.CI_TariffNum] = "11111111";
				cusClassPartPivot[CusClassPartPivotSchema.Constants.CI_RN_NKCountry] = "US";

				var childPivot = (BusinessObject)factory1.New<IBaseCusClassPartPivot>();
				childPivot[CusClassPartPivotSchema.Constants.CI_OP] = product.PK;
				childPivot[CusClassPartPivotSchema.Constants.CI_CI_Parent] = cusClassPartPivot.PK;
				childPivot[CusClassPartPivotSchema.Constants.CI_ChildType] = "COM";
				childPivot[CusClassPartPivotSchema.Constants.CI_TariffNum] = "22222222";
				childPivot[CusClassPartPivotSchema.Constants.CI_RN_NKCountry] = "US";
				factory1.Save();

				var factory2 = new BusinessObjectFactory();
				var shipment1 = factory2.Load<ForwardingShipment>(shipment.PK);
				AssertContainsExactElementsInAnyOrder(["33333333"], ((IComplianceCommodityRiskStatusProvider)shipment1).Commodities.Select(x => x.HarmonizedCode));

				var declaration1 = factory2.Load<US.IJobDeclaration>(declaration.PK);
				_ = declaration1.InvoiceLines;
				AssertContainsExactElementsInAnyOrder(["11111111", "22222222"], ((IComplianceCommodityRiskStatusProvider)shipment1).Commodities.Select(x => x.HarmonizedCode));
			}
		}

		public void TestCheckTotalsDiffer_WithDifferentWeight_UpdateShipmentActualWeight()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_ShipmentType = ShipmentTypes.HighVolumeLowValue;
			shipment.JS_ActualWeight = 1;
			shipment.JS_UnitOfWeight = Weight.Kilograms;

			var packLine = shipment.OuterPackLines.AddNew();
			packLine.JL_PackageCount = 4;
			packLine.JL_ActualWeight = 50;
			packLine.JL_ActualVolume = 60;

			var header = Factory.LoadTop1<IHVLVConsignmentHeader>(new ZQuery(HVLVConsignmentHeaderSchema.HCH_JS_Shipment, shipment.PK)) as BusinessObject;

			var consignment = Factory.New<IHVLVConsignment>() as BusinessObject;
			consignment[HVLVConsignmentSchema.HVC_HCH_Header.Name] = header.PK;
			consignment[HVLVConsignmentSchema.HVC_WeightUQ.Name] = Weight.Grams;

			var item = Factory.New<IHVLVItem>() as BusinessObject;
			item[HVLVItemSchema.HVI_HVC_Consignment.Name] = consignment.PK;
			item[HVLVItemSchema.HVI_JS_LoadedOnShipment.Name] = shipment.PK;
			item[HVLVItemSchema.HVI_ActualWeight.Name] = 3000;

			Factory.Save();

			var eventHandlerWasCalled = false;
			shipment.UpdateShipmentTotalsPackQuantityVariation += (sender, args) => eventHandlerWasCalled = true;

			AssertNotEquals("Precondition: shipment weight and consignment total weight are different", shipment.JS_ActualWeight, shipment.HVLVConsignmentHeader.TotalWeight);

			shipment.CheckTotalsDiffer();

			CombineAssertions(() =>
			{
				AssertEquals("Actual weight value updated", 3m, shipment.JS_ActualWeight);
				AssertEquals("Should have fired event", true, eventHandlerWasCalled);
			});

			HVLVDataRegistry.Instance.HVLVShipmentWeightUpdateMethod.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, Core.Constants.ShipmentWeightUpdateOptions.Code.ShowWarningFromPackingDetails);

			item[HVLVItemSchema.HVI_ActualWeight.Name] = 4000;
			eventHandlerWasCalled = false;

			AssertNotEquals("Precondition: shipment weight and consignment total weight still are different", shipment.JS_ActualWeight, shipment.HVLVConsignmentHeader.TotalWeight);
			shipment.CheckTotalsDiffer();

			CombineAssertions(() =>
			{
				AssertEquals("Actual weight value updated by packLines", 51m, shipment.JS_ActualWeight);
				AssertEquals("Should have fired event", true, eventHandlerWasCalled);
			});
		}

