		public void TestCheckTotalsDiffer_WithDifferentVolume_UpdateShipmentActualVolume()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_ShipmentType = ShipmentTypes.HighVolumeLowValue;
			shipment.JS_ActualVolume = 1;
			shipment.JS_UnitOfVolume = Volume.CubicMetres;

			var packLine = shipment.OuterPackLines.AddNew();
			packLine.JL_PackageCount = 4;
			packLine.JL_ActualWeight = 50;
			packLine.JL_ActualVolume = 60;

			var header = Factory.LoadTop1<IHVLVConsignmentHeader>(new ZQuery(HVLVConsignmentHeaderSchema.HCH_JS_Shipment, shipment.PK)) as BusinessObject;

			var consignment = Factory.New<IHVLVConsignment>() as BusinessObject;
			consignment[HVLVConsignmentSchema.HVC_HCH_Header.Name] = header.PK;
			consignment[HVLVConsignmentSchema.HVC_VolumeUQ.Name] = Volume.CubicCentimeters;

			var item = Factory.New<IHVLVItem>() as BusinessObject;
			item[HVLVItemSchema.HVI_HVC_Consignment.Name] = consignment.PK;
			item[HVLVItemSchema.HVI_JS_LoadedOnShipment.Name] = shipment.PK;
			item[HVLVItemSchema.HVI_ActualVolume.Name] = 300000;

			Factory.Save();

			var eventHandlerWasCalled = false;
			shipment.UpdateShipmentTotalsPackQuantityVariation += (sender, args) => eventHandlerWasCalled = true;

			AssertNotEquals("Precondition: shipment volume and consignment total volume are different", shipment.JS_ActualVolume, shipment.HVLVConsignmentHeader.TotalVolume);

			shipment.CheckTotalsDiffer();

			CombineAssertions(() =>
			{
				AssertEquals("Actual volume value updated", 0.3m, shipment.JS_ActualVolume);
				AssertEquals("Should have fired event", true, eventHandlerWasCalled);
			});

			HVLVDataRegistry.Instance.HVLVShipmentWeightUpdateMethod.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, Core.Constants.ShipmentWeightUpdateOptions.Code.ShowWarningFromPackingDetails);

			item[HVLVItemSchema.HVI_ActualVolume.Name] = 400000;
			eventHandlerWasCalled = false;

			AssertNotEquals("Precondition: shipment volume and consignment total volume are different", shipment.JS_ActualVolume, shipment.HVLVConsignmentHeader.TotalVolume);
			shipment.CheckTotalsDiffer();

			CombineAssertions(() =>
			{
				AssertEquals("Actual volume value updated", 61m, shipment.JS_ActualVolume);
				AssertEquals("Should have fired event", true, eventHandlerWasCalled);
			});
		}

		public void TestCheckTotalsDiffer_WithDifferentInnerPacksTotals_UpdateShipmentFromInnerPackLines()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_ShipmentType = ShipmentTypes.StandardHouse;
			shipment.UpdateShipmentTotalsPackQuantityVariation += (sender, e) => e.Cancel = false;
			var outer = shipment.OuterPackLines.AddNew();
			outer.JL_ActualVolume = 111;
			outer.JL_ActualWeight = 222;
			shipment.UpdateShipmentFromOuterPackLines();

			var inner1 = shipment.InnerPackLines.AddNew();
			inner1.JL_F3_NKPackType = PkgUnit.Pallet;
			inner1.JL_ActualVolume = 333;
			inner1.JL_ActualWeight = 333;
			inner1.JL_PackageCount = 5;
			var inner2 = shipment.InnerPackLines.AddNew();
			inner2.JL_F3_NKPackType = PkgUnit.Pallet;
			inner2.JL_ActualVolume = 444;
			inner2.JL_ActualWeight = 444;
			inner2.JL_PackageCount = 10;

			Factory.Save();

			var anotherFactory = new BusinessObjectFactory { RefreshEnabled = false };
			var shipmentInAnotherFactory = anotherFactory.Load<ForwardingShipment>(shipment.PK);
			var inner3 = shipmentInAnotherFactory.InnerPackLines.AddNew();
			inner3.JL_F3_NKPackType = PkgUnit.Bag;
			inner3.JL_ActualVolume = 555;
			inner3.JL_ActualWeight = 555;
			inner3.JL_PackageCount = 15;

			anotherFactory.Save();

			AssertEquals("Precondition: JS_ActualVolume == JL_ActualVolume", shipment.JS_ActualVolume, outer.JL_ActualVolume);
			AssertEquals("Precondition: JS_ActualWeight == JL_ActualWeight", shipment.JS_ActualWeight, outer.JL_ActualWeight);
			shipment.CheckTotalsDiffer();
			AssertEquals(30, shipment.JS_TotalPackageCount);
			AssertEquals(PkgUnit.Package, shipment.JS_F3_NKTotalCountPackType);
		}

		public void TestForwardingShipment_ComplianceRiskStatusObject()
		{
			Test("OVR", "PSK", "CLR", "CLR");
			Test("OVR", "CLR", "CLR", "PSK");
			Test("PSK", "PSK", "PSK", "CLR");
			Test("CLR", "CLR", "CLR", "CLR");

			void Test(ZString overallRisk, ZString commodityRisk, ZString partyRisk, ZString locationRisk)
			{
				var type = ObjectFactory.GetType("ComplianceRiskStatus");
				var shipment = Factory.New<ForwardingShipment>();
				var instance = Factory.New(type);
				instance[ComplianceRiskStatusSchema.COR_ParentTableCode] = shipment.TablePrefix;
				instance[ComplianceRiskStatusSchema.COR_ParentID] = shipment.PK;

				instance[ComplianceRiskStatusSchema.COR_CommodityRisk] = commodityRisk;
				instance[ComplianceRiskStatusSchema.COR_PartyRisk] = partyRisk;
				instance[ComplianceRiskStatusSchema.COR_LocationRisk] = locationRisk;
				instance[ComplianceRiskStatusSchema.COR_OverallRisk] = overallRisk;

				Factory.Save();

				AssertEquals(overallRisk, shipment.ComplianceRiskStatus.JobRisk);
				AssertEquals(partyRisk, shipment.ComplianceRiskStatus.PartyRisk);
				AssertEquals(commodityRisk, shipment.ComplianceRiskStatus.CommodityRisk);
				AssertEquals(locationRisk, shipment.ComplianceRiskStatus.LocationRisk);
			}
		}

