		public void TestInspectionTypeCodes()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry("AU"))
			{
				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "AUSYD";
				shipment.JS_RL_NKDestination = "CNSHA";
				shipment.JS_TransportMode = "AIR";
				var packLine = shipment.OuterPackLines.AddNew();

				var trigger = shipment.WorkflowItems.Triggers.AddNew();
				trigger.TriggerConditions.TriggerEventCode = Events.EditedARecordCode;
				var notification = trigger.ProcessTaskNotifications.AddNew();
				notification.PQ_FieldName = "<JS_InspectionTypeCode>";
				notification.PQ_TriggerType = WorkflowTriggerActionTypeConstants.Codes.ImmediateFieldChange;
				notification.PQ_FieldValue = "CMD";

				shipment.ReDefaultPackLineInspectionTypeCodesEventHandler += (s, e) =>
				{
					throw new Exception("should not show dialog about appling this  inspection type to all pack lines");
				};

				shipment.GetReasonChangingSecurityInspectionStatusEventHandler += (s, e) =>
				{
					throw new Exception("should not show get reason dialog when changing inspection type");
				};

				Factory.Save();

				shipment.JS_GoodsDescription = "good description";
				AssertNoExceptionThrown(() => BusinessObjectFactory.SaveTogether(Factory));
			}
		}

		public void TestInspectionTypeCodesWhenOuterPackLinesCountChanged()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry("FR"))
			{
				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "FRPAR";
				shipment.JS_RL_NKDestination = "USCHI";
				shipment.JS_TransportMode = "AIR";

				AssertEquals("Pre-condition", "UNK", shipment.JS_InspectionTypeCode);

				var packline1 = shipment.OuterPackLines.AddNew();
				AssertEquals("Pre-condition", "UNK", packline1.JL_InspectionTypeCode);

				packline1.JL_InspectionTypeCode = "XRY";
				AssertEquals("Shipment Inspection was changed to XRY because the only packline has XRY Inspection", "XRY", shipment.JS_InspectionTypeCode);

				var packline2 = shipment.OuterPackLines.AddNew();
				AssertEquals("Pre-condition", "UNK", packline2.JL_InspectionTypeCode);
				AssertEquals("Shipment Inspection was changed to UNK because the new packline has UNK Inspection", "UNK", shipment.JS_InspectionTypeCode);

				shipment.JS_InspectionTypeCode = "XRY";
				((ISupportDataImporting)shipment).IsImportingData = true;

				var packline3 = shipment.OuterPackLines.AddNew();
				AssertEquals("Pre-condition", "UNK", packline3.JL_InspectionTypeCode);
				AssertEquals("Shipment Inspection remains to XRY because the new packline has added during importing data", "XRY", shipment.JS_InspectionTypeCode);
			}
		}

		public void TestRedefaultShipmentInspectionTypeCodes()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry("GB"))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "GBLHR";
				shipment.JS_RL_NKDestination = "CNSHA";
				shipment.JS_TransportMode = "AIR";
				var packLine = shipment.OuterPackLines.AddNew();

				shipment.ReDefaultPackLineInspectionTypeCodesEventHandler += (s, e) => { };

				shipment.JS_InspectionTypeCode = "CMD";
				AssertEquals("Packline status is defaulted to UNK if the user does not have a certificate", "UNK", packLine.JL_InspectionTypeCode);

				shipment.JS_InspectionTypeCode = "APP";
				AssertEquals("Packline status is defaulted to empty if the user does not have a certificate", "", packLine.JL_InspectionTypeCode);

				shipment.JS_InspectionTypeCode = "PHS";
				AssertEquals("Packline status is defaulted to UNK if the user does not have a certificate", "UNK", packLine.JL_InspectionTypeCode);

				shipment.JS_InspectionTypeCode = "SCR";
				AssertEquals("Packline status is defaulted to UNK if the user does not have a certificate", "UNK", packLine.JL_InspectionTypeCode);

				var uKStaffHandlingSecuredCargoCertificate = GlbStaff.CurrentUser.Certificates.AddNew();
				uKStaffHandlingSecuredCargoCertificate.XZ_Type = StaffDefaultCertificateIDAndTrainingTypes.CO1;
				uKStaffHandlingSecuredCargoCertificate.XZ_ExpiryOrDueDate = ZDate.Today.AddDays(1);

				shipment.JS_InspectionTypeCode = "CMD";
				AssertEquals("CMD status is defaulted to packline", "CMD", packLine.JL_InspectionTypeCode);

				shipment.JS_InspectionTypeCode = "APP";
				AssertEquals("APP status removes packline status", "", packLine.JL_InspectionTypeCode);

				shipment.JS_InspectionTypeCode = "PHS";
				AssertEquals("PHS status is defaulted to packline", "PHS", packLine.JL_InspectionTypeCode);

				shipment.JS_InspectionTypeCode = "SCR";
				AssertEquals("SCR status does not affect packline status", "PHS", packLine.JL_InspectionTypeCode);
			}
		}

		public void TestRedefaultShipmentInspectionTypeCodes_MultiplePacklines()
		{
			var countryCodeList = new List<string> { "GB", "AU", "US", "CA" };
			foreach (var countryCode in countryCodeList)
			{
				using (GlbCompany.CurrentCompany.TemporarilySetCountry(countryCode))
				{
					var shipment = Factory.New<ForwardingShipment>();
					shipment.JS_RL_NKOrigin = "GBLHR";
					shipment.JS_RL_NKDestination = "CNSHA";
					shipment.JS_TransportMode = "AIR";

					var packLine1 = shipment.OuterPackLines.AddNew();
					var packLine2 = shipment.OuterPackLines.AddNew();

					packLine1.JL_InspectionTypeCode = "CMD";
					packLine2.JL_InspectionTypeCode = "XRY";
					AssertEquals("Shipment inspection status is defaulted to SCR when packlines have different inspection types",
						"SCR", shipment.JS_InspectionTypeCode);

					packLine1.JL_InspectionTypeCode = "PHS";
					packLine2.JL_InspectionTypeCode = "PHS";
					AssertEquals("Shipment inspection status is defaulted to the same status when packlines have the same inspection type",
						"PHS", shipment.JS_InspectionTypeCode);
				}
			}
		}

		public void TestRedefaultShipmentSecurityStatus_FromUKtoUSviaEU()
		{
			var shipment = CreateShipment_ThroughDifferentCountries("GBLHR", "FRPAR", "USCHI");
			Factory.Save();

			using (GlbCompany.CurrentCompany.TemporarilySetCountry(CountryCodes.UnitedKingdom))
			{
				var newFactory = new BusinessObjectFactory();
				var reloadedShipment = newFactory.Load<ForwardingShipment>(shipment.PK);
				var certificate = GlbStaff.CurrentUser.Certificates.AddNew();
				certificate.XZ_Type = "CS2";
				certificate.XZ_ExpiryOrDueDate = ZDate.Today.AddDays(1);

				var packline = reloadedShipment.OuterPackLines.AddNew();
				packline.JL_IsHighRisk = true;
				AssertEquals("Shipment Is High Risk is updated by packline", true, reloadedShipment.JS_IsHighRisk);

				packline.JL_AdditionalInspectionTypeCode = "XRY";
				AssertEquals("Shipment Additional Inspection Type Code is updated by packline", "XRY", reloadedShipment.JS_AdditionalInspectionTypeCode);

