		ForwardingShipment CreateShipment_ThroughDifferentCountries(string origin, string transit, string destination)
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = "AIR";
			shipment.JS_RL_NKOrigin = origin;
			shipment.JS_RL_NKDestination = destination;

			var consol1 = shipment.Consols.AddNew();
			consol1.JK_TransportMode = Core.Constants.TransportModes.Air;
			consol1.JK_RL_NKLoadPort = origin;
			consol1.JK_RL_NKDischargePort = transit;

			var consol2 = shipment.Consols.AddNew();
			consol2.JK_TransportMode = Core.Constants.TransportModes.Air;
			consol2.JK_RL_NKLoadPort = transit;
			consol2.JK_RL_NKDischargePort = destination;
			Factory.Save();

			return shipment;
		}

		public void TestUpdateHVLSubShipmentInspectionTypeCodes_HVLShipmentUpdated()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry("GB"))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "GBLHR";
				shipment.JS_RL_NKDestination = "CNSHA";
				shipment.JS_TransportMode = "AIR";
				shipment.JS_ShipmentType = "HVM";
				var coLoadShipment = shipment.CoLoadShipments.AddNew();

				coLoadShipment.JS_ShipmentType = "HVL";
				AssertEquals("sub HVL shipment does not have inspection type", "UNK", coLoadShipment.JS_InspectionTypeCode);

				shipment.UpdateSubHVLShipmentsInspectionTypeEventHandler += (s, e) => { };

				shipment.JS_InspectionTypeCode = "CMD";
				AssertEquals("sub HVL shipment inspection type is changed to CMD", "CMD", coLoadShipment.JS_InspectionTypeCode);
			}
		}

