				coLoadShipment.JS_InspectionTypeCode = "XRY";

				var packLine = coLoadShipment.OuterPackLines.AddNew();
				var isGetReasonTriggered = false;
				var isPackLineTriggered = false;

				var uKStaffHandlingSecuredCargoCertificate = GlbStaff.CurrentUser.Certificates.AddNew();
				uKStaffHandlingSecuredCargoCertificate.XZ_Type = StaffDefaultCertificateIDAndTrainingTypes.CO1;
				uKStaffHandlingSecuredCargoCertificate.XZ_ExpiryOrDueDate = ZDate.Today.AddDays(1);

				Factory.Save();

				shipment.UpdateSubHVLShipmentsInspectionTypeEventHandler += (s, e) => { };
				shipment.GetReasonChangingSecurityInspectionStatusEventHandler += (sender, arg) => arg.Reason = "test reason";

				coLoadShipment.ReDefaultPackLineInspectionTypeCodesEventHandler += (s, e) => { isPackLineTriggered = true; };
				coLoadShipment.GetReasonChangingSecurityInspectionStatusEventHandler += (s, e) => { isGetReasonTriggered = true; };

				shipment.JS_InspectionTypeCode = "CMD";
				AssertEquals(false, isGetReasonTriggered);
				AssertEquals(false, isPackLineTriggered);
				AssertEquals("sub HVL shipment inspection type is changed to CMD", "CMD", coLoadShipment.JS_InspectionTypeCode);
			}
		}

		public void TestJS_InspectionTypeCodeReportError()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_TransportMode = Constants.TransportModes.Air;
			shipment.JS_RL_NKOrigin = "DEHAM";
			shipment.JS_RL_NKDestination = "AUSYD";

			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Constants.CountryCodes.Germany))
			{
				shipment.JS_InspectionTypeCode = BaseJobShipmentLookups.InspectionType_Approved;

				shipment.OnSaving();
				AssertEquals("No exception is reported to ErrorReporter.", 0, ErrorReporter.LastExceptionsReported().Count);

				shipment.JS_InspectionTypeCode = ZString.Empty;
				shipment.OnSaving();
				Assert(ErrorReporter.LastMessageReported.Contains($"No CE_EntryNum Found : {shipment.PK} Country: DE, Type: INS"));

				ErrorReporter.Clear();

				shipment.JS_InspectionTypeCode = BaseJobShipmentLookups.InspectionType_Approved;
				shipment.OnSaving();
				AssertEquals("No exception is reported to ErrorReporter.", 0, ErrorReporter.LastExceptionsReported().Count);
			}
		}

