		public void TestHVLVConsignmentsContainsActiveConsignments()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_ShipmentType = ShipmentTypes.HighVolumeLowValue;
			var otherShipment = Factory.NewWithValidTestData<ForwardingShipment>();
			otherShipment.JS_ShipmentType = ShipmentTypes.HighVolumeLowValue;

			var header = Factory.LoadTop1<IHVLVConsignmentHeader>(new ZQuery(HVLVConsignmentHeaderSchema.HCH_JS_Shipment, shipment.PK)) as BusinessObject;
			header.FillWithValidTestData();

			var otherHeader = Factory.LoadTop1<IHVLVConsignmentHeader>(new ZQuery(HVLVConsignmentHeaderSchema.HCH_JS_Shipment, otherShipment.PK)) as BusinessObject;
			otherHeader.FillWithValidTestData();

			var consignment1 = Factory.New<IHVLVConsignment>() as BusinessObject;
			var consignment2 = Factory.New<IHVLVConsignment>() as BusinessObject;
			var consignment3 = Factory.New<IHVLVConsignment>() as BusinessObject;
			var consignment4 = Factory.New<IHVLVConsignment>() as BusinessObject;

			consignment1.FillWithValidTestData();
			consignment2.FillWithValidTestData();
			consignment3.FillWithValidTestData();
			consignment4.FillWithValidTestData();

			var item1 = Factory.New<IHVLVItem>();
			var item2 = Factory.New<IHVLVItem>();
			var item3 = Factory.New<IHVLVItem>();
			var item4 = Factory.New<IHVLVItem>();

			consignment1[HVLVConsignmentSchema.HVC_HCH_Header] = header.PK;
			consignment2[HVLVConsignmentSchema.HVC_HCH_Header] = header.PK;
			consignment3[HVLVConsignmentSchema.HVC_HCH_Header] = otherHeader.PK;
			consignment4[HVLVConsignmentSchema.HVC_HCH_Header] = otherHeader.PK;

			item3.HVI_JS_LoadedOnShipment = shipment.PK;
			item4.HVI_JS_LoadedOnShipment = shipment.PK;

			item1.HVI_HVC_Consignment = consignment1.PK;
			item2.HVI_HVC_Consignment = consignment2.PK;
			item3.HVI_HVC_Consignment = consignment3.PK;
			item4.HVI_HVC_Consignment = consignment4.PK;

			consignment1[HVLVConsignmentSchema.HVC_IsActive] = true;
			consignment2[HVLVConsignmentSchema.HVC_IsActive] = true;
			consignment3[HVLVConsignmentSchema.HVC_IsActive] = true;
			consignment4[HVLVConsignmentSchema.HVC_IsActive] = true;

			Factory.Save();

			var factory2 = new BusinessObjectFactory();
			var reloadedConsignment2 = factory2.Load<IHVLVConsignment>(consignment2.PK) as BusinessObject;
			reloadedConsignment2[HVLVConsignmentSchema.HVC_IsActive] = false;
			var reloadedConsignment4 = factory2.Load<IHVLVConsignment>(consignment4.PK) as BusinessObject;
			reloadedConsignment4[HVLVConsignmentSchema.HVC_IsActive] = false;
			factory2.Save();

			var factory3 = new BusinessObjectFactory();
			var loadedShipment = factory3.Load<ForwardingShipment>(shipment.PK);
			var consignmentPKs = loadedShipment.HVLVConsignments.Select(consignment => consignment.PK);

			AssertContainsExactElementsInAnyOrder("HVLVConsignments collection contains consignment1 and consignment3", new[] { consignment1.PK, consignment3.PK }, consignmentPKs);
		}

