		public void TestAddRemoveOrInsertPartyScreeningLogWhenSavingShipmentForm()
		{
			var matchedOrg1 = Factory.NewWithValidTestData<OrgHeader>();
			matchedOrg1.OH_FullName = "matchedOrg1";
			var matchedOrg2 = Factory.NewWithValidTestData<OrgHeader>();
			matchedOrg2.OH_FullName = "matchedOrg2";
			var unknownOrg = Factory.NewWithValidTestData<OrgHeader>();
			unknownOrg.OH_FullName = "unknownOrg";
			var clearedOrg = Factory.NewWithValidTestData<OrgHeader>();
			clearedOrg.OH_FullName = "clearedOrg";
			Factory.Save();

			matchedOrg1.OH_ScreeningStatus = ScreeningStatusesList.Codes.Matched;
			matchedOrg2.OH_ScreeningStatus = ScreeningStatusesList.Codes.Matched;
			unknownOrg.OH_ScreeningStatus = ScreeningStatusesList.Codes.Unknown;
			clearedOrg.OH_ScreeningStatus = ScreeningStatusesList.Codes.Clear;
			Factory.Save();

			var masterShipment = Factory.NewWithValidTestData<ForwardingShipment>();
			masterShipment.JS_ShipmentType = Constants.ShipmentTypes.CoLoadMaster;
			masterShipment.JS_UniqueConsignRef = "masterShipment";

			var coloadShipment1 = Factory.NewWithValidTestData<ForwardingShipment>();
			coloadShipment1.JS_UniqueConsignRef = "coloadShipment1";

			var coloadShipment2 = Factory.NewWithValidTestData<ForwardingShipment>();
			coloadShipment2.JS_UniqueConsignRef = "coloadShipment2";

			Factory.Save();

			masterShipment.CoLoadShipments.Add(coloadShipment1);
			masterShipment.CoLoadShipments.Add(coloadShipment2);
			masterShipment.JS_OH_ImportBroker = clearedOrg.PK;
			coloadShipment1.JS_OH_ImportBroker = matchedOrg1.PK;
			coloadShipment2.JS_OH_ImportBroker = matchedOrg2.PK;
			Factory.Save();

			masterShipment.CoLoadShipments[0].JS_OH_ImportBroker = unknownOrg.PK;
			Factory.Save();

			var relatedScreeningStatus = masterShipment.RelatedOrgPartyScreeningStatusCollection.ToList<IRelatedOrgPartyScreeningStatus>();

			var masterrelatedScreeningStatus = relatedScreeningStatus.Where(u => u.PJ_ParentID == masterShipment.PK).ToList();
			CombineAssertions(() =>
			{
				AssertEquals(1, masterrelatedScreeningStatus.Count);
				AssertEquals(true, masterrelatedScreeningStatus.Any(u => u.PJ_Status == "PAA" && u.PJ_ClearedReason == "Parties Info:clearedOrg(Import Broker)"));
			});

			var coloadShipment1relatedScreeningStatus = relatedScreeningStatus.Where(u => u.PJ_ParentID == coloadShipment1.PK).ToList();
			CombineAssertions(() =>
			{
				AssertEquals(3, coloadShipment1relatedScreeningStatus.Count);
				AssertEquals(true, coloadShipment1relatedScreeningStatus.Any(u => u.PJ_Status == "PAA" && u.PJ_ClearedReason == "Parties Info:matchedOrg1(Import Broker)"));
				AssertEquals(true, coloadShipment1relatedScreeningStatus.Any(u => u.PJ_Status == "PAA" && u.PJ_ClearedReason == "Parties Info:unknownOrg(Import Broker)"));
				AssertEquals(true, coloadShipment1relatedScreeningStatus.Any(u => u.PJ_Status == "PAR" && u.PJ_ClearedReason == "Parties Info:matchedOrg1(Import Broker)"));
			});

			var coloadShipment2relatedScreeningStatus = relatedScreeningStatus.Where(u => u.PJ_ParentID == coloadShipment2.PK).ToList();
			CombineAssertions(() =>
			{
				AssertEquals(1, coloadShipment2relatedScreeningStatus.Count);
				AssertEquals(true, coloadShipment2relatedScreeningStatus.Any(u => u.PJ_Status == "PAA" && u.PJ_ClearedReason == "Parties Info:matchedOrg2(Import Broker)"));
			});
		}

		public void TestAddRemoveOrInsertPartyScreeningLogWhenSavingHasConcurrency()
		{
			var secondFactory = new BusinessObjectFactory();
			secondFactory.RefreshEnabled = false;
			Factory.RefreshEnabled = false;

			var org1 = Factory.NewWithValidTestData<OrgHeader>();
			org1.OH_FullName = "Org1";

			var org2 = Factory.NewWithValidTestData<OrgHeader>();
			org2.OH_FullName = "Org2";

			var org3 = Factory.NewWithValidTestData<OrgHeader>();
			org3.OH_FullName = "Org3";

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();

			Factory.Save();

			var loadedShipment = secondFactory.Load<ForwardingShipment>(shipment.PK);

			shipment.JS_OH_ImportBroker = org1.PK;
			Factory.Save();

			var screeningStatus1 = shipment.RelatedOrgPartyScreeningStatusCollection.ToList<IRelatedOrgPartyScreeningStatus>();
			CombineAssertions(() =>
			{
				AssertEquals(1, screeningStatus1.Count);
				AssertEquals(true, screeningStatus1.Any(u => u.PJ_Status == "PAA" && u.PJ_ClearedReason == "Parties Info:Org1(Import Broker)"));
			});

			try
			{
				loadedShipment.JS_OH_ImportBroker = org2.PK;
				secondFactory.Save();
				Assert("Save should not have succeeded.", false);
			}
			catch (Exception ex)
			{
				UnitTestUserNotification.Instance.ClearMessagesAndAnswers();
				ZExceptionReporting.HandleSaveException(ex);

				AssertEquals("User should have been notified of the problem.", false, UnitTestUserNotification.Instance.LastMessage.WasNone);
				Assert(UnitTestUserNotification.Instance.LastMessage.Text.Contains("While you have been working with this form, another user has made changes."));
				AssertNoExceptionThrown(() => { loadedShipment.JS_OH_ImportBroker = org3.PK; secondFactory.Save(); });
			}

			var screeningStatus2 = loadedShipment.RelatedOrgPartyScreeningStatusCollection.ToList<IRelatedOrgPartyScreeningStatus>();
			CombineAssertions(() =>
			{
				AssertEquals(true, screeningStatus2.Any(u => u.PJ_Status == "PAR" && u.PJ_ClearedReason == "Parties Info:Org1(Import Broker)"));
				AssertEquals(false, screeningStatus2.Any(u => u.PJ_Status == "PAA" && u.PJ_ClearedReason == "Parties Info:Org2(Import Broker)"));
				AssertEquals(true, screeningStatus2.Any(u => u.PJ_Status == "PAA" && u.PJ_ClearedReason == "Parties Info:Org3(Import Broker)"));
			});
		}

