		public void TestGetWorstScreeningStatus_ForHVLShipment()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_ShipmentType = ShipmentTypes.HighVolumeLowValue;
			shipment.JS_ScreeningStatus = ScreeningStatusesList.Codes.Clear;

			var consigneeAddress = Factory.NewWithValidTestData<OrgAddress>();
			consigneeAddress.Header.OH_Code = "CONSIGNEE";
			consigneeAddress.Header.OH_ScreeningStatus = ScreeningStatusesList.Codes.Clear;

			var header = Factory.LoadTop1<IHVLVConsignmentHeader>(new ZQuery(HVLVConsignmentHeaderSchema.HCH_JS_Shipment, shipment.PK)) as BusinessObject;
			header.FillWithValidTestData();

			var consignment = Factory.New<IHVLVConsignment>() as BusinessObject;
			consignment.FillWithValidTestData();
			consignment[HVLVConsignmentSchema.HVC_HCH_Header.Name] = header.PK;
			consignment[HVLVConsignmentSchema.HVC_OA_ConsigneeAddress.Name] = consigneeAddress.PK;
			consignment[HVLVConsignmentSchema.HVC_DeniedPartyScreeningStatus.Name] = ScreeningStatusesList.Codes.Matched;

			Factory.Save();

			using (HVLVDataRegistry.Instance.HVLVEnablePartyScreening.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new HVLVEnablePartyScreening() { EnableHVLVPartyScreening = false }))
			{
				var result = (shipment as IScreeningPartyProvider).GetWorstScreeningStatus();
				AssertEquals("Registry setting is off, consignment will not be included as part of the worst status", ScreeningStatusesList.Codes.Clear, result);
			}

			using (HVLVDataRegistry.Instance.HVLVEnablePartyScreening.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new HVLVEnablePartyScreening() { EnableHVLVPartyScreening = true }))
			{
				var result = (shipment as IScreeningPartyProvider).GetWorstScreeningStatus();
				AssertEquals("Registry setting is on, consignment will be included as part of the worst status", ScreeningStatusesList.Codes.Matched, result);
			}
		}

