		public void TestUniversalCopy_DeclarationCanBeSuccessfullyCopiedIfCreated()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();

			var shipmentType = typeof(ForwardingShipment);
			var interfaceType = GlowInterfaceReferenceAttribute.GetGlowInterfaceFromType(shipmentType, true);
			var copyTemplateTree = new CopyTemplateTree(interfaceType, shipmentType,
				BusinessObjectCopyManager.CopyTreeConfiguration);
			var declarationNode = (RelatedEntityCopyTemplateNode)((EntityCopyTemplateNode)copyTemplateTree.InnerNode).Nodes.Find(node =>
					node is RelatedEntityCopyTemplateNode &&
					((RelatedEntityCopyTemplateNode)node).Name == "JobDeclaration");
			declarationNode.CopyMethod = RelatedEntityCopyMethod.Copy;
			var copiedShipment = new BusinessObjectCopyManager().Copy(shipment, copyTemplateTree).Object as ForwardingShipment;

			AssertNull("When shipment without a declaration copied, the copied shipment should have no declaration as well.", copiedShipment.JobDeclaration);

			var declaration = Factory.New<IBaseJobDeclaration>();
			declaration.JE_JS = shipment.PK;
			declaration.JE_MasterBill = "MASTER1";
			var currentCompanyPK1 = GlbCompany.CurrentCompany.PK;
			declaration.JE_GC = currentCompanyPK1;
			using (GlbCompany.TemporaryLoginInNewCompanyForCountry(Core.Constants.CountryCodes.France))
			{
				var currentCompanyPK2 = GlbCompany.CurrentCompany.PK;
				AssertNotEquals("Two declarations should be created under different companies.", currentCompanyPK1, currentCompanyPK2);

				declaration = Factory.New<IBaseJobDeclaration>();
				declaration.JE_JS = shipment.PK;
				declaration.JE_MasterBill = "MASTER1";
				declaration.JE_GC = currentCompanyPK2;
			}

			AssertEquals("Prerequisite: There're already 2 declarations created under different companies.", 2, Factory.Load<IBaseJobDeclaration>(new ZQuery()).Length);
			CombineAssertions(() =>
			{
				var copiedShipment2 = new BusinessObjectCopyManager().Copy(shipment, copyTemplateTree).Object as ForwardingShipment;
				var copiedDeclaration = copiedShipment2.JobDeclaration;
				AssertNotNull("When shipment with a declaration copied, the copied shipment should have a declaration.", copiedDeclaration);
				AssertEquals("The declaration should be created for current company.", currentCompanyPK1, copiedDeclaration.JE_GC);
				AssertEquals("Only one declaration of current company copied.", 3, Factory.Load<IBaseJobDeclaration>(new ZQuery()).Length);
			});
		}

		public void TestUniversalCopy_IsDomesticFreight()
		{
			var entityNode = new EntityCopyTemplateNode();
			entityNode.Nodes.Add(new PropertyCopyTemplateNode { Name = JobShipmentSchema.Constants.JS_RL_NKOrigin, CopyMethod = CopyMethod.Copy });
			entityNode.Nodes.Add(new PropertyCopyTemplateNode { Name = JobShipmentSchema.Constants.JS_RL_NKDestination, CopyMethod = CopyMethod.Copy });
			var copyTree = new CopyTemplateTree { InnerNode = entityNode };

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_RL_NKOrigin = "USLAX";
			shipment.JS_RL_NKDestination = "USCHI";

			Assert("Precondition", shipment.IsDomesticFreight);

			var copyShipment = new BusinessObjectCopyManager().Copy(shipment, copyTree).Object as ForwardingShipment;
			Assert("IsDomesticFreight", copyShipment.IsDomesticFreight);

			shipment.JS_RL_NKDestination = "NZAKL";

			Assert("Precondition", !shipment.IsDomesticFreight);

			var copyShipment2 = new BusinessObjectCopyManager().Copy(shipment, copyTree).Object as ForwardingShipment;
			Assert("!IsDomesticFreight", !copyShipment2.IsDomesticFreight);
		}

		public void TestUniversalCopy_ContainerPackLinkCreateMissingConShipLinks()
		{
			var (sourceConsol, sourceShipment) = CreateConsolAndShipmentWithConShipLink();
			CopyAndAssertCopiedConsol(CreateShipmentCopyTemplateTree("Copy PackLine and Link PackLine.Container", false), sourceConsol, sourceShipment, "N95");

			(sourceConsol, sourceShipment) = CreateConsolAndShipmentWithConShipLink();
			CopyAndAssertCopiedConsol(CreateShipmentCopyTemplateTree("Copy PackLine and Link PackLine.Container with ConsolShip link", true), sourceConsol, sourceShipment, "N95");

			var consolRelatedEntityNode = new RelatedEntityCopyTemplateNode
			{
				Name = "JobConsol",
				RelatedEntityTableName = "JobConsol",
				RelatedPropertyName = "JC_JK",
				CopyMethod = RelatedEntityCopyMethod.Link
			};
			var containerEntityNode = new EntityCopyTemplateNode
			{
				Name = "JobContainer"
			};
			containerEntityNode.Nodes.Add(new PropertyCopyTemplateNode { Name = "JC_ContainerNum", CopyMethod = CopyMethod.Value, Value = "N98" });
			containerEntityNode.Nodes.Add(consolRelatedEntityNode);

			(sourceConsol, sourceShipment) = CreateConsolAndShipmentWithConShipLink();
			CopyAndAssertCopiedConsol(CreateShipmentCopyTemplateTree("Copy PackLine + Container and Link PackLine.Container.Consol", false, containerEntityNode), sourceConsol, sourceShipment, "N98");

			(sourceConsol, sourceShipment) = CreateConsolAndShipmentWithConShipLink();
			CopyAndAssertCopiedConsol(CreateShipmentCopyTemplateTree("Copy PackLine + Container and Link PackLine.Container.Consol with ConsolShip link", true, containerEntityNode), sourceConsol, sourceShipment, "N98");
		}

		(ForwardingConsol, ForwardingShipment) CreateConsolAndShipmentWithConShipLink()
		{
			var consol = Factory.New<ForwardingConsol>();
			consol.JK_TransportMode = "SEA";
			consol.JK_ConsolMode = "FCL";
			var container = consol.Containers.AddNew();
			container.JC_ContainerNum = "N95";
			container.JC_ContainerMode = "FCL";

			var shipment = consol.Shipments.AddNew();
			shipment.JS_ActualWeight = 5;
			shipment.JS_ActualVolume = 5;
			shipment.JS_OuterPacks = 5;

			Factory.Save();
			AssertEquals("Pre-condition: shipment has one packline.", 1, shipment.OuterPackLines.Count);
			AssertEquals("Pre-condition: shipment's packline is linked to consol's container.", "N95", shipment.OuterPackLines[0].JL_Calc_ContainerNum);

			return (consol, shipment);
		}

		void CopyAndAssertCopiedConsol(CopyTemplateTree copyTree, ForwardingConsol sourceConsol, ForwardingShipment sourceShipment, string expectedLinkedContainerNum)
		{
			var copyManager = new BusinessObjectCopyManager(Factory);
			var copiedShipment = copyManager.Copy(sourceShipment, copyTree).Object as ForwardingShipment;

			CombineAssertions($"UC template: {copyTree.Description}", () =>
			{
				AssertNoExceptionThrown("Saving should not throw missing Con-Ship link exception.", () => Factory.Save());
				AssertEquals("PackLine is copied.", 1, copiedShipment.OuterPackLines.Count);
				AssertEquals("Consol-Shipment link is created.", 1, copiedShipment.Consols.Count);
				AssertEquals("Consol-Shipment link is created.", sourceConsol.PK, copiedShipment.Consols[0].PK);
				AssertEquals("PackLine is linked to container.", 1, copiedShipment.OuterPackLines[0].Containers.Count);
				AssertEquals("PackLine is linked to container.", copiedShipment.Consols[0].PK, copiedShipment.OuterPackLines[0].Containers[0].Consol.PK);
				AssertEquals("PackLine is linked to container.", expectedLinkedContainerNum, copiedShipment.OuterPackLines[0].Containers[0].JC_ContainerNum);
			});
		}

		CopyTemplateTree CreateShipmentCopyTemplateTree(string templateDescription, bool withConShipLink, EntityCopyTemplateNode containerEntityNode = null)
		{
			var containerRelatedEntityNode = new RelatedEntityCopyTemplateNode
			{
				Name = "JobContainer",
				RelatedEntityTableName = "JobContainer",
				RelatedPropertyName = "J6_JC",
				CopyMethod = containerEntityNode == null ? RelatedEntityCopyMethod.Link : RelatedEntityCopyMethod.Copy,
				InnerNode = containerEntityNode
			};

			var containerPackPivotEntityNode = new EntityCopyTemplateNode
			{
				Name = "JobContainerPackPivot",
			};
			containerPackPivotEntityNode.Nodes.Add(containerRelatedEntityNode);

			var containerPackPivotsCollectionNode = new CollectionCopyTemplateNode()
			{
				Name = "JobContainerPackPivots",
				ItemPropertyName = "J6_JL",
				ItemsTableName = "JobContainerPackPivot",
				InnerNode = containerPackPivotEntityNode,
				CopyMethod = CollectionCopyMethod.All
			};

			var packLineEntityNode = new EntityCopyTemplateNode
			{
				Name = "JobPackLine"
			};
			packLineEntityNode.Nodes.Add(new PropertyCopyTemplateNode { Name = "JL_FreightMode", CopyMethod = CopyMethod.Copy });
			packLineEntityNode.Nodes.Add(containerPackPivotsCollectionNode);

			var packLinesCollectionNode = new CollectionCopyTemplateNode
			{
				Name = "JobPackLines",
				ItemPropertyName = "JL_JS",
				ItemsTableName = "JobPackLines",
				InnerNode = packLineEntityNode,
				CopyMethod = CollectionCopyMethod.All
			};

			var shipmentEntityNode = new EntityCopyTemplateNode
			{
				Name = "JobShipment"
			};
			shipmentEntityNode.Nodes.Add(packLinesCollectionNode);

			if (withConShipLink)
			{
				var consolRelatedEntityNode = new RelatedEntityCopyTemplateNode
				{
					Name = "JobConsol",
					RelatedEntityTableName = "JobConsol",
					RelatedPropertyName = "JN_JK",
					CopyMethod = RelatedEntityCopyMethod.Link
				};

				var conShipLinkEntityNode = new EntityCopyTemplateNode
				{
					Name = "JobConShipLink",
				};
				conShipLinkEntityNode.Nodes.Add(consolRelatedEntityNode);

				var conShipLinkCollectionNode = new CollectionCopyTemplateNode()
				{
					Name = "JobConShipLinks",
					ItemPropertyName = "JN_JS",
					ItemsTableName = "JobConShipLink",
					InnerNode = conShipLinkEntityNode,
					CopyMethod = CollectionCopyMethod.All
				};

				shipmentEntityNode.Nodes.Add(conShipLinkCollectionNode);
			}

			var copyTree = new CopyTemplateTree
			{
				Name = "JobShipment",
				InnerNode = shipmentEntityNode,
				TableName = "JobShipment",
				Description = templateDescription
			};

			return copyTree;
		}

		public void TestUniversalCopy_UNDG()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_TransportMode = "AIR";
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "MYKUL";
			shipment.JS_OuterPacks = 1;
			var packLine = shipment.OuterPackLines[0];
			var undgDataItem = packLine.UNDGs.AddNew();
			var substance = Factory.NewWithValidTestData<UNDGSubstance>();
			substance.DG_Standard = UNDGSubstanceLookups.UNDGSubstanceStandardTypes.IATA;
			substance.DG_UNNO = "0004";
			substance.DG_Variant = "a";
			substance.DG_PSN = "very dangerous thing";
			undgDataItem.DI_DG = substance.PK;

			Factory.Save();

			AssertEquals("Precondition: shipment UNDG PSN", "very dangerous thing", packLine.UNDGs[0].Subs.DG_PSN);

			var undgDataItemEntityNode = new EntityCopyTemplateNode { Name = "UNDGDataItem" };
			undgDataItemEntityNode.Nodes.Add(new PropertyCopyTemplateNode { Name = "DI_DG", CopyMethod = CopyMethod.Copy });

			var undgDataItemsCollectionNode = new CollectionCopyTemplateNode
			{
				Name = "UNDGDataItems",
				ItemPropertyName = "DI_ParentID",
				ItemsTableName = "UNDGDataItem",
				InnerNode = undgDataItemEntityNode,
				CopyMethod = CollectionCopyMethod.All
			};

			var packLineEntityNode = new EntityCopyTemplateNode { Name = "JobPackLine" };
			packLineEntityNode.Nodes.Add(new PropertyCopyTemplateNode { Name = "JL_FreightMode", CopyMethod = CopyMethod.Copy });
			packLineEntityNode.Nodes.Add(undgDataItemsCollectionNode);

			var packLinesCollectionNode = new CollectionCopyTemplateNode
			{
				Name = "JobPackLines",
				ItemPropertyName = "JL_JS",
				ItemsTableName = "JobPackLines",
				InnerNode = packLineEntityNode,
				CopyMethod = CollectionCopyMethod.All
			};

			var shipmentEntityNode = new EntityCopyTemplateNode { Name = "JobShipment" };
			shipmentEntityNode.Nodes.Add(packLinesCollectionNode);

			var copyTree = new CopyTemplateTree { InnerNode = shipmentEntityNode };

			var copyManager = new BusinessObjectCopyManager();

			var copiedShipment = copyManager.Copy(shipment, copyTree).Object as ForwardingShipment;
			AssertNotNull("New CommonShipment created by Universal Copy", copiedShipment);
			AssertEquals("PackLines are copied", 1, copiedShipment.OuterPackLines.Count);
			AssertEquals("PackLine UNDGs are copied", 1, copiedShipment.OuterPackLines[0].UNDGs.Count);
			AssertEquals("UNDG Substance is copied", substance.PK, copiedShipment.OuterPackLines[0].UNDGs[0].DI_DG);
			AssertEquals("UNDG PSN is copied", "very dangerous thing", copiedShipment.OuterPackLines[0].UNDGs[0].Subs.DG_PSN);
		}

		public void TestUniversalCopy_JobDocAddresses()
		{
			Env.Security.MaintainShipmentAllowPublisheHBL.IsAllowed = true;

			var boleroEBLConfiguration = new BoleroEBLConfiguration()
			{
				EnableEBLIntegration = true,
				GalileoEndPointUrl = "http://test.test",
				GalileoAudience = Guid.NewGuid().ToString(),
				GalileoTestEndPointUrl = "http://test.test",
				GalileoTestAudience = Guid.NewGuid().ToString()
			};

			GlbBranch.CurrentBranch.OrgProxy.CustomsCodes.AddNew(OrgCusCode.CodeTypes.BoleroTitleRegisterID, "123456789");

			using (FreightDataRegistry.Instance.EnableBoleroEHBLIntegration.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, boleroEBLConfiguration))
			{
				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "AUSYD";
				shipment.JS_RL_NKDestination = "MYKUL";

				shipment.JS_HouseBill = "S000Z1001";
				shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;

				shipment.ConsigneeDocumentaryAddress.E2_OA_Address = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;
				shipment.ConsignorDocumentaryAddress.E2_OA_Address = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;
				shipment.ControllingCustomerAddress.E2_OA_Address = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;
				shipment.ControllingCustomerAddress.E2_GovRegNumType = "CNO";
				shipment.DocAddresses.AddNew(DocAddressType.ControllingAgent).E2_OA_Address = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;

				shipment.DocAddresses.AddNew(DocAddressType.Holder).E2_OA_Address = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;
				shipment.DocAddresses.AddNew(DocAddressType.Shipper).E2_OA_Address = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;
				shipment.DocAddresses.AddNew(DocAddressType.ConsigneeElectronicBOLAddress).E2_OA_Address = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;
				shipment.DocAddresses.AddNew(DocAddressType.SurrenderParty).E2_OA_Address = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;

				Factory.Save();

				Assert("EnabledElectronicBOL", shipment.EnabledElectronicBOL);

				var entityNode = new EntityCopyTemplateNode();
				entityNode.Nodes.Add(new PropertyCopyTemplateNode { Name = JobShipmentSchema.Constants.JS_RL_NKOrigin, CopyMethod = CopyMethod.Copy });
				entityNode.Nodes.Add(new PropertyCopyTemplateNode { Name = JobShipmentSchema.Constants.JS_RL_NKDestination, CopyMethod = CopyMethod.Copy });
				entityNode.Nodes.Add(new PropertyCopyTemplateNode { Name = JobShipmentSchema.Constants.JS_TransportMode, CopyMethod = CopyMethod.Copy });
				entityNode.Nodes.Add(new PropertyCopyTemplateNode { Name = JobShipmentSchema.Constants.JS_HouseBill, CopyMethod = CopyMethod.Copy });

				var jobDocAddressesNode = new CollectionCopyTemplateNode
				{
					Name = "Addresses",
					ItemPropertyName = "Addresses",
					ItemsTableName = JobDocAddressSchema.Constants.TableName,
					InnerNode = CreateJobDocAddressEntityTemplateNode("Address"),
					CopyMethod = CollectionCopyMethod.All
				};

				entityNode.Nodes.Add(jobDocAddressesNode);

				var copyTree = new CopyTemplateTree { InnerNode = entityNode };

				var copyManager = new BusinessObjectCopyManager();

				var copiedShipment = copyManager.Copy(shipment, copyTree).Object as ForwardingShipment;
				AssertNotNull("New ForwardingShipment created by copy BusinessObjectCopyManager", copiedShipment);
				AssertEquals("AUSYD", copiedShipment.JS_RL_NKOrigin);
				AssertEquals("MYKUL", copiedShipment.JS_RL_NKDestination);
				AssertEquals("S000Z1001", copiedShipment.JS_HouseBill);
				AssertEquals(Core.Constants.TransportModes.Sea, copiedShipment.JS_TransportMode);
				Assert(copiedShipment.EnabledElectronicBOL);

				copiedShipment.JS_HouseBill = "S000Z1002";
				Factory.Save();

				AssertGreaterThan(shipment.DocAddresses.Count, copiedShipment.DocAddresses.Count);
				Assert(copiedShipment.IsInDatabase);

				AssertNotNull(shipment.DocAddresses.FindByDocAddressType(DocAddressType.Holder));
				AssertNull(copiedShipment.DocAddresses.FindByDocAddressType(DocAddressType.Holder));

				AssertNotNull(shipment.DocAddresses.FindByDocAddressType(DocAddressType.SurrenderParty));
				AssertNull(copiedShipment.DocAddresses.FindByDocAddressType(DocAddressType.SurrenderParty));

				AssertNotNull(shipment.DocAddresses.FindByDocAddressType(DocAddressType.ConsigneeElectronicBOLAddress));
				AssertEquals(false, copiedShipment.DocAddresses.FindByDocAddressType(DocAddressType.ConsigneeElectronicBOLAddress)?.IsInDatabase ?? false);

				AssertNotNull(shipment.DocAddresses.FindByDocAddressType(DocAddressType.Shipper));
				AssertEquals(false, copiedShipment.DocAddresses.FindByDocAddressType(DocAddressType.Shipper)?.IsInDatabase ?? false);
			}
		}

		EntityCopyTemplateNode CreateJobDocAddressEntityTemplateNode(string name)
