		public void TestCFSAddressesDefaultFromRelatedParty()
		{
			var consignor = Factory.New<OrgHeader>();
			var consignee = Factory.New<OrgHeader>();
			var cnrClientCFS = Factory.New<OrgHeader>();
			var cneClientCFS = Factory.New<OrgHeader>();

			consignor.AddRelatedParty(cnrClientCFS.PK, RelatedPartyTypeList.Codes.ClientCFS, RelatedPartyDirectionList.Codes.Pickup, Constants.TransportModes.All, ZString.Empty, GlbCompany.CurrentCompany);
			consignee.AddRelatedParty(cneClientCFS.PK, RelatedPartyTypeList.Codes.ClientCFS, RelatedPartyDirectionList.Codes.Delivery, Constants.TransportModes.All, ZString.Empty, GlbCompany.CurrentCompany);

			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Constants.TransportModes.Road;
			shipment.ConsignorPK = consignor.PK;
			shipment.ConsigneePK = consignee.PK;

			AssertEquals(cnrClientCFS.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);
			AssertEquals(cneClientCFS.PK, shipment.JS_OA_ImportReleaseDepot_ZAddress.OrgPK);

			shipment.JS_TransportMode = Constants.TransportModes.Sea;
			shipment.ConsignorPK = consignor.PK;
			shipment.ConsigneePK = consignee.PK;

			AssertEquals(cnrClientCFS.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);
			AssertEquals(cneClientCFS.PK, shipment.JS_OA_ImportReleaseDepot_ZAddress.OrgPK);
		}

