		public void TestBusinessObjectWithRelatedEventsOnManifest()
		{
			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.JK_UniqueConsignRef = "CS223344";
			var header1 = Factory.New<ASYCUDA.ZAManifest.IAsycudaManifestHeader>();
			((BusinessObject)header1).FillWithValidTestData();
			header1.AMA_ParentId = consol.PK;
			header1.AMA_ParentTableCode = consol.TablePrefix;
			header1.AMA_JobReference = "1";

			var shipment = consol.Shipments.AddNew();
			shipment.JS_UniqueConsignRef = "SP546";

			var bill1 = Factory.New<ASYCUDA.ZAManifest.IAsycudaBill>();
			bill1.ABL_AMA = header1.PK;
			bill1.ABL_BillNumber = "bill1";
			bill1.ABL_JS_Shipment = shipment.PK;

			var pack1 = Factory.New<ASYCUDA.ZAManifest.IAsycudaPack>();
			pack1.APA_ABL_Bill = bill1.PK;
			pack1.APA_GoodsDescription = "pack1";

			var header2 = Factory.New<ASYCUDA.NZManifest.IAsycudaManifestHeader>();
			((BusinessObject)header2).FillWithValidTestData();
			header2.AMA_ParentId = consol.PK;
			header2.AMA_ParentTableCode = consol.TablePrefix;
			header2.AMA_JobReference = "2";

			var header3 = Factory.New<ASYCUDA.ACEManifest.IAsycudaManifestHeader>();
			((BusinessObject)header3).FillWithValidTestData();
			header3.AMA_ParentId = consol.PK;
			header3.AMA_ParentTableCode = consol.TablePrefix;
			var bill3 = Factory.New<ASYCUDA.ACEManifest.IAsycudaBill>();
			bill3.ABL_AMA = header3.PK;
			var pack3 = Factory.New<ASYCUDA.ACEManifest.IAsycudaPack>();
			pack3.APA_ABL_Bill = bill3.PK;
			pack3.APA_GoodsDescription = "pack3";

			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var newShipment = newFactory.Load<ForwardingShipment>(shipment.PK);
			Assert("Header1 should be in the list of related objects", newShipment.BusinessObjectsWithRelatedEvents.Any(x => x.PK == header1.PK));
			Assert("Header2 should not be in the list of related objects, NZ manifests are all Shipping Line manifests.", !newShipment.BusinessObjectsWithRelatedEvents.Any(x => x.PK == header2.PK));
			Assert("Header3 should be in the list of related objects", newShipment.BusinessObjectsWithRelatedEvents.Any(x => x.PK == header3.PK));

			Assert("Bill1 should be in the list of related objects", newShipment.BusinessObjectsWithRelatedEvents.Any(x => x.PK == bill1.PK));
			Assert("Pack1 should be in the list of related objects", newShipment.BusinessObjectsWithRelatedEvents.Any(x => x.PK == pack1.PK));

			Assert("Bill3 should not be in the list of related objects", !newShipment.BusinessObjectsWithRelatedEvents.Any(x => x.PK == bill3.PK));
			Assert("Pack3 should not be in the list of related objects", !newShipment.BusinessObjectsWithRelatedEvents.Any(x => x.PK == pack3.PK));
		}

