		public void TestPackingModeDefaultsCorrectly()
		{
			FreightConfigurationRegistry.Instance.DefaultContainerModes.SetValue(Guid.Empty,
																		Guid.Empty,
																		Guid.Empty,
																		new DefaultContainerModesCollection
																			{
																				new DefaultContainerModes
																					{
																						TransportMode = Constants.TransportModes.Sea,
																						ContainerMode = Constants.ContainerModes.FCL
																					}
																			});
			var shipment = Factory.New<ForwardingShipment>();
			AssertEquals(string.Empty, shipment.JS_TransportMode);
			AssertEquals("LCL", shipment.JS_PackingMode);

			var dep = GlbDepartment.CurrentDepartment;
			dep.GE_Air = false;
			dep.GE_Sea = true;

			try
			{
				shipment = Factory.New<ForwardingShipment>();
				AssertEquals("SEA", shipment.JS_TransportMode);
				AssertEquals("FCL", shipment.JS_PackingMode);

				FreightConfigurationRegistry.Instance.DefaultContainerModes.SetValue(Guid.Empty,
					Guid.Empty,
					Guid.Empty,
					new DefaultContainerModesCollection
					{
						new DefaultContainerModes
						{
							TransportMode = Constants.TransportModes.Sea,
							ContainerMode = Constants.ContainerModes.LCL
						}
					});

				shipment = new BusinessObjectFactory().New<ForwardingShipment>();
				AssertEquals("SEA", shipment.JS_TransportMode);
				AssertEquals("LCL", shipment.JS_PackingMode);
			}
			finally
			{
				dep.GE_Sea = false;
			}
		}

