		public void TestRaiseJobDeclarationCreated()
		{
			var declaration1 = Factory.New<IBaseJobDeclaration>();
			var shipment = Factory.New<ForwardingShipment>();
			var count = 0;
			shipment.OnJobDeclarationCreated += (object sender, JobDeclarationCreationEventArgs e) =>
			{
				if (e.Declaration == declaration1)
				{
					count++;
				}
			};
			shipment.RaiseJobDeclarationCreated(null);
			AssertEquals(0, count);
			shipment.RaiseJobDeclarationCreated(declaration1);
			AssertEquals(1, count);
			shipment.RaiseJobDeclarationCreated(Factory.New<IBaseJobDeclaration>());
			AssertEquals(1, count);
		}

