		public void TestPrepaindAndCollectTotalsAreRefreshedOnUpdatedByDataRefreshBus()
		{
			ForwardingConsol consol = Factory.New<ForwardingConsol>();

			bool totalCollectRefreshed = false;
			bool totalPrepaidRefreshed = false;

			consol.JK_TotalCollectShipmentChargeableAmountInfo.ValueChanged += (s, e) => { totalCollectRefreshed = true; };
			consol.JK_TotalPrepaidShipmentChargeableAmountInfo.ValueChanged += (s, e) => { totalPrepaidRefreshed = true; };

			ForwardingShipment shipment = consol.Shipments.AddNew();
			shipment.JS_ActualVolume = 10;

			Factory.Save();

			AssertEquals(true, totalCollectRefreshed);
			AssertEquals(true, totalPrepaidRefreshed);

			totalCollectRefreshed = false;
			totalPrepaidRefreshed = false;

			BusinessObjectFactory anotherFactory = new BusinessObjectFactory();
			ForwardingShipment shipmentReloadedInAnotherFactory = anotherFactory.Load<ForwardingShipment>(shipment.PK);
			shipmentReloadedInAnotherFactory.JS_ActualVolume = 20;
			anotherFactory.Save();

			AssertEquals(true, totalCollectRefreshed);
			AssertEquals(true, totalPrepaidRefreshed);
		}

		public void TestPopulateAWBIfExists()
		{
			OrgHeader org1 = Factory.New<OrgHeader>();
			org1.OH_Code = "ORG1";
			org1.OH_FullName = "Org 1";

			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Constants.TransportModes.Air;
			Assert(!shipment.IsAWBLoaded);

			shipment.ConsigneeDocumentaryAddress.OrganisationPK = org1.PK;
			shipment.ConsignorDocumentaryAddress.OrganisationPK = org1.PK;
			shipment.NotifyPartyDocumentaryAddress.OrganisationPK = org1.PK;
			Assert(!shipment.IsAWBLoaded);

			shipment.PopulateAWB();
			Assert(shipment.IsAWBLoaded);

			AssertEquals("Org 1", shipment.AWBHeader.EH_ConsigneeName);
			AssertEquals("Org 1", shipment.AWBHeader.EH_ShipperName);
			AssertEquals("Org 1", shipment.AWBHeader.EH_NotifyOverride1);

			OrgHeader org2 = Factory.New<OrgHeader>();
			org2.OH_Code = "ORG2";
			org2.OH_FullName = "Org 2";

			OrgHeader org3 = Factory.New<OrgHeader>();
			org3.OH_Code = "ORG3";
			org3.OH_FullName = "Org 3";

			OrgHeader org4 = Factory.New<OrgHeader>();
			org4.OH_Code = "ORG4";
			org4.OH_FullName = "Org 4";

			shipment.ConsigneeDocumentaryAddress.OrganisationPK = org2.PK;
			shipment.ConsignorDocumentaryAddress.OrganisationPK = org3.PK;
			shipment.NotifyPartyDocumentaryAddress.OrganisationPK = org4.PK;

			AssertEquals("Org 2", shipment.AWBHeader.EH_ConsigneeName);
			AssertEquals("Org 3", shipment.AWBHeader.EH_ShipperName);
			AssertEquals("Org 4", shipment.AWBHeader.EH_NotifyOverride1);
		}

		public void TestPopulateAWBForDocuments()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = TransportModes.Air;
			Assert(!shipment.IsAWBLoaded);
			Assert(!shipment.AWBForDocumentsPopulated);

			shipment.AWBForDocumentsPopulated = true;
			shipment.PopulateAWBForDocuments();
			Assert(!shipment.IsAWBLoaded);
			Assert(shipment.AWBForDocumentsPopulated);

