		#region Test Save Performance

		public void TestSavePerformance()
		{
			//this test will fail if you remove if (HasChanges) in CalculateJC_EmptyReturnedBy_ForContainersIfRequired
			ForwardingShipment motherShip = Factory.New<ForwardingShipment>();
			ForwardingConsol mainConsol = motherShip.Consols.AddNew();
			ForwardingShipment lastChild = AddShipmentsToConsol(mainConsol);

			for (int i = 0; i <= 5; i++)
			{
				lastChild = AddShipmentsToConsol(lastChild.Consols.AddNew());
			}

			Factory.Save();

			BusinessObjectFactory newFactory = new BusinessObjectFactory();
			motherShip = newFactory.Load<ForwardingShipment>(motherShip.PK);

			motherShip.JS_HouseBill = "dd";
			newFactory.Save();

			ZQuery query = new ZQuery();
			query.FetchOnlyFromLocalCache = true;

			ForwardingShipment[] shipmentsLoadedIntoFactoryWhenSavingOneShipment = newFactory.Load<ForwardingShipment>(query);
			AssertEquals("Saving one shipment shouldn't load all related shipments", 1, shipmentsLoadedIntoFactoryWhenSavingOneShipment.Length);
		}

		ForwardingShipment AddShipmentsToConsol(ForwardingConsol mainConsol)
