		public void TestShipmentCustomsEntryNumber_ValidatesPacklines()
		{
			var shipment = Factory.New<ForwardingShipment>();
			var packline = shipment.OuterPackLines.AddNew();

			packline.JL_ExportRefNumber = "Dorcus rudis";

			shipment.CustomsEntryNumber = ZString.Empty;
			shipment.CustomsEntryNumberType = CusEntryNumberTypes.Standard.MovementReferenceNumber;

			AssertHasWarning(packline.JL_ExportRefNumberInfo, @"MRN does not conform to the correct format. Please enter the MRN in the following format with only numbers and upper case letters:
• two numbers for the year of issue,
• two letters for the ISO country/region code for country/region of issue,
• thirteen alphanumeric characters for unique identification and
• one number check digit");

			shipment.CustomsEntryNumber = "Macrodorcas humilis";
			AssertNoWarnings("No warning when cusentrynumber on shipment level", packline.JL_ExportRefNumberInfo);

			shipment.CustomsEntryNumber = ZString.Empty;

			AssertHasWarning("Warning should be back", packline.JL_ExportRefNumberInfo, @"MRN does not conform to the correct format. Please enter the MRN in the following format with only numbers and upper case letters:
• two numbers for the year of issue,
• two letters for the ISO country/region code for country/region of issue,
• thirteen alphanumeric characters for unique identification and
• one number check digit");

			shipment.CustomsEntryNumberType = CusEntryNumberTypes.Standard.DrawbackClaim;

			AssertNoWarnings("Warning should only be for MRN", packline.JL_ExportRefNumberInfo);

			shipment.CustomsEntryNumberType = CusEntryNumberTypes.Standard.MovementReferenceNumber;
			packline.JL_ExportRefNumber = "10DE210119797085T1";

			AssertNoWarnings("No warning with valid MRN number", packline.JL_ExportRefNumberInfo);
		}

