		void AssertAddDateEventsCancelsOldOnes(SchemaColumn column, string eventCode)
		{
			ZQuery logsQuery = new ZQuery(StmALogSchema.SL_SE_NKEvent, eventCode);
			logsQuery.OrderBy = StmALogSchema.Constants.SL_EventTime + " DESC";

			ZDateTime dt0 = ZDateTime.Today;
			ZDateTime dt1 = ZDateTime.Today.AddDays(-5);
			ZDateTime dt2 = ZDateTime.Today.AddDays(5);
			ZDateTime dt3 = ZDateTime.Today.AddDays(7);

			CommonShipment shipment = Factory.New<CommonShipment>();
			shipment[column] = dt0;
			Factory.Save();
			StmALog[] logs = shipment.Logs.Find(logsQuery);
			AssertEquals(1, logs.Length);
			AssertEquals(dt0, logs[0].SL_EventTime);
			AssertEquals(false, logs[0].IsCancelled);

			shipment[column] = dt1;
			Factory.Save();

			logs = shipment.Logs.Find(logsQuery);
			AssertEquals(2, logs.Length);
			AssertEquals(dt0, logs[0].SL_EventTime);
			AssertEquals(true, logs[0].IsCancelled);
			AssertEquals(dt1, logs[1].SL_EventTime);
			AssertEquals(false, logs[1].IsCancelled);

			shipment[column] = dt2;
			Factory.Save();

			logs = shipment.Logs.Find(logsQuery);
			AssertEquals(3, logs.Length);
			AssertEquals(dt2, logs[0].SL_EventTime);
			AssertEquals(false, logs[0].IsCancelled);
			AssertEquals(dt0, logs[1].SL_EventTime);
			AssertEquals(true, logs[1].IsCancelled);
			AssertEquals(dt1, logs[2].SL_EventTime);
			AssertEquals(true, logs[2].IsCancelled);

			var log4 = shipment.Logs.AddNew(Events.All[eventCode], "ABC From: 01-JAN-12 To: 31-DEC-12", dt0.ToOffset(), true);
			shipment[column] = dt3;
			Factory.Save();

			Assert("Should not cancel log with non-standard reference", !log4.SL_IsCancelled);
		}

