		#region TestOrderedInvoiceTargets

		public void TestOrderedInvoiceTargets()
		{
			ForwardingShipment createShipment(string jobNumber, string loadPort, string dischargePort, ForwardingConsol consol = null)
			{
				var s = consol != null
					? consol.Shipments.AddNew()
					: Factory.NewWithValidTestData<ForwardingShipment>();

				s.JS_RL_NKLoadPort = loadPort;
				s.JS_RL_NKDischargePort = dischargePort;

				return s;
			}

			ForwardingConsol createConsol(string loadPort, string dischargePort, string jobNumber)
			{
				var c = Factory.NewWithValidTestData<ForwardingConsol>();
				c.JK_RL_NKLoadPort = loadPort;
				c.JK_RL_NKDischargePort = dischargePort;

				return c;
			}

			var cSS = createConsol("AUSYD", "SGSIN", "C00SS");
			var shipment1 = createShipment("S0001", "AUSYD", "USLAX", cSS);
			var shipment2 = createShipment("S0002", "AUBNE", "USNYC", cSS);
			var shipment3 = createShipment("S0003", "AUBNE", "SGSIN", cSS);
			var shipment4 = createShipment("S0004", "AUMEL", "USLAX");

			//			cBS			cSS			cSH			cHL
			//	AUBNE	-	AUSYD	-	SGSIN	-	HKHKG	-	USLAX
			//												 \
			//													cHN
			//														\
			//															USNYC
			//				|-	-	-	-	Shipment1	-	-	-|
			//	|-	-	-	-	-	-	-	Shipment2	-	-	-	-	-|
			//	|-	-	Shipment3	-	-|
			//
			ForwardingConsol cHL = createConsol("HKHKG", "USLAX", "C00HL");
			ForwardingConsol cBS = createConsol("AUBNE", "AUSYD", "C00BS");
			ForwardingConsol cSH = createConsol("SGSIN", "HKHKG", "C00SH");
			ForwardingConsol cHN = createConsol("HKHKG", "USNYC", "C00HN");

			shipment1.Consols.Add(cHL);
			shipment1.Consols.Add(cSH);
			shipment2.Consols.Add(cHN);
			shipment2.Consols.Add(cSH);
			shipment2.Consols.Add(cBS);
			shipment3.Consols.Add(cBS);

			Factory.Save();

			var expected = new[] { cSS, cSH, cHL }.Select(x => x);
			AssertArrayEqualsByElements(expected.ToArray(), (shipment1.InvoicingSupporter as IGatewayJobInvoicingSupporter).OrderedInvoiceTargets.ToArray());

			expected = new[] { cBS, cSS, cSH, cHN }.Select(x => x);
			AssertArrayEqualsByElements(expected.ToArray(), (shipment2.InvoicingSupporter as IGatewayJobInvoicingSupporter).OrderedInvoiceTargets.ToArray());

			expected = new[] { cBS, cSS }.Select(x => x);
			AssertArrayEqualsByElements(expected.ToArray(), (shipment3.InvoicingSupporter as IGatewayJobInvoicingSupporter).OrderedInvoiceTargets.ToArray());

			AssertArrayEqualsByElements(Array.Empty<IJobInvoicingPlugIn>(), (shipment4.InvoicingSupporter as IGatewayJobInvoicingSupporter).OrderedInvoiceTargets.ToArray());
		}

