		public void TestCustomsCharges()
		{
			var shipment = Factory.New<ForwardingShipment>();
			var declaration = Factory.New<IBaseJobDeclaration>();
			declaration.JE_JS = shipment.PK;
			declaration.JE_MessageType = "IMP";

			ICustomsCharges customsCharges = ServiceLocator.GetService<ICustomsCharges>(declaration);
			AssertEquals("precondition: Declaration should be active", true, customsCharges.IsActive);

			AssertContainsExactElementsInAnyOrder("precondition: Declarations should contain the declaration",
				new BusinessObject[] { (BusinessObject)declaration },
				shipment.Declarations);

			AssertContainsExactElementsInAnyOrder("AdditionalCharges should contain the declaration",
				new ICustomsChargesComparer(),
				new ICustomsCharges[] { ServiceLocator.GetService<ICustomsCharges>(declaration) },
				((ICustomsChargesAdditionalCharges)shipment).AdditionalCharges);
		}

		public class ICustomsChargesComparer : IEqualityComparer<ICustomsCharges>
		{
			#region IEqualityComparer<ICustomsCharges> Members

			bool IEqualityComparer<ICustomsCharges>.Equals(ICustomsCharges x, ICustomsCharges y)
			{
				bool result = x.IsActive == y.IsActive && x.GetCustomsCharges(null).Length == y.GetCustomsCharges(null).Length;
				if (result)
				{
					var comparer = new Comparison<CustomsCharge>((CustomsCharge charge1, CustomsCharge charge2) => { return charge1.ChargeCodePK.CompareTo(charge2.ChargeCodePK); });
					var xCharges = new List<CustomsCharge>(x.GetCustomsCharges(null));
					xCharges.Sort(comparer);
					var yCharges = new List<CustomsCharge>(y.GetCustomsCharges(null));
					yCharges.Sort(comparer);

					for (int i = 0; i < xCharges.Count; i++)
					{
						if (xCharges[i] != yCharges[i])
						{
							return false;
						}
					}
				}
				return result;
			}

			int IEqualityComparer<ICustomsCharges>.GetHashCode(ICustomsCharges obj)
			{
				throw new NotSupportedException("Not currently supported in testing");
			}

			#endregion
		}

