		#region TestConsolsListFilterDefaults

		public void TestConsolsListFilterDefaults()
		{
			string transportModeKey = "Transport Mode" + FilterBusinessObjectDefault.FilterPropertyDelimiter + "Property";
			string eTDFrom = "ETD" + FilterBusinessObjectDefault.FilterPropertyDelimiter + "Property1";
			string eTATo = "ETA" + FilterBusinessObjectDefault.FilterPropertyDelimiter + "Property2";

			ZDateTime currentTime = ZDateTime.Now;
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
			shipment.JS_RL_NKOrigin = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			shipment.JS_RL_NKDestination = "USLAX";
			shipment.JS_E_DEP = currentTime;
			shipment.JS_E_ARV = currentTime.AddDays(1);
			AssertEquals("Consols filter - Transport mode", Core.Constants.TransportModes.Air, shipment.Lookups.Consols_List.FilterBusinessObjectDefaults[transportModeKey].Value);
			AssertEquals("Consols filter - ETD should be truncated", currentTime.Date, shipment.Lookups.Consols_List.FilterBusinessObjectDefaults[eTDFrom].Value);

			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			shipment.JS_RL_NKOrigin = "GBLON";
			shipment.JS_RL_NKDestination = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			AssertEquals("Consol Transport mode changed", Core.Constants.TransportModes.Sea, shipment.Lookups.Consols_List.FilterBusinessObjectDefaults[transportModeKey].Value);
			AssertEquals("Consol changed to import - ETA should be truncated", currentTime.AddDays(1).Date, shipment.Lookups.Consols_List.FilterBusinessObjectDefaults[eTATo].Value);
		}

