		#region OnSaving

		public void TestUpdateConsolsPreAllocatedAmountExceededStatus()
		{
			ForwardingConsol consol = Factory.New<ForwardingConsol>();
			consol.JK_TotalShipmentActWeightCheck = 1000m;
			consol.JK_TotalShipmentActVolumeCheck = 100m;

			ForwardingShipment shipment = consol.Shipments.AddNew();
			shipment.JS_ActualWeight = 800m;
			shipment.JS_ActualVolume = 60m;

			ForwardingConsol anotherConsol = Factory.New<ForwardingConsol>();
			anotherConsol.JK_TotalShipmentActWeightCheck = 1000m;
			anotherConsol.JK_TotalShipmentActVolumeCheck = 100m;
			anotherConsol.Shipments.Add(shipment);

			Factory.Save();

			BusinessObjectFactory anotherFactory = new BusinessObjectFactory();
			ForwardingShipment shipmentLoadedInAnotherFactory = anotherFactory.Load<ForwardingShipment>(shipment.PK);

			AssertConsolPreAllocatedAmountExceededEvent(consol, false);
			AssertConsolPreAllocatedAmountExceededEvent(anotherConsol, false);

			PreAllocationCheckCollection preAllocationChecks = ForwardingConfigurationRegistry.Instance.ConsolPreAllocationCheck.Value;
			foreach (PreAllocationCheck check in preAllocationChecks)
			{
				if (check.Measure != PreAllocationCheck.Measures.Dimensions)
				{
					check.Action = PreAllocationCheck.Actions.Warning;
					check.Percentage = 50m;
				}
			}
			ForwardingConfigurationRegistry.Instance.ConsolPreAllocationCheck.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, preAllocationChecks);

			shipmentLoadedInAnotherFactory.JS_ActualVolume = 70;
			anotherFactory.Save();

			AssertConsolPreAllocatedAmountExceededEvent(consol, true);
			AssertConsolPreAllocatedAmountExceededEvent(anotherConsol, true);

			shipmentLoadedInAnotherFactory.JS_ActualVolume = 10;
			shipmentLoadedInAnotherFactory.JS_ActualWeight = 10;
			anotherFactory.Save();

			AssertConsolPreAllocatedAmountExceededEvent(consol, false);
			AssertConsolPreAllocatedAmountExceededEvent(anotherConsol, false);
		}

		void AssertConsolPreAllocatedAmountExceededEvent(ForwardingConsol consol, bool isActive)
		{
			AssertEquals("Event logged", 1, consol.Logs.GetAllLogs().Find(new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.PreAllocatedAmountExceeded.Code)).Length);
			AssertEquals("Event status", !isActive, ((StmALog)consol.Logs.GetAllLogs().Find(new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.PreAllocatedAmountExceeded.Code))[0]).SL_IsCancelled);
		}
