			shipment.JS_IsCFSRegistered = false;
			Factory.Save();

			shipment.JS_OA_ExportReceivingDepot = proxy.MainAddress.PK;
			AssertEquals("The ExportReceivingDepot is a OrgProxy but the shipment was already saved, Should still be CFS Registered", true, shipment.JS_IsCFSRegistered);
		}

