		#region TestRelatedBusinessObjectsAppearForSeaCargo

		public void TestRelatedBusinessObjectsAppearForSeaCargo()
		{
			ForwardingShipment shipment = (ForwardingShipment)GetShipment();
			shipment.Logs.AddNew(Events.Departure);
			int initialLogCount = shipment.Logs.GetAllLogs().Count;
			BusinessObject relatedSeaCargoHouse = (BusinessObject)Factory.New<AU.ICusSCAHouse>();
			relatedSeaCargoHouse[CusSCAHouseSchema.CA_JS.Name] = shipment.PK;
			relatedSeaCargoHouse.GetLogs().AddNew(Events.DeclarationSentToCustoms);
			StmALogCollectionView shipmentLogs = new StmALogCollectionView(shipment);
			int countWithHouse = shipmentLogs.Count;
			Assert("CusSCAHouse Added, should reflect in related Logs", countWithHouse > initialLogCount);
			BusinessObject relatedSeaCargoPivot = (BusinessObject)Factory.New<AU.ICusSCAPivot>();
			relatedSeaCargoPivot[CusSCAPivotSchema.CV_CA.Name] = relatedSeaCargoHouse.PK;
			relatedSeaCargoPivot.GetLogs().AddNew(Events.DeclarationPermitApproved);
			shipmentLogs = new StmALogCollectionView(shipment);
			Assert("CusSCAPivot Added, should appear in logs", shipmentLogs.Count > countWithHouse);
		}

