		#region TestUniqueIndexFailureHandler_WithConsol

		public void TestUniqueIndexFailureHandler_WithConsol()
		{
			TestUniqueIndexFailureHandler_WithConsolCore();
		}

		protected virtual void TestUniqueIndexFailureHandler_WithConsolCore()
		{
			ErrorReporter.Clear();

			bool oldValue = Env.Registry.AllowManualShipmentEntry;
			Env.Registry.AllowManualShipmentEntry = true;
			try
			{
				ForwardingConsol consol1 = Factory.New<ForwardingConsol>();
				ForwardingShipment shipment1 = consol1.Shipments.AddNew();
				shipment1.JS_UniqueConsignRef = "BlahBlahBlah";

				Factory.Save();
				ForwardingConsol consol2 = Factory.New<ForwardingConsol>();
				consol2.IsRoot = true;

				ForwardingShipment shipment2 = consol2.Shipments.AddNew();

				shipment2.RunPreSaveValidation();
				shipment2.JS_UniqueConsignRef = shipment1.JS_UniqueConsignRef;
				shipment2.JS_UniqueConsignRefInfo.ClearAllNotifications();
				AssertNoNotifications("precondition: should not have errors yet", shipment2.JS_UniqueConsignRefInfo);

				bool saveFailed = false;
				try
				{
					Factory.Save();
				}
				catch (Exception ex)
				{
					saveFailed = true;
					AssertEquals("should not have changed the shipment number", shipment1.JS_UniqueConsignRef, shipment2.JS_UniqueConsignRef);
					ZExceptionReporting.HandleSaveException(ex);
					AssertHasError("should now have an error", shipment2.JS_UniqueConsignRefInfo, "Another Shipment with this number already exists. Please change the number.");
				}

				Assert("Save should have failed", saveFailed);
			}
			finally
			{
				Env.Registry.AllowManualShipmentEntry = oldValue;
				ErrorReporter.Clear();
			}
		}

		#endregion

