		protected virtual void TestUniqueIndexFailureHandler_WithoutConsolCore()
		{
			ErrorReporter.Clear();

			bool oldValue = Env.Registry.AllowManualShipmentEntry;
			Env.Registry.AllowManualShipmentEntry = true;
			try
			{
				ForwardingShipment shipment1 = Factory.New<ForwardingShipment>();
				shipment1.JS_UniqueConsignRef = "BlahBlahBlah";

				Factory.Save();
				ForwardingShipment shipment2 = Factory.New<ForwardingShipment>();

				shipment2.RunPreSaveValidation();
				shipment2.JS_UniqueConsignRef = shipment1.JS_UniqueConsignRef;
				shipment2.JS_UniqueConsignRefInfo.ClearAllNotifications();
				AssertNoNotifications("precondition: should not have errors yet", shipment2.JS_UniqueConsignRefInfo);

				bool saveFailed = false;
				try
				{
					Factory.Save();
				}
				catch (Exception ex)
				{
					saveFailed = true;
					AssertEquals("should not have changed the shipment number", shipment1.JS_UniqueConsignRef, shipment2.JS_UniqueConsignRef);
					UnitTestUserNotification.Instance.ClearMessagesAndAnswers();
					ZExceptionReporting.HandleSaveException(ex);
					AssertEquals("should have shown an error", true, UnitTestUserNotification.Instance.LastMessage.WasError);
					AssertEquals("The shipment number 'BlahBlahBlah' is already in use; please enter a unique shipment number and try again.", UnitTestUserNotification.Instance.LastMessage.Text);
				}

				Assert("Save should have failed", saveFailed);
			}
			finally
			{
				Env.Registry.AllowManualShipmentEntry = oldValue;
				ErrorReporter.Clear();
			}
		}

