		#region TestGoodsAndInsuranceDependences

		public void TestInsuranceValueDefaulting_True()
		{
			using (FreightDataRegistry.Instance.InsuranceValueDefaulting.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();

				shipment.JS_GoodsValue = 500;
				shipment.JS_RX_NKGoodsValueCurr = "USD";
				AssertEquals(shipment.JS_GoodsValue, shipment.JS_InsuranceValue);
				AssertEquals(shipment.JS_RX_NKGoodsValueCurr, shipment.JS_RX_NKInsuranceCurrency);

				shipment.JS_InsuranceValue = 69;
				shipment.JS_RX_NKInsuranceCurrency = "AUD";
				shipment.JS_GoodsValue = 600;
				shipment.JS_RX_NKGoodsValueCurr = "EUR";
				AssertNotEquals(shipment.JS_GoodsValue, shipment.JS_InsuranceValue);
				AssertNotEquals(shipment.JS_RX_NKGoodsValueCurr, shipment.JS_RX_NKInsuranceCurrency);
			}
		}

		public void TestInsuranceValueDefaulting_False()
		{
			using (FreightDataRegistry.Instance.InsuranceValueDefaulting.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
			{
				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
				shipment.JS_GoodsValue = 500;
				shipment.JS_RX_NKGoodsValueCurr = "USD";

				shipment.JS_RX_NKInsuranceCurrency = ZString.Empty;
				shipment.JS_InsuranceValue = 100;
				AssertEquals("When insurance currency is empty, setting insurance value should default insurance value currency to goods value currency.", shipment.JS_RX_NKGoodsValueCurr, shipment.JS_RX_NKInsuranceCurrency);

				shipment.JS_GoodsValue = 400;
				shipment.JS_RX_NKGoodsValueCurr = "AUD";
				AssertNotEquals("When Insurance Value Defaulting is set to no, changes to goods value should not affect insurance value.", shipment.JS_GoodsValue, shipment.JS_InsuranceValue);
				AssertNotEquals("When Insurance Value Defaulting it set to no, changes to goods value currency should not affect insurance value currency.", shipment.JS_RX_NKGoodsValueCurr, shipment.JS_RX_NKInsuranceCurrency);
			}
		}

