		public void TestIsPPQFormCompatibleUsedByDocumentMenuFilter()
		{
			var company = Factory.New<GlbCompany>();
			company.GC_RN_NKCountryCode = "US";
			company.GC_Code = "~US";
			var branch = company.Branches.AddNew();
			branch.GB_Code = "~US";
			Factory.Save();

			using (DisposableEnvironment.ForBranch(branch.PK.ToGuid()))
			{
				var shipment = (ForwardingShipment)GetShipment();
				shipment.JS_HouseBill = "BILL1";

				Assert(!shipment.IsPPQForm368Box13Compatible);

				var declaration = (BusinessObject)Factory.New<IBaseJobDeclaration>();
				declaration[JobDeclarationSchema.JE_JS] = shipment.PK;
				declaration[JobDeclarationSchema.JE_GB] = branch.PK;
				Assert(!shipment.IsPPQForm368Box13Compatible);

				declaration["US_PPQForm368Box13A"] = "Test";
				AssertEquals("PreCondition", declaration, shipment.DeclarationForDocuments);

				Assert(new ZBool(declaration["IsPPQForm368Box13Compatible"]));
				Assert(shipment.IsPPQForm368Box13Compatible);
			}
		}

