		#region TestTransportsinLegOrder

		public void TestTransportsInLegOrder()
		{
			ForwardingShipment testShipment = (ForwardingShipment)GetShipment();

			testShipment.JS_TransportMode = "SEA";
			testShipment.JS_HouseBill = "TESTHBL";

			ForwardingConsol testConsol = Factory.New<ForwardingConsol>();
			AssertNotNull("The consol must contain one default transport.", testConsol.Transports.Count);

			Transport testTransport1 = testConsol.Transports[0];

			testTransport1.JW_LegOrder = 1;
			testTransport1.JW_TransportMode = "SEA";
			testTransport1.JW_TransportType = "MAI";
			testTransport1.JW_Vessel = "Test vessel";
			testTransport1.JW_VoyageFlight = "VFTEST";
			testTransport1.JW_RL_NKLoadPort = "AUSYD";
			testTransport1.JW_RL_NKDiscPort = "PHMNL";
			testTransport1.JW_ETD = new DateTime(2006, 7, 31);
			testTransport1.JW_ETA = new DateTime(2006, 8, 2);

			Transport testTransport2 = testConsol.Transports.AddNew();
			testTransport2.JW_LegOrder = 2;
			testTransport2.JW_TransportMode = "SEA";
			testTransport2.JW_TransportType = "MAI";
			testTransport2.JW_Vessel = "Test vessel 2";
			testTransport2.JW_VoyageFlight = "VFTEST2";
			testTransport2.JW_RL_NKLoadPort = "PHMNL";
			testTransport2.JW_RL_NKDiscPort = "HKHKG";
			testTransport2.JW_ETD = new DateTime(2006, 8, 4);
			testTransport2.JW_ETA = new DateTime(2006, 8, 5);

			testShipment.Consols.Add(testConsol);

			AssertEquals("The attached consol be be present on the shipment.", 1, testShipment.Consols.Count);
			AssertEquals("The attached transports must be present on the consol.", 2, testConsol.Transports.Count);

			ForwardingTransportCollection transports = testShipment.TransportsInLegOrder;

			AssertEquals(2, transports.Count);

			AssertEquals("Transport1 should be the first element", testTransport1, transports[0]);
			AssertEquals("Transport2 should be the second element", testTransport2, transports[1]);
		}

