		#region TestEntryNumberAndEntryNumberTypeReadOnly

		public void TestEntryNumberAndEntryNumberTypeReadOnly()
		{
			string originalCountryCode = GlbCompany.CurrentCompany.GC_RN_NKCountryCode;
			try
			{
				ForwardingShipment shipment = base.Factory.New<ForwardingShipment>();
				CusEntryNumber cusEntryNumber = shipment.CusEntryNumbers.AddNew();
				cusEntryNumber.CE_EntryIsSystemGenerated = false;
				AssertEquals("Sanity check", 1, shipment.CusEntryNumbers.Count);
				Assert("Pre-condition", !shipment.CustomsEntryNumberInfo.ReadOnly);
				Assert("Pre-condition", !shipment.CustomsEntryNumberTypeInfo.ReadOnly);
				GlbCompany.CurrentCompany.SetCountry("SG");
				AssertEquals("Should always be read-only for SG", false, shipment.CustomsEntryNumberInfo.ReadOnly);
				AssertEquals("Should always be read-only for SG", false, shipment.CustomsEntryNumberTypeInfo.ReadOnly);
			}
			finally
			{
				GlbCompany.CurrentCompany.SetCountry(originalCountryCode);
