		public void TestKnownShipperForExport()
		{
			var expectedConsignorError = "This Consignor is not Approved so an Inspection Type of Approved/Known Shipper is not allowed.";
			var expectedNoInspectionTypeError = "Please enter an Aviation Security Inspection.";

			var shipment = (ForwardingShipment)GetShipment();
			GlbCompany.CurrentCompany.SetCountry("JM");
			shipment.JS_TransportMode = "AIR";

			shipment.JS_RL_NKOrigin = "JMKIN";
			shipment.JS_RL_NKDestination = "JMAPP";
			shipment.JS_InspectionTypeCode = "APP";
			AssertHasError(shipment.JS_InspectionTypeCodeInfo, expectedConsignorError);
			AssertEquals("No recalculation message as Inspection Type has been manually set", ZString.Empty, shipment.MostRecentInspectionTypeChangeReason);

			shipment.JS_RL_NKOrigin = "JMALP";
			shipment.JS_RL_NKDestination = "AGBBQ";
			shipment.JS_InspectionTypeCode = "APP";
			AssertHasError(shipment.JS_InspectionTypeCodeInfo, expectedConsignorError);

			shipment.JS_RL_NKOrigin = "AGBBQ";
			shipment.JS_RL_NKDestination = "JMKIN";
			shipment.JS_InspectionTypeCode = "APP";
			AssertNoErrors(shipment.JS_InspectionTypeCodeInfo);

			shipment.JS_RL_NKOrigin = "JMALP";
			shipment.JS_RL_NKDestination = "JMKIN";
			shipment.JS_InspectionTypeCode = "";
			AssertHasError(shipment.JS_InspectionTypeCodeInfo, expectedNoInspectionTypeError);
			AssertEquals("No recalculation message as Inspection Type has been manually set", ZString.Empty, shipment.MostRecentInspectionTypeChangeReason);

			shipment.JS_RL_NKOrigin = "JMKIN";
			shipment.JS_RL_NKDestination = "AGBBQ";
			shipment.JS_InspectionTypeCode = "";
			AssertHasError(shipment.JS_InspectionTypeCodeInfo, expectedNoInspectionTypeError);

			shipment.JS_RL_NKOrigin = "AGBBQ";
			shipment.JS_RL_NKDestination = "JMALP";
			shipment.JS_InspectionTypeCode = "";
			AssertNoErrors(shipment.JS_InspectionTypeCodeInfo);
			AssertEquals("No recalculation message as Inspection Type has been manually set", ZString.Empty, shipment.MostRecentInspectionTypeChangeReason);

			shipment.JS_RL_NKOrigin = "AGBBQ";
			shipment.JS_RL_NKDestination = "JMKIN";
			shipment.JS_InspectionTypeCode = "APP";

			using (GlbCompany.CurrentCompany.TemporarilySetCountry("AG"))
			{
				shipment.JS_RL_NKOrigin = "AGFAM";
				AssertNoErrors(shipment.JS_InspectionTypeCodeInfo);
			}

			shipment.JS_InspectionTypeCode = FreightDataRegistry.AviationSecurity_Unknown_Code;
			shipment.Validation.ValidateJS_InspectionTypeCode();
			AssertNoErrors("No validation for Import", shipment.JS_InspectionTypeCodeInfo);
		}

		public void TestKnownShipperDefaulted_UsesConsignorOrLocalClient()
		{
			GlbCompany.CurrentCompany.SetCountry("JM");

			FreightDataRegistry.Instance.ShipmentInspectionTypeDefault.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, ZString.Empty);
			FreightDataRegistry.Instance.ShipmentInspectionOrganisationToUse.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, SupplyChainSecurityOrganisationTypes.Consignor);

			var consignor = Factory.NewWithValidTestData<OrgHeader>();
			consignor.CountryData.OV_EXApprovedOrMajorExporter = AviationSecuritySchemeMembershipEx.Codes.Yes;

			var client = Factory.NewWithValidTestData<OrgHeader>();
			client.CountryData.OV_EXApprovedOrMajorExporter = AviationSecuritySchemeMembershipEx.Codes.Yes;

			var shipment = CreateShipmentWithJob("JMKIN");

			shipment.ShipmentJobHeader.JH_OA_LocalChargesAddr = client.MainAddress.PK;
			AssertEquals(ZString.Empty, shipment.JS_InspectionTypeCode);

			shipment.ConsignorDocumentaryAddress.E2_OA_Address = consignor.MainAddress.PK;
			AssertEquals(BaseJobShipmentLookups.InspectionType_Approved, shipment.JS_InspectionTypeCode);

			shipment.JS_InspectionTypeCode = ZString.Empty;
			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			AssertEquals(ZString.Empty, shipment.JS_InspectionTypeCode);

			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
			AssertEquals(BaseJobShipmentLookups.InspectionType_Approved, shipment.JS_InspectionTypeCode);

			FreightDataRegistry.Instance.ShipmentInspectionOrganisationToUse.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, SupplyChainSecurityOrganisationTypes.LocalClient);

			var shipment2 = CreateShipmentWithJob("JMKIN");

			shipment2.ConsignorDocumentaryAddress.E2_OA_Address = consignor.MainAddress.PK;
			shipment2.ShipmentJobHeader.JH_OA_LocalChargesAddr = ZGuid.Empty;
			AssertEquals(ZString.Empty, shipment2.JS_InspectionTypeCode);

			shipment2.ShipmentJobHeader.JH_OA_LocalChargesAddr = client.MainAddress.PK;
			AssertEquals(BaseJobShipmentLookups.InspectionType_Approved, shipment2.JS_InspectionTypeCode);

			shipment2.JS_InspectionTypeCode = ZString.Empty;
			shipment2.JS_TransportMode = Core.Constants.TransportModes.Sea;
			AssertEquals(ZString.Empty, shipment2.JS_InspectionTypeCode);

			shipment2.JS_TransportMode = Core.Constants.TransportModes.Air;
			AssertEquals(BaseJobShipmentLookups.InspectionType_Approved, shipment2.JS_InspectionTypeCode);
		}

		public void TestKnownShipperDefaulted_UsesShipmentPickupFrom()
		{
			var collection = new SupplyChainSecurityOrganisationToUseCollection
			{
				{
					SupplyChainSecurityOrganisationTypes.ShipmentPickupFrom,
					SupplyChainSecurityOrganisationTypes.GetDescription(SupplyChainSecurityOrganisationTypes.ShipmentPickupFrom),
					SupplyChainSecurityOrganisationToUse.ValidationCodes.Yes
				}
			};

			using (GlbCompany.CurrentCompany.TemporarilySetCountry("FR"))
