		public void TestKnownShipper_ResetOnJobLocalClientChange()
		{
			FreightDataRegistry.Instance.ShipmentInspectionOrganisationToUse.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, SupplyChainSecurityOrganisationTypes.LocalClient);

			var client = Factory.NewWithValidTestData<OrgHeader>();
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
			shipment.JS_RL_NKOrigin = "AUBNE";

			var job = new JobHeader.Loader(shipment).TryCreate();
			shipment.ShipmentJobHeader.JH_OA_LocalChargesAddr = client.MainAddress.PK;

			shipment.JS_InspectionTypeCode = "HAN";
			shipment.ShipmentJobHeader.JH_OA_LocalChargesAddrInfo.RefreshBinding(); // causes a ValueChanged even though the value has not really changed
			AssertEquals("HAN", shipment.JS_InspectionTypeCode);

			shipment.ConsignorDocumentaryAddress.E2_OA_Address = client.MainAddress.PK;
			AssertEquals("Should not change as Reg set to LOCAL CLIENT, not Consignor", "HAN", shipment.JS_InspectionTypeCode);

			FreightDataRegistry.Instance.ShipmentInspectionOrganisationToUse.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, SupplyChainSecurityOrganisationTypes.Consignor);
			shipment.ShipmentJobHeader.JH_OA_LocalChargesAddr = ZGuid.Empty;
			AssertEquals("Should not change as Reg set to CONSIGNOR, not Local Client", "HAN", shipment.JS_InspectionTypeCode);
		}

