				OrgCountryData data = consignor.MainAddress.KnownShipperDetails.AddNew();
				data.OV_EXApprovedOrMajorExporter = AviationSecuritySchemeMembership.Codes.KnownConsignor;
				data.OV_EXApprovalExpiryDate = ZDate.Today.AddDays(1);

				OrgAddress consignorAddress2 = consignor.Addresses.AddNew();
				data = consignorAddress2.KnownShipperDetails.AddNew();
				data.OV_EXApprovedOrMajorExporter = AviationSecuritySchemeMembershipEx.Codes.No;

				OrgAddress consignorAddress3 = consignor.Addresses.AddNew();
				data = consignorAddress3.KnownShipperDetails.AddNew();
				data.OV_EXApprovedOrMajorExporter = AviationSecuritySchemeMembership.Codes.KnownConsignor;
				data.OV_EXApprovalExpiryDate = ZDate.Today.AddDays(-1);

				ForwardingShipment shipment = Factory.New<ForwardingShipment>();
				shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
				shipment.JS_RL_NKOrigin = "JPOSA";
				shipment.JS_E_DEP = ZDateTime.Today;
				shipment.ConsignorDocumentaryAddress.E2_OA_Address = consignor.MainAddress.PK;
