				shipment.ConsignorDocumentaryAddress.E2_OA_Address = consignorAddress3.PK;
				AssertEquals("Approval has expired", "UNK", shipment.JS_InspectionTypeCode);

				shipment.ConsignorDocumentaryAddress.E2_OA_Address = consignor.MainAddress.PK;
