		public void TestJS_InspectionTypeCode_ReadOnlyWithAccessControl()
		{
			bool isAllowed = Env.Security.MaintainShipmentAllowToOverrideInspection.IsAllowed;
			try
			{
				ForwardingShipment shipment = (ForwardingShipment)GetShipment();
				shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
				shipment.JS_RL_NKDestination = OverseasPort;
				shipment.JS_RL_NKOrigin = HomePort;

				Env.Security.MaintainShipmentAllowToOverrideInspection.IsAllowed = true;
				shipment.JS_ShipmentType = Constants.ShipmentTypes.StandardHouse;
				AssertEquals("Allow to Override Inspection set to true, shouldn't be readonly", false, shipment.JS_InspectionTypeCodeInfo.ReadOnly);

				Env.Security.MaintainShipmentAllowToOverrideInspection.IsAllowed = false;
				shipment.JS_ShipmentType = Constants.ShipmentTypes.StandardHouse;
				AssertEquals("Allow to Override Inspection set to false, should be readonly", true, shipment.JS_InspectionTypeCodeInfo.ReadOnly);
			}
			finally
			{
				Env.Security.MaintainShipmentAllowToOverrideInspection.IsAllowed = isAllowed;
			}
		}

		public void TestHasUserSelectedUnknownInspectionType()
		{
			var ra = GlbCompany.CurrentCompany.OrgProxy.MainAddress.KnownShipperDetails.AddNew();
			ra.OV_OH_OrgHeader = GlbCompany.CurrentCompany.OrgProxy.PK;
			ra.OV_RN_NKClientCountryRelation = "AU";
			ra.OV_EXApprovedOrMajorExporter = "RA";
			ra.OV_EXApprovalNumber = "99299";
			ra.OV_EXApprovalExpiryDate = ZDate.Today.AddDays(10);

			var shipment1 = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment1.JS_TransportMode = "AIR";
			shipment1.JS_RL_NKOrigin = "AUBNE";
			shipment1.JS_RL_NKLoadPort = "AUBNE";
			shipment1.JS_RL_NKDischargePort = "HKHKG";

			var shipment2 = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment2.JS_TransportMode = "AIR";
			shipment2.JS_RL_NKOrigin = "AUBNE";
			shipment2.JS_RL_NKLoadPort = "AUBNE";
			shipment2.JS_RL_NKDischargePort = "HKHKG";

			var shipment3 = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment3.JS_TransportMode = "AIR";
			shipment3.JS_RL_NKOrigin = "AUBNE";
			shipment3.JS_RL_NKLoadPort = "AUBNE";
			shipment3.JS_RL_NKDischargePort = "HKHKG";

			AssertEquals("Precondition: shipment1 is UNK", "UNK", shipment1.JS_InspectionTypeCode);
			Assert("Shipment1: UNK is not user selected", !shipment1.HasUserSelectedUnknownInspectionType);

			AssertEquals("Precondition: shipment2 is UNK", "UNK", shipment2.JS_InspectionTypeCode);
			Assert("Shipment2: UNK is not user selected", !shipment2.HasUserSelectedUnknownInspectionType);

			AssertEquals("Precondition: shipment3 is UNK", "UNK", shipment3.JS_InspectionTypeCode);
			Assert("Shipment3: UNK is not user selected", !shipment3.HasUserSelectedUnknownInspectionType);

			var consignor = Factory.NewWithValidTestData<OrgHeader>();
			consignor.OH_RL_NKClosestPort = "AUBNE";
			consignor.MainAddress.OA_RN_NKCountryCode = "AU";
			consignor.MainAddress.OA_RL_NKRelatedPortCode = "AUBNE";

			var approval = consignor.MainAddress.KnownShipperDetails.AddNew();
			approval.OV_OH_OrgHeader = consignor.PK;
			approval.OV_RN_NKClientCountryRelation = "AU";
			approval.OV_EXApprovedOrMajorExporter = "KC";
			approval.OV_EXApprovalNumber = "12345";
			approval.OV_EXApprovalExpiryDate = ZDate.Today.AddDays(1);

			shipment1.ConsignorDocumentaryAddress.E2_OA_Address = consignor.MainAddress.PK;

			AssertEquals("Inspection type has been calculated as APP", "APP", shipment1.JS_InspectionTypeCode);
			Assert("APP is not UNK", !shipment1.HasUserSelectedUnknownInspectionType);
			AssertEquals("Recalculation message as Inspection Type has been automatically calculated", "Consignor has been changed", shipment1.MostRecentInspectionTypeChangeReason);

			shipment1.JS_InspectionTypeCode = "UNK";

			Assert("Now shipment1 has user selected UNK Inspection Type", shipment1.HasUserSelectedUnknownInspectionType);
			AssertEquals("No recalculation message as Inspection Type has been manually set", "", shipment1.MostRecentInspectionTypeChangeReason);

			shipment2.ConsignorDocumentaryAddress.E2_OA_Address = consignor.MainAddress.PK;

			AssertEquals("Inspection type has been calculated as APP", "APP", shipment2.JS_InspectionTypeCode);
			Assert("APP is not UNK", !shipment2.HasUserSelectedUnknownInspectionType);
			AssertEquals("Recalculation message as Inspection Type has been automatically calculated", "Consignor has been changed", shipment2.MostRecentInspectionTypeChangeReason);

			Factory.Save();

			shipment2.ConsignorDocumentaryAddress.E2_OA_Address = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;

			AssertEquals("Inspection type has been calculated as UNK", "UNK", shipment2.JS_InspectionTypeCode);
			Assert("UNK has not been user selected", !shipment2.HasUserSelectedUnknownInspectionType);
			AssertEquals("Recalculation message as Inspection Type has been automatically calculated", "Consignor has been changed", shipment2.MostRecentInspectionTypeChangeReason);

			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var reloadedShipment1 = newFactory.Load<ForwardingShipment>(shipment1.PK);
			var reloadedShipment2 = newFactory.Load<ForwardingShipment>(shipment2.PK);
			var reloadedShipment3 = newFactory.Load<ForwardingShipment>(shipment3.PK);

			AssertEquals("Reloaded shipment1 is UNK", "UNK", reloadedShipment1.JS_InspectionTypeCode);
			Assert("Reloaded shipment1 has user selected UNK inspection type", reloadedShipment1.HasUserSelectedUnknownInspectionType);

			AssertEquals("Reloaded shipment2 is UNK", "UNK", reloadedShipment2.JS_InspectionTypeCode);
			Assert("Reloaded shipment2 doesn't have user selected UNK inspection type", !reloadedShipment2.HasUserSelectedUnknownInspectionType);

			AssertEquals("Reloaded shipment3 is UNK", "UNK", reloadedShipment3.JS_InspectionTypeCode);
			Assert("Reloaded shipment3 doesn't have user selected UNK inspection type", !reloadedShipment3.HasUserSelectedUnknownInspectionType);
		}

		public void TestHasUserSelectedUnknownInspectionType_IgnoresIrrelevantLogs()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_TransportMode = "AIR";
			shipment.JS_RL_NKLoadPort = "AUBNE";
			shipment.JS_RL_NKDischargePort = "HKHKG";

			Assert("Precondition", !shipment.HasUserSelectedUnknownInspectionType);

			AddLog("|NEW=UNK|OLD=EDD|RES=Compromised|TYP=High Risk", false);
			Assert("High risk log is ignored", !shipment.HasUserSelectedUnknownInspectionType);

			AddLog("Propagated: All Shipments|NEW=UNK|OLD=EDD|RES=Compromised", false);
			Assert("Propagated log is ignored", !shipment.HasUserSelectedUnknownInspectionType);

			AddLog("|NEW=UNK|OLD=EDD|RES=Compromised", true);
			Assert("Cancelled log is ignored", !shipment.HasUserSelectedUnknownInspectionType);

			AddLog("|NEW=UNK|OLD=EDD|RES=Compromised", false);
			Assert("Valid log", shipment.HasUserSelectedUnknownInspectionType);

			void AddLog(string reference, bool isCancelled)
			{
				var log = shipment.Logs.CreateRecreateOrUpdateEventLog(Events.SecurityModified, EstimateActual.Actual, ZDateTimeOffset.Now, reference);

				if (log != null && isCancelled)
				{
					log.Cancel();
				}
			}
		}

