		public void TestTriggerAutomaticDeliveryDueDateCalculationForDOOR_X()
		{
			var newDeliveryDueDate = new ZDateTime(2022, 10, 04, 09, 30, 0);
			var deliveryDueDateCalculatorManagerMock = DeliveryDueDateCalculationTestHelper.SetupDeliveryDueDateCalculatorManagerMock(newDeliveryDueDate);

			using (FreightDataRegistry.Instance.CalculateDeliveryDueDateByTransportMode.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new CalculateDeliveryDueDateOptions { IsActive = true, TransportModes = ActiveTransportModesForCalculateDeliveryDateOption() }))
			{
				Env.Security.MaintainShipmentDeliveryDueDateOverride.IsAllowed = true;
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_TransportMode = Core.Constants.TransportModes.Air;

				var consignor = Factory.NewWithValidTestData<OrgHeader>();
				var consignee = Factory.NewWithValidTestData<OrgHeader>();
				var pickupCFS = Factory.NewWithValidTestData<OrgHeader>();
				var deliveryCFS = Factory.NewWithValidTestData<OrgHeader>();

				shipment.ConsignorDocumentaryAddress.OrganisationPK = consignor.PK;
				shipment.ConsigneeDocumentaryAddress.OrganisationPK = consignee.PK;
				shipment.JS_OA_ExportReceivingDepot = pickupCFS.MainAddress.PK;
				shipment.JS_OA_ImportReleaseDepot = deliveryCFS.MainAddress.PK;

				shipment.JS_HBLContainerPackModeOverride = Core.Constants.HBLDeliveryModes.Codes.DOOR_DOOR;
				shipment.JS_RS_NKServiceLevel = "STD";
				AssertTestCase();

				shipment.JS_HBLContainerPackModeOverride = Core.Constants.HBLDeliveryModes.Codes.DOOR_CFS;
				shipment.DocsAndCartage.JP_PickupRequiredBy = ZDateTime.Empty;
				AssertTestCase();

				shipment.JS_HBLContainerPackModeOverride = Core.Constants.HBLDeliveryModes.Codes.DOOR_DOOR;
				shipment.DocsAndCartage.JP_PickupRequiredBy = ZDateTime.Empty;
				var deliveryAgent = Factory.NewWithValidTestData<OrgHeader>();
				shipment.JS_OH_DeliveryAgent = deliveryAgent.PK;
				shipment.JS_OA_ImportReleaseDepot = ZGuid.Empty;
				AssertTestCase();

				void AssertTestCase()
				{
					shipment.JS_DeliveryDueDate = ZDateTime.Empty;
					deliveryDueDateCalculatorManagerMock.Invocations.Clear();
					AssertEquals("Pre-condition: Delivery Due Date is empty", ZDateTime.Empty, shipment.JS_DeliveryDueDate);
					deliveryDueDateCalculatorManagerMock.Verify(manager => manager.Calculate(It.IsAny<ForwardingShipment>()), Times.Never, "Pre-condition: Automatic Delivery Due Date Calculation has not been triggered");

					shipment.DocsAndCartage.JP_PickupCartageCompleted = ZDateTime.Now;
					deliveryDueDateCalculatorManagerMock.Verify(manager => manager.Calculate(It.IsAny<ForwardingShipment>()), Times.Once, "Automatic Delivery Due Date Calculation is triggered, when all factors are provided");
					AssertEquals("Delivery Due Date is auto-calculated", newDeliveryDueDate, shipment.JS_DeliveryDueDate);

					shipment.JS_DeliveryDueDate = ZDateTime.Empty;
					deliveryDueDateCalculatorManagerMock.Invocations.Clear();
					shipment.DocsAndCartage.JP_PickupCartageCompleted = ZDateTime.Empty;
					deliveryDueDateCalculatorManagerMock.Verify(manager => manager.Calculate(It.IsAny<ForwardingShipment>()), Times.Never, "Pre-condition: Automatic Delivery Due Date Calculation has not been triggered");

					shipment.DocsAndCartage.JP_PickupRequiredBy = ZDateTime.Now;
					deliveryDueDateCalculatorManagerMock.Verify(manager => manager.Calculate(It.IsAny<ForwardingShipment>()), Times.Once, "Automatic Delivery Due Date Calculation is triggered, when all factors are provided");
					AssertEquals("Delivery Due Date is auto-calculated", newDeliveryDueDate, shipment.JS_DeliveryDueDate);
				}
			}
		}

