			var newDeliveryDueDate = new ZDateTime(2022, 10, 04, 09, 30, 0);
			DeliveryDueDateCalculationTestHelper.SetupDeliveryDueDateCalculatorManagerMock(newDeliveryDueDate);
			using (FreightDataRegistry.Instance.CalculateDeliveryDueDateByTransportMode.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new CalculateDeliveryDueDateOptions { IsActive = true, TransportModes = ActiveTransportModesForCalculateDeliveryDateOption() }))
			{
				Env.Security.MaintainShipmentDeliveryDueDateOverride.IsAllowed = true;
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
				shipment.JS_IsForwardRegistered = false;
				AssertEquals("Pre-condition: Delivery Due Date is empty", ZDateTime.Empty, shipment.JS_DeliveryDueDate);

				shipment.CalculateDeliveryDueDate(ForwardingShipment.DeliveryDueDateCalculationMode.Automatic);
				AssertEquals("Delivery Due Date is auto-calculated", newDeliveryDueDate, shipment.JS_DeliveryDueDate);
				AssertEquals("DDE event will not be logged until shipment is saved, DDE event count = 0", 0, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.DeliveryDateUpdatedCode).Count());
				AssertEquals("RDD event will not be logged until shipment is saved, RDD event count = 0", 0, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.CalculateDeliveryDateWithExceptionsRequestedCode).Count());

				Factory.Save();
				AssertEquals("DDE event is logged, DDE event count = 1", 1, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.DeliveryDateUpdatedCode).Count());
				AssertEquals("RDD event is logged, RDD event count = 0", 0, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.CalculateDeliveryDateWithExceptionsRequestedCode).Count());
				var ddeEvent = shipment.Logs.MostRecentLogByEventTime(Events.DeliveryDateUpdated);
				AssertNotNull(ddeEvent);
				AssertEquals("|ACT=Automatic|NEW=04-Oct-22 09:30|RES=Automatically calculated for new shipment|TYP=Original", ddeEvent.SL_Reference);

				var rddEvent = shipment.Logs.MostRecentLogByEventTime(Events.CalculateDeliveryDateWithExceptionsRequested);
				AssertNull(rddEvent);

				shipment.GetReasonForChangingDeliveryDueDateEventHandler += (sender, arg) => arg.Reason = "I want to override";
				shipment.JS_DeliveryDueDate = newDeliveryDueDate.AddDays(2);
				Factory.Save();
				AssertEquals("Delivery Due Date is overriden", new ZDateTime(2022, 10, 06, 09, 30, 0), shipment.JS_DeliveryDueDate);
				AssertEquals("New DDE event is logged, DDE event count = 2", 2, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.DeliveryDateUpdatedCode).Count());
				AssertEquals("New RDD event is logged, RDD event count = 0", 0, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.CalculateDeliveryDateWithExceptionsRequestedCode).Count());
				ddeEvent = shipment.Logs.MostRecentLogByEventTime(Events.DeliveryDateUpdated);
				AssertNotNull(ddeEvent);
				AssertEquals("|ACT=Override|NEW=06-Oct-22 09:30|OLD=04-Oct-22 09:30|RES=I want to override|TYP=Original", ddeEvent.SL_Reference);

				rddEvent = shipment.Logs.MostRecentLogByEventTime(Events.CalculateDeliveryDateWithExceptionsRequested);
				AssertNull(rddEvent);
			}
		}

