		public void TestGetCalculatedDeliveryDueDateWithExceptions_UpdatesNote()
		{
			var newDeliveryDueDate = new ZDateTime(2022, 10, 04, 09, 30, 0);
			using (FreightDataRegistry.Instance.CalculateDeliveryDueDateByTransportMode.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new CalculateDeliveryDueDateOptions { IsActive = true, TransportModes = ActiveTransportModesForCalculateDeliveryDateOption() }))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
				reasonForChangeDeliveryDueDate = "For Test";
				shipment.GetReasonForChangingDeliveryDueDateEventHandler += Shipment_GetReasonForChangingDeliveryDueDateEventHandler;
				shipment.JS_DeliveryDueDate = newDeliveryDueDate;
				var cfsOrg = Factory.NewWithValidTestData<OrgHeader>();
				var address = cfsOrg.Addresses.AddNew();
				address.OA_Address1 = "357/3 Bindon Place";
				shipment.JS_OA_ImportReleaseDepot = address.PK;

				var exception = shipment.WorkflowItems.Exceptions.AddNew();
				exception.P9_TaskID = "T001";
				exception.P9_ActualDateOffset = ZDateTimeOffset.Now.AddDays(-3);
				exception.P9_ExceptionDurationHours = 20;

				Factory.Save();

				var statusChangeContext = shipment as IRegisterStatusChangeContext;
				var stmAlog = Factory.New<StmALog>();
				using (stmAlog.LockForUpdatingKeyFieldsForTesting())
				{
					stmAlog.SL_Parent = shipment.PK;
					stmAlog.SL_Table = CommonShipment.Schema.TableName;
					stmAlog.SL_SE_NKEvent = Events.CalculateDeliveryDateWithExceptionsRequestedCode;
					stmAlog.SL_Reference = "123";
				}
				statusChangeContext.TemporarilySetStatusChangedByTriggerEvent(stmAlog);

				var revisedDeliveryDueDate = shipment.GetCalculatedDeliveryDueDateWithExceptions;
				var deliveryDueDateNoteText = shipment.Notes.FindByDescription(PredefinedNoteTypes.Instance.DeliveryDueDateCalculationLog.Description).FirstOrDefault().ST_NoteText;
				Assert("Note should contain date", deliveryDueDateNoteText.Contains("Date:"));
				Assert("Note should contain user", deliveryDueDateNoteText.Contains($"[User: {Env.CurrentUser.FullName}]"));
				Assert("Note should contain company", deliveryDueDateNoteText.Contains($"[Company: {Env.CurrentCompany.Name}]"));
				Assert("Note should contain branch", deliveryDueDateNoteText.Contains($"[Branch: {Env.CurrentBranch.Name}]"));
				Assert("Note should contain previous value", deliveryDueDateNoteText.Contains("Previous Revised Delivery Due Date: -"));
				Assert("Note should contain calculated value", deliveryDueDateNoteText.Contains("Calculated Revised Delivery Due Date: 05-Oct-22 09:00:00"));
				Assert("Note should contain reason", deliveryDueDateNoteText.Contains("Reason: Event [RDD] triggered a trigger/milestone"));
				Assert("Note should contain exceptions list", deliveryDueDateNoteText.Contains("Calculating Delivery Due Date With Exceptions..."));
				Assert("Note should contain original DDD", deliveryDueDateNoteText.Contains("Original Delivery Due Date: 04-Oct-22 09:30:00"));
				Assert("Note should contain opening hour", deliveryDueDateNoteText.Contains("Finding closest opening hour: 05-Oct-22 05:30:00 adjusted to 05-Oct-22 09:00:00"));
				Assert("Note should contain calculated value", deliveryDueDateNoteText.Contains("Calculated revised delivery due date by applying exception delays and finding closest opening hours: 05-Oct-22 09:00:00"));
			}
		}

