		public void TestJS_DeliveryDueDate_WorkflowFieldChangeEvent()
		{
			WorkflowDescriptors.Instance.TryGetValue("SHP", out var workflowDescriptor);
			var configManager = ObjectFactory.New<IProcessFieldChangeRuleConfigurationManager>();
			var rule = Factory.New<IProcessFieldChangeRule>();
			rule.PFR_ProcessType = workflowDescriptor.Code;
			rule.PFR_GroupName = "Group1";
			rule.PFR_SE_NKEvent = "Z00";
			rule.Fields.AddNew().PFL_FieldName = JobShipmentSchema.Constants.JS_DeliveryDueDate;

			Factory.Save();
			var factory = new BusinessObjectFactory();
			var shipment = factory.New(workflowDescriptor.WorkflowProviderType) as ForwardingShipment;
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
			using (shipment.GetValidationSuspender())
			{
				shipment.GetReasonForChangingDeliveryDueDateEventHandler += (sender, arg) => arg.Reason = "mock reason";

				var val = shipment.GetPropertyValue(JobShipmentSchema.Constants.JS_DeliveryDueDate);
				AssertEquals("Event exists without setting anything JS_DeliveryDueDate for type ForwardingShipment, workflow SHP", 0, shipment.Logs.Find(new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.CustomisableEvent00.Code)).Where(log => !log.IsInDatabase).ToList().Count);

				shipment.SetPropertyValue(JobShipmentSchema.Constants.JS_DeliveryDueDate, ZDateTime.Now);
				AssertEquals("No event for JS_DeliveryDueDate for type ForwardingShipment, workflow SHP", 1, shipment.Logs.Find(new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.CustomisableEvent00.Code)).Where(log => !log.IsInDatabase).ToList().Count);

				shipment.SetPropertyValue(JobShipmentSchema.Constants.JS_DeliveryDueDate, val);
				AssertEquals("Event not cleared for JS_DeliveryDueDate for type ForwardingShipment, workflow SHP", 0, shipment.Logs.Find(new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.CustomisableEvent00.Code)).Where(log => !log.IsInDatabase).ToList().Count);
			}
		}

