					shipment.ConsigneeDocumentaryAddress.OrganisationPK = consignee1.PK;
					shipment.JS_OA_ExportReceivingDepot = pickupCFS1.MainAddress.PK;
					shipment.JS_OA_ImportReleaseDepot = deliveryCFS1.MainAddress.PK;
					shipment.JS_HBLContainerPackModeOverride = Core.Constants.HBLDeliveryModes.Codes.ARPT_ARPT;
					shipment.JS_RS_NKServiceLevel = "SL1";
					shipment.DocsAndCartage.JP_PickupRequiredBy = ZDateTime.Now;
				}

				deliveryDueDateCalculatorManagerMock.Verify(manager => manager.Calculate(It.IsAny<ForwardingShipment>()), Times.Once, "Automatic Delivery Due Date Calculation is triggered, when all factors are provided");
				AssertEquals("Pre-condition: Delivery Due Date is auto-calculated", newDeliveryDueDate, shipment.JS_DeliveryDueDate);
				Factory.Save();

				Transport transport = null;
				ForwardingConsol consol = null;

				var dashboard = new ConsolDashboard(Factory);
				consol = Factory.New<ForwardingConsol>();
				consol.JK_ConsolMode = Constants.ContainerModes.Loose;
				consol.JK_RL_NKLoadPort = "AUMEL";
				consol.JK_RL_NKDischargePort = "NZAKL";
				consol.JK_TransportMode = Constants.TransportModes.Air;
				transport = consol.Transports[0];
				transport.JW_ETA = newDeliveryDueDate.AddDays(1);
				Factory.Save();

				dashboard.AddConsols(new[] { consol });
				dashboard.Shipments.Add(shipment);

				SetupAndAssertOneOrMoreFactorChanges(shipment, (s) =>
				{
					dashboard.TryAttach(consol, new[] { shipment });
				}, newDeliveryDueDate.AddDays(1), "Consol Attached changed", dashboard: dashboard);

				SetupAndAssertOneOrMoreFactorChanges(shipment, (s) =>
				{
					dashboard.TryDetach(consol, new[] { shipment });
				}, newDeliveryDueDate.AddDays(2), "Consol Attached changed", dashboard: dashboard);
			}
		}

		void SetupAndAssertOneOrMoreFactorChanges(ForwardingShipment shipment, Action<ForwardingShipment> change, ZDateTime newDeliveryDueDate, string reason = "", bool recalculationExpected = true, ConsolDashboard dashboard = null)
		{
			var oldDeliveryDueDate = shipment.JS_DeliveryDueDate;
			var deliveryDueDateCalculatorManagerMock = DeliveryDueDateCalculationTestHelper.SetupDeliveryDueDateCalculatorManagerMockWithoutSubstitution(newDeliveryDueDate);
			using (ObjectFactory.Substitute(deliveryDueDateCalculatorManagerMock.Object))
			{
				change.Invoke(shipment);

				if (dashboard != null)
				{
					dashboard.Save();
					shipment = new BusinessObjectFactory().Load<ForwardingShipment>(shipment.PK);
				}
				else
				{
					shipment.Factory.Save();
				}

				if (recalculationExpected)
				{
					deliveryDueDateCalculatorManagerMock.Verify(manager => manager.Calculate(It.IsAny<ForwardingShipment>()), Times.Once, "Factor change triggered Delivery Due Date recalculation");
					CombineAssertions(reason, () =>
					{
						AssertEquals("Delivery Due Date is recalculated", newDeliveryDueDate, shipment.JS_DeliveryDueDate);
						var ddeEvent = shipment.Logs.MostRecentLogByEventTime(Events.DeliveryDateUpdated);
						AssertEquals("DDE is logged", $"|ACT=FactorChanged|NEW={newDeliveryDueDate.ToLongTimeString()}|OLD={oldDeliveryDueDate.ToLongTimeString()}|RES={reason}|TYP=Original", ddeEvent.SL_Reference);

						var rddEvent = shipment.Logs.MostRecentLogByEventTime(Events.CalculateDeliveryDateWithExceptionsRequested);
						AssertEquals("RDD is logged", $"|CHG=Delivery Due Date Changed {oldDeliveryDueDate.ToLongTimeString()} To {newDeliveryDueDate.ToLongTimeString()}", rddEvent.SL_Reference);
					});
				}
				else
				{
					deliveryDueDateCalculatorManagerMock.Verify(manager => manager.Calculate(It.IsAny<ForwardingShipment>()), Times.Never, "Delivery Due Date recalculation should not trigger");
					CombineAssertions(reason, () =>
					{
						AssertEquals("Delivery Due Date remains the same", oldDeliveryDueDate, shipment.JS_DeliveryDueDate);
					});
				}
			}
		}

