		#region Is High Risk

		public void TestRedefaultShipmentIsHighRisk()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry("FR"))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "FRPAR";
				shipment.JS_RL_NKDestination = "CNSHA";
				shipment.JS_TransportMode = "AIR";
				shipment.ReDefaultPackLineIsHighRiskEventHandler += (s, e) => { };
				shipment.JS_IsHighRisk = false;
				AssertEquals(true, shipment.AviationSecurity.SupplyChainSecurityConfiguration.IsHighRiskApplicable);
				var packLine1 = shipment.OuterPackLines.AddNew();
				var packLine2 = shipment.OuterPackLines.AddNew();
				AssertEquals(false, packLine1.JL_IsHighRisk);
				AssertEquals(false, packLine2.JL_IsHighRisk);
				shipment.JS_IsHighRisk = true;
				AssertEquals("Packline Is High Risk is still true", true, packLine1.JL_IsHighRisk);
				AssertEquals("Packline Is High Risk is defaulted to true", true, packLine2.JL_IsHighRisk);

				shipment.JS_IsHighRisk = false;
				AssertEquals("Packline Is High Risk redefaults to false", false, packLine1.JL_IsHighRisk);
				AssertEquals("Packline Is High Risk redefaults to false", false, packLine2.JL_IsHighRisk);

				shipment.ReDefaultPackLineIsHighRiskEventHandler += (s, e) => { e.Cancel = true; };

				shipment.JS_IsHighRisk = true;
				AssertEquals("Packline Is High Risk is still false", false, packLine1.JL_IsHighRisk);
				AssertEquals("Packline Is High Risk is still false", false, packLine2.JL_IsHighRisk);

				packLine1.JL_IsHighRisk = true;
				packLine2.JL_IsHighRisk = true;

				shipment.JS_IsHighRisk = false;
				AssertEquals("Packline Is High Risk is still true", true, packLine1.JL_IsHighRisk);
				AssertEquals("Packline Is High Risk is still true", true, packLine2.JL_IsHighRisk);

				packLine1.JL_IsHighRisk = false;
				packLine2.JL_IsHighRisk = false;

				packLine1.JL_IsHighRisk = true;
				AssertEquals("Shipment Is High Risk is defaulted to true", true, shipment.JS_IsHighRisk);
				AssertEquals("Packline2 Is High Risk is still false because Is High Risk of shipment is updated by packline1", false, packLine2.JL_IsHighRisk);
			}

			using (GlbCompany.CurrentCompany.TemporarilySetCountry("IT"))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "FRPAR";
				shipment.JS_RL_NKDestination = "CNSHA";
				shipment.JS_TransportMode = "AIR";
				shipment.JS_IsHighRisk = false;
				AssertEquals(true, shipment.AviationSecurity.SupplyChainSecurityConfiguration.IsHighRiskApplicable);
				var packLine1 = shipment.OuterPackLines.AddNew();
				var packLine2 = shipment.OuterPackLines.AddNew();
				AssertEquals(false, packLine1.JL_IsHighRisk);
				AssertEquals(false, packLine2.JL_IsHighRisk);

				shipment.JS_IsHighRisk = true;
				AssertEquals("pack Is High Risk is still false because ReDefaultPackLineIsHighRiskEventHandler is null", false, packLine1.JL_IsHighRisk);
				AssertEquals("pack Is High Risk is still false because ReDefaultPackLineIsHighRiskEventHandler is null", false, packLine2.JL_IsHighRisk);
			}
		}

