		#region Additional Inspection Type Code

		public void TestRedefaultShipmentAdditionalInspectionTypeCodes()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry("FR"))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "FRPAR";
				shipment.JS_RL_NKDestination = "CNSHA";
				shipment.JS_TransportMode = "AIR";
				shipment.ReDefaultPackLineAdditionalInspectionTypeCodesEventHandler += (s, e) => { };
				shipment.JS_IsHighRisk = true;
				var packLine1 = shipment.OuterPackLines.AddNew();
				packLine1.JL_IsHighRisk = true;
				var packLine2 = shipment.OuterPackLines.AddNew();
				packLine2.JL_IsHighRisk = true;
				var packLine3 = shipment.OuterPackLines.AddNew();
				packLine3.JL_IsHighRisk = false;
				AssertEquals(FreightDataRegistry.AviationSecurity_Unknown_Code, packLine1.JL_AdditionalInspectionTypeCode);
				AssertEquals(FreightDataRegistry.AviationSecurity_Unknown_Code, packLine2.JL_AdditionalInspectionTypeCode);
				AssertEquals(FreightDataRegistry.AviationSecurity_Unknown_Code, packLine3.JL_AdditionalInspectionTypeCode);

				packLine1.JL_AdditionalInspectionTypeCode = AdditionalScreeningMethods.Codes.VisualCheck;
				AssertEquals(FreightDataRegistry.AviationSecurity_Unknown_Code, shipment.JS_AdditionalInspectionTypeCode);
				packLine2.JL_AdditionalInspectionTypeCode = AdditionalScreeningMethods.Codes.VisualCheck;
				AssertEquals("VCK status is defaulted to shipment", AdditionalScreeningMethods.Codes.VisualCheck, shipment.JS_AdditionalInspectionTypeCode);

				shipment.JS_AdditionalInspectionTypeCode = AdditionalScreeningMethods.Codes.PhysicalInspectionAndHandSearch;
				AssertEquals("PHS status is defaulted to packline1", AdditionalScreeningMethods.Codes.PhysicalInspectionAndHandSearch, packLine1.JL_AdditionalInspectionTypeCode);
				AssertEquals("PHS status is defaulted to packline2", AdditionalScreeningMethods.Codes.PhysicalInspectionAndHandSearch, packLine2.JL_AdditionalInspectionTypeCode);
				AssertEquals("packLine3's Additional Inspection Type is still UNK because it's JL_IsHighRisk is false", FreightDataRegistry.AviationSecurity_Unknown_Code, packLine3.JL_AdditionalInspectionTypeCode);

				packLine1.JL_AdditionalInspectionTypeCode = AdditionalScreeningMethods.Codes.VisualCheck;
				AssertEquals("SCR status is defaulted to shipment", BaseJobShipmentLookups.InspectionType_Screened, shipment.JS_AdditionalInspectionTypeCode);
				packLine2.JL_AdditionalInspectionTypeCode = AdditionalScreeningMethods.Codes.VisualCheck;
				AssertEquals("VCK status is defaulted to shipment", AdditionalScreeningMethods.Codes.VisualCheck, shipment.JS_AdditionalInspectionTypeCode);

				packLine1.JL_AdditionalInspectionTypeCode = FreightDataRegistry.AviationSecurity_Unknown_Code;
				AssertEquals("UNK status is defaulted to shipment", FreightDataRegistry.AviationSecurity_Unknown_Code, shipment.JS_AdditionalInspectionTypeCode);
				packLine2.JL_AdditionalInspectionTypeCode = FreightDataRegistry.AviationSecurity_Unknown_Code;
				AssertEquals("Shipment Additional Inspection Type remains UNK", FreightDataRegistry.AviationSecurity_Unknown_Code, shipment.JS_AdditionalInspectionTypeCode);

				packLine1.JL_AdditionalInspectionTypeCode = AdditionalScreeningMethods.Codes.VisualCheck;
				packLine2.JL_AdditionalInspectionTypeCode = AdditionalScreeningMethods.Codes.PhysicalInspectionAndHandSearch;
				AssertEquals("SCR status is defaulted to shipment", BaseJobShipmentLookups.InspectionType_Screened, shipment.JS_AdditionalInspectionTypeCode);
				packLine1.JL_IsHighRisk = false;
				AssertEquals("PHS status is defaulted to shipment", AdditionalScreeningMethods.Codes.PhysicalInspectionAndHandSearch, shipment.JS_AdditionalInspectionTypeCode);
			}

			using (GlbCompany.CurrentCompany.TemporarilySetCountry("IT"))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "FRPAR";
				shipment.JS_RL_NKDestination = "CNSHA";
				shipment.JS_TransportMode = "AIR";
				shipment.JS_IsHighRisk = true;
				var packLine = shipment.OuterPackLines.AddNew();
				packLine.JL_IsHighRisk = true;
				AssertEquals(FreightDataRegistry.AviationSecurity_Unknown_Code, packLine.JL_AdditionalInspectionTypeCode);
				packLine.JL_AdditionalInspectionTypeCode = AdditionalScreeningMethods.Codes.VisualCheck;
				shipment.JS_AdditionalInspectionTypeCode = AdditionalScreeningMethods.Codes.PhysicalInspectionAndHandSearch;
				AssertEquals("packline's Additional Inspection Type is still VCK because ReDefaultPackLineAdditionalInspectionTypeCodesEventHandler is null", AdditionalScreeningMethods.Codes.VisualCheck, packLine.JL_AdditionalInspectionTypeCode);
			}
		}

