		public void TestJS_AdditionalInspectionTypeCode()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry("IT"))
			{
				var shipment = Factory.New<ForwardingShipment>();
				AssertEquals("Inspection Type is UNK", "UNK", shipment.JS_InspectionTypeCode);
				AssertEquals("Additional Inspection is also UNK", "UNK", shipment.JS_AdditionalInspectionTypeCode);
				Assert("Read only as not high risk", shipment.JS_AdditionalInspectionTypeCode_ReadOnly);

				shipment.JS_TransportMode = "AIR";
				shipment.JS_RL_NKOrigin = "ITMIL";
				shipment.JS_RL_NKDestination = "USCHI";
				AssertEquals("UNK", shipment.JS_AdditionalInspectionTypeCode);
				Assert("Read only as not high risk", shipment.JS_AdditionalInspectionTypeCode_ReadOnly);

				shipment.JS_IsHighRisk = true;
				AssertEquals("UNK", shipment.JS_AdditionalInspectionTypeCode);
				Assert("Read / write as high risk", !shipment.JS_AdditionalInspectionTypeCode_ReadOnly);

				shipment.JS_AdditionalInspectionTypeCode = "PHS";
				AssertEquals("PHS", shipment.JS_AdditionalInspectionTypeCode);
				Assert("Read / write as high risk", !shipment.JS_AdditionalInspectionTypeCode_ReadOnly);

				shipment.JS_IsHighRisk = false;
				AssertEquals("Additional Inspection is reset", "UNK", shipment.JS_AdditionalInspectionTypeCode);
				Assert("Read only as not high risk", shipment.JS_AdditionalInspectionTypeCode_ReadOnly);
			}

			using (FreightDataRegistry.Instance.ShipmentInspectionTypeDefault.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, "PHS"))
			using (GlbCompany.CurrentCompany.TemporarilySetCountry("IT"))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_TransportMode = "AIR";
				shipment.JS_RL_NKOrigin = "ITMIL";
				shipment.JS_RL_NKDestination = "USCHI";
				AssertEquals("Inspection Type is PHS", "PHS", shipment.JS_InspectionTypeCode);
				AssertEquals("Additional Inspection is UNK", "UNK", shipment.JS_AdditionalInspectionTypeCode);
				Assert("Read only as not high risk", shipment.JS_AdditionalInspectionTypeCode_ReadOnly);

				shipment.JS_IsHighRisk = true;
				AssertEquals("UNK", shipment.JS_AdditionalInspectionTypeCode);
				Assert("Read / write as high risk", !shipment.JS_AdditionalInspectionTypeCode_ReadOnly);

				shipment.JS_AdditionalInspectionTypeCode = "XRY";
				AssertEquals("XRY", shipment.JS_AdditionalInspectionTypeCode);
				Assert("Read / write as high risk", !shipment.JS_AdditionalInspectionTypeCode_ReadOnly);

				shipment.JS_IsHighRisk = false;
				AssertEquals("Additional Inspection is reset", "UNK", shipment.JS_AdditionalInspectionTypeCode);
				Assert("Read only as not high risk", shipment.JS_AdditionalInspectionTypeCode_ReadOnly);
			}
		}

