		public void TestCoLoadShipmentsCollectionConsolCutOffSecurity()
		{
			#region Setup

			ForwardingConsol consol1 = Factory.NewWithValidTestData<ForwardingConsol>();
			ForwardingConsol consol2 = Factory.NewWithValidTestData<ForwardingConsol>();
			ForwardingConsol consol3 = Factory.NewWithValidTestData<ForwardingConsol>();

			consol2.JK_ConsolCutOffDateLocal = ZDateTime.Now.AddDays(1);
			consol3.JK_ConsolCutOffDateLocal = ZDateTime.Now.AddDays(-1);

			ForwardingShipment shipment1 = consol1.Shipments.AddNew();
			ForwardingShipment shipment2 = consol2.Shipments.AddNew();
			ForwardingShipment shipment3 = consol3.Shipments.AddNew();

			Factory.Save();

			#endregion

			BusinessObjectFactory newFactory = new BusinessObjectFactory();

			ForwardingShipment testShipment = newFactory.Load<ForwardingShipment>(shipment1.PK);
			Assert("Security Granted. Consol has no cut off. Can add coloads.", testShipment.CoLoadShipments.AllowAddNew);

			testShipment = newFactory.Load<ForwardingShipment>(shipment2.PK);
			Assert("Security Granted. Future cut off date. Can add coloads.", testShipment.CoLoadShipments.AllowAddNew);

			testShipment = newFactory.Load<ForwardingShipment>(shipment3.PK);
			Assert("Security Granted. Cut off date breached. Can add coloads.", testShipment.CoLoadShipments.AllowAddNew);

			try
			{
				Env.Security.ConsolAttachDetachShipmentAfterCutOffDate.IsAllowed = false;

				newFactory = new BusinessObjectFactory();

				testShipment = newFactory.Load<ForwardingShipment>(shipment1.PK);
				Assert("Security Denied. Consol has no cut off. Can add coloads.", testShipment.CoLoadShipments.AllowAddNew);

				testShipment = newFactory.Load<ForwardingShipment>(shipment2.PK);
				Assert("Security Denied. Future cut off date. Can add coloads.", testShipment.CoLoadShipments.AllowAddNew);

				testShipment = newFactory.Load<ForwardingShipment>(shipment3.PK);
				Assert("Security Denied. Cut off date breached. Can't add coloads.", !testShipment.CoLoadShipments.AllowAddNew);
			}
			finally
			{
				Env.Security.ConsolAttachDetachShipmentAfterCutOffDate.IsAllowed = true;
			}
		}

