		public void TestSupplierBuyerLink_DefaultsToShipment()
		{
			var deliveryCartage = Factory.NewWithValidTestData<OrgHeader>();
			var pickupCartage = Factory.NewWithValidTestData<OrgHeader>();

			var consignee = Factory.NewWithValidTestData<OrgHeader>();
			var consigneeContact1 = consignee.Contacts.AddNew();
			consigneeContact1.OC_ContactName = "ConsigneeContact1";

			var consigneeContact2 = consignee.Contacts.AddNew();
			consigneeContact2.OC_ContactName = "ConsigneeContact2";

			var consigneeAddress1 = consignee.Addresses.AddNew();
			consigneeAddress1.OA_Code = "ConsigneeAddress1";
			consigneeAddress1.OA_Address1 = "ConsigneeAddress1";

			var consignor = Factory.NewWithValidTestData<OrgHeader>();
			var consignorContact1 = consignor.Contacts.AddNew();
			consignorContact1.OC_ContactName = "ConsignorContact1";

			var consignorAddress1 = consignor.Addresses.AddNew();
			consignorAddress1.OA_Code = "ConsignorAddress1";
			consignorAddress1.OA_Address1 = "ConsignorAddress1";

			OrgSupplierBuyerLink link = consignee.SupplierLinks.AddNew(consignor);
			link.OL_RN_NKImporterCountry = Core.Constants.CountryCodes.UnitedStates;

			var linkDetails = link.OrgSupBuyLinkTrnModes.AddNew();
			linkDetails.PF_TransportMode = Core.Constants.TransportModes.Air;
			linkDetails.PF_ContainerMode = Core.Constants.ContainerModes.Loose;
			linkDetails.PF_IncoTerm = "CIF";
			linkDetails.PF_RL_NKPlaceOfDeliveryPort = "USLAX";
			linkDetails.PF_RL_NKPlaceOfReceivalPort = "AUSYD";
			linkDetails.PF_RS_NKDefaultServiceLevel = "DIR";
			linkDetails.PF_OC_OverrideConsigneeContact = consigneeContact1.PK;
			linkDetails.PF_OC_OverrideNotifyParty = consigneeContact2.PK;
			linkDetails.PF_OC_OverrideSupplierContact = consignorContact1.PK;

			linkDetails.PF_OA_OverrideDeliveryAddress = consigneeAddress1.PK;
			linkDetails.PF_OA_OverridePickupAddress = consignorAddress1.PK;
			linkDetails.PF_OH_DeliveryCartageContractor = deliveryCartage.PK;
			linkDetails.PF_OH_PickupCartageContractor = pickupCartage.PK;

			Factory.Save();

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_RL_NKDestination = "USLAX";
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
			shipment.JS_PackingMode = Core.Constants.ContainerModes.Loose;
			shipment.ConsignorDocumentaryAddress.OrganisationPK = consignor.PK;
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = consignee.PK;

			AssertEquals("CIF", shipment.JS_INCO);
			AssertEquals("USLAX", shipment.JS_RL_NKDestination);
			AssertEquals("AUSYD", shipment.JS_RL_NKOrigin);
			AssertEquals("DIR", shipment.JS_RS_NKServiceLevel);
			AssertEquals("ConsigneeContact1", shipment.ConsigneeDeliveryAddress.Contact.OC_ContactName);
			AssertEquals("ConsignorContact1", shipment.ConsignorPickupAddress.Contact.OC_ContactName);
			AssertEquals(consigneeContact2.PK, shipment.NotifyPartyContactPK);

			AssertEquals(consigneeAddress1.PK, shipment.ConsigneeDeliveryAddress.E2_OA_Address);
			AssertEquals(consignorAddress1.PK, shipment.ConsignorPickupAddress.E2_OA_Address);

			AssertEquals(deliveryCartage.PK, shipment.DocsAndCartage.DeliveryCartageCoPK);
			AssertEquals(pickupCartage.PK, shipment.DocsAndCartage.PickupCartageCoPK);
		}

		public void TestSupplierBuyerLink()
		{
			var consol = GetConsol();
			consol.IsRoot = true;

			ShipmentDomainService.GetInstance(Factory).NewSupplierBuyerLink += new EventHandler<NewSupplierBuyerLinkEventArgs>(GridShipments_OnNewSupplierBuyer);

			var shipment = consol.Shipments.AddNew();
			shipment.JS_UniqueConsignRef = "S1010";
			var newConsignor = Factory.New<OrgHeader>();
			newConsignor.OH_Code = "CONSIGNOR";
			newConsignor.OH_FullName = "Supplier";
			newConsignor.MainAddress.OA_Address1 = "Supplier Address";

			var newConsignee = Factory.New<OrgHeader>();
			newConsignee.OH_Code = "CONSIGNEE";
			newConsignee.OH_FullName = "Buyer";
			newConsignee.MainAddress.OA_Address1 = "Buyer Address";

			Factory.Save();

			OnNewSupplierBuyerTriggered = 0;
			shipment.JS_INCO = "DDP";
			shipment.ConsignorPK = newConsignor.PK;
			shipment.ConsigneePK = newConsignee.PK;
			shipment.JS_RL_NKDestination = "SGSIN";
			Assert("Shipment buyer/supplier prompt triggered should be true", OnNewSupplierBuyerTriggered > 0);
			Factory.Save();

			var filter = new ZQuery();
			filter.AddToFilter(OrgSupplierBuyerLinkSchema.OL_OH_Buyer, newConsignee.PK);
			filter.AddToFilter(OrgSupplierBuyerLinkSchema.OL_OH_Supplier, newConsignor.PK);
			var links = Factory.Load<OrgSupplierBuyerLink>(filter);
			AssertEquals("Supplier Buyer Link not saved.", 1, links.Length);

			var link = links[0];

			AssertEquals("Values copied to buyer supplier link", "SG", link.ImporterCountry.RN_Code);
			AssertEquals("Values copied to buyer supplier link", shipment.JS_NoCopyBills, link.OrgSupBuyLinkTrnModes[0].PF_NoOfCopyBills);
			AssertEquals("Values copied to buyer supplier link", shipment.JS_NoOriginalBills, link.OrgSupBuyLinkTrnModes[0].PF_NoOfOriginalBills);
			AssertEquals("Values copied to buyer supplier link", shipment.JS_INCO, link.OrgSupBuyLinkTrnModes[0].PF_IncoTerm);

			var newShipment = Factory.New<ForwardingShipment>();
			newShipment.JS_UniqueConsignRef = "S0101";
			newConsignor.BuyerLinks.Load();
			newShipment.ConsignorPK = newConsignor.PK;
			AssertEquals("Consignee should be defaulted from Supplier Buyer.", newConsignee.PK, newShipment.ConsigneePK);
			Factory.Save();
			links = Factory.Load<OrgSupplierBuyerLink>(filter);
			AssertEquals("No new Supplier Buyer Link should be saved", 1, links.Length);
		}

