			carrier.OH_Code = "Carrier";
			carrier.OH_IsAirLine = true;
			carrier.OH_IsShippingProvider = true;

			carrier.MiscServ.OM_RM_Airline = Factory.LoadFromNaturalKey<RefAirline>(RefAirlineSchema.RM_EagleAddedAirlinePrefixOrAccountingCode, "081").PK;

			var airLine = carrier.MiscServ.Airline;
			var rule = airLine.EFreightStatusCollection.AddNew();
			rule.RME_OriginLocation = "SGSIN";
			rule.RME_DestinationLocation = "AUSYD";
			rule.RME_EFreightStatus = "ECC";

			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Constants.TransportModes.Air;
			shipment.JS_PackingMode = Constants.ContainerModes.FCL;
			shipment.JS_RL_NKOrigin = "NZAKL";
			shipment.JS_RL_NKDestination = "AUBNE";
			shipment.ConsignorDocumentaryAddress.OrganisationPK = cnr.PK;
			shipment.JS_EFreightStatus = "";

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.JK_TransportMode = Constants.TransportModes.Air;
			consol.JK_AgentType = "AGT";
			consol.JK_ConsolMode = "LSE";
			consol.JK_RL_NKLoadPort = "SGSIN";
			consol.JK_RL_NKDischargePort = "AUSYD";
			consol.JK_OA_ShippingLineAddress = carrier.Addresses.AddNewMainAddress().PK;

			Factory.Save();

			consol.Shipments.Add(shipment);
			AssertEquals("E-Freight status should get from the matched air line rule in consol's carrier when it is blank.", "ECC", shipment.JS_EFreightStatus);

			shipment.JS_EFreightStatus = "";
			consol.Shipments.Remove(shipment);
			AssertEquals("E-Freight status should not change when shipment does not have a departure consol.", "", shipment.JS_EFreightStatus);

			shipment.JS_EFreightStatus = "NON";
			consol.Shipments.Add(shipment);
			AssertEquals("E-Freight status should not change when it is not blank.", "NON", shipment.JS_EFreightStatus);
		}

