		public void TestSaveBuyerSupplierRelationshipsWith2ShipmentsOnConsol()
		{
			var consol = GetConsol();
			consol.IsRoot = true;

			ShipmentDomainService.GetInstance(Factory).NewSupplierBuyerLink += new EventHandler<NewSupplierBuyerLinkEventArgs>(GridShipments_OnNewSupplierBuyer);

			OnNewSupplierBuyerTriggered = 0;
			var shipment1 = consol.Shipments.AddNew();
			shipment1.JS_UniqueConsignRef = "S1010";
			shipment1.ConsigneePK = CreateTestLocalConsignee().PK;
			shipment1.ConsignorPK = CreateTestLocalConsignor().PK;
			AssertEquals("Shipment1 Save relationship prompt should be already triggered, added before save", false, shipment1.BuyerSupplierLinksHelper.ShouldPromptToSaveSupplierBuyerRelationship);
			Assert("Shipment1 buyer/supplier prompt triggered should be true", OnNewSupplierBuyerTriggered > 0);

			OnNewSupplierBuyerTriggered = 0;
			var shipment2 = consol.Shipments.AddNew();
			shipment2.JS_UniqueConsignRef = "S2020";
			shipment2.ConsigneePK = shipment1.ConsigneePK;
			shipment2.ConsignorPK = shipment1.ConsignorPK;
			AssertEquals("Shipment2 Save relationship prompt should be already triggered, added before save", false, shipment2.BuyerSupplierLinksHelper.ShouldPromptToSaveSupplierBuyerRelationship);
			AssertEquals("Shipment1 buyer/supplier prompt triggered should be false, link already in consol link collection", 0, OnNewSupplierBuyerTriggered);

			Factory.Save();

			AssertEquals("Shipment2 Save relationship prompt should be false, now in db", false, shipment2.BuyerSupplierLinksHelper.ShouldPromptToSaveSupplierBuyerRelationship);
		}

		public void TestSaveBuyerSupplierRelationshipsDoesNotAskASecondTimeWith2ShipmentsOnConsol()
		{
			var consol = GetConsol();
			consol.IsRoot = true;

			ShipmentDomainService.GetInstance(Factory).NewSupplierBuyerLink += new EventHandler<NewSupplierBuyerLinkEventArgs>(GridShipments_OnNewSupplierBuyer);
			SupplierBuyerDialogResult = ZDialogResult.No;

			OnNewSupplierBuyerTriggered = 0;
			var shipment1 = consol.Shipments.AddNew();
			shipment1.ConsigneePK = CreateTestLocalConsignee().PK;
			shipment1.ConsignorPK = CreateTestLocalConsignor().PK;
			AssertEquals("Shipment1 Save relationship prompt should be true, cause it hasn't been added", true, shipment1.BuyerSupplierLinksHelper.ShouldPromptToSaveSupplierBuyerRelationship);
			AssertEquals("Shipment1 buyer/supplier prompt triggered should be true", 1, OnNewSupplierBuyerTriggered);

			OnNewSupplierBuyerTriggered = 0;
			var shipment2 = consol.Shipments.AddNew();
			shipment2.ConsigneePK = shipment1.ConsigneePK;
			shipment2.ConsignorPK = shipment1.ConsignorPK;
			AssertEquals("Shipment2 Save relationship prompt should be true, cause it hasn't been added", true, shipment2.BuyerSupplierLinksHelper.ShouldPromptToSaveSupplierBuyerRelationship);
			AssertEquals("Shipment1 buyer/supplier prompt triggered should be false, Question was already asked", 0, OnNewSupplierBuyerTriggered);
		}

		public void TestConsigneeOrConsignorCanNotBeSetWhenDocumentaryAddressIsReadOnly()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();

			OrgHeader consignor = Factory.NewWithValidTestData<OrgHeader>();
			consignor.OH_Code = "CONSIGNOR";

			OrgHeader consignee = Factory.NewWithValidTestData<OrgHeader>();
			consignee.OH_Code = "CONSIGNEE";

			shipment.ConsignorPK = consignor.PK;
			shipment.ConsigneePK = consignee.PK;

			AssertEquals(consignor, shipment.Consignor);
			AssertEquals(consignee, shipment.Consignee);

			OrgHeader newConsignor = Factory.NewWithValidTestData<OrgHeader>();
			consignor.OH_Code = "NewCONSIGNOR";

			OrgHeader newConsignee = Factory.NewWithValidTestData<OrgHeader>();
			consignee.OH_Code = "NewCONSIGNEE";

			shipment.ConsignorDocumentaryAddress.ReadOnly = true;
			shipment.ConsigneeDocumentaryAddress.ReadOnly = true;

			((IBuyerSupplierRelationshipConsumer)shipment).Consignor = newConsignor;
			((IBuyerSupplierRelationshipConsumer)shipment).Consignee = newConsignee;

			AssertEquals("consignor should NOT changed as ConsignorDocumentaryAddress is readonly", consignor, shipment.Consignor);
			AssertEquals("consignee should NOT changed as ConsigneeDocumentaryAddress is readonly", consignee, shipment.Consignee);
		}

		public void TestPromptToSaveSupplierBuyer()
		{
			ForwardingShipment shipment = (ForwardingShipment)GetShipment();
			shipment.JS_UniqueConsignRef = "S1010";
			OrgHeader newConsignor = Factory.New<OrgHeader>();
			newConsignor.OH_Code = "CONSIGNOR";
			newConsignor.OH_FullName = "Supplier";
			newConsignor.MainAddress.OA_Address1 = "Supplier Address";

			OrgHeader newConsignee = Factory.New<OrgHeader>();
			newConsignee.OH_Code = "CONSIGNEE";
			newConsignee.OH_FullName = "Buyer";
			newConsignee.MainAddress.OA_Address1 = "Buyer Address";

			Factory.Save();

			shipment.ConsignorPK = newConsignor.PK;
			shipment.ConsigneePK = newConsignee.PK;
			AssertEquals("Shipment Save relationship prompt should be true, no consol & no prompt, so hasn't been added", true, shipment.BuyerSupplierLinksHelper.ShouldPromptToSaveSupplierBuyerRelationship);

			shipment.ConsignorPK = ZGuid.Empty;
			AssertEquals("Shipment has no Consignor so dont ask", false, shipment.BuyerSupplierLinksHelper.ShouldPromptToSaveSupplierBuyerRelationship);

			shipment.ConsignorPK = newConsignor.PK;
			shipment.ConsigneePK = ZGuid.Empty;
			AssertEquals("Shipment has no Consignee so dont ask", false, shipment.BuyerSupplierLinksHelper.ShouldPromptToSaveSupplierBuyerRelationship);

			JobDocAddress consignorAddress = shipment.DocAddresses.FindOrCreateWithDocAddressType(DocAddressType.ConsignorDocumentaryAddress);
			JobDocAddress consigneeAddress = shipment.DocAddresses.FindOrCreateWithDocAddressType(DocAddressType.ConsigneeDocumentaryAddress);

			consignorAddress.E2_AddressOverride = true;
			AssertEquals("Consignor is overridden, dont ask", false, shipment.BuyerSupplierLinksHelper.ShouldPromptToSaveSupplierBuyerRelationship);

			consignorAddress.E2_AddressOverride = false;
			consigneeAddress.E2_AddressOverride = true;
			AssertEquals("Consignee is overridden, dont ask", false, shipment.BuyerSupplierLinksHelper.ShouldPromptToSaveSupplierBuyerRelationship);

			OnNewSupplierBuyerTriggered = 0;
			ForwardingConsol consol = GetConsol();
			consol.IsRoot = true;

			ShipmentDomainService.GetInstance(Factory).NewSupplierBuyerLink += new EventHandler<NewSupplierBuyerLinkEventArgs>(GridShipments_OnNewSupplierBuyer);
			ForwardingShipment newShipment = consol.Shipments.AddNew();
			newShipment.JS_UniqueConsignRef = "S0101";
			newShipment.ConsignorPK = newConsignor.PK;
			newShipment.ConsigneePK = newConsignee.PK;
			AssertEquals("Shipment Save relationship prompt should be true, hasn't been added, not until save", true, newShipment.BuyerSupplierLinksHelper.ShouldPromptToSaveSupplierBuyerRelationship);
			AssertEquals("Shipment buyer/supplier prompt triggered should be true, link already made", 1, OnNewSupplierBuyerTriggered);

			Factory.Save();
			AssertEquals("Shipment Save relationship prompt should be false, added after save", false, newShipment.BuyerSupplierLinksHelper.ShouldPromptToSaveSupplierBuyerRelationship);
		}

		public void TestSettingConsigneeFromDestination()
		{
			var consignor = Factory.New<OrgHeader>();
			consignor.OH_Code = "TSCNR";
			consignor.OH_FullName = "Test Consignor";
			consignor.OH_IsConsignor = true;
			consignor.OH_RL_NKClosestPort = GlbBranch.CurrentBranch.HomePort.RL_Code;

			var consignee = Factory.New<OrgHeader>();
			consignee.OH_Code = "TSCNE";
			consignee.OH_FullName = "Test Consignee";
			consignee.OH_IsConsignee = true;
			consignee.OH_RL_NKClosestPort = "GBLON";

			var cneAddress1 = consignee.MainAddress;
			cneAddress1.OA_Address1 = "Test Consignee Address 1";
			cneAddress1.AddressCapability.SetCapabilityEnabled("OFC");
			cneAddress1.AddressCapability.SetIsMainAddress("OFC");
			cneAddress1.OA_RL_NKRelatedPortCode = "DEHAM";

			var cneAddress2 = consignee.Addresses.AddNew();
			cneAddress2.OA_Address1 = "Test Consignee Address 2";
			cneAddress2.AddressCapability.SetCapabilityEnabled("OFC");
			cneAddress2.AddressCapability.SetIsNotMainAddress("OFC");
			cneAddress2.OA_RL_NKRelatedPortCode = "NZABY";

			var link = consignor.BuyerLinks.AddNew(consignee);
			link.OrgSupBuyLinkTrnModes.RemoveAndDeleteAll();

			var mode = link.OrgSupBuyLinkTrnModes.AddNew();
			mode.PF_TransportMode = "SEA";
			mode.PF_ContainerMode = "FCL";
			mode.PF_RL_NKPlaceOfReceivalPort = "ADALV";
			mode.PF_RL_NKPlaceOfDeliveryPort = "DEHAM";

			Factory.Save();

			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = "SEA";
			shipment.JS_PackingMode = "FCL";
			shipment.ConsignorPK = consignor.PK;

			AssertEquals("The address should be main office address.", cneAddress1.PK, shipment.ConsigneeDocumentaryAddress.E2_OA_Address);

			shipment.ConsigneeDocumentaryAddress.E2_OA_Address = cneAddress2.PK;
			AssertEquals("The address should be set to test consignee address 2.", cneAddress2.PK, shipment.ConsigneeDocumentaryAddress.E2_OA_Address);
		}

