		#region JC_EmptyReturnedBy_ForContainersIfRequired

		[TestDate(2008, 2, 3)]
		public void TestCalculateJC_EmptyReturnedBy_ForContainersIfRequired()
		{
			var anotherFactory = new BusinessObjectFactory();

			ForwardingConsol consol = Factory.New<ForwardingConsol>();
			ContainerForTest cont1 = Factory.New<ContainerForTest>();
			ContainerForTest cont2 = Factory.New<ContainerForTest>();
			ContainerForTest cont3 = Factory.New<ContainerForTest>();
			consol.Containers.Add(cont1);
			consol.Containers.Add(cont2);
			consol.Containers.Add(cont3);
			ContainerDefaultingStrategyForTest strat1 = new ContainerDefaultingStrategyForTest();
			ContainerDefaultingStrategyForTest strat2 = new ContainerDefaultingStrategyForTest();
			ContainerDefaultingStrategyForTest strat3 = new ContainerDefaultingStrategyForTest();
			cont1.ContainerDefaultingStrategy = strat1;
			cont2.ContainerDefaultingStrategy = strat2;
			cont3.ContainerDefaultingStrategy = strat3;
			cont1.JC_FCLAvailable = ZDateTime.Now;
			cont2.JC_FCLAvailable = ZDateTime.Now;
			cont3.JC_FCLAvailable = ZDateTime.Now;
			strat1.ExpectedDate = ZDateTime.Now;
			strat2.ExpectedDate = ZDateTime.Now.AddDays(1);
			strat3.ExpectedDate = ZDateTime.Now.AddDays(2);
			Factory.Save();
			AssertEquals(ZDateTime.Now, cont1.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(1), cont2.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(2), cont3.JC_EmptyReturnedBy);

			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			strat1.ExpectedDate = ZDateTime.Now.AddDays(3);
			strat2.ExpectedDate = ZDateTime.Now.AddDays(4);
			strat3.ExpectedDate = ZDateTime.Now.AddDays(5);
			Factory.Save();
			AssertEquals(ZDateTime.Now, cont1.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(1), cont2.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(2), cont3.JC_EmptyReturnedBy);

			shipment.Consols.Add(consol);
			Factory.Save();
			AssertEquals(ZDateTime.Now, cont1.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(1), cont2.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(2), cont3.JC_EmptyReturnedBy);

			SetCalculateEmptyReturnedByToEmpty(cont1, anotherFactory);
			SetCalculateEmptyReturnedByToEmpty(cont2, anotherFactory);

			shipment = Factory.New<ForwardingShipment>();
			shipment.Consols.Add(consol);
			PackLine packLine1 = shipment.OuterPackLines.AddNew();
			packLine1.Containers.RemoveAll();
			packLine1.Containers.Add(cont1);
			PackLine packLine2 = shipment.OuterPackLines.AddNew();
			packLine2.Containers.RemoveAll();
			packLine2.Containers.Add(cont2);
			Factory.Save();
			AssertEquals(ZDateTime.Now.AddDays(3), cont1.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(4), cont2.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(2), cont3.JC_EmptyReturnedBy);

			shipment.JS_GoodsDescription = "~~~JKUHJH";
			Factory.Save();
			AssertEquals(ZDateTime.Now.AddDays(3), cont1.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(4), cont2.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(2), cont3.JC_EmptyReturnedBy);

			PackLine packLine3 = shipment.OuterPackLines.AddNew();
			packLine3.Containers.RemoveAll();
			packLine3.Containers.Add(cont3);
			Factory.Save();
			AssertEquals(ZDateTime.Now.AddDays(3), cont1.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(4), cont2.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(2), cont3.JC_EmptyReturnedBy);

			strat1.ExpectedDate = ZDateTime.Now.AddDays(6);
			strat2.ExpectedDate = ZDateTime.Now.AddDays(7);
			strat3.ExpectedDate = ZDateTime.Now.AddDays(8);
			SetCalculateEmptyReturnedByToEmpty(cont1, anotherFactory);
			SetCalculateEmptyReturnedByToEmpty(cont2, anotherFactory);

			OrgHeader org = Factory.New<OrgHeader>();
			org.OH_Code = "~~jhsdf";
			org.OH_FullName = "~~jjuiuh";
			shipment.ConsigneePK = org.PK;
			Factory.Save();
			AssertEquals(ZDateTime.Now.AddDays(6), cont1.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(7), cont2.JC_EmptyReturnedBy);

			shipment.JS_GoodsDescription = "~~~1112233";
			Factory.Save();
			AssertEquals(ZDateTime.Now.AddDays(6), cont1.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(7), cont2.JC_EmptyReturnedBy);

			SetCalculateEmptyReturnedByToEmpty(cont1, anotherFactory);
			SetCalculateEmptyReturnedByToEmpty(cont2, anotherFactory);
			strat1.ExpectedDate = ZDateTime.Now.AddDays(9);
			strat2.ExpectedDate = ZDateTime.Now.AddDays(10);
			strat3.ExpectedDate = ZDateTime.Now.AddDays(11);
			OrgHeader org1 = Factory.New<OrgHeader>();
			org1.OH_Code = "~~jhsdf11";
			org1.OH_FullName = "~~jjuiuh22";
			shipment.ConsigneePK = org1.PK;
			shipment.JS_GoodsDescription = "~~~2233";
			Factory.Save();
			AssertEquals(ZDateTime.Now.AddDays(9), cont1.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(10), cont2.JC_EmptyReturnedBy);

			SetCalculateEmptyReturnedByToEmpty(cont1, anotherFactory);
			SetCalculateEmptyReturnedByToEmpty(cont2, anotherFactory);
			strat1.ExpectedDate = ZDateTime.Now.AddDays(12);
			strat2.ExpectedDate = ZDateTime.Now.AddDays(13);
			strat3.ExpectedDate = ZDateTime.Now.AddDays(14);
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = ZGuid.Empty;
			shipment.ConsigneeDocumentaryAddress.E2_AddressOverride = true;
			shipment.ConsigneeDocumentaryAddress.E2_CompanyName = "~ZZZZ~~";
			shipment.JS_GoodsDescription = "~~~1112233";
			Factory.Save();
			AssertEquals(ZDateTime.Now.AddDays(12), cont1.JC_EmptyReturnedBy);
			AssertEquals(ZDateTime.Now.AddDays(13), cont2.JC_EmptyReturnedBy);
		}

