		#region OnImportExportChanged

		public void TestImportExportChanged()
		{
			ForwardingShipment shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.ImportExportChanged += (sender, args) => ImportExportChangedHandlerWasRun = true;
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "AUDRW";
			ImportExportChangedHandlerWasRun = false;
			shipment.JS_RL_NKDestination = "AUMEL";
			Assert(!ImportExportChangedHandlerWasRun);
			shipment.JS_RL_NKDestination = "USCHI";
			Assert(ImportExportChangedHandlerWasRun);
			ImportExportChangedHandlerWasRun = false;
			shipment.JS_RL_NKDestination = "USNYC";
			Assert(!ImportExportChangedHandlerWasRun);
			shipment.JS_RL_NKOrigin = "USCHI";
			Assert(ImportExportChangedHandlerWasRun);
			ImportExportChangedHandlerWasRun = false;
			shipment.JS_RL_NKDestination = "AUSYD";
			Assert(ImportExportChangedHandlerWasRun);
			ImportExportChangedHandlerWasRun = false;
			shipment.JS_RL_NKOrigin = "USNYC";
			Assert(!ImportExportChangedHandlerWasRun);
		}

