		public void TestJS_PackingMode_RedefaultsFCLDetentionCharges()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = "ROA";
			shipment.JS_PackingMode = "FTL";
			shipment.DocsAndCartage.JP_FCLPickupDetentionFreeDays = 1;
			shipment.DocsAndCartage.JP_FCLPickupDetentionDays = 2;
			shipment.DocsAndCartage.JP_FCLPickupDetentionCharge = 3;
			shipment.DocsAndCartage.JP_FCLDeliveryDetentionFreeDays = 4;
			shipment.DocsAndCartage.JP_FCLDeliveryDetentionDays = 5;
			shipment.DocsAndCartage.JP_FCLDeliveryDetentionCharge = 6;

			shipment.JS_TransportMode = "SEA";
			AssertEquals("Packing mode redefaults to FCL", "FCL", shipment.JS_PackingMode);
			AssertEquals("Detention is not affected as still FCL type", (ZByte)1, shipment.DocsAndCartage.JP_FCLPickupDetentionFreeDays);
			AssertEquals("Detention is not affected as still FCL type", (ZByte)2, shipment.DocsAndCartage.JP_FCLPickupDetentionDays);
			AssertEquals("Detention is not affected as still FCL type", (ZDecimal)3, shipment.DocsAndCartage.JP_FCLPickupDetentionCharge);
			AssertEquals("Detention is not affected as still FCL type", (ZByte)4, shipment.DocsAndCartage.JP_FCLDeliveryDetentionFreeDays);
			AssertEquals("Detention is not affected as still FCL type", (ZByte)5, shipment.DocsAndCartage.JP_FCLDeliveryDetentionDays);
			AssertEquals("Detention is not affected as still FCL type", (ZDecimal)6, shipment.DocsAndCartage.JP_FCLDeliveryDetentionCharge);

			shipment.JS_TransportMode = "AIR";
			AssertEquals("Packing mode redefaults to LSE", "LSE", shipment.JS_PackingMode);
			AssertEquals("Detention is reset as not applicable to LSE", ZByte.Zero, shipment.DocsAndCartage.JP_FCLPickupDetentionFreeDays);
			AssertEquals("Detention is reset as not applicable to LSE", ZByte.Zero, shipment.DocsAndCartage.JP_FCLPickupDetentionDays);
			AssertEquals("Detention is reset as not applicable to LSE", ZDecimal.Zero, shipment.DocsAndCartage.JP_FCLPickupDetentionCharge);
			AssertEquals("Detention is reset as not applicable to LSE", ZByte.Zero, shipment.DocsAndCartage.JP_FCLDeliveryDetentionFreeDays);
			AssertEquals("Detention is reset as not applicable to LSE", ZByte.Zero, shipment.DocsAndCartage.JP_FCLDeliveryDetentionDays);
			AssertEquals("Detention is reset as not applicable to LSE", ZDecimal.Zero, shipment.DocsAndCartage.JP_FCLDeliveryDetentionCharge);
		}

