		void AssertParentConsolIsCFS_SetTranshipToOtherCFS(ZString masterType)
		{
			var importConsol = Factory.NewWithValidTestData<ForwardingConsol>();

			var importShipment = importConsol.Shipments.AddNew();
			importShipment.JS_RL_NKOrigin = "NZAKL";
			importShipment.JS_RL_NKDestination = "AUSYD";
			importShipment.JS_ShipmentType = masterType;
			importShipment.JS_IsCFSRegistered = true;

			var importShipment1 = importConsol.Shipments.AddNew();
			importShipment1.JS_RL_NKOrigin = "NZWEL";
			importShipment1.JS_RL_NKDestination = "AUMEL";
			importShipment1.JS_ShipmentType = Constants.ShipmentTypes.StandardHouse;
			importShipment1.JS_IsCFSRegistered = true;

			var importShipment2 = Factory.NewWithValidTestData<ForwardingShipment>();
			importShipment2.JS_RL_NKOrigin = "SGSIN";
			importShipment2.JS_RL_NKDestination = "AUBNE";
			importShipment2.JS_ShipmentType = Constants.ShipmentTypes.StandardHouse;
