			Factory.Save();
			AssertEquals(false, importShipment.JS_TranshipToOtherCFS);
			AssertEquals(true, importShipment1.JS_TranshipToOtherCFS);
			AssertEquals(false, importShipment2.JS_TranshipToOtherCFS);

			var exportConsol = Factory.NewWithValidTestData<ForwardingConsol>();

			var exportShipment = Factory.New<ForwardingShipment>();
			exportShipment.JS_RL_NKOrigin = "AUSYD";
			exportShipment.JS_RL_NKDestination = "NZAKL";
			exportShipment.JS_ShipmentType = "STD";
			exportShipment.JS_IsCFSRegistered = true;
			exportConsol.Shipments.Add(exportShipment);

			Factory.Save();
			AssertEquals(false, exportShipment.JS_TranshipToOtherCFS);
		}

