		public void TestBulkShipmentJS_Phase_UpdatedByOperationalAction_WhenConsolPhaseSecurityReadOnly_ButShipmentPhaseSecurityOverrideAllowed()
		{
			var restrictedPhaseValue = "XXX";
			var security = PhaseSecurityTestHelper.Consol.SetupRestricted(restrictedPhaseValue);
			Env.Security.ShipmentPhaseSecurityOverride.IsAllowed = true;

			var consol = new BusinessObjectFactory().New<ForwardingConsol>();
			var shipment1 = consol.Shipments.AddNew();
			var shipment2 = consol.Shipments.AddNew();
			shipment1.JS_Phase = "ALL";
			shipment2.JS_Phase = "ALL";
			consol.JK_Phase = restrictedPhaseValue;
			consol.Factory.Save();

			ForwardingConfigurationRegistry.Instance.ConsolPhaseSecurity.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, security);

			consol = Factory.Load<ForwardingConsol>(consol.PK);

			AssertEquals("Phase is set to ALL", "ALL", shipment1.JS_Phase);
			AssertEquals("Phase is set to ALL", "ALL", shipment2.JS_Phase);
			AssertEquals("Forced to readonly when accessed from Consol", true, consol.JK_ConsolModeInfo.ReadOnly);
			AssertEquals("Forced to readonly when accessed from Consol", true, consol.Shipments[0].JS_PhaseInfo.ReadOnly);
			AssertEquals("Shipment should not be readonly", false, shipment1.JS_PhaseInfo.ReadOnly);

			SetCustomFieldChangeEventForPhase_WithPropagtion(true);
			PerformOperationActionToUpdatePhase(shipment1, shipment2, restrictedPhaseValue);

			AssertEquals("Phase should be updated", restrictedPhaseValue, shipment1.JS_Phase);
			AssertEquals("Phase should be updated", restrictedPhaseValue, shipment2.JS_Phase);
		}

		public void TestBulkShipmentJS_Phase_NotUpdatedByOperationalAction_WhenShipmentPhaseSecurityOverride_NotAllowed()
		{
			var restrictedPhaseValue = "XXX";
			var security = PhaseSecurityTestHelper.Consol.SetupRestricted(restrictedPhaseValue);

			var consol = new BusinessObjectFactory().New<ForwardingConsol>();
			var shipment1 = consol.Shipments.AddNew();
			var shipment2 = consol.Shipments.AddNew();
			shipment1.JS_Phase = "ALL";
			shipment2.JS_Phase = "ALL";
			consol.JK_Phase = restrictedPhaseValue;
			consol.Factory.Save();

			ForwardingConfigurationRegistry.Instance.ConsolPhaseSecurity.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, security);

			consol = Factory.Load<ForwardingConsol>(consol.PK);

			AssertEquals("Phase is set to ALL", "ALL", shipment1.JS_Phase);
			AssertEquals("Phase is set to ALL", "ALL", shipment2.JS_Phase);
			AssertEquals("Forced to readonly when accessed from Consol", true, consol.JK_ConsolModeInfo.ReadOnly);
			AssertEquals("Forced to readonly when accessed from Consol", true, consol.Shipments[0].JS_PhaseInfo.ReadOnly);

			Env.Security.ShipmentPhaseSecurityOverride.IsAllowed = false;
			AssertEquals("Shipment should be readonly", true, shipment1.JS_PhaseInfo.ReadOnly);

			SetCustomFieldChangeEventForPhase_WithPropagtion(true);
			PerformOperationActionToUpdatePhase(shipment1, shipment2, restrictedPhaseValue);

			AssertEquals("Phase should not be updated", "ALL", shipment1.JS_Phase);
			AssertEquals("Phase should not be updated", "ALL", shipment2.JS_Phase);
		}

		void SetCustomFieldChangeEventForPhase_WithPropagtion(bool shouldPropagate)
		{
			Factory.LoadFromNaturalKey<StmEvent>(StmEventSchema.SE_Code, Events.CustomisableEvent00Code).SE_PropagateToParent = shouldPropagate;

			WorkflowDescriptors.Instance.TryGetValue("SHP", out var workflowDescriptor);
			var configManager = ObjectFactory.New<IProcessFieldChangeRuleConfigurationManager>();
			var rule = Factory.New<IProcessFieldChangeRule>();
			rule.PFR_ProcessType = workflowDescriptor.Code;
			rule.PFR_GroupName = "Group1";
			rule.PFR_SE_NKEvent = Events.CustomisableEvent00Code;
			rule.Fields.AddNew().PFL_FieldName = JobShipmentSchema.Constants.JS_Phase;
			Factory.Save();
		}

		void PerformOperationActionToUpdatePhase(ForwardingShipment shipment1, ForwardingShipment shipment2, string phase)
		{
			using (var shipmentModule = ObjectFactory.Get<IModuleFactory>().Create(ModuleIDs.JobShipment))
			{
				var context = new OperationalActionContext(((IOperationalActionSupportable)shipmentModule).OperationalActionSupporter, "ForwardingShipmentSupporter", WorkflowDescriptors.ForwardingShipmentWorkflowDescriptorCode);
				var action = Factory.New<OperationalAction>();
				action.Context = context;

				var descriptor = action.FieldDescriptors.AddNew();
				descriptor.FieldName = "JS_Phase";
				descriptor.EmptyBehaviour = EmptyBehaviourList.Codes.Skip;

				var selectedRecords = new SelectedRecords
				{ PrimaryKeys = new[] { shipment1.PK, shipment2.PK } };

				var factoryForChanges = new BusinessObjectFactory();
				var dummyLog = new DummyOperationalActionLog();
				var runner = new OperationalActionRunner(action, typeof(ForwardingShipment), selectedRecords);
				runner.Printer = ZGuid.NewZGuid();
				runner.Fields[0][RunnerTextField.Schema.Property] = phase;
				runner.Run(dummyLog, factoryForChanges);
				factoryForChanges.Save();
			}
		}

		public void TestJS_ShipmentStatus_Rejected()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			AssertEquals($"JS_ShipmentStatus is initiated to {ShipmentStatusList.Codes.Confirmed}.", ShipmentStatusList.Codes.Confirmed, shipment.JS_ShipmentStatus);

			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.SIRejected;
			AssertEquals($"JS_ShipmentStatus is set as {ShipmentStatusList.Codes.SIRejected}.", ShipmentStatusList.Codes.SIRejected, shipment.JS_ShipmentStatus);

			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.ElectronicShippingInstruction;
			AssertEquals($"JS_ShipmentStatus is set as {ShipmentStatusList.Codes.ElectronicShippingInstruction}.", ShipmentStatusList.Codes.ElectronicShippingInstruction, shipment.JS_ShipmentStatus);

			shipment.OnShipmentBookingStatusUpdate += new EventHandler<ShipmentBookingStatusEventArgs>(UpdateShipmentBookingStatusWithEmptyReason);
			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.SIRejected;
			AssertEquals("JS_ShipmentStatus is not changed - no reason provided.", ShipmentStatusList.Codes.ElectronicShippingInstruction, shipment.JS_ShipmentStatus);
			shipment.OnShipmentBookingStatusUpdate -= new EventHandler<ShipmentBookingStatusEventArgs>(UpdateShipmentBookingStatusWithEmptyReason);

			shipment.OnShipmentBookingStatusUpdate += new EventHandler<ShipmentBookingStatusEventArgs>(UpdateShipmentBookingStatusWithNonEmptyReason);
			shipment.Logs.RemoveAndDeleteAll();
			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.Confirmed;
			var log = shipment.Logs.MostRecentLog;
			CombineAssertions(() =>
			{
				AssertEquals($"JS_ShipmentStatus is set as {ShipmentStatusList.Codes.Confirmed}", ShipmentStatusList.Codes.Confirmed, shipment.JS_ShipmentStatus);
				AssertEquals("Check event free text", ZString.Empty, log.ReferenceFreeText);
				AssertEquals("Check event type", "Shipment Status", log.Parameters[Params.Type]);
				AssertEquals("Check event new status", ShipmentStatusList.Codes.Confirmed, log.Parameters[Params.New]);
				AssertEquals("Check event old status", ShipmentStatusList.Codes.ElectronicShippingInstruction, log.Parameters[Params.Old]);
				AssertEquals("Check event reason", "Shipping Instruction Confirmed", log.Parameters[Params.Reason]);
				Assert("JS_ShipmentStatus should be readonly", shipment.JS_ShipmentStatusInfo.ReadOnly);
			});

			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.ElectronicShippingInstruction;
			AssertEquals(ShipmentStatusList.Codes.ElectronicShippingInstruction, shipment.JS_ShipmentStatus);

			shipment.Logs.RemoveAndDeleteAll();
			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.SIRejected;
			log = shipment.Logs.MostRecentLog;
			CombineAssertions(() =>
			{
				AssertEquals($"JS_ShipmentStatus is set as {ShipmentStatusList.Codes.SIRejected}", ShipmentStatusList.Codes.SIRejected, shipment.JS_ShipmentStatus);
				AssertEquals("Check event free text", ZString.Empty, log.ReferenceFreeText);
				AssertEquals("Check event type", "Shipment Status", log.Parameters[Params.Type]);
				AssertEquals("Check event new status", ShipmentStatusList.Codes.SIRejected, log.Parameters[Params.New]);
				AssertEquals("Check event old status", ShipmentStatusList.Codes.ElectronicShippingInstruction, log.Parameters[Params.Old]);
				AssertEquals("Check event reason", "Shipping Instruction Rejected, The shipping instruction is rejected for some reason.", log.Parameters[Params.Reason]);
				Assert("ShipmentStatus should be readonly", shipment.JS_ShipmentStatusInfo.ReadOnly);
			});

			shipment.OnShipmentBookingStatusUpdate -= new EventHandler<ShipmentBookingStatusEventArgs>(UpdateShipmentBookingStatusWithNonEmptyReason);
		}

		public void TestJS_ShipmentStatus_Comfirmed()
		{
			var isPromptForConfirmationCalled = false;
			void PromptForConfirmation(object sender, ShipmentBookingStatusEventArgs e)
			{
				isPromptForConfirmationCalled = true;
			}

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			AssertEquals($"JS_ShipmentStatus is initiated to {ShipmentStatusList.Codes.Confirmed}.", ShipmentStatusList.Codes.Confirmed, shipment.JS_ShipmentStatus);

			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.ElectronicShippingInstruction;

			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.Confirmed;
			AssertEquals($"JS_ShipmentStatus is set as {ShipmentStatusList.Codes.Confirmed}.", ShipmentStatusList.Codes.Confirmed, shipment.JS_ShipmentStatus);

			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.ElectronicShippingInstruction;

			shipment.OnShipmentBookingStatusUpdate += new EventHandler<ShipmentBookingStatusEventArgs>(PromptForConfirmation);
			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.Confirmed;
			AssertEquals(ShipmentStatusList.Codes.Confirmed, shipment.JS_ShipmentStatus);
			Assert("No popup called as STU event with ESI hasn't been received", !isPromptForConfirmationCalled);

			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.ElectronicShippingInstruction;
			shipment.Logs.AddNew(Events.StatusUpdated, $"|{Params.Type}={Constants.EventReferenceMessageTypes.ShipmentStatus}", new KeyValuePair<string, string>(Params.New, ShipmentStatusList.Codes.ElectronicShippingInstruction));

			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.Confirmed;
			AssertEquals(ShipmentStatusList.Codes.ElectronicShippingInstruction, shipment.JS_ShipmentStatus);
			Assert("Popoup called", isPromptForConfirmationCalled);

			shipment.OnShipmentBookingStatusUpdate -= new EventHandler<ShipmentBookingStatusEventArgs>(UpdateShipmentBookingStatusWithNonEmptyReason);
		}

		public void TestJS_ShipmentStatus_CreateStatusUpdatedLog_OnlyWhenChanged()
		{
			var shipment = Factory.New<ForwardingShipment>();
			AssertEquals(ShipmentStatusList.Codes.Confirmed, shipment.JS_ShipmentStatus);
			var statusUpdatedLog = shipment.Logs.Find(s => s.SL_SE_NKEvent == Events.StatusUpdatedCode).FirstOrDefault();
			AssertNull("StatusUpdated event will not be created during setting default values.", statusUpdatedLog);

			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.Confirmed;
			statusUpdatedLog = shipment.Logs.Find(s => s.SL_SE_NKEvent == Events.StatusUpdatedCode).FirstOrDefault();
			AssertNull("StatusUpdated event will not be created when JS_ShipmentStatus is not changed.", statusUpdatedLog);

			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.SIRejected;
			statusUpdatedLog = shipment.Logs.Find(s => s.SL_SE_NKEvent == Events.StatusUpdatedCode).FirstOrDefault();
			AssertNotNull("StatusUpdated event will be created when JS_ShipmentStatus is changed.", statusUpdatedLog);
		}

