		#region Pickup/Delivery Confirms Signed For By

		public void TestGoodsSignedForBy()
		{
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			PackLine packline = shipment.OuterPackLines.AddNew();

			AssertEquals("No signatures", "", shipment.DeliveryGoodsSignedForBy);
			AssertEquals("No signatures", "", shipment.PickupGoodsSignedForBy);

			packline.JL_PackageCount = 1;
			AssertPickupDeliverySignature("1 signature", shipment, "Bill", "Bill2", "Bill", "Bill2");

			packline.JL_PackageCount = 2;
			AssertPickupDeliverySignature("2 identical signatures", shipment, "Bill", "Bill2", "Bill", "Bill2");

			packline.JL_PackageCount = 3;
			AssertPickupDeliverySignature("Multiple, unique signatures", shipment, "Steve", "Steve2", "Multiple", "Multiple");

			packline.Delete();
			packline = shipment.OuterPackLines.AddNew();
			packline.JL_PackageCount = 0;
			shipment.DeliveryConfirms.DeleteAll();
			shipment.PickupConfirms.DeleteAll();
			AssertEquals("No signatures after delete all", "", shipment.DeliveryGoodsSignedForBy);
			AssertEquals("No signatures after delete all", "", shipment.PickupGoodsSignedForBy);

			packline.JL_PackageCount = 3;
			AssertPickupDeliverySignature("one blank signature", shipment, "", "", "", "");
			AssertPickupDeliverySignature("two blank signatures", shipment, "", "", "", "");
			AssertPickupDeliverySignature("Couple of blank signatures and a name", shipment, "Zubin", "Zubin2", "Multiple", "Multiple");

			ForwardingConsol consol = Factory.New<ForwardingConsol>();
			ForwardingContainer container1 = consol.Containers.AddNew();
			ForwardingContainer container2 = consol.Containers.AddNew();
			ForwardingShipment shipment1 = consol.Shipments.AddNew();
			ForwardingPackLine line1 = shipment1.OuterPackLines.AddNew();
			ForwardingPackLine line2 = shipment1.OuterPackLines.AddNew();
			line1.SetContainer(consol, container1);
			line2.SetContainer(consol, container2);
			CommonPickupDeliveryConfirm oConfirm1 = container1.OriginConfirm;
			CommonPickupDeliveryConfirm oConfirm2 = container2.OriginConfirm;
			CommonPickupDeliveryConfirm dConfirm1 = container1.DestinationConfirm;
			CommonPickupDeliveryConfirm dConfirm2 = container2.DestinationConfirm;

			AssertEquals("both blank", "", shipment1.PickupGoodsSignedForBy);
			AssertEquals("both blank", "", shipment1.DeliveryGoodsSignedForBy);

			oConfirm1.EU_GoodsSignForBy = "Zub";
			dConfirm1.EU_GoodsSignForBy = "Zub";
			AssertEquals("one & blank sig", "Multiple", shipment1.PickupGoodsSignedForBy);
			AssertEquals("one & blank sig", "Multiple", shipment1.DeliveryGoodsSignedForBy);

			oConfirm2.EU_GoodsSignForBy = "Zub";
			dConfirm2.EU_GoodsSignForBy = "Zub";
			AssertEquals("both same sig", "Zub", shipment1.PickupGoodsSignedForBy);
			AssertEquals("both same sig", "Zub", shipment1.DeliveryGoodsSignedForBy);

			oConfirm2.EU_GoodsSignForBy = "Zub2";
			dConfirm2.EU_GoodsSignForBy = "Zub2";
			AssertEquals("both dif sig", "Multiple", shipment1.PickupGoodsSignedForBy);
			AssertEquals("both dif sig", "Multiple", shipment1.DeliveryGoodsSignedForBy);
		}

		void AssertPickupDeliverySignature(ZString message, ForwardingShipment shipment, ZString pickupSign, ZString deliverySign, ZString expectedPickupSign, ZString expectedDeliverySign)
		{
			CommonPickupDeliveryConfirm pickupConfirm = shipment.PickupConfirms.AddNew();
			CommonPickupDeliveryConfirm deliveryConfirm = shipment.DeliveryConfirms.AddNew();
			pickupConfirm.EU_GoodsSignForBy = pickupSign;
			deliveryConfirm.EU_GoodsSignForBy = deliverySign;
			AssertEquals(message, expectedPickupSign, shipment.PickupGoodsSignedForBy);
			AssertEquals(message, expectedDeliverySign, shipment.DeliveryGoodsSignedForBy);
		}

