		public void TestCheckHVLVItemCountWithoutUsingFactoryLoad()
		{
			var shipment = Factory.New<ForwardingShipment>();

			var consignmentHeader = Factory.New<IHVLVConsignmentHeader>() as BusinessObject;
			consignmentHeader[HVLVConsignmentHeaderSchema.HCH_JS_Shipment.Name] = shipment.PK;

			var consignment = Factory.New<IHVLVConsignment>() as BusinessObject;
			consignment[HVLVConsignmentSchema.HVC_HCH_Header] = consignmentHeader.PK;
			consignment[HVLVConsignmentSchema.HVC_WaybillNumber] = "BOOKS";

			var item1 = Factory.New<IHVLVItem>();
			item1.HVI_HVC_Consignment = consignment.PK;
			item1.HVI_JS_LoadedOnShipment = shipment.PK;

			var item2 = Factory.New<IHVLVItem>();
			item2.HVI_HVC_Consignment = consignment.PK;
			item2.HVI_JS_LoadedOnShipment = shipment.PK;

			Factory.Save();

			var factoryForLoad = new BusinessObjectFactory();
			var reloadedShipment = factoryForLoad.Load<ForwardingShipment>(shipment.PK);
			item2 = reloadedShipment.HVLVItems.Cast<IHVLVItem>().Single(item => item.PK.Equals(item2.PK));
			item2.HVI_IsActive = false;

			var item3 = factoryForLoad.New<IHVLVItem>();
			item3.HVI_JS_LoadedOnShipment = shipment.PK;

			AssertEquals("The count of HVLVItem should equal 2.", 2, reloadedShipment.HVLVItemCount);
			AssertEquals("No hit from the Factory load.", 0, factoryForLoad.GetTableHitCount(HVLVItemSchema.Constants.Prefix));
		}

