		public void TestPackLineTotalsWithDifferentUnits()
		{
			ForwardingShipment shipment = (ForwardingShipment)GetShipment();
			shipment.OuterPackLines.RemoveAndDeleteAll();
			shipment.InnerPackLines.RemoveAndDeleteAll();

			PackLine inner1 = shipment.InnerPackLines.AddNew();
			inner1.JL_PackageCount = 2;
			inner1.JL_F3_NKPackType = Constants.PkgUnit.Carton;
			inner1.JL_ActualWeight = 10.0m;
			inner1.JL_ActualWeightUQ = Constants.Weight.Kilograms;
			inner1.JL_Length = 100;
			inner1.JL_Width = 50;
			inner1.JL_Height = 50;
			inner1.JL_UnitOfDimension = Constants.Length.Centimetres;
			inner1.JL_ActualVolumeUQ = Constants.Volume.CubicFeet;
			AssertEquals("Volume in CF.", 17.657m, ZArchitecture.Core.Utilities.Round(inner1.JL_ActualVolume, 3));

			PackLine inner2 = shipment.InnerPackLines.AddNew();
			inner2.JL_PackageCount = 10;
			inner2.JL_F3_NKPackType = Constants.PkgUnit.Box;
			inner2.JL_ActualWeight = 200;
			inner2.JL_ActualWeightUQ = Constants.Weight.Pounds;
			inner2.JL_Length = 1.5m;
			inner2.JL_Width = 1;
			inner2.JL_Height = 1;
			inner2.JL_UnitOfDimension = Constants.Length.Metres;
			inner2.JL_ActualVolumeUQ = Constants.Volume.CubicMetres;
			AssertEquals("Volume in M3.", 15m, inner2.JL_ActualVolume);

			AssertEquals("Inner Packs Total Packages.", 12, shipment.TotalInnerPackLinePackages);
			AssertEquals("Inner Packs Total Weight.", 100.718m, ZArchitecture.Core.Utilities.Round(shipment.TotalInnerPackLineWeight, 3));
			AssertEquals("Inner Packs Total Volume.", 15.5m, ZArchitecture.Core.Utilities.Round(shipment.TotalInnerPackLineVolume, 3));

			inner1.JL_ActualVolumeUQ = Constants.Volume.CubicMetres;
			inner2.JL_ActualWeightUQ = Constants.Weight.Kilograms;
			AssertEquals("Change Volume Unit.", 15.5m, shipment.TotalInnerPackLineVolume);
			AssertEquals("Change Weight Unit.", 210m, shipment.TotalInnerPackLineWeight);

			PackLine outer1 = shipment.OuterPackLines.AddNew();
			outer1.JL_PackageCount = 10;
			outer1.JL_ActualWeight = 100.2m;
			outer1.JL_ActualWeightUQ = Constants.Weight.Pounds;
			outer1.JL_ActualVolume = 0.9m;
			outer1.JL_ActualVolumeUQ = Constants.Volume.CubicFeet;
			AssertEquals("Outer Packs Total Packages.", 10, shipment.TotalOuterPacks);
			AssertEquals("Outer Packs Total Weight.", 45.450m, ZArchitecture.Core.Utilities.Round(shipment.TotalOuterPacksWeight, 3));
			AssertEquals("Outer Packs Total Volume.", 0.025m, ZArchitecture.Core.Utilities.Round(shipment.TotalOuterPacksVolume, 3));

			outer1.JL_ActualWeightUQ = Constants.Weight.Kilograms;
			outer1.JL_ActualVolumeUQ = Constants.Volume.CubicMetres;
			AssertEquals("Change Outer Weight Unit.", 100.2m, shipment.TotalOuterPacksWeight);
			AssertEquals("Change Outer Volume Unit.", 0.9m, shipment.TotalOuterPacksVolume);

			outer1.JL_UnitOfDimension = "iw";
			AssertEquals("Outer packlines total volume should not change if ud is invalid.", 0.9m, ZArchitecture.Core.Utilities.Round(shipment.TotalOuterPacksVolume, 1));
			outer1.JL_UnitOfDimension = ZString.Empty;
			AssertEquals("Outer packlines total volume should not change if ud is empty.", 0.9m, ZArchitecture.Core.Utilities.Round(shipment.TotalOuterPacksVolume, 1));
			outer1.JL_ActualVolumeUQ = "IE";
			AssertEquals("Outer packlines total volume should not change if uv is invalid.", 0.9m, ZArchitecture.Core.Utilities.Round(shipment.TotalOuterPacksVolume, 1));
			outer1.JL_ActualVolumeUQ = ZString.Empty;
			AssertEquals("Outer packlines total volume should not change if uv is empty.", 0.9m, ZArchitecture.Core.Utilities.Round(shipment.TotalOuterPacksVolume, 1));

			outer1.JL_UnitOfDimension = "iw";
			AssertEquals("Outer packlines total weight should not change if ud is invalid.", 100.2m, shipment.TotalOuterPacksWeight);
			outer1.JL_UnitOfDimension = ZString.Empty;
			AssertEquals("Outer packlines total weight should not change if ud is empty.", 100.2m, shipment.TotalOuterPacksWeight);
			outer1.JL_ActualWeightUQ = "IE";
			AssertEquals("Outer packlines total weight should not change if uw is invalid.", 100.2m, shipment.TotalOuterPacksWeight);
			outer1.JL_ActualWeightUQ = ZString.Empty;
			AssertEquals("Outer packlines total weight should not change if uw is empty.", 100.2m, shipment.TotalOuterPacksWeight);
		}

