		public void TestShipmentPackagesDetail()
		{
			ForwardingShipment shipment = (ForwardingShipment)GetShipment();
			shipment.InnerPackLines.RemoveAndDeleteAll();
			shipment.OuterPackLines.RemoveAndDeleteAll();
			shipment.JS_OuterPacks = 1;
			shipment.JS_TotalPackageCount = 10;
			shipment.JS_ActualWeight = 100;
			shipment.JS_ActualVolume = 1.5m;

			ForwardingShipment clone = (ForwardingShipment)shipment.Clone();
			AssertEquals("Should only be 1 inner packline in clone.", 1, clone.InnerPackLines.Count);
			AssertEquals("Outer packlines should not be cloned.", 1, clone.OuterPackLines.Count);
			clone.InnerPackLines[0].JL_PackageCount = 11;
			clone.InnerPackLines[0].JL_ActualWeight = 110m;
			clone.InnerPackLines[0].JL_ActualVolume = 2.5m;
			clone.UpdateShipmentFromInnerPackLines();
			AssertEquals("Package Count was updated.", 11, clone.JS_TotalPackageCount);
			AssertEquals("Weight was not updated.", 100m, clone.JS_ActualWeight);
			AssertEquals("Volume was not updated.", 1.5m, clone.JS_ActualVolume);
			AssertEquals("Default outer packline should not be created in clone.", 1, clone.OuterPackLines.Count);

			shipment.CopyPersistentValuesFrom(clone);
			AssertEquals("Package Count was not copied.", 11, shipment.JS_TotalPackageCount);
			AssertEquals("Weight was not copied.", 100m, shipment.JS_ActualWeight);
			AssertEquals("Volume was not copied.", 1.5m, shipment.JS_ActualVolume);
			AssertEquals("Default outer packline should be unchanged.", 1, shipment.OuterPackLines.Count);
		}

