		public void TestDefaultImportBrokerFromBuyerSupplierLink()
		{
			ZGuid airBroker = CreateOrgHeader().PK;
			ZGuid seaBroker = CreateOrgHeader().PK;
			ZGuid linkBroker = CreateOrgHeader().PK;
			ForwardingShipment shipment = (ForwardingShipment)GetShipment();
			shipment.JS_UniqueConsignRef = "S1010";
			shipment.OnExportOrImportBrokerUpdate += (sender, e) => { e.ShouldUpdateBroker = true; };

			//Setup a Consignee with default Air and Sea Broker
			OrgHeader consignee = Factory.New<OrgHeader>();
			consignee.OH_Code = "--CNEE--";
			consignee.OH_FullName = "Test Consignee";
			consignee.MainAddress.OA_Address1 = "Consignee Address";
			consignee.OH_IsConsignee = true;
			consignee.OH_RL_NKClosestPort = GlbBranch.CurrentBranch.HomePort.RL_Code;
			consignee.SetRelatedParty(airBroker, RelatedPartyTypeList.Codes.CustomsAgentBroker, RelatedPartyDirectionList.Codes.Delivery, Core.Constants.TransportModes.Air, ZString.Empty);
			consignee.SetRelatedParty(seaBroker, RelatedPartyTypeList.Codes.CustomsAgentBroker, RelatedPartyDirectionList.Codes.Delivery, Core.Constants.TransportModes.Sea, ZString.Empty);

			//Setup Consignor
			OrgHeader consignor = Factory.New<OrgHeader>();
			consignor.OH_Code = "--CNOR--";
			consignor.OH_FullName = "Test Consignor";
			consignor.MainAddress.OA_Address1 = "Consignor Address";
			consignor.OH_IsConsignor = true;
			consignor.OH_RL_NKClosestPort = "GBLON";

			//Setup Supplier Buyer Link with a different Import Broker
			OrgSupplierBuyerLink link = consignee.SupplierLinks.AddNew();
			link.OL_OH_Supplier = consignor.PK;
			link.OL_OH_ImportBroker = linkBroker;
			//Setup a second link on the consignee so consignor doesn't default
			(consignee.SupplierLinks.AddNew()).OL_OH_Supplier = CreateOrgHeader().PK;
			Factory.Save();

			//Clear any defaulted ports
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
			shipment.JS_RL_NKOrigin = "";
			shipment.JS_RL_NKDestination = "";
			shipment.ConsigneePK = consignee.PK;
			AssertEquals("Set Consignee, No Consignor - Import Broker should default from Consignee.", airBroker, shipment.JS_OH_ImportBroker);

			shipment.ConsignorPK = consignor.PK;
			AssertEquals("Set Consignor. Import Broker should not default from Buyer Supplier Link.", airBroker, shipment.JS_OH_ImportBroker);
		}

