		public void TestDefaultTransportAndContainerModeFromBuyerSupplierLink()
		{
			OrgHeader consignee = Factory.New<OrgHeader>();
			consignee.OH_Code = "--CNEE--";
			consignee.OH_FullName = "Test Consignee";
			consignee.MainAddress.OA_Address1 = "Consignee Address";
			consignee.OH_IsConsignee = true;
			consignee.OH_RL_NKClosestPort = GlbBranch.CurrentBranch.HomePort.RL_Code;

			OrgHeader consignor = Factory.New<OrgHeader>();
			consignor.OH_Code = "--CNOR--";
			consignor.OH_FullName = "Test Consignor";
			consignor.MainAddress.OA_Address1 = "Consignor Address";
			consignor.OH_IsConsignor = true;
			consignor.OH_RL_NKClosestPort = "GBLON";

			OrgSupplierBuyerLink link = consignee.SupplierLinks.AddNew();
			link.OL_OH_Supplier = consignor.PK;

			OrgSupBuyLinkTrnMode transport = link.OrgSupBuyLinkTrnModes[0];
			transport.PF_TransportMode = "SEA";
			transport.PF_ContainerMode = "LCL";

			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.ConsignorPK = consignor.PK;
			shipment.ConsigneePK = consignee.PK;
			AssertEquals("FCL. Transport default from Buyer Supplier Link.", "SEA", shipment.JS_TransportMode);
			AssertEquals("Container is not default from Buyer Supplier Link.", "FCL", shipment.JS_PackingMode);

			transport.PF_TransportMode = "AIR";
			transport.PF_ContainerMode = "BLK";
			shipment = Factory.New<ForwardingShipment>();
			shipment.ConsignorPK = consignor.PK;
			shipment.ConsigneePK = consignee.PK;
			AssertEquals("AIR. Transport default from Buyer Supplier Link.", "AIR", shipment.JS_TransportMode);
			AssertEquals("BLK is not containirised so packing mode should not be changed, here it stays LSE as when transport mode is set to AIR  then it set containerMode to LSE.", "LSE", shipment.JS_PackingMode);
		}

