		public void TestINCOUpdatesOnAddingConsingorAndConsigneeRelationship()
		{
			OrgHeader consignee = Factory.New<OrgHeader>();
			consignee.OH_Code = "*CNEE*";
			consignee.OH_FullName = "Test Consignee";
			consignee.MainAddress.OA_Address1 = "Consignee Address";
			consignee.OH_RL_NKClosestPort = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			consignee.OH_IsConsignee = true;
			consignee.MiscServ.OM_IMDefaultINCOTerm = Constants.IncoTerms.ExWorks;

			OrgHeader consignor = Factory.New<OrgHeader>();
			consignor.OH_Code = "*CNOR*";
			consignor.OH_FullName = "Test Consignor";
			consignor.MainAddress.OA_Address1 = "Consignor Address";
			consignor.OH_IsConsignor = true;
			consignor.MiscServ.OM_EXDefaultIncoTerm = Constants.IncoTerms.DeliveredDutyPaid;

			OrgHeader consignor2 = Factory.New<OrgHeader>();
			consignor2.OH_Code = "*CNOR2*";
			consignor2.OH_FullName = "Second Consignor";
			consignor2.MainAddress.OA_Address1 = "Consignor Two Address";
			consignor2.OH_IsConsignor = true;
			consignor2.MiscServ.OM_EXDefaultIncoTerm = Constants.IncoTerms.FreeCarrier;

			ForwardingShipment shipment = (ForwardingShipment)GetShipment();
			AssertEquals("Pre-requisite: shipment's starting JS_INCO should be empty", ZString.Empty, shipment.JS_INCO);

			shipment.ConsignorPK = consignor.PK;
			AssertEquals("No Consignee, default to Inco on Consignor.", Constants.IncoTerms.DeliveredDutyPaid, shipment.JS_INCO);

			shipment.JS_INCO = ZString.Empty;
			shipment.ConsigneePK = consignee.PK;
			AssertEquals("Default to Inco on Consignee.", Constants.IncoTerms.ExWorks, shipment.JS_INCO);

			shipment.JS_INCO = ZString.Empty;
			shipment.ConsignorPK = consignor2.PK;
			AssertEquals("Consignee exists, Inco should not change", Constants.IncoTerms.ExWorks, shipment.JS_INCO);

			shipment.ConsignorPK = ZGuid.Empty;
			shipment.ConsigneePK = ZGuid.Empty;

			OrgSupplierBuyerLink link = consignee.SupplierLinks.AddNew(consignor);
			shipment.JS_TransportMode = Constants.TransportModes.Sea;
			shipment.JS_RL_NKDestination = "USLAX";
			link.OL_RN_NKImporterCountry = Constants.CountryCodes.UnitedStates;
			link.OrgSupBuyLinkTrnModes[0].PF_IncoTerm = Constants.IncoTerms.CarriagePaidTo;
			Factory.Save();

			shipment.ConsigneePK = consignee.PK;
			AssertEquals("Should have found Buyer/Supplier link.", consignor.PK, shipment.ConsignorPK);
			AssertEquals("Should overwrite existing INCO with default INCO from link.", Constants.IncoTerms.CarriagePaidTo, shipment.JS_INCO);

			shipment.ConsigneePK = ZGuid.Empty;
			shipment.IsDomesticFreight = true;
			AssertEquals("Pre-requisite: shipment's starting JS_INCO should be set to empty", ZString.Empty, shipment.JS_INCO);

			shipment.ConsigneePK = consignee.PK;
			AssertEquals("Should have found Buyer/Supplier link.", consignor.PK, shipment.ConsignorPK);
			AssertEquals("Should NOT update INCO from link if INCO is not in the incoterm list.", ZString.Empty, shipment.JS_INCO);

			link.OrgSupBuyLinkTrnModes[0].PF_IncoTerm = Constants.DomesticPaymentTerms.CollectCOD;
			shipment.ConsigneePK = ZGuid.Empty;

			shipment.ConsigneePK = consignee.PK;
			AssertEquals("Should have found Buyer/Supplier link.", consignor.PK, shipment.ConsignorPK);
			AssertEquals("Should overwrite existing INCO with default INCO from link as INCO Is a valid domestic INCOTERM.", Constants.DomesticPaymentTerms.CollectCOD, shipment.JS_INCO);
		}

		public void TestINCOUpdatesOnMatchingShipmentToConsignorConsigneeRelationship()
		{
			OrgHeader consignor = Factory.New<OrgHeader>();
			consignor.OH_Code = "*CNOR*";
			consignor.OH_FullName = "Test Consignor";
			consignor.MainAddress.OA_Address1 = "Consignor Address";
			consignor.OH_IsConsignor = true;
			consignor.MiscServ.OM_EXDefaultIncoTerm = Constants.IncoTerms.FreeOnBoard;

			OrgHeader consignee = Factory.New<OrgHeader>();
			consignee.OH_Code = "*CNEE*";
			consignee.OH_FullName = "Test Consignee";
			consignee.MainAddress.OA_Address1 = "Consignee Address";
			consignee.OH_RL_NKClosestPort = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			consignee.OH_IsConsignee = true;
			consignee.MiscServ.OM_IMDefaultINCOTerm = Constants.IncoTerms.ExWorks;

			ForwardingShipment shipment = (ForwardingShipment)GetShipment();
			shipment.JS_TransportMode = Constants.TransportModes.Air;
			shipment.JS_PackingMode = Constants.ContainerModes.Loose;
			shipment.JS_INCO = Constants.IncoTerms.DeliveredAtTerminal;

			shipment.ConsignorPK = consignor.PK;
			AssertEquals("INCO term already populated, no buyer/supplier link: should not be updated to Consignor INCO", Constants.IncoTerms.DeliveredAtTerminal, shipment.JS_INCO);

			shipment.ConsigneePK = consignee.PK;
			AssertEquals("INCO term already populated, no buyer/supplier link: should not be updated to Consignee INCO", Constants.IncoTerms.DeliveredAtTerminal, shipment.JS_INCO);

			OrgSupplierBuyerLink link = consignee.SupplierLinks.AddNew(consignor);
			link.OrgSupBuyLinkTrnModes[0].PF_TransportMode = Constants.TransportModes.Sea;
			link.OrgSupBuyLinkTrnModes[0].PF_ContainerMode = Constants.ContainerModes.FCL;
			link.OrgSupBuyLinkTrnModes[0].PF_IncoTerm = Constants.IncoTerms.CostAndFreight;
			Factory.Save();

			shipment.JS_TransportMode = Constants.TransportModes.Sea;
			shipment.JS_PackingMode = Constants.ContainerModes.FCL;
			AssertEquals("Should now override existing INCO with INCO from link when shipment transport mode and container modes match Buyer/Supplier link", Constants.IncoTerms.CostAndFreight, shipment.JS_INCO);

			link.OrgSupBuyLinkTrnModes[0].PF_IncoTerm = ZString.Empty;
			Factory.Save();

			shipment.JS_INCO = ZString.Empty;
			shipment.JS_TransportMode = Constants.TransportModes.Air;
			AssertEquals("Should default back to consignee INCO term when Buyer/Seller link not found and shipment INCO term is empty", Constants.IncoTerms.ExWorks, shipment.JS_INCO);

			shipment.JS_TransportMode = Constants.TransportModes.Sea;
			AssertEquals("Buyer/Seller link exist but INCO term is empty: should not override existing one with empty one", Constants.IncoTerms.ExWorks, shipment.JS_INCO);

			shipment.JS_TransportMode = Constants.TransportModes.Air;
			shipment.JS_INCO = ZString.Empty;
			shipment.JS_TransportMode = Constants.TransportModes.Sea;
			AssertEquals("Buyer/Seller link exist but INCO term is empty: should leave existing INCO term on shipment unchanged", ZString.Empty, shipment.JS_INCO);
		}

