		public void TestFallbackFirstArrivalProperties()
		{
			ZDateTime currentTime = new ZDateTime(2008, 1, 3);
			ForwardingShipment shipment = (ForwardingShipment)GetShipment();
			shipment.JS_E_ARV = currentTime;
			shipment.JS_RL_NKDestination = "AUSYD";
			AssertEquals("shipment not on consol", "AUSYD", shipment.FallbackPortOfFirstArrival);
			AssertEquals("shipment not on consol", currentTime, shipment.FallbackPortOfFirstArrivalETA);
			ForwardingConsol consol = GetConsol();
			consol.JK_TransportMode = Core.Constants.TransportModes.Sea;
			consol.JK_RL_NKLoadPort = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			consol.JK_RL_NKDischargePort = "AUADL";
			consol.Shipments.Add(shipment);
			Transport transport = consol.Transports.ArrivalTransport;
			AssertNotNull(transport);
			transport.JW_ETA = currentTime.AddDays(1);
			transport.JW_RL_NKDiscPort = "AUMEL";
			AssertEquals("use arrival transport", "AUMEL", shipment.FallbackPortOfFirstArrival);
			AssertEquals("ause rrival transport", currentTime.AddDays(1), shipment.FallbackPortOfFirstArrivalETA);
			consol.JK_DatePortOfFirstArrival = currentTime.AddDays(2);
			consol.JK_RL_NKPortOfFirstArrival = "AUBNE";
			AssertEquals("use consol", "AUBNE", shipment.FallbackPortOfFirstArrival);
			AssertEquals("use consol", currentTime.AddDays(2), shipment.FallbackPortOfFirstArrivalETA);
		}

