		[TestDate(2008, 1, 15, 1, 2, 3)]
		public void TestOverdueCargoReportException()
		{
			var testDate = new ZDateTimeOffset(new ZDateTime(2008, 1, 15, 1, 2, 3));
			StmEvent cRAEvent = Factory.LoadFromNaturalKey<StmEvent>(StmEventSchema.SE_Code, Events.CargoReportAccepted.Code);
			cRAEvent.SE_AirExceptionSafetyMargin = 24;
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Enterprise.Core.Constants.TransportModes.Air;
			shipment.JS_RL_NKDestination = "AUSYD";
			shipment.JS_E_ARV = testDate.ToZDateTime();
			AssertNull("No exception", shipment.OverdueCargoReportException);
			ProcessTask mileStone = shipment.WorkflowItems.Milestones.AddNew();
			mileStone.TriggerConditions.TriggerEventCode = ((IParentForCargoReporter)shipment).CargoReportAcceptedEvent.Code;
			mileStone.SetMilestoneScheduledDateForTest(testDate.AddHours(-25));
			AssertNull("No exception", shipment.OverdueCargoReportException);
			ProcessTask mileStoneException = mileStone.CreateMilestoneException();
			AssertEquals(((IParentForCargoReporter)shipment).CargoReportAcceptedEvent.Code, mileStoneException.TriggerConditions.TriggerEventCode);
			AssertEquals("Overdue Exception returned", mileStoneException, shipment.OverdueCargoReportException);
			mileStone.SetMilestoneScheduledDateForTest(testDate);
			AssertNull("No exception", shipment.OverdueCargoReportException);
		}

		[TestDate(2008, 1, 15, 1, 2, 3)]
		public void TestIsCargoReportOverdue()
		{
			var testDate = new ZDateTimeOffset(new ZDateTime(2008, 1, 15, 1, 2, 3));
			StmEvent cRAEvent = Factory.LoadFromNaturalKey<StmEvent>(StmEventSchema.SE_Code, Events.CargoReportAccepted.Code);
			cRAEvent.SE_AirExceptionSafetyMargin = 24;
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Enterprise.Core.Constants.TransportModes.Air;
			shipment.JS_RL_NKDestination = "AUSYD";
			shipment.JS_E_ARV = testDate.ToZDateTime();
			ProcessTask milestone = shipment.WorkflowItems.Milestones.AddNew();
			milestone.TriggerConditions.TriggerEventCode = ((IParentForCargoReporter)shipment).CargoReportAcceptedEvent.Code;
			Assert("Invalide scheduled date", !shipment.IsCargoReportOverdue(milestone));
			milestone.SetMilestoneScheduledDateForTest(testDate.AddHours(-25));
			Assert("Is overdue", shipment.IsCargoReportOverdue(milestone));
			milestone.SetMilestoneScheduledDateForTest(testDate);
			Assert("Is not overdue", !shipment.IsCargoReportOverdue(milestone));
			milestone.SetMilestoneScheduledDateForTest(testDate.AddHours(-25));
			Assert("Is overdue again", shipment.IsCargoReportOverdue(milestone));
			milestone.SetMilestoneActualDateForTest(testDate);
			Factory.Save();
			Assert("Milestone is closed", milestone.IsClosed);
			Assert("Milestone closed, so is not overdue", !shipment.IsCargoReportOverdue(milestone));
		}

