		public void TestGetAddressBookSelection_AUDeclaration()
		{
			var auShipment = Factory.New<ForwardingShipment>();
			var selection = ((ISendEmailSource)auShipment).GetAddressBookSelection();
			AssertEquals("No declaration yet", 0, selection.Recipients.Count);

			var auSupplier = Factory.NewWithValidTestData<OrgHeader>();
			var auSupplierContact = auSupplier.Contacts.AddNew();

			var auDeclaration = Factory.NewWithValidTestData(ObjectFactory.GetType<AU.IJobDeclaration>());
			((AU.IJobDeclaration)auDeclaration).JE_OH_Supplier = auSupplier.PK;
			AssertEquals("AU declaration implements ISendEmailSource", true, auDeclaration is ISendEmailSource);
			selection = ((ISendEmailSource)auDeclaration).GetAddressBookSelection();
			AssertEquals("Pre-condition", 1, selection.Recipients.Count);
			AssertEquals("Pre-condition", true, selection.Recipients.Contains(auSupplierContact));

			((AU.IJobDeclaration)auDeclaration).JE_JS = auShipment.PK;
			Factory.Save();
			AssertEquals("AU Customs Declaration attached", true, auShipment.Declarations.Contains((IBaseJobDeclaration)auDeclaration));
			selection = ((ISendEmailSource)auShipment).GetAddressBookSelection();
			AssertEquals(1, selection.Recipients.Count);
			AssertEquals(true, selection.Recipients.Contains(auSupplierContact));
		}

