		#region TestNumberOfHAWBMenuItems

		public void TestNumberOfHAWBMenuItems()
		{
			DocumentZQuery filter = new DocumentZQuery("Shipment");

			ZQuery doumentNames = new ZQuery(StmMenuItemSchema.SU_MenuName, SQLComparisonOperator.Contains, "HAWB");
			doumentNames.AddToFilter(JoinCondition.Or, StmMenuItemSchema.SU_MenuName, SQLComparisonOperator.EndsWith, "House Bill");
			filter.AddToFilter(doumentNames, JoinCondition.And);

			StmMenuItem[] menuItems = Factory.Load<StmMenuItem>(filter);

			ZString reasonForMakingSureYouKnowWhatYouAreDoing =
				"The ForwardingShipment.GetDataStateBeforeRun() method makes checks on menu item name.\n" +
				"It does not allow HAWB menu items to be run on a direct consol.\n" +
				"Since this test is failing you may have renamed a HAWB menu item, which would make\n" +
				"GetDataStateBeforeRun() fail to work properly.\n" +
				"To make this test pass, make sure that GetDataStateBeforeRun() will still function correctly\n" +
				"then change the number of expected menu items in the AssertEquals.";

			AssertEquals(reasonForMakingSureYouKnowWhatYouAreDoing, 14, menuItems.Length);
		}

