		public void TestSetDefaultsOnOrder()
		{
			OrgHeader consignor = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader consignee = Factory.NewWithValidTestData<OrgHeader>();

			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Constants.TransportModes.Air;
			shipment.JS_PackingMode = Constants.ContainerModes.ULD;
			shipment.JS_F3_NKPackType = Constants.PkgUnit.Bottle;
			shipment.ConsignorPK = consignor.PK;
			shipment.ConsigneePK = consignee.PK;
			shipment.JS_GoodsDescription = "DESCRIPTION";
			shipment.JS_RS_NKServiceLevel = "STD";
			shipment.JS_INCO = Constants.IncoTerms.CostAndFreight;

			Order order = Factory.New<Order>();
			shipment.SetDefaultsOnOrder(order);
			AssertEquals("Transport defaulted from shipment", Constants.TransportModes.Air, order.JD_TransportMode);
			AssertEquals("Container defaulted from shipment", Constants.ContainerModes.ULD, order.JD_ContainerMode);
			AssertEquals("PackType defaulted from shipment", Constants.PkgUnit.Bottle, order.JD_F3_NKPackType);
			AssertEquals("Buyer defaulted from shipment", consignee.PK, order.BuyerPK);
			AssertEquals("Supplier defaulted from shipment", consignor.PK, order.SupplierPK);
			AssertEquals("Description defaulted from shipment", "DESCRIPTION", order.JD_OrderGoodsDescription);
			AssertEquals("Service defaulted from shipment", "STD", order.ServiceLevel_NI.RS_Code);
			AssertEquals("INCO defaulted from shipment", Constants.IncoTerms.CostAndFreight, order.JD_IncoTerm);

			OrgHeader sendingAgent = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader receivingAgent = Factory.NewWithValidTestData<OrgHeader>();

			ForwardingConsol consol = shipment.Consols.AddNew();
			consol.JK_OA_SendingForwarderAddress = sendingAgent.MainAddress.PK;
			consol.JK_OA_ReceivingForwarderAddress = receivingAgent.MainAddress.PK;

			order = Factory.New<Order>();
			AssertEquals("Precondition", ZGuid.Empty, order.JD_OH_SendingAgent);
			AssertEquals("Precondition", ZGuid.Empty, order.JD_OH_ReceivingAgent);

			shipment.SetDefaultsOnOrder(order);
			AssertEquals("SendingAgent from consol", sendingAgent.PK, order.JD_OH_SendingAgent);
			AssertEquals("ReceivingAgent from consol", receivingAgent.PK, order.JD_OH_ReceivingAgent);

			shipment.Consols.AddNew();
			AssertEquals("Precondition", 2, shipment.Consols.Count);

			order = Factory.New<Order>();
			shipment.SetDefaultsOnOrder(order);
			AssertEquals("Many consols on shipment, don't set agent", ZGuid.Empty, order.JD_OH_SendingAgent);
			AssertEquals("Many consols on shipment, don't set agent", ZGuid.Empty, order.JD_OH_ReceivingAgent);

			order = Factory.New<Order>();
			order.BuyerPK = consignee.PK;
			order.SupplierPK = consignor.PK;

			shipment = Factory.New<ForwardingShipment>();
			shipment.SetDefaultsOnOrder(order);
			AssertEquals("No consignee on shipment => buyer not changed", consignee.PK, order.BuyerPK);
			AssertEquals("No consignor on shipment => supplier not changed", consignor.PK, order.SupplierPK);

			var shipment2 = Factory.New<ForwardingShipment>();
			shipment2.JS_TransportMode = Constants.TransportModes.Sea;
			shipment2.JS_PackingMode = Constants.ContainerModes.ShippersConsol;

			var order2 = Factory.New<Order>();
			shipment2.SetDefaultsOnOrder(order2);
			AssertEquals(Constants.ContainerModes.LCL, order2.JD_ContainerMode);
		}

