		public void TestOnNewGenericOrder_OrderRefDoesNotClearWithoutSave()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.DocsAndCartage.JP_OrderItemsAsString = "Gazorpazorp";
			Factory.Save();

			AssertEquals("Precondition: Shipment should not have orders yet", 0, shipment.GenericOrders.Count);
			AssertEquals("Precondition: Shipment should have Order Ref", "Gazorpazorp", shipment.DocsAndCartage.JP_OrderItemsAsString);
			Assert("Precondition: Shipment without Orders should have editable Order Ref", !shipment.DocsAndCartage.JP_OrderItemsAsStringInfo.ReadOnly);

			var warehouseOrder = (BusinessObject)Factory.New<IWhsOrder>();
			warehouseOrder.FillWithValidTestData();
			shipment.GenericOrders.Add(warehouseOrder);

			AssertEquals("Shipment should now have one warehouse order", 1, shipment.GenericOrders.Count);
			Assert("Order Ref should be read-write without saving", !shipment.DocsAndCartage.JP_OrderItemsAsStringInfo.ReadOnly);
			Assert("Order Ref should remain without saving", !shipment.DocsAndCartage.JP_OrderItemsAsString.IsEmpty);

			shipment.GenericOrders.Remove(warehouseOrder);
			shipment.DocsAndCartage.JP_OrderItemsAsString = "Froopyland";

			Factory.Save();

			AssertEquals("Shipment should now have no warehouse orders", 0, shipment.GenericOrders.Count);
			Assert("Order Ref should refresh and not be readonly", !shipment.DocsAndCartage.JP_OrderItemsAsStringInfo.ReadOnly);
			AssertEquals("Order Ref should remain", shipment.DocsAndCartage.JP_OrderItemsAsString, "Froopyland");
		}

		public void TestHasChangesNotSetAfterTransaction()
		{
			var shipment = Factory.New<ForwardingShipment>();
			Factory.Save();

			var whsOrder = (BusinessObject)Factory.New<IWhsOrder>();
			whsOrder.FillWithValidTestData();
			shipment.GenericOrders.Add(whsOrder);

			var hasChangesCalledAfterTransactions = false;

			shipment.DocsAndCartage.JP_OrderItemsAsString = "0123456";
			shipment.HasChangesChanged += (sender, e) =>
			{
				if (((IBusinessObjectFactoryInternals)Factory).IsProcessingOnAllTransactionsCommitted && e.ObjectJustWasChanged)
				{
					hasChangesCalledAfterTransactions = true;
				}
			};

			Factory.Save();
			AssertEquals("Changes should not be made after factory transactions are committed.", false, hasChangesCalledAfterTransactions);
		}

