			Factory.Save();

			OrderForTesting order = Factory.NewWithValidTestData<OrderForTesting>();
			AssertEquals("Precondition", false, order.IsInDatabase);
			AssertEquals("Precondition", false, order.IsPopulateShipmentCalled);

			shipment.OnOrderAttached(order);
			AssertEquals("PopulateShipment not called on unsaved order", false, order.IsPopulateShipmentCalled);

			Factory.Save();

			AssertEquals("Precondition", true, order.IsInDatabase);
			AssertEquals("Precondition", false, order.IsPopulateShipmentCalled);

			shipment.OnOrderAttached(order);
			AssertEquals("PopulateShipment was called on order", true, order.IsPopulateShipmentCalled);
		}

