		public void TestCreatePackLinesFromOrderLines()
		{
			Order order1 = Factory.NewWithValidTestData<Order>();
			order1.OrderLines.AddNew();
			order1.OrderLines.AddNew();

			Order order2 = Factory.NewWithValidTestData<Order>();
			order2.OrderLines.AddNew();
			Factory.Save();

			ForwardingShipment shipment = (ForwardingShipment)GetShipment();
			shipment.OnOrderLineToPackLineConversion += new EventHandler<OrderLineToPackLineConversionEventArgs>((sender, e) => e.ShouldCreatePacklines = true);
			AssertEquals("Precondition: no attached orders", 0, shipment.AttachedOrders.Count);
			AssertEquals("Precondition: no packlines", 0, shipment.OuterPackLines.Count);

			shipment.AttachedOrders.AddRange(new Order[] { order1, order2 });
			AssertEquals("Two orders attached", 2, shipment.AttachedOrders.Count);
			AssertEquals("No packlines were created from orderlines", 0, shipment.OuterPackLines.Count);

			shipment.CreatePackLinesFromOrderLines(new Order[] { order1, order2 });
			AssertEquals("No new orders attached", 2, shipment.AttachedOrders.Count);
			AssertEquals("Packlines were created from orderlines", 3, shipment.OuterPackLines.Count);
		}

