		public void TestQueryAttachRelatedOrder()
		{
			OrgHeader buyer = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader supplier = Factory.NewWithValidTestData<OrgHeader>();

			Order order = Factory.New<Order>();
			order.BuyerPK = buyer.PK;
			order.SupplierPK = supplier.PK;
			order.JD_TransportMode = Constants.TransportModes.Sea;
			order.JD_ContainerMode = Constants.ContainerModes.FCL;

			Factory.Save();

			bool shipmentWasQueried = false;
			ShipmentDomainService.GetInstance(Factory).AttachRelatedOrderRequest += (s, e) => { shipmentWasQueried = true; };

			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Constants.TransportModes.Sea;
			shipment.JS_PackingMode = Constants.ContainerModes.FCL;

			AssertEquals("Precondition", 0, shipment.AttachedOrders.Count);
			AssertEquals("Precondition", 0, shipment.StrictlyMatchedRelatedOrders.Count);

			shipment.ConsigneePK = buyer.PK;
			AssertEquals("Event not triggered yet", false, shipmentWasQueried);

			shipment.ConsignorPK = supplier.PK;
			AssertEquals("Matched related orders found", 1, shipment.StrictlyMatchedRelatedOrders.Count);
			AssertEquals("Event should have been triggered", true, shipmentWasQueried);

			shipment.ConsigneePK = ZGuid.Empty;
			shipment.ConsignorPK = ZGuid.Empty;
			shipmentWasQueried = false;

			shipment.ConsignorPK = supplier.PK;
			AssertEquals("Event not triggered yet", false, shipmentWasQueried);

			shipment.ConsigneePK = buyer.PK;
			AssertEquals("Matched related orders found", 1, shipment.StrictlyMatchedRelatedOrders.Count);
			AssertEquals("Event should have been triggered", true, shipmentWasQueried);
		}

		public void TestStrictlyMatchedRelatedOrders()
		{
			OrgHeader buyer = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader supplier = Factory.NewWithValidTestData<OrgHeader>();

			Order orderFCL = Factory.New<Order>();
			orderFCL.JD_OrderNumber = "1";
			orderFCL.BuyerPK = buyer.PK;
			orderFCL.SupplierPK = supplier.PK;
			orderFCL.JD_TransportMode = Constants.TransportModes.Sea;
			orderFCL.JD_ContainerMode = Constants.ContainerModes.FCL;

			Order orderLCL = Factory.New<Order>();
			orderLCL.JD_OrderNumber = "2";
			orderLCL.BuyerPK = buyer.PK;
			orderLCL.SupplierPK = supplier.PK;
			orderLCL.JD_TransportMode = Constants.TransportModes.Sea;
			orderLCL.JD_ContainerMode = Constants.ContainerModes.LCL;

			Factory.Save();

			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			AssertEquals("Precondition", 0, shipment.StrictlyMatchedRelatedOrders.Count);

			shipment.JS_TransportMode = Constants.TransportModes.Sea;
			shipment.ConsigneePK = buyer.PK;
			shipment.ConsignorPK = supplier.PK;
			shipment.JS_PackingMode = Constants.ContainerModes.LCL;

			AssertContainsExactElementsInAnyOrder("Strictly matched related orders should contain LCL only",
				new Order[] { orderLCL }, shipment.StrictlyMatchedRelatedOrders);

			shipment.JS_PackingMode = Constants.ContainerModes.FCL;
			AssertContainsExactElementsInAnyOrder("Strictly matched related orders should contain FCL only",
				new Order[] { orderFCL }, shipment.StrictlyMatchedRelatedOrders);

			shipment.JS_PackingMode = Constants.ContainerModes.BuyersConsol;
			AssertContainsExactElementsInAnyOrder("Strictly matched related orders should contain LCL only",
				new Order[] { orderLCL }, shipment.StrictlyMatchedRelatedOrders);

			shipment.JS_PackingMode = Constants.ContainerModes.ShippersConsol;
			AssertContainsExactElementsInAnyOrder("Strictly matched related orders should contain LCL only",
				new Order[] { orderLCL }, shipment.StrictlyMatchedRelatedOrders);

			orderLCL.BuyerPK = Factory.NewWithValidTestData<OrgHeader>().PK;
			AssertEquals("No orders should be matched", 0, shipment.StrictlyMatchedRelatedOrders.Count);

			orderLCL.BuyerPK = buyer.PK;
			AssertContainsExactElementsInAnyOrder("Strictly matched related orders should contain LCL only",
				new Order[] { orderLCL }, shipment.StrictlyMatchedRelatedOrders);

			orderLCL.JD_JE = Factory.New<IBaseJobDeclaration>().PK;
			AssertEquals("No orders should be matched", 0, shipment.StrictlyMatchedRelatedOrders.Count);
		}

