		public void TestManualRegenerateHouseBillNumber_ShouldBeResetWhenOnSavingFails_NoLog()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_HouseBill = "ORIGIN";
			Factory.Save();

			try
			{
				var org = Factory.New<OrgHeader>();
				org.OH_Code = "abc";
				org.OH_ScreeningStatus = "abc";
				shipment.RegenerateHouseBillNumber(true);
				Factory.Save();

				Fail("Should not reach this point because org headers has invalid column. That org has no relevance to this test other than to ensure saving will fail.");
			}
			catch (ZSaveException) { }

			Assert(!shipment.JS_HouseBillInfo.HasChanges);
			AssertEquals("Saving was not successful and JS_HouseBill should remain the origin value", "ORIGIN", shipment.JS_HouseBill);
			AssertEquals("No CID Log", 0, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.ChangeOfIdentifier.Code).Count());
		}

