			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_UniqueConsignRef = "S0002001";
			shipment.JS_HouseBill = "BILL2001";
			shipment.JS_ShipmentType = Constants.ShipmentTypes.StandardHouse;
			shipment.JS_TransportMode = Constants.TransportModes.Sea;
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "BRGIG";
			shipment.JS_ElectronicBillOfLadingStatus = "SUR";
			shipment.JS_ElectronicBillOfLadingHouseBill = "BILL20011";

			Factory.Save();
			AssertNoWarnings(shipment.JS_HouseBillInfo);

			using (FreightDataRegistry.Instance.EnableBoleroEHBLIntegration.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, boleroEBLConfiguration))
			{
				foreach (var status in readOnlyStatuses)
				{
					shipment.JS_ElectronicBillOfLadingStatus = status;
					Assert(shipment.JS_HouseBillInfo.ReadOnly);
					Assert(!shipment.JS_ElectronicBillOfLadingHouseBillInfo.ReadOnly);
				}

				foreach (var status in notReadOnlyStatuses)
				{
					shipment.JS_ElectronicBillOfLadingStatus = status;
					Assert(!shipment.JS_HouseBillInfo.ReadOnly);
					Assert(!shipment.JS_ElectronicBillOfLadingHouseBillInfo.ReadOnly);
				}

				foreach (var transportMode in transportModes)
				{
					shipment.JS_TransportMode = transportMode;
					shipment.JS_ElectronicBillOfLadingStatus = readOnlyStatuses.First();
					Assert(!shipment.JS_HouseBillInfo.ReadOnly);
					Assert(!shipment.JS_ElectronicBillOfLadingHouseBillInfo.ReadOnly);
				}
			}

			boleroEBLConfiguration.EnableEBLIntegration = false;
			using (FreightDataRegistry.Instance.EnableBoleroEHBLIntegration.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, boleroEBLConfiguration))
			{
				shipment.JS_TransportMode = Constants.TransportModes.Sea;
				shipment.JS_ElectronicBillOfLadingStatus = readOnlyStatuses.First();
				Assert(!shipment.JS_HouseBillInfo.ReadOnly);
				Assert(!shipment.JS_ElectronicBillOfLadingHouseBillInfo.ReadOnly);
			}
		}

		public void TestRegenerateHouseBillNumber()
		{
			BillOfLadingNumberCustomisationsByServiceLevel customisations = new BillOfLadingNumberCustomisationsByServiceLevel();
			BillOfLadingNumberCustomisation allCustomisation = customisations.BillOfLadingNumberCustomisations["ALL"];
			BillOfLadingNumberCustomisation stdCustomisation = customisations.BillOfLadingNumberCustomisations.AddNew();
			stdCustomisation.ServiceLevel = "STD";
			BillOfLadingNumberCustomisation d2dCustomisation = customisations.BillOfLadingNumberCustomisations.AddNew();
			d2dCustomisation.ServiceLevel = "D2D";

			foreach (BillOfLadingNumberCustomisation customisation in customisations.BillOfLadingNumberCustomisations)
			{
				customisation.RemoveFountainPrefix = true;
				foreach (BillOfLadingNumberCustomisationElement element in customisation.Elements)
				{
					switch (element.Key)
					{
						case BillOfLadingNumberCustomisationElement.Keys.SequenceNumber:
							element.Include = true;
							element.Detail = "6";
							element.Order = 50;
							break;

						case BillOfLadingNumberCustomisationElement.Keys.ClientCoded1:
							element.Include = true;
							element.Detail = customisation.ServiceLevel.SubstringSafe(0, 2);
							element.Fountain = true;
							element.Order = 1;
							break;

						case BillOfLadingNumberCustomisationElement.Keys.ServiceLevel:
							element.Include = true;
							element.Order = 2;
							break;

						default:
							element.Include = false;
							break;
					}
				}
			}

			FreightDataRegistry.Instance.HouseBillNumberCustomisation.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, customisations);

			ForwardingShipment shipment = Factory.New<ForwardingShipment>();

			BusinessObjectFactory.SavingEventHandler generationDelegate = null;
			generationDelegate = delegate
			{
				shipment.RegenerateHouseBillNumber();
			};

			Factory.Saving += generationDelegate;

			shipment.JS_RS_NKServiceLevel = "";
			Factory.Save();
			AssertEquals("AL000001", shipment.JS_HouseBill);

			shipment.JS_RS_NKServiceLevel = "STD";
			Factory.Save();
			AssertEquals("STSTD000001", shipment.JS_HouseBill);

			shipment.JS_RS_NKServiceLevel = "D2D";
			Factory.Save();
			AssertEquals("D2D2D000001", shipment.JS_HouseBill);

			shipment.JS_RS_NKServiceLevel = "";
			Factory.Save();
			AssertEquals("AL000002", shipment.JS_HouseBill);

			shipment.JS_RS_NKServiceLevel = "STD";
			Factory.Save();
			AssertEquals("STSTD000002", shipment.JS_HouseBill);

			shipment.JS_RS_NKServiceLevel = "D2D";
			Factory.Save();
			AssertEquals("D2D2D000002", shipment.JS_HouseBill);

			Factory.Saving -= generationDelegate;
		}

		public void TestRegenerateHouseBillNumber_ShouldBeResetWhenOnSavingFails()
		{
			var airCustomisations = CreateCustomisations("CC");
			FreightDataRegistry.Instance.HouseBillNumberCustomisation_AIR.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, airCustomisations);

			var shipment = Factory.New<ForwardingShipment>();

			shipment.JS_TransportMode = Constants.TransportModes.Air;
			shipment.JS_RS_NKServiceLevel = "";
			shipment.JS_RL_NKOrigin = "AUSYD";

			Factory.Save();

			var expectedHouseBill = "CCALA000001";
			AssertEquals(expectedHouseBill, shipment.JS_HouseBill);

			BusinessObjectFactory.SavingEventHandler generationDelegate = delegate
			{
				shipment.RegenerateHouseBillNumber();
			};

			Factory.Saving += generationDelegate;

			try
			{
				shipment.JS_RS_NKServiceLevel = "STD";
				var org = Factory.New<OrgHeader>();
				org.OH_Code = "abc";
				org.OH_ScreeningStatus = "abc";

				Factory.Save();

				Fail("Should not reach this point because org headers has invalid column. That org has no relevance to this test other than to ensure saving will fail.");
			}
			catch (ZSaveException) { }

			Assert(!shipment.JS_HouseBillInfo.HasChanges);
			AssertEquals("Saving was not successful JS_UniqueConsignRef number should remain the same", expectedHouseBill, shipment.JS_HouseBill);

			Factory.Saving -= generationDelegate;
		}

