		public void TestHouseBillCheckDigitValidationCanBeApplied()
		{
			BillOfLadingNumberCustomisationsByServiceLevel seaCustomisations = CreateCustomisations("BB");
			FreightDataRegistry.Instance.HouseBillNumberCustomisation_SEA.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, seaCustomisations);

			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
			shipment.JS_RS_NKServiceLevel = "STD";
			shipment.JS_RL_NKOrigin = "AUSYD";

			AssertEquals("House bill is not autogenerated for air", true, shipment.HouseBillCheckDigitValidationCanBeApplied);

			shipment.JS_HouseBill = "ABCDEF";
			AssertEquals("Can still check after edit", true, shipment.HouseBillCheckDigitValidationCanBeApplied);

			Factory.Save();

			BusinessObjectFactory reloadFactory = new BusinessObjectFactory();
			ForwardingShipment reloadedShipment = reloadFactory.Load<ForwardingShipment>(shipment.PK);

			AssertEquals("Can't check house bill for shipment loaded from database.", false, shipment.HouseBillCheckDigitValidationCanBeApplied);

			reloadedShipment.JS_HouseBill = "ABC123";

			AssertEquals("Can check the house bill if it has changed.", true, reloadedShipment.HouseBillCheckDigitValidationCanBeApplied);

			shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			shipment.JS_RS_NKServiceLevel = "";
			shipment.JS_RL_NKOrigin = "AUSYD";

			Factory.Save();

			Assert("Autogenerated HBL number", !shipment.JS_HouseBill.IsEmpty);
			AssertEquals("House bill is autogenerated", false, shipment.HouseBillCheckDigitValidationCanBeApplied);

			reloadedShipment = reloadFactory.Load<ForwardingShipment>(shipment.PK);

			AssertEquals("Can't check house bill for reloaded shipment", false, reloadedShipment.HouseBillCheckDigitValidationCanBeApplied);

			reloadedShipment.JS_HouseBill = "XYZ789";

			AssertEquals("Can check the house bill if it has been changed", true, reloadedShipment.HouseBillCheckDigitValidationCanBeApplied);

			shipment.JS_HouseBill = "VWXYZ";

			AssertEquals("Can check the house bill if autogenerated number is subsequently changed.", true, shipment.HouseBillCheckDigitValidationCanBeApplied);
		}

