			var header = Factory.LoadTop1<IHVLVConsignmentHeader>(new ZQuery(HVLVConsignmentHeaderSchema.HCH_JS_Shipment, shipment.PK)) as BusinessObject;
			header.FillWithValidTestData();

			var consignment = Factory.New<IHVLVConsignment>() as BusinessObject;
			consignment.FillWithValidTestData();
			consignment[HVLVConsignmentSchema.HVC_HCH_Header.Name] = header.PK;
			consignment[HVLVConsignmentSchema.HVC_OA_ConsigneeAddress.Name] = consigneeAddress.PK;

			Factory.Save();

			using (HVLVDataRegistry.Instance.HVLVEnablePartyScreening.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new HVLVEnablePartyScreening() { EnableHVLVPartyScreening = false }))
			{
				var screeningParties = ((IScreeningPartyProvider)shipment).ScreeningParties;
				AssertNull("Does not contain candidates from consignment header, registry is currently not enabled", screeningParties.SingleOrDefault(x => x.OrgCode == "CONSIGNEE"));
			}

			using (HVLVDataRegistry.Instance.HVLVEnablePartyScreening.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new HVLVEnablePartyScreening() { EnableHVLVPartyScreening = true }))
			{
				var screeningParties = ((IScreeningPartyProvider)shipment).ScreeningParties;
				AssertNotNull("Contains candidates from consignment header, registry is enabled", screeningParties.SingleOrDefault(x => x.OrgCode == "CONSIGNEE"));
			}

			using (HVLVDataRegistry.Instance.HVLVEnablePartyScreening.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new HVLVEnablePartyScreening() { EnableHVLVPartyScreening = true }))
			{
				shipment.JS_ShipmentType = ShipmentTypes.StandardHouse;
				var screeningParties = ((IScreeningPartyProvider)shipment).ScreeningParties;
				AssertNull("Does not contains candidates from consignment header, shipment type is not HVL", screeningParties.SingleOrDefault(x => x.OrgCode == "CONSIGNEE"));
			}
		}

