		public void TestScreeningPartiesWhenHaveChildShipments()
		{
			var shipment = CreateShipment(Constants.ShipmentTypes.BuyersConsolLead, Constants.ShipmentTypes.ShippersConsolLead);
			AssertScreeningPartiesWhenHaveChildShipments(shipment, false, false);

			shipment = CreateShipment(Constants.ShipmentTypes.ShippersConsolLead, Constants.ShipmentTypes.ThirdPartyOwnershipHouse);
			AssertScreeningPartiesWhenHaveChildShipments(shipment, false, false);

			shipment = CreateShipment(Constants.ShipmentTypes.AssemblyMaster, Constants.ShipmentTypes.BuyersConsolLead);
			AssertScreeningPartiesWhenHaveChildShipments(shipment, true, false);

			shipment = CreateShipment(Constants.ShipmentTypes.BlindCoLoadMaster, Constants.ShipmentTypes.CoLoadMaster);
			AssertScreeningPartiesWhenHaveChildShipments(shipment, true, true);
		}

		void AssertScreeningPartiesWhenHaveChildShipments(ForwardingShipment shipment, bool shouldHaveSecondLayerScreeningParties, bool shouldHaveThirdLayerScreeningParties)
		{
			var deniedCandidates = ((IScreeningPartyProvider)shipment).ScreeningParties.ToList();
			var secondLayerScreeningParties = ((IScreeningPartyProvider)shipment.CoLoadShipments.First()).ScreeningParties.ToList();
			var thirdLayerScreeningParties = ((IScreeningPartyProvider)(shipment.CoLoadShipments.First() as ForwardingShipment).CoLoadShipments.First()).ScreeningParties.ToList();

			CombineAssertions(() =>
			{
				AssertEquals(0, thirdLayerScreeningParties.Count(x => x.Description == "Local Client"));
				AssertEquals(1, thirdLayerScreeningParties.Count(x => x.Description == "Export CFS"));

				if (shouldHaveSecondLayerScreeningParties && shouldHaveThirdLayerScreeningParties)
				{
					AssertEquals("Second layer should have 'Local Client', it comes from itself.", 1, secondLayerScreeningParties.Count(x => x.Description == "Local Client"));
					AssertEquals("Second layer should have 'Export CFS', it comes from third layer.", 1, secondLayerScreeningParties.Count(x => x.Description == "Export CFS"));

					AssertEquals("First layer should have 'Local Client', it comes from second layer.", 1, deniedCandidates.Count(x => x.Description == "Local Client"));
					AssertEquals("First layer should have 'Export CFS', it comes from third layer.", 1, deniedCandidates.Count(x => x.Description == "Export CFS"));
				}
				else if (shouldHaveSecondLayerScreeningParties)
				{
					AssertEquals("Second layer should have 'Local Client', it comes from itself.", 1, secondLayerScreeningParties.Count(x => x.Description == "Local Client"));
					AssertEquals("Second layer should not have 'Export CFS'.", 0, secondLayerScreeningParties.Count(x => x.Description == "Export CFS"));

					AssertEquals("First layer should have 'Local Client', it comes from second layer.", 1, deniedCandidates.Count(x => x.Description == "Local Client"));
					AssertEquals("First layer should not have 'Export CFS'.", 0, deniedCandidates.Count(x => x.Description == "Export CFS"));
				}
				else
				{
					AssertEquals("First layer should not have 'Local Client'", 0, deniedCandidates.Count(x => x.Description == "Local Client"));
					AssertEquals("First layer should not have 'Export CFS'", 0, deniedCandidates.Count(x => x.Description == "Export CFS"));
				}
			});
		}

		ForwardingShipment CreateShipment(string shipmentType, string subShipmentType)
		{
			var masterShipment = Factory.NewWithValidTestData<ForwardingShipment>();
			masterShipment.JS_ShipmentType = shipmentType;

			var secondLayerShipment = Factory.NewWithValidTestData<ForwardingShipment>();
			secondLayerShipment.JS_ShipmentType = subShipmentType ?? shipmentType;
			var localClient = Factory.NewWithValidTestData<OrgHeader>();
			var job = Factory.NewJobForTesting<JobHeader>();
			job.JH_GB = GlbBranch.CurrentBranch.PK;
			job.JH_GC = GlbCompany.CurrentCompany.PK;
			job.JH_GE = GlbDepartment.CurrentDepartment.PK;
			job.JH_ParentID = secondLayerShipment.PK;
			job.JH_OA_LocalChargesAddr = localClient.MainAddress.PK;
			job.JH_JobNum = "ABC123";

			var thirdLayerShipment = Factory.NewWithValidTestData<ForwardingShipment>();
			var exportReceivingDepot = Factory.NewWithValidTestData<OrgHeader>();
			thirdLayerShipment.JS_OA_ExportReceivingDepot = exportReceivingDepot.MainAddress.PK;

			masterShipment.CoLoadShipments.Add(secondLayerShipment);
			secondLayerShipment.CoLoadShipments.Add(thirdLayerShipment);
			Factory.Save();

			return masterShipment;
		}

