		public void TestScreeningStatusUpdatedWithReplacedParty_DocAddress()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			var docAddressOrg = Factory.NewWithValidTestData<OrgHeader>();
			var docAddressOrgMatched = Factory.NewWithValidTestData<OrgHeader>();

			var docAddress = Factory.NewWithValidTestData<JobDocAddress>();
			docAddress.E2_AddressOverride = false;
			docAddress.E2_ParentID = shipment.PK;
			docAddress.E2_ParentTableCode = "JS";
			docAddress.E2_OA_Address = docAddressOrg.MainAddress.PK;

			Factory.Save();
			AssertEquals("Shipment's Screening Status", ScreeningStatusesList.Codes.NotScreened, shipment.JS_ScreeningStatus);

			docAddressOrgMatched.OH_ScreeningStatus = ScreeningStatusesList.Codes.Matched;
			docAddress.E2_OA_Address = docAddressOrgMatched.MainAddress.PK;
			Factory.Save();

			AssertEquals("Shipment's Screening Status", ScreeningStatusesList.Codes.Matched, shipment.JS_ScreeningStatus);

			docAddress.E2_OA_Address = docAddressOrg.MainAddress.PK;
			Factory.Save();

			AssertEquals("Shipment's Screening Status", ScreeningStatusesList.Codes.NotScreened, shipment.JS_ScreeningStatus);

			docAddress.E2_AddressOverride = true;
			(docAddress as IScreeningStatusProvider).ScreeningStatus = "MAT";

			AssertEquals("Shipment's Screening Status", ScreeningStatusesList.Codes.Matched, (shipment as IScreeningPartyProvider).GetWorstScreeningStatus());
		}

