		public void TestParentShipmentScreeningStatusWhenChangingSubShipment()
		{
			AssertParentShipmentScreeningStatusWhenChangingSubShipment(Constants.ShipmentTypes.AssemblyMaster, true);
			AssertParentShipmentScreeningStatusWhenChangingSubShipment(Constants.ShipmentTypes.CoLoadMaster, true);
			AssertParentShipmentScreeningStatusWhenChangingSubShipment(Constants.ShipmentTypes.BlindCoLoadMaster, true);

			AssertParentShipmentScreeningStatusWhenChangingSubShipment(Constants.ShipmentTypes.BuyersConsolLead, false);
			AssertParentShipmentScreeningStatusWhenChangingSubShipment(Constants.ShipmentTypes.ShippersConsolLead, false);
			AssertParentShipmentScreeningStatusWhenChangingSubShipment(Constants.ShipmentTypes.ThirdPartyOwnershipHouse, false);
		}

		void AssertParentShipmentScreeningStatusWhenChangingSubShipment(string shipmentType, bool shouldUpdate)
		{
			var clearedOrg = Factory.NewWithValidTestData<OrgHeader>();
			var matchedOrg = Factory.NewWithValidTestData<OrgHeader>();
			var unknownOrg = Factory.NewWithValidTestData<OrgHeader>();
			Factory.Save();

			clearedOrg.OH_ScreeningStatus = ScreeningStatusesList.Codes.Clear;
			matchedOrg.OH_ScreeningStatus = ScreeningStatusesList.Codes.Matched;
			unknownOrg.OH_ScreeningStatus = ScreeningStatusesList.Codes.Unknown;
			Factory.Save();

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_ShipmentType = shipmentType;

			var subShipment = Factory.NewWithValidTestData<ForwardingShipment>();
			subShipment.JS_OH_ExportBroker = clearedOrg.PK;
			shipment.CoLoadShipments.Add(subShipment);
			Factory.Save();

			AssertEquals("PreCondition", ScreeningStatusesList.Codes.Clear, shipment.JS_ScreeningStatus);

			subShipment.JS_OH_ExportBroker = matchedOrg.PK;
			Factory.Save();
			AssertEquals(shouldUpdate ? ScreeningStatusesList.Codes.Matched : ScreeningStatusesList.Codes.Clear, shipment.JS_ScreeningStatus);

			subShipment.JS_OH_ExportBroker = unknownOrg.PK;
			Factory.Save();
			AssertEquals(shouldUpdate ? ScreeningStatusesList.Codes.Unknown : ScreeningStatusesList.Codes.Clear, shipment.JS_ScreeningStatus);

			subShipment.JS_OH_ExportBroker = clearedOrg.PK;
			Factory.Save();
			AssertEquals(shouldUpdate ? ScreeningStatusesList.Codes.Clear : ScreeningStatusesList.Codes.Clear, shipment.JS_ScreeningStatus);
		}

		public void TestParentConsolScreeningStatusWhenChangingSubShipment()
		{
			var clearedOrg = Factory.NewWithValidTestData<OrgHeader>();
			var matchedOrg = Factory.NewWithValidTestData<OrgHeader>();
			var unknownOrg = Factory.NewWithValidTestData<OrgHeader>();
			Factory.Save();

			clearedOrg.OH_ScreeningStatus = ScreeningStatusesList.Codes.Clear;
			matchedOrg.OH_ScreeningStatus = ScreeningStatusesList.Codes.Matched;
			unknownOrg.OH_ScreeningStatus = ScreeningStatusesList.Codes.Unknown;
			Factory.Save();

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_OH_ExportBroker = clearedOrg.PK;
			consol.Shipments.Add(shipment);
			Factory.Save();

			AssertEquals("PreCondition", ScreeningStatusesList.Codes.Clear, consol.JK_ScreeningStatus);

			shipment.JS_OH_ExportBroker = matchedOrg.PK;
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.Matched, consol.JK_ScreeningStatus);

			shipment.JS_OH_ExportBroker = unknownOrg.PK;
			consol.Transports.Cast<Transport>().ForEach(o => o.JW_IsLinked = true);
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.Unknown, consol.JK_ScreeningStatus);

			shipment.JS_OH_ExportBroker = clearedOrg.PK;
			consol.Transports.Cast<Transport>().ForEach(o => o.JW_IsLinked = true);
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.Clear, consol.JK_ScreeningStatus);
		}

