		void AssertParentConsolScreeningStatus(bool expectedParentShouldUpdateScreeningStatus, string childPreviousStatus, string childSetStatus, string parentPreviousStatus, string parentExpectedStatus = null)
		{
			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_ScreeningStatus = childPreviousStatus;
			Factory.Save();
			(consol.Transports.FirstOrDefault() as Transport).JW_TransportMode = TransportModes.Sea;
			(consol.Transports.FirstOrDefault() as Transport).JW_Vessel = "TestCode";
			consol.Shipments.Add(shipment);
			Factory.Save();

			consol.JK_ScreeningStatus = parentPreviousStatus;
			Factory.Save();
			AssertEquals(parentPreviousStatus, consol.JK_ScreeningStatus);

			shipment.JS_ScreeningStatus = childSetStatus;
			if (shipment.JS_ScreeningStatus == ScreeningStatusesList.Codes.JobCleared)
			{
				(shipment as IShouldUpdateScreeningStatus).ShouldUpdateScreeningStatus = true;
			}

			var consolShouldUpdateScreeningStatus = (consol as IShouldUpdateScreeningStatus).ShouldUpdateScreeningStatus;
			AssertEquals(expectedParentShouldUpdateScreeningStatus, consolShouldUpdateScreeningStatus);

			Factory.Save();
			if (consolShouldUpdateScreeningStatus)
			{
				AssertEquals(parentExpectedStatus, consol.JK_ScreeningStatus);
			}
			else
			{
				AssertEquals(parentPreviousStatus, consol.JK_ScreeningStatus);
			}
		}

