		void AssertColoadMasterShipmentScreeningStatus(bool expectedParentShouldUpdateScreeningStatus, string childPreviousStatus, string childSetStatus, string parentPreviousStatus, string parentExpectedStatus = null)
		{
			var parentShipment = Factory.NewWithValidTestData<ForwardingShipment>();
