			parentShipment.CoLoadShipments.Add(childShipment);
			Factory.Save();

			parentShipment.JS_ScreeningStatus = parentPreviousStatus;
			Factory.Save();
			AssertEquals(parentPreviousStatus, parentShipment.JS_ScreeningStatus);

			childShipment.JS_ScreeningStatus = childSetStatus;
			if (childShipment.JS_ScreeningStatus == ScreeningStatusesList.Codes.JobCleared)
			{
				(childShipment as IShouldUpdateScreeningStatus).ShouldUpdateScreeningStatus = true;
			}

			var parentShipmentShouldUpdateScreeningStatus = (parentShipment as IShouldUpdateScreeningStatus).ShouldUpdateScreeningStatus;
			AssertEquals(expectedParentShouldUpdateScreeningStatus, parentShipmentShouldUpdateScreeningStatus);

			Factory.Save();
			if (parentShipmentShouldUpdateScreeningStatus)
			{
				AssertEquals(parentExpectedStatus, parentShipment.JS_ScreeningStatus);
			}
			else
			{
				AssertEquals(parentPreviousStatus, parentShipment.JS_ScreeningStatus);
			}
		}

