				AssertEquals(notifyParty.PK, suggestions.Single(s => s.organisationType == "Notify Party").orgHeader.PK);
				AssertEquals(localClient.PK, suggestions.Single(s => s.organisationType == "Local Client").orgHeader.PK);
				AssertEquals(exportBroker.PK, suggestions.Single(s => s.organisationType == "Export Broker").orgHeader.PK);
				AssertEquals(pickupCartage.PK, suggestions.Single(s => s.organisationType == "Pickup Local Transport Company").orgHeader.PK);
				AssertEquals(pickupAgent.PK, suggestions.Single(s => s.organisationType == "Pickup Agent").orgHeader.PK);
				AssertEquals(exportReceivingDepot.PK, suggestions.Single(s => s.organisationType == "Export CFS").orgHeader.PK);
				AssertEquals(importBroker.PK, suggestions.Single(s => s.organisationType == "Import Broker").orgHeader.PK);
				AssertEquals(deliveryCartage.PK, suggestions.Single(s => s.organisationType == "Delivery Local Transport Company").orgHeader.PK);
				AssertEquals(deliveryAgent.PK, suggestions.Single(s => s.organisationType == "Delivery Agent").orgHeader.PK);
				AssertEquals(importReleaseDepot.PK, suggestions.Single(s => s.organisationType == "Import CFS").orgHeader.PK);
			});
		}

