		#region TestCloneInternalConsiderAllColumnsWithoutDuplicatesWhenCopyingToBooking

		public void TestCloneInternalConsiderAllColumnsWithoutDuplicatesWhenCopyingToBooking()
		{
			var columns = ObjectFactory.Get<IApplicationSchemaResolver>().GetSchemaColumns("JobShipment");

			var unhandledColumns = new StringBuilder();
			var duplicatedColumns = new StringBuilder();
			var testDescription = @"Description: If you are adding a new column to JobShipment, please consider the situation when it is cloned to booking and please make sure you add the column name to
									EITHER BookingExcludedColumns in ForwardingShipment class (which means it won't be copied to booking) OR IncludedColumns below this test.";

			foreach (SchemaColumn column in columns)
			{
				bool isIncluded = false;
				bool isExcluded = false;

				if (IncludedColumns.Contains(column.Name))
				{
					isIncluded = true;
				}

				if (ForwardingShipment.BookingExcludedColumns.Contains(column.Name))
				{
					isExcluded = true;
				}

				if (isIncluded && isExcluded)
				{
					duplicatedColumns.AppendLine(column.Name);
				}

				if (!isIncluded && !isExcluded)
				{
					unhandledColumns.AppendLine(column.Name);
				}
			}

			var summaryMessage = "";

			if (!unhandledColumns.ToString().IsNullOrEmpty())
			{
				summaryMessage = "UNHANDLED COLUMNS: Please handle the following column(s) and add it(them) to ONE OF the arrays as description suggests:"
								+ System.Environment.NewLine
								+ unhandledColumns;
			}

			if (!duplicatedColumns.ToString().IsNullOrEmpty())
			{
				summaryMessage += "AMBIGUOUS COLUMNS: Please remove following column(s) from one of the arrays as it(they) can't be at both in the same time:"
								+ System.Environment.NewLine
								+ duplicatedColumns;
			}

			Assert(summaryMessage + System.Environment.NewLine + testDescription, summaryMessage.IsNullOrEmpty());
		}

		#region TestClone_JobDocAddressesEnumerationWorks

		PhaseSecurity GetPhaseSecurityForTesting_ConsigneePK()
		{
			var locationsList = PhaseConstants.GetShipmentLocationsList();

			var security = new PhaseSecurity(locationsList);
			security.IsEnabled = true;

			var phase = security.Phases.AddNew();
			phase.Code = "AAA";
			phase.Description = (NoResString)"AAA Phase Description";

			var rule = phase.Rules.AddNew();
			rule.Location = PhaseConstants.Locations.AnyLocation;
			rule.DepartmentPK = GlbDepartment.CurrentDepartment.PK;

			Action<PhaseRule, string> addDependant = (phaseRule, dependantName) =>
			{
				var dependant = phaseRule.Dependants.AddNew();
				dependant.DependantType = PhaseConstants.DependantType.Property;
				dependant.Name = dependantName;
				dependant.Description = dependantName + "Description";
				dependant.IsMandatory = true;
			};

			addDependant(rule, "ConsigneePK");

			security.Phases.Add(phase);

			return security;
		}

		public void TestClone_JobDocAddressesEnumerationWorks()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_Phase = "AAA";

			shipment.ConsigneeDocumentaryAddress.E2_OA_Address = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;
			shipment.ConsignorDocumentaryAddress.E2_OA_Address = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;
			shipment.ControllingCustomerAddress.E2_OA_Address = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;
			shipment.ControllingCustomerAddress.E2_GovRegNumType = "CNO";

			var controllingAgentAddress = shipment.DocAddresses.AddNew(DocAddressType.ControllingAgent);
			controllingAgentAddress.E2_OA_Address = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;
			shipment.DocAddresses.RemoveAndDelete(shipment.DocAddresses.FindByDocAddressType(DocAddressType.ConsigneePickupDeliveryAddress));

			Factory.Save();

			using (ForwardingConfigurationRegistry.Instance.ShipmentPhaseSecurity.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, GetPhaseSecurityForTesting_ConsigneePK()))
			{
				var factoryNew = new BusinessObjectFactory();
				var factoryNew2 = new BusinessObjectFactory();

				var reloadedShipment = factoryNew.Load<ForwardingShipment>(shipment.PK);

				Assert("precondition: has no consignee pickup/delivery address", !reloadedShipment.DocAddresses.ContainsDocAddressType(DocAddressType.ConsigneePickupDeliveryAddress));
				AssertNoExceptionThrown("ensure JobDocAddress enumeration doesn't fail", () => reloadedShipment.TemplateCopy(factoryNew2));
				Assert("side effect: DocAddress is added to fulfil ConsigneePickupDeliveryAddress requirement for ConsigneeDocumentaryAddress", reloadedShipment.DocAddresses.ContainsDocAddressType(DocAddressType.ConsigneePickupDeliveryAddress));
			}
		}

