			using (GlbCompany.CurrentCompany.TemporarilySetCountry(CountryCodes.UnitedStates))
			{
				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();

				var header1 = Factory.New<US.InBond.ICusInBondHeader>();
				header1.BH_ParentID = shipment.PK;
				header1.BH_ParentTableCode = shipment.TablePrefix;
				header1.BH_CarrierSCAC = "AAA";

