				{
					var shipmentWithInBond = Factory.LoadTop1<ForwardingShipment>(new ZQuery(JobShipmentSchema.PK, shipment.PK));
					var auClonedShipment = (ForwardingShipment)shipmentWithInBond.TemplateCopy();
