		public void TestDefaultConsolSelfFiler_WhenChangingConsignee()
		{
			var unloco = Factory.New<RefUNLOCO>();
			unloco.RL_Code = "NO!2#";

			var org1 = Factory.New<OrgHeader>();
			org1.OH_Code = "org1";
			org1.OH_IsConsignee = true;
			org1.MiscServ.OM_IMAdvanceCargoReportingSelfFiler = true;

			var org2 = Factory.New<OrgHeader>();
			org2.OH_Code = "org2";
			org2.OH_IsConsignee = true;
			org2.MiscServ.OM_IMAdvanceCargoReportingSelfFiler = true;

			var existingRelationShip = org1.AllRelatedParties.AddNew();
			existingRelationShip.PR_PartyType = RelatedPartyTypeList.Codes.SelfFilerForICS2;
			existingRelationShip.PR_OH_RelatedParty = org2.PK;
			existingRelationShip.PR_Location = unloco.RL_Code;
			existingRelationShip.PR_FreightTransportMode = TransportModes.Sea;

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.JK_AgentType = AgentType.Direct;
			consol.JK_RL_NKDischargePort = "NO!2#";
			consol.JK_RL_NKLoadPort = "AUSYD";
			consol.JK_OA_ReceivingForwarderAddress = org1.MainAddress.PK;

			var transport = consol.Transports.AddNew();
			transport.JW_TransportMode = TransportModes.Sea;
			transport.JW_RL_NKLoadPort = "AUSYD";
			transport.JW_RL_NKDiscPort = "NO!2#";

			var shipment = consol.Shipments.AddNew();
			shipment.JS_TransportMode = TransportModes.Sea;
			shipment.JS_ShipmentType = ShipmentTypes.StandardHouse;

			Factory.Save();
			shipment.ConsigneePK = org1.PK;
			var selfFiler = consol.DocAddresses.FindByDocAddressType(DocAddressType.SelfFiler);

			AssertNotNull(selfFiler);
			AssertEquals(org1.PK, selfFiler.OrganisationPK);

			shipment.ConsigneePK = ZGuid.Empty;
			selfFiler = consol.DocAddresses.FindByDocAddressType(DocAddressType.SelfFiler);

			AssertNull(selfFiler);

			org1.MiscServ.OM_IMAdvanceCargoReportingSelfFiler = false;
			shipment.ConsigneePK = org1.PK;
			selfFiler = consol.DocAddresses.FindByDocAddressType(DocAddressType.SelfFiler);

			AssertNotNull(selfFiler);
			AssertEquals(org2.PK, selfFiler.OrganisationPK);
		}

		public void TestConsigneeConsignorControllingCustomerDefaulting()
		{
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = "AIR";

			OrgHeader consignee = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader consignor = Factory.NewWithValidTestData<OrgHeader>();

			shipment.ConsigneeDocumentaryAddress.OrganisationPK = consignee.PK;
			shipment.ConsignorDocumentaryAddress.OrganisationPK = consignor.PK;
			var controllingCustomer = Factory.NewWithValidTestData<OrgHeader>();
			OrgSupplierBuyerLink supplierBuyerLink = consignee.SupplierLinks.AddNew(consignor);
			supplierBuyerLink.OrgSupBuyLinkTrnModes[0].PF_TransportMode = "ALL";
			supplierBuyerLink.OrgSupBuyLinkTrnModes[0].PF_OH_ControllingCustomer = controllingCustomer.PK;

			OrgHeader localClient = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader localControllingCustomer = Factory.NewWithValidTestData<OrgHeader>();

			localClient.AllRelatedParties.AddNew();
			localClient.AllRelatedParties[0].PR_OH_RelatedParty = localControllingCustomer.PK;
			localClient.AllRelatedParties[0].PR_PartyType = RelatedPartyTypeList.Codes.ControllingCustomer;
			localClient.AllRelatedParties[0].PR_FreightDirection = RelatedPartyDirectionList.Codes.PickupAndDelivery;

			shipment.JS_UniqueConsignRef = "1234";
			var job = new JobHeader.Loader(shipment).TryCreate();
			job.JH_GE = GlbDepartment.CurrentDepartment.PK;
			job.JH_GB = GlbBranch.CurrentBranch.PK;
			job.LocalChargesPK = localClient.PK;

			FreightDataRegistry.Instance.DefaultShipmentControllingCustomer.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, false);
			shipment.DefaultControllingCustomer(shipment.BuyerSupplierLinksHelper?.GetControllingCustomer(), false);
			AssertEquals(null, shipment.DocAddresses.FindByDocAddressType(DocAddressType.ControllingCustomer).Organisation);

			FreightDataRegistry.Instance.DefaultShipmentControllingCustomer.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
			shipment.DefaultControllingCustomer(shipment.BuyerSupplierLinksHelper?.GetControllingCustomer(), false);
			AssertEquals(controllingCustomer, shipment.DocAddresses.FindByDocAddressType(DocAddressType.ControllingCustomer).Organisation);

			Factory.Save();
			OrgHeader consignor2 = Factory.NewWithValidTestData<OrgHeader>();
			shipment.ConsignorDocumentaryAddress.OrganisationPK = consignor2.PK;
			shipment.DefaultControllingCustomer(shipment.BuyerSupplierLinksHelper?.GetControllingCustomer(), false);
			AssertEquals(controllingCustomer, shipment.DocAddresses.FindByDocAddressType(DocAddressType.ControllingCustomer).Organisation);
		}

