		public void TestSetJS_ShipmentType()
		{
			OrgHeader org1 = Factory.NewWithValidTestData<OrgHeader>();
			org1.OH_Code = "aaa";
			org1.OH_FullName = "bbb";

			OrgHeader org2 = Factory.NewWithValidTestData<OrgHeader>();
			org2.OH_Code = "ccc";
			org2.OH_FullName = "ddd";

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.JK_RL_NKDischargePort = "NZAKL";
			consol.JK_RL_NKLoadPort = "AUSYD";

			var shipment = consol.Shipments.AddNew();
			shipment.JS_RL_NKDestination = "NZAKL";
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_PackingMode = Constants.ContainerModes.BuyersConsol;
			shipment.JS_ShipmentType = Constants.ShipmentTypes.BuyersConsolLead;
			shipment.ConsignorPK = org2.PK;

			var subShipment = consol.Shipments.AddNew();
			subShipment.JS_RL_NKDestination = "NZAKL";
			subShipment.JS_RL_NKOrigin = "AUSYD";
			subShipment.JS_ShipmentType = Constants.ShipmentTypes.AssemblyMaster;

			var notificationMessage = "Only Assembly Master shipments can have sub-shipments that are neither Standard House nor HVLV Shipper Consolidation (Legacy) shipments.";

			AssertNoNotifications(notificationMessage, subShipment.JS_ShipmentTypeInfo);

			subShipment.JS_JS_ColoadMasterShipment = shipment.PK;

			AssertHasNotifications(notificationMessage, subShipment.JS_ShipmentTypeInfo);

			subShipment.JS_JS_ColoadMasterShipment = ZGuid.Empty;

			AssertNoNotifications(notificationMessage, subShipment.JS_ShipmentTypeInfo);
		}

		void AssertJS_OH_HandledOnBehalfOfForwarder_FromConsignee(ZString masterType)
		{
			var org1 = Factory.NewWithValidTestData<OrgHeader>();
			var org2 = Factory.NewWithValidTestData<OrgHeader>();
			var org3 = Factory.NewWithValidTestData<OrgHeader>();

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.JK_RL_NKDischargePort = "AUSYD";
			consol.JK_RL_NKLoadPort = "NZAKL";
			consol.JK_IsCFS = true;
			consol.JK_IsForwarding = true;

			var shipment = consol.Shipments.AddNew();
			shipment.JS_RL_NKDestination = "AUSYD";
			shipment.JS_RL_NKOrigin = "NZAKL";
			shipment.JS_ShipmentType = masterType;
			shipment.ConsigneePK = org2.PK;

			var subShipment = consol.Shipments.AddNew();
			subShipment.JS_RL_NKDestination = "AUSYD";
			subShipment.JS_RL_NKOrigin = "NZAKL";
			subShipment.JS_ShipmentType = Constants.ShipmentTypes.StandardHouse;
			subShipment.JS_IsCFSRegistered = true;
