		public void TestOriginChanged_SetsDefaultCFS()
		{
			OrgHeader orgFallback = Factory.New<OrgHeader>();
			OrgHeader orgAU = Factory.New<OrgHeader>();
			OrgHeader orgMEL = Factory.New<OrgHeader>();

			OrgHeader mainOrg = Factory.New<OrgHeader>();
			mainOrg.MainAddress.OA_Address1 = "TEST";

			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			shipment.JS_PackingMode = Core.Constants.ContainerModes.Bulk;
			shipment.JS_RL_NKDestination = "NZAKL";
			shipment.ConsignorDocumentaryAddress.OrganisationPK = mainOrg.PK;

			mainOrg.SetRelatedParty(orgFallback, RelatedPartyTypeList.Codes.ClientCFS, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.All, ZString.Empty);
			mainOrg.SetRelatedParty(orgAU, RelatedPartyTypeList.Codes.ClientCFS, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.All, ZString.Empty, "AU");
			mainOrg.SetRelatedParty(orgMEL, RelatedPartyTypeList.Codes.ClientCFS, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.All, ZString.Empty, "AUMEL");

			AssertEquals(ZGuid.Empty, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);

			shipment.JS_RL_NKOrigin = "AUBNE";
			AssertEquals(orgAU.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);

			shipment.JS_RL_NKOrigin = "AUMEL";
			AssertEquals(orgMEL.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);

			shipment.JS_RL_NKOrigin = "SGSIN";
			AssertEquals(orgFallback.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);
		}

		public void TestOriginChanged_DefaultPickupCFSFromTransitTimeZoneOwner_FallbackToCFSRelatedParty()
		{
			var serviceLevel = "STD";
			var postCode = "2234";
			var country = Constants.CountryCodes.Australia;

			var orgCFSRelatedPartyForAir = Factory.NewWithValidTestData<OrgHeader>();
			var orgCFSRelatedPartyForAUAir = Factory.NewWithValidTestData<OrgHeader>();
			var orgCFSRelatedPartyForAUSea = Factory.NewWithValidTestData<OrgHeader>();
			var firstOrgTransitTimeZoneOwner = Factory.NewWithValidTestData<OrgHeader>();
			SetupTransportZoneOwnerAddresses(firstOrgTransitTimeZoneOwner, country, postCode);

			var consignor = Factory.NewWithValidTestData<OrgHeader>();
			consignor.MainAddress.OA_Address1 = "TEST";
			consignor.MainAddress.Postcode = postCode;
			consignor.MainAddress.OA_RN_NKCountryCode = country;

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_TransportMode = Constants.TransportModes.Sea;
			shipment.JS_PackingMode = Constants.ContainerModes.Bulk;
			shipment.JS_RS_NKServiceLevel = serviceLevel;
			shipment.JS_RL_NKDestination = "NZAKL";

			shipment.ConsignorDocumentaryAddress.OrganisationPK = consignor.PK;
			shipment.ConsignorDocumentaryAddress.E2_OA_Address = consignor.MainAddress.PK;

			consignor.SetRelatedParty(orgCFSRelatedPartyForAir, RelatedPartyTypeList.Codes.ClientCFS, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.Air, ZString.Empty);
			consignor.SetRelatedParty(orgCFSRelatedPartyForAUAir, RelatedPartyTypeList.Codes.ClientCFS, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.Air, ZString.Empty, "AU");
			consignor.SetRelatedParty(orgCFSRelatedPartyForAUSea, RelatedPartyTypeList.Codes.ClientCFS, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.Sea, ZString.Empty, "AU");
			AssertEquals(ZGuid.Empty, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);

			shipment.JS_RL_NKOrigin = "AUBNE";
			AssertEquals(orgCFSRelatedPartyForAUSea.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);

			using (FreightDataRegistry.Instance.CalculateDeliveryDueDateByTransportMode.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new CalculateDeliveryDueDateOptions { IsActive = true, TransportModes = ActiveTransportModesForCalculateDeliveryDateOption() }))
			{
				SetupTransportZoneWithDomesticZoneOwner(firstOrgTransitTimeZoneOwner, postCode, ZString.Empty, country);
				Factory.Save();
				shipment.JS_RL_NKOrigin = "AUSYD";

				var transitTimeZoneOwnerPickupAddress = GetAddressBasedOnCapability(firstOrgTransitTimeZoneOwner, OrgAddressType.Pickup.Code);
				AssertEquals(firstOrgTransitTimeZoneOwner.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);
				AssertEquals(transitTimeZoneOwnerPickupAddress.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.AddressFK);

				transitTimeZoneOwnerPickupAddress.OA_IsActive = false;
				var transitTimeZoneOwnerPickupAndDeliveryAddress = GetAddressBasedOnCapability(firstOrgTransitTimeZoneOwner, OrgAddressType.PickupAndDelivery.Code);
				shipment.JS_RL_NKOrigin = "AUMEL";
				AssertEquals(firstOrgTransitTimeZoneOwner.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);
				AssertEquals(transitTimeZoneOwnerPickupAndDeliveryAddress.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.AddressFK);

				transitTimeZoneOwnerPickupAndDeliveryAddress.OA_IsActive = false;
				shipment.ConsignorPickupAddress.E2_OA_Address = ZGuid.Empty;
				shipment.ConsignorPickupAddress.E2_OA_Address = consignor.MainAddress.PK;
				AssertEquals(firstOrgTransitTimeZoneOwner.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);
				AssertEquals(firstOrgTransitTimeZoneOwner.MainAddress.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.AddressFK);

				var secondOrgTransitTimeZoneOwner = Factory.NewWithValidTestData<OrgHeader>();
				SetupTransportZoneOwnerAddresses(secondOrgTransitTimeZoneOwner, country, postCode);
				var secondZone = SetupTransportZoneWithDomesticZoneOwner(secondOrgTransitTimeZoneOwner, "2233", "2235", country);
				Factory.Save();
				shipment.JS_OA_ExportReceivingDepot_ZAddress.AddressFK = ZGuid.Empty;
				shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK = ZGuid.Empty;

				shipment.ConsignorPickupAddress.E2_OA_Address = ZGuid.Empty;
				shipment.ConsignorPickupAddress.E2_OA_Address = consignor.MainAddress.PK;
				AssertEquals("Pickup CFS should fall back to related Client CFS", orgCFSRelatedPartyForAUSea.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);

				secondZone.Items[0].TQ_ToPostCode = ZString.Empty;
				Factory.Save();

				shipment.JS_OA_ExportReceivingDepot_ZAddress.AddressFK = ZGuid.Empty;
				shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK = ZGuid.Empty;

				shipment.ConsignorPickupAddress.E2_OA_Address = ZGuid.Empty;
				shipment.ConsignorPickupAddress.E2_OA_Address = consignor.MainAddress.PK;
				AssertEquals(firstOrgTransitTimeZoneOwner.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);
				AssertEquals(firstOrgTransitTimeZoneOwner.MainAddress.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.AddressFK);

				secondZone.Items[0].TQ_ToPostCode = "2235";
				secondZone.TZ_IsActive = false;
				Factory.Save();

				shipment.JS_OA_ExportReceivingDepot_ZAddress.AddressFK = ZGuid.Empty;
				shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK = ZGuid.Empty;

				shipment.ConsignorPickupAddress.E2_OA_Address = ZGuid.Empty;
				shipment.ConsignorPickupAddress.E2_OA_Address = consignor.MainAddress.PK;
				AssertEquals(firstOrgTransitTimeZoneOwner.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.OrgPK);
				AssertEquals(firstOrgTransitTimeZoneOwner.MainAddress.PK, shipment.JS_OA_ExportReceivingDepot_ZAddress.AddressFK);
			}
		}

		OrgAddress GetAddressBasedOnCapability(OrgHeader org, ZString capability)
		{
			return org.Addresses.Cast<OrgAddress>().FirstOrDefault(address => address.AddressCapability.GetAddressCapabilityOnCode(capability)?.Enabled ?? false);
		}

		void SetupTransportZoneOwnerAddresses(OrgHeader orgTransitTimeZoneOwner, ZString country, ZString postCode)
		{
			var orgPickupAddress = orgTransitTimeZoneOwner.Addresses.AddNew();
			orgPickupAddress.Address1 = "Menai market";
			orgPickupAddress.Postcode = postCode;
			orgPickupAddress.AddressCapability.SetCapabilityDisabled(OrgAddressType.PickupAndDelivery.Code);
			orgPickupAddress.AddressCapability.SetCapabilityEnabled(OrgAddressType.Pickup.Code);
			orgPickupAddress.AddressCapability.SetCapabilityDisabled(OrgAddressType.Delivery.Code);
			orgPickupAddress.OA_RN_NKCountryCode = country;

			var orgDeliveryAddress = orgTransitTimeZoneOwner.Addresses.AddNew();
			orgDeliveryAddress.Address1 = "AnyTimeFitness";
			orgDeliveryAddress.Postcode = postCode;
			orgDeliveryAddress.AddressCapability.SetCapabilityDisabled(OrgAddressType.PickupAndDelivery.Code);
			orgDeliveryAddress.AddressCapability.SetCapabilityDisabled(OrgAddressType.Pickup.Code);
			orgDeliveryAddress.AddressCapability.SetCapabilityEnabled(OrgAddressType.Delivery.Code);
			orgDeliveryAddress.OA_RN_NKCountryCode = country;

			var orgPickupAndDeliveryAddress = orgTransitTimeZoneOwner.Addresses.AddNew();
			orgPickupAndDeliveryAddress.Address1 = "ALDI";
			orgPickupAndDeliveryAddress.Postcode = postCode;
			orgPickupAndDeliveryAddress.AddressCapability.SetCapabilityEnabled(OrgAddressType.PickupAndDelivery.Code);
			orgPickupAndDeliveryAddress.AddressCapability.SetCapabilityDisabled(OrgAddressType.Pickup.Code);
			orgPickupAndDeliveryAddress.AddressCapability.SetCapabilityDisabled(OrgAddressType.Delivery.Code);

			orgPickupAddress.AddressCapability.SetCapabilityEnabled(OrgAddressType.Pickup.Code);
			orgPickupAndDeliveryAddress.OA_RN_NKCountryCode = country;

			var orgMainAddress = orgTransitTimeZoneOwner.MainAddress;
			orgMainAddress.Address1 = "Coles";
			orgMainAddress.Postcode = postCode;
			orgMainAddress.AddressCapability.SetCapabilityDisabled(OrgAddressType.PickupAndDelivery.Code);
			orgMainAddress.AddressCapability.SetCapabilityDisabled(OrgAddressType.Pickup.Code);
			orgMainAddress.AddressCapability.SetCapabilityDisabled(OrgAddressType.Delivery.Code);
			orgMainAddress.OA_RN_NKCountryCode = country;
		}

		RateTransportZone SetupTransportZoneWithDomesticZoneOwner(
								OrgHeader orgTransitTimeZoneOwner,
								ZString fromPostCode,
								ZString toPostCode,
								ZString country)
		{
			var provider = Factory.NewWithValidTestData<RateTransportProvider>();
			provider.TP_ZoneType = RatingConstants.RatingZoneTypes.All;
			provider.TP_OH_RelatedParty = orgTransitTimeZoneOwner.PK;

			var zone = provider.Zones.AddNew();
			zone.TZ_IsActive = true;

			var zoneItem = zone.Items.AddNew();
			zoneItem.TQ_FromPostCode = fromPostCode;
			zoneItem.TQ_ToPostCode = toPostCode;
			zoneItem.TQ_RN_NKCountry = country;

			return zone;
		}

