		public void TestDestinationChanged_DefaultDeliveryCFSFromTransitTimeZoneOwner_FallbackToCFSRelatedParty()
		{
			var serviceLevel = "STD";
			var postCode = "2234";
			var country = Constants.CountryCodes.Australia;

			var orgCFSRelatedPartyForAir = Factory.NewWithValidTestData<OrgHeader>();
			var orgCFSRelatedPartyForAUAir = Factory.NewWithValidTestData<OrgHeader>();
			var orgCFSRelatedPartyForAUSea = Factory.NewWithValidTestData<OrgHeader>();
			var orgTransitTimeZoneOwner = Factory.NewWithValidTestData<OrgHeader>();
			SetupTransportZoneOwnerAddresses(orgTransitTimeZoneOwner, country, postCode);

			var consignee = Factory.NewWithValidTestData<OrgHeader>();
			consignee.MainAddress.OA_Address1 = "TEST";
			consignee.MainAddress.Postcode = postCode;
			consignee.MainAddress.OA_RN_NKCountryCode = country;

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_TransportMode = Constants.TransportModes.Sea;
			shipment.JS_PackingMode = Constants.ContainerModes.Bulk;
			shipment.JS_RS_NKServiceLevel = serviceLevel;
			shipment.JS_RL_NKOrigin = "NZAKL";

			shipment.ConsigneeDocumentaryAddress.OrganisationPK = consignee.PK;
			shipment.ConsigneeDocumentaryAddress.E2_OA_Address = consignee.MainAddress.PK;

			consignee.SetRelatedParty(orgCFSRelatedPartyForAir, RelatedPartyTypeList.Codes.ClientCFS, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.Air, ZString.Empty);
			consignee.SetRelatedParty(orgCFSRelatedPartyForAUAir, RelatedPartyTypeList.Codes.ClientCFS, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.Air, ZString.Empty, "AU");
			consignee.SetRelatedParty(orgCFSRelatedPartyForAUSea, RelatedPartyTypeList.Codes.ClientCFS, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.Sea, ZString.Empty, "AU");

			shipment.JS_RL_NKDestination = "AUBNE";
			AssertEquals(orgCFSRelatedPartyForAUSea.PK, shipment.JS_OA_ImportReleaseDepot_ZAddress.OrgPK);

			using (FreightDataRegistry.Instance.CalculateDeliveryDueDateByTransportMode.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new CalculateDeliveryDueDateOptions { IsActive = true, TransportModes = ActiveTransportModesForCalculateDeliveryDateOption() }))
			{
				SetupTransportZoneWithDomesticZoneOwner(orgTransitTimeZoneOwner, postCode, ZString.Empty, country);
				Factory.Save();
				shipment.JS_RL_NKDestination = "AUSYD";

				var transitTimeZoneOwnerDeliveryAddress = GetAddressBasedOnCapability(orgTransitTimeZoneOwner, OrgAddressType.Delivery.Code);
				AssertEquals(orgTransitTimeZoneOwner.PK, shipment.JS_OA_ImportReleaseDepot_ZAddress.OrgPK);
				AssertEquals(transitTimeZoneOwnerDeliveryAddress.PK, shipment.JS_OA_ImportReleaseDepot_ZAddress.AddressFK);

				transitTimeZoneOwnerDeliveryAddress.OA_IsActive = false;
				var transitTimeZoneOwnerPickupAndDeliveryAddress = GetAddressBasedOnCapability(orgTransitTimeZoneOwner, OrgAddressType.PickupAndDelivery.Code);
				shipment.JS_RL_NKDestination = "AUMEL";
				AssertEquals(orgTransitTimeZoneOwner.PK, shipment.JS_OA_ImportReleaseDepot_ZAddress.OrgPK);
				AssertEquals(transitTimeZoneOwnerPickupAndDeliveryAddress.PK, shipment.JS_OA_ImportReleaseDepot_ZAddress.AddressFK);

				transitTimeZoneOwnerPickupAndDeliveryAddress.OA_IsActive = false;
				shipment.ConsigneeDeliveryAddress.E2_OA_Address = ZGuid.Empty;
				shipment.ConsigneeDeliveryAddress.E2_OA_Address = consignee.MainAddress.PK;
				AssertEquals(orgTransitTimeZoneOwner.PK, shipment.JS_OA_ImportReleaseDepot_ZAddress.OrgPK);
				AssertEquals(orgTransitTimeZoneOwner.MainAddress.PK, shipment.JS_OA_ImportReleaseDepot_ZAddress.AddressFK);

				var secondOrgTransitTimeZoneOwner = Factory.NewWithValidTestData<OrgHeader>();
				SetupTransportZoneOwnerAddresses(secondOrgTransitTimeZoneOwner, country, postCode);
				var secondZone = SetupTransportZoneWithDomesticZoneOwner(secondOrgTransitTimeZoneOwner, "2233", "2235", country);
				Factory.Save();
				shipment.JS_OA_ImportReleaseDepot_ZAddress.AddressFK = ZGuid.Empty;
				shipment.JS_OA_ImportReleaseDepot_ZAddress.OrgPK = ZGuid.Empty;

				shipment.ConsigneeDeliveryAddress.E2_OA_Address = ZGuid.Empty;
				shipment.ConsigneeDeliveryAddress.E2_OA_Address = consignee.MainAddress.PK;
				AssertEquals("Delivery CFS should fall back to related Client CFS", orgCFSRelatedPartyForAUSea.PK, shipment.JS_OA_ImportReleaseDepot_ZAddress.OrgPK);

				secondZone.Items[0].TQ_ToPostCode = ZString.Empty;
				Factory.Save();

				shipment.JS_OA_ImportReleaseDepot_ZAddress.AddressFK = ZGuid.Empty;
				shipment.JS_OA_ImportReleaseDepot_ZAddress.OrgPK = ZGuid.Empty;

				shipment.ConsigneeDeliveryAddress.E2_OA_Address = ZGuid.Empty;
				shipment.ConsigneeDeliveryAddress.E2_OA_Address = consignee.MainAddress.PK;
				AssertEquals(orgTransitTimeZoneOwner.PK, shipment.JS_OA_ImportReleaseDepot_ZAddress.OrgPK);
				AssertEquals(orgTransitTimeZoneOwner.MainAddress.PK, shipment.JS_OA_ImportReleaseDepot_ZAddress.AddressFK);
			}
		}

