		public void TestSetDeliveryAgent()
		{
			var orgALL = Factory.New<OrgHeader>();
			var orgAIR = Factory.New<OrgHeader>();
			var orgSEA = Factory.New<OrgHeader>();
			var orgFCL = Factory.New<OrgHeader>();
			var orgLCL = Factory.New<OrgHeader>();

			var mainOrg = Factory.New<OrgHeader>();
			mainOrg.MainAddress.OA_Address1 = "TEST";

			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			shipment.JS_PackingMode = Core.Constants.ContainerModes.Bulk;
			shipment.JS_RL_NKDestination = "AUBNE";
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = mainOrg.PK;
			AssertEquals(ZGuid.Empty, shipment.JS_OH_DeliveryAgent);

			mainOrg.SetRelatedParty(orgAIR, RelatedPartyTypeList.Codes.DeliveryAgent, RelatedPartyDirectionList.Codes.Delivery, Constants.TransportModes.Air, ZString.Empty, "AUBNE");
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = ZGuid.Empty;
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = mainOrg.PK;
			AssertEquals(ZGuid.Empty, shipment.JS_OH_DeliveryAgent);

			mainOrg.SetRelatedParty(orgALL, RelatedPartyTypeList.Codes.DeliveryAgent, RelatedPartyDirectionList.Codes.Delivery, Constants.TransportModes.All, ZString.Empty);
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = ZGuid.Empty;
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = mainOrg.PK;
			AssertEquals(orgALL.PK, shipment.JS_OH_DeliveryAgent);

			mainOrg.SetRelatedParty(orgSEA, RelatedPartyTypeList.Codes.DeliveryAgent, RelatedPartyDirectionList.Codes.Delivery, Constants.TransportModes.Sea, ZString.Empty);
			shipment.JS_OH_DeliveryAgent = ZGuid.Empty;
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = ZGuid.Empty;
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = mainOrg.PK;
			AssertEquals(orgSEA.PK, shipment.JS_OH_DeliveryAgent);

			mainOrg.SetRelatedParty(orgFCL, RelatedPartyTypeList.Codes.DeliveryAgent, RelatedPartyDirectionList.Codes.Delivery, Constants.TransportModes.Sea, Constants.ContainerModes.FCL);
			mainOrg.SetRelatedParty(orgLCL, RelatedPartyTypeList.Codes.DeliveryAgent, RelatedPartyDirectionList.Codes.Delivery, Constants.TransportModes.Sea, Constants.ContainerModes.LCL);
			shipment.JS_OH_DeliveryAgent = ZGuid.Empty;
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = ZGuid.Empty;
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = mainOrg.PK;
			AssertEquals(orgSEA.PK, shipment.JS_OH_DeliveryAgent);

			shipment.JS_OH_DeliveryAgent = ZGuid.Empty;
			shipment.JS_PackingMode = Core.Constants.ContainerModes.FCL;
			AssertEquals(orgFCL.PK, shipment.JS_OH_DeliveryAgent);

			shipment.JS_OH_DeliveryAgent = ZGuid.Empty;
			shipment.JS_PackingMode = Core.Constants.ContainerModes.LCL;
			AssertEquals(orgLCL.PK, shipment.JS_OH_DeliveryAgent);

			shipment.JS_PackingMode = Core.Constants.ContainerModes.Loose;
			shipment.JS_OH_DeliveryAgent = ZGuid.Empty;
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
			AssertEquals(orgAIR.PK, shipment.JS_OH_DeliveryAgent);
		}

