		public void TestSetPickupAddress()
		{
			var consignor = Factory.NewWithValidTestData<OrgHeader>();
			var consignorPickupAddress = consignor.Addresses.AddNew(OrgAddressType.Pickup, true);

			var consignee = Factory.NewWithValidTestData<OrgHeader>();

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_TransportMode = TransportModes.Sea;
			shipment.JS_PackingMode = ContainerModes.Bulk;
			shipment.JS_RL_NKOrigin = "AUBNE";
			shipment.JS_RL_NKDestination = "USLAX";
			shipment.ConsignorDocumentaryAddress.OrganisationPK = consignor.PK;
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = consignee.PK;

			var pickupAddress = shipment.DocAddresses.FindOrCreateWithDocAddressType(DocAddressType.ConsignorPickupDeliveryAddress);
			AssertEquals(consignorPickupAddress.PK, pickupAddress.E2_OA_Address);

			var pickupFromOrg = Factory.NewWithValidTestData<OrgHeader>();
			var pickupFromOrgSalesAddress = pickupFromOrg.Addresses.AddNew(OrgAddressType.Sales, true);
			var pickupFromOrgPickupAddress = pickupFromOrg.Addresses.AddNew(OrgAddressType.Pickup, true);

			consignor.SetRelatedParty(ZGuid.Empty, pickupFromOrg, RelatedPartyTypeList.Codes.PickupFrom, RelatedPartyDirectionList.Codes.Pickup, TransportModes.Sea, ContainerModes.Bulk, "AUBNE");
			shipment.ConsignorDocumentaryAddress.OrganisationPK = ZGuid.Empty;
			shipment.ConsignorDocumentaryAddress.OrganisationPK = consignor.PK;
