			consignee.OH_RL_NKClosestPort = "AUSYD";
			var consigneeAddress = consignee.Addresses.AddNew(OrgAddressType.Office, true);
			var consigneeContact = consignee.Contacts.AddNew();
			consigneeContact.OC_IsActive = true;

			var consigneeContactDocument = consigneeContact.Documents.AddNew();
			consigneeContactDocument.OD_DocumentGroup = ContactType.NotifyParty.Code;
			consigneeContactDocument.OD_DefaultContact = true;

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_TransportMode = TransportModes.Sea;
			shipment.JS_PackingMode = ContainerModes.Bulk;
			shipment.ConsignorDocumentaryAddress.OrganisationPK = consignor.PK;
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = consignee.PK;

