			AssertEquals(consigneeContact.PK, notifyPartyAddress.ContactPK);

			AssertSetDefaultNotifyPartyFromRelatedParty(consignor, shipment.ConsignorDocumentaryAddress, RelatedPartyDirectionList.Codes.PickupAndDelivery, notifyPartyAddress);
			AssertSetDefaultNotifyPartyFromRelatedParty(consignor, shipment.ConsignorDocumentaryAddress, RelatedPartyDirectionList.Codes.Pickup, notifyPartyAddress);
			AssertSetDefaultNotifyPartyFromRelatedParty(consignee, shipment.ConsigneeDocumentaryAddress, RelatedPartyDirectionList.Codes.PickupAndDelivery, notifyPartyAddress);
