		//This is used by Enterprise.Customs.EU.Business.TESTING
		public static ForwardingShipment CreateForwardingShipmentWithManyLegsForTesting(BusinessObjectFactory factory)
		{
			ForwardingShipment shipment = factory.New<ForwardingShipment>();
			ForwardingConsol consol1 = factory.New<ForwardingConsol>();
			consol1.Shipments.Add(shipment);

			ForwardingConsol consol2 = factory.New<ForwardingConsol>();
			consol2.Shipments.Add(shipment);

			Transport melbourneToSydney = consol1.Transports.AddNew();
			Transport sydneyToHongKong = consol1.Transports.AddNew();
			Transport hongKongToFrankfurt = consol1.Transports.AddNew();
			Transport frankfurtToParis = consol1.Transports.AddNew();
			Transport parisToLondon = consol2.Transports.AddNew();
			Transport londonToLeeds = consol2.Transports.AddNew();

			melbourneToSydney.JW_RL_NKLoadPort = "AUMEL";
			melbourneToSydney.JW_RL_NKDiscPort = "AUSYD";
			melbourneToSydney.JW_ATA = ZDateTime.Now;

			sydneyToHongKong.JW_RL_NKLoadPort = melbourneToSydney.JW_RL_NKDiscPort;
			sydneyToHongKong.JW_RL_NKDiscPort = "HKHKG";
			sydneyToHongKong.JW_ATA = ZDateTime.Now;

			hongKongToFrankfurt.JW_RL_NKLoadPort = sydneyToHongKong.JW_RL_NKDiscPort;
			hongKongToFrankfurt.JW_RL_NKDiscPort = "DEFRA";
			hongKongToFrankfurt.JW_ATA = ZDateTime.Now;

			frankfurtToParis.JW_RL_NKLoadPort = hongKongToFrankfurt.JW_RL_NKDiscPort;
			frankfurtToParis.JW_RL_NKDiscPort = "FRPAR";
			frankfurtToParis.JW_ATA = ZDateTime.Now;

			parisToLondon.JW_RL_NKLoadPort = frankfurtToParis.JW_RL_NKDiscPort;
			parisToLondon.JW_RL_NKDiscPort = "GBLON";
			parisToLondon.JW_ATA = ZDateTime.Now;

			londonToLeeds.JW_RL_NKLoadPort = parisToLondon.JW_RL_NKDiscPort;
			londonToLeeds.JW_RL_NKDiscPort = "GBLBA";
			londonToLeeds.JW_ATA = ZDateTime.Now;
			return shipment;
		}

