		public void TestShowOnManifestAndOtherDocs()
		{
			ForwardingShipment masterShipment = (ForwardingShipment)GetImportShipment(typeof(ForwardingShipment));
			masterShipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			masterShipment.JS_ShipmentType = Constants.ShipmentTypes.CoLoadMaster;

			ForwardingConsol consol = Factory.New<ForwardingConsol>();
			consol.JK_TransportMode = masterShipment.JS_TransportMode;
			consol.JK_RL_NKLoadPort = masterShipment.JS_RL_NKOrigin;
			consol.JK_RL_NKDischargePort = masterShipment.JS_RL_NKDestination;

			consol.Shipments.Add(masterShipment);
			masterShipment.CurrentConsolForDocuments = consol;

			ForwardingShipment subShipment = (ForwardingShipment)GetImportShipment(typeof(ForwardingShipment));
			subShipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			subShipment.JS_ShipmentType = Constants.ShipmentTypes.StandardHouse;
			subShipment.JS_JS_ColoadMasterShipment = masterShipment.PK;
			subShipment.CurrentConsolForDocuments = consol;

			consol.JK_PrintOptionForColoadsOnManifest = FreightConstants.PrintOptionForCoLoads.MastersOnly;

			AssertEquals("Master Shipment should be included on manifest for MastersOnly", true, masterShipment.ShowOnManifest);
			AssertEquals("Sub Shipment should be excluded on manifest for MastersOnly", false, subShipment.ShowOnManifest);

			consol.JK_PrintOptionForColoadsOnManifest = FreightConstants.PrintOptionForCoLoads.SubHouseBillsOnly;

			AssertEquals("Master Shipment should be excluded on manifest for SubsOnly", false, masterShipment.ShowOnManifest);
			AssertEquals("Sub Shipment should be included on manifest for SubsOnly", true, subShipment.ShowOnManifest);

			consol.JK_PrintOptionForColoadsOnManifest = FreightConstants.PrintOptionForCoLoads.All;

			AssertEquals("Master Shipment should be included on manifest for All", true, masterShipment.ShowOnManifest);
			AssertEquals("Sub Shipment should be included on manifest for All", true, subShipment.ShowOnManifest);

			consol.JK_PrintOptionForColoadsOnOtherDocs = FreightConstants.PrintOptionForCoLoads.MastersOnly;

			AssertEquals("Master Shipment should be included on other docs for MastersOnly", true, masterShipment.ShowOnOtherDocs);
			AssertEquals("Sub Shipment should be excluded on other docs for MastersOnly", false, subShipment.ShowOnOtherDocs);

			consol.JK_PrintOptionForColoadsOnOtherDocs = FreightConstants.PrintOptionForCoLoads.SubHouseBillsOnly;

			AssertEquals("Master Shipment should be excluded on other docs for SubsOnly", false, masterShipment.ShowOnOtherDocs);
			AssertEquals("Sub Shipment should be included on other docs for SubsOnly", true, subShipment.ShowOnOtherDocs);

			consol.JK_PrintOptionForColoadsOnOtherDocs = FreightConstants.PrintOptionForCoLoads.All;

			AssertEquals("Master Shipment should be included on other docs for All", true, masterShipment.ShowOnOtherDocs);
			AssertEquals("Sub Shipment should be included on other docs for All", true, subShipment.ShowOnOtherDocs);
		}

