		#region Workflow Tests

		/// <remarks>It tests Method CommonShipment.AddDateEvent() here, because CommonShipment does not implements IWorkflowProvider.</remarks>
		public void TestDateEventsAreAddedBeforeMilestones()
		{
			ZDateTime oldDate = ZDateTime.Today.AddDays(-5);
			ZDateTime newDate = ZDateTime.Today.AddDays(+5);

			// Add shipment and ARV event
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.JS_E_ARV = oldDate;
			shipment.JS_TransportMode = "AIR";
			Factory.Save();

			AssertEquals("No milestones should be added to shipment", 0, shipment.WorkflowItems.Milestones.Count);

			// Create milestones template
			ProcessTaskTemplate template = Factory.NewWithValidTestData<ProcessTaskTemplate>();
			template.P0_ProcessType = "SHP";
			template.P0_SubType1 = "AIR";

			ProcessTask milestone = template.WorkflowItems.Milestones.AddNew();
			milestone.P9_Type = "MIL";
			milestone.TriggerConditions.TriggerEventCode = "ARV";

			Factory.Save();

			// Change date and apply template
			shipment.JS_E_ARV = newDate;
			Factory.Save();

			AssertEquals("New date should remain in field", newDate, shipment.JS_E_ARV);

			AssertEquals("1 milestone should be added to shipment", 1, shipment.WorkflowItems.Milestones.Count);
			AssertEquals("ARV", shipment.WorkflowItems.Milestones[0].P9_SE_NKMilestoneEvent);
			AssertEquals(newDate, shipment.WorkflowItems.Milestones[0].P9_ScheduledDate.ToZDateTime());
		}

