		#region JS_Calc_EstimatedExportClearanceDate

		public void TestJS_Calc_EstimatedExportClearanceDate_AddingEventFromEventLogs()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			Factory.Save();

			var anotherFactory = new BusinessObjectFactory();
			var reloadShipment = anotherFactory.Load<ForwardingShipment>(shipment.PK);
			AssertEquals("The shipment's Estimated Export Customs Cleared date should default to empty", ZDateTime.Empty, reloadShipment.JS_Calc_EstimatedExportClearanceDate);

			var eccEventLog1 = shipment.Logs.AddNew(Events.ExportCustomsCleared, new ZDateTimeOffset(2013, 1, 1), true);
			var eccEventLog2 = shipment.Logs.AddNew(Events.ExportCustomsCleared, new ZDateTimeOffset(2013, 4, 4), true);

			Factory.Save();

			anotherFactory = new BusinessObjectFactory();
			reloadShipment = anotherFactory.Load<ForwardingShipment>(shipment.PK);
			AssertEquals("The reloadShipment's Estimated Export Customs Cleared date should be set to the latest ECC event", new ZDateTime(2013, 4, 4), reloadShipment.JS_Calc_EstimatedExportClearanceDate);

			var eccEventLog3 = shipment.Logs.AddNew(Events.ExportCustomsCleared, new ZDateTimeOffset(2013, 3, 3), true);
			Factory.Save();

			anotherFactory = new BusinessObjectFactory();
			reloadShipment = anotherFactory.Load<ForwardingShipment>(shipment.PK);
			AssertEquals("The date on the reloadShipment should not change as the new event added is earlier than the current date", new ZDateTime(2013, 4, 4), reloadShipment.JS_Calc_EstimatedExportClearanceDate);

			eccEventLog2.Cancel();
			Factory.Save();

			anotherFactory = new BusinessObjectFactory();
			reloadShipment = anotherFactory.Load<ForwardingShipment>(shipment.PK);
			AssertEquals("Cancelling the latest event should cause the date on the reloadShipment to fall back to an earlier event", new ZDateTime(2013, 3, 3), reloadShipment.JS_Calc_EstimatedExportClearanceDate);

			eccEventLog3.Cancel();
			eccEventLog1.Cancel();
			Factory.Save();

			anotherFactory = new BusinessObjectFactory();
			reloadShipment = anotherFactory.Load<ForwardingShipment>(shipment.PK);
			AssertEquals("Cancelling all remaining events should empty the export clearance date", ZDateTime.Empty, reloadShipment.JS_Calc_EstimatedExportClearanceDate);
		}

		public void TestJS_Calc_EstimatedExportClearanceDate_AddingEventFromShipment()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			Factory.Save();

			var currentECCEvent = shipment.Logs.MostRecentLogByEventTime(Events.ExportCustomsCleared, new ZQuery(StmALogSchema.SL_IsEstimate, true));

			AssertNull("There should be no Export Customs Cleared event attached to this shipment", currentECCEvent);

			var today = ZDateTime.Today;
			shipment.JS_Calc_EstimatedExportClearanceDate = today;
			currentECCEvent = shipment.Logs.MostRecentLogByEventTime(Events.ExportCustomsCleared, new ZQuery(StmALogSchema.SL_IsEstimate, true));
			Factory.Save();

			AssertNotNull("There should be a current Export Customs Cleared event attached to this shipment", currentECCEvent);
			AssertEquals("The current event's time should be set from the Estimated Export Customs Clearance date", today, currentECCEvent.SL_EventTime);

			shipment.JS_Calc_EstimatedExportClearanceDate = today.AddMonths(1);
			currentECCEvent = shipment.Logs.MostRecentLogByEventTime(Events.ExportCustomsCleared, new ZQuery(StmALogSchema.SL_IsEstimate, true));

			AssertEquals("The current event's time should be set from the Estimated Export Customs Clearance date", today.AddMonths(1), currentECCEvent.SL_EventTime);

			shipment.JS_Calc_EstimatedExportClearanceDate = ZDateTime.Empty;

			Assert("ECC events should be cancelled when the shipment's Estimated Export Customs Cleared date is cleared", currentECCEvent.SL_IsCancelled);
		}

