		#region Test JS_Calc_PossibleOversize

		public void TestJS_Calc_PossibleOversize_Air()
		{
			var shipment = (ForwardingShipment)GetShipment();
			shipment.JS_TransportMode = Constants.TransportModes.Air;

			var pack1 = shipment.OuterPackLines.AddNew();
			pack1.JL_Length = 200m;
			pack1.JL_Width = 100m;
			pack1.JL_Height = 80m;
			pack1.JL_UnitOfDimension = Constants.Length.Centimetres;
			Assert("Shipment should not have oversize packs yet", shipment.JS_Calc_PossibleOversize.IsEmpty);

			var pack2 = shipment.OuterPackLines.AddNew();
			pack2.JL_Length = 150m;
			pack2.JL_Width = 150m;
			pack2.JL_Height = 300m;
			pack2.JL_UnitOfDimension = Constants.Length.Centimetres;
			AssertEquals("Shipment should have one oversize pack due to height of pack2",
				"150x150x300 CM exceeds 300x200x160 CM", shipment.JS_Calc_PossibleOversize);

			var pack3 = shipment.OuterPackLines.AddNew();
			pack3.JL_Length = 150m;
			pack3.JL_Width = 150m;
			pack3.JL_Height = 200m;
			pack3.JL_UnitOfDimension = Constants.Length.Centimetres;
			AssertEquals("Shipment should keep the same possible oversize message",
				"150x150x300 CM exceeds 300x200x160 CM", shipment.JS_Calc_PossibleOversize);

			var pack4 = shipment.OuterPackLines.AddNew();
			pack4.JL_Length = 5m;
			pack4.JL_Width = 1m;
			pack4.JL_Height = 1m;
			pack4.JL_UnitOfDimension = Constants.Length.Metres;
			AssertEquals("Shipment should update message as pack4 larger oversize pack",
				"5x1x1 M exceeds 300x200x160 CM", shipment.JS_Calc_PossibleOversize);
		}

		public void TestJS_Calc_PossibleOversize_Air_Rotated()
		{
			var shipment = (ForwardingShipment)GetShipment();
			shipment.JS_TransportMode = Constants.TransportModes.Air;

			var pack1 = shipment.OuterPackLines.AddNew();
			pack1.JL_Length = 240m;
			pack1.JL_Width = 220m;
			pack1.JL_Height = 80m;
			pack1.JL_UnitOfDimension = Constants.Length.Centimetres;

			AssertEquals("Shipment should have one oversize pack due to width, even though both length and width are < max length", "240x220x80 CM exceeds 300x200x160 CM", shipment.JS_Calc_PossibleOversize);

			pack1.JL_Length = 220m;
			pack1.JL_Width = 240m;

			AssertEquals("It still doesn't fit if length and width are swapped", "220x240x80 CM exceeds 300x200x160 CM", shipment.JS_Calc_PossibleOversize);

			pack1.JL_Length = 180m;

			AssertEquals("Pack now fits when rotated", "", shipment.JS_Calc_PossibleOversize);
		}

		public void TestJS_Calc_PossibleOversize_Air_PreAllocatedDims()
		{
			var shipment = (ForwardingShipment)GetShipment();
			shipment.JS_TransportMode = Constants.TransportModes.Air;

			var consol1 = shipment.Consols.AddNew();
			consol1.JK_TransportMode = Constants.TransportModes.Air;

			var consol2 = shipment.Consols.AddNew();
			consol2.JK_TransportMode = Constants.TransportModes.Air;

			var pack1 = shipment.OuterPackLines.AddNew();
			pack1.JL_Length = 200;
			pack1.JL_Width = 100;
			pack1.JL_Height = 180;
			pack1.JL_UnitOfDimension = Constants.Length.Centimetres;
			AssertEquals("Consols do not have pre-allocation dims, so Shipment should have one oversize pack based on default dimensions and height of pack", "200x100x180 CM exceeds 300x200x160 CM", shipment.JS_Calc_PossibleOversize);

			consol1.JK_MaximumAllowablePackageLength = 120;
			consol1.JK_MaximumAllowablePackageWidth = 240;
			consol1.JK_MaximumAllowablePackageHeight = 250;
			consol1.JK_MaximumAllowablePackageUnit = Constants.Length.Centimetres;

			AssertEquals("Shipment fits into consol1 (when rotated), but not into consol2 which doesn't have pre-allocated dims set", "200x100x180 CM exceeds 300x200x160 CM", shipment.JS_Calc_PossibleOversize);

			consol2.JK_MaximumAllowablePackageLength = 220;
			consol2.JK_MaximumAllowablePackageWidth = 80;
			consol2.JK_MaximumAllowablePackageHeight = 240;
			consol2.JK_MaximumAllowablePackageUnit = Constants.Length.Centimetres;

			AssertEquals("Shipment fits into consol1 (when rotated), but not into consol2 which has pre-allocated dims", "200x100x180 CM exceeds 220x80x240 CM", shipment.JS_Calc_PossibleOversize);

			consol2.JK_MaximumAllowablePackageWidth = 120;

			AssertEquals("Shipment fits into both consols", "", shipment.JS_Calc_PossibleOversize);
		}

		public void TestJS_Calc_PossibleOversize_Sea()
		{
			var shipment = (ForwardingShipment)GetShipment();
			shipment.JS_TransportMode = Constants.TransportModes.Sea;

			var pack1 = shipment.OuterPackLines.AddNew();
			pack1.JL_Length = 18m;
			pack1.JL_Width = 6m;
			pack1.JL_Height = 8m;
			pack1.JL_UnitOfDimension = Constants.Length.Feet;
			Assert("Shipment should not have oversize packs yet", shipment.JS_Calc_PossibleOversize.IsEmpty);

			var pack2 = shipment.OuterPackLines.AddNew();
			pack2.JL_Length = 20m;
			pack2.JL_Width = 10m;
			pack2.JL_Height = 5m;
			pack2.JL_UnitOfDimension = Constants.Length.Feet;
			AssertEquals("Shipment should have one oversize pack even if only pack2's width is oversize",
				"20x10x5 FT exceeds dimensions of 20GP container", shipment.JS_Calc_PossibleOversize);

			var pack3 = shipment.OuterPackLines.AddNew();
			pack3.JL_Length = 250m;
			pack3.JL_Width = 300m;
			pack3.JL_Height = 85m;
			pack3.JL_UnitOfDimension = Constants.Length.Inches;
			AssertEquals("Shipment should update message as width of pack3 is longer than length of pack2",
				"250x300x85 IN exceeds dimensions of 20GP container", shipment.JS_Calc_PossibleOversize);

			var pack4 = shipment.OuterPackLines.AddNew();
			pack4.JL_Length = 10m;
			pack4.JL_Width = 8m;
			pack4.JL_Height = 5m;
			pack4.JL_UnitOfDimension = Constants.Length.Metres;
			AssertEquals("Shipment should update message as pack4 is larger oversize pack",
				"10x8x5 M exceeds dimensions of 20GP container", shipment.JS_Calc_PossibleOversize);

			AssertEquals("Pack4 should retain units of measurement in database", Constants.Length.Metres, pack4.JL_UnitOfDimension);
			AssertEquals("Pack4 should retain length in metres", 10m, pack4.JL_Length);
			AssertEquals("Pack4 should retain width in metres", 8m, pack4.JL_Width);
			AssertEquals("Pack4 should retain height in metres", 5m, pack4.JL_Height);
		}

		public void TestJS_Calc_PossibleOversize_InapplicableContainerModes()
		{
			var shipment = (ForwardingShipment)GetShipment();
			shipment.JS_TransportMode = Constants.TransportModes.Sea;

			var pack = shipment.OuterPackLines.AddNew();
			pack.JL_Length = 7m;
			pack.JL_Width = 3m;
			pack.JL_Height = 2m;
			pack.JL_UnitOfDimension = Constants.Length.Metres;
			AssertEquals("Precondition: pack is actually oversize",
				"7x3x2 M exceeds dimensions of 20GP container", shipment.JS_Calc_PossibleOversize);

			shipment.JS_PackingMode = Constants.ContainerModes.RollOnRollOff;
			Assert("Possible Oversize is not calculated for 'Roll On Roll Off' Container Mode", shipment.JS_Calc_PossibleOversize.IsEmpty);

			shipment.JS_PackingMode = Constants.ContainerModes.Bulk;
			Assert("Possible Oversize is not calculated for 'Bulk' Container Mode", shipment.JS_Calc_PossibleOversize.IsEmpty);

			shipment.JS_PackingMode = Constants.ContainerModes.BreakBulk;
			Assert("Possible Oversize is not calculated for 'Break Bulk' Container Mode", shipment.JS_Calc_PossibleOversize.IsEmpty);

			shipment.JS_PackingMode = Constants.ContainerModes.Liquid;
			Assert("Possible Oversize is not calculated for 'Liquid' Container Mode", shipment.JS_Calc_PossibleOversize.IsEmpty);

			shipment.JS_PackingMode = Constants.ContainerModes.FCL;
			AssertEquals("Postcondition: when changed back to applicable container mode, possible oversize is calculated",
				"7x3x2 M exceeds dimensions of 20GP container", shipment.JS_Calc_PossibleOversize);
		}

