		#region Can Cancel Forwarding Shipments

		public void TestCanCancelForwardingShipmentWithDeclarations()
		{
			var rowShipment = Factory.NewWithValidTestData(ObjectFactory.GetType(typeof(ICommonShipment))) as INeedRow;
			var shipmentCanDelete = new ForwardingShipmentForTest(Factory, rowShipment.Row);
			Assert(string.IsNullOrEmpty(shipmentCanDelete.CanCancel()));

			var mockerDeclarationCanDelete = new Mock<IBaseJobDeclaration>();
			mockerDeclarationCanDelete.As<ICanDelete>().Setup(d => d.CanDelete).Returns(true);
			mockerDeclarationCanDelete.As<ICanDelete>().Setup(d => d.ReasonForNotAbleToDelete).Returns((NoResString)"");

			var declarationCanDelete = mockerDeclarationCanDelete.Object;
			declarationCanDelete.JE_JS = shipmentCanDelete.PK;
			shipmentCanDelete.DeclarationsForTest = new IBaseJobDeclaration[] { declarationCanDelete };

			Assert(string.IsNullOrEmpty(shipmentCanDelete.CanCancel()));
			AssertEquals(true, ((ICanDelete)declarationCanDelete).CanDelete);

			rowShipment = Factory.NewWithValidTestData(ObjectFactory.GetType(typeof(ICommonShipment)));
			var shipmentNoDelete = new ForwardingShipmentForTest(Factory, rowShipment.Row);

			var mockerDeclarationNoDelete = new Mock<IBaseJobDeclaration>();
			mockerDeclarationNoDelete.Setup(d => d.CanCancel()).Returns("POOP");
			mockerDeclarationNoDelete.Setup(d => d.HumanReadableName).Returns("Daniel");

			var declarationNoDelete = mockerDeclarationNoDelete.Object;
			declarationNoDelete.JE_JS = shipmentNoDelete.PK;
			shipmentNoDelete.DeclarationsForTest = new IBaseJobDeclaration[] { declarationNoDelete };

			var cannotCancelShipmentReason = shipmentNoDelete.CanCancel();
			AssertContains("Declaration's reason shown on shipment", "POOP", cannotCancelShipmentReason);
			AssertContains("Declaration's name shown on shipment", "Daniel", cannotCancelShipmentReason);
		}

		public void TestCanCancelForwardingShipmentWithOrders()
		{
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();

			Assert("Expected no attached orders on shipment", shipment.AttachedOrders.Count == 0);
			Assert("Expected not to cancel shipment without attached orders", string.IsNullOrEmpty(shipment.CanCancel()));

			Order order = shipment.AttachedOrders.AddNew();

			Assert("Expected at least 1 attached orders to shipment", shipment.AttachedOrders.Count > 0);
			Assert("Expected  to cancel shipment with attached orders", !string.IsNullOrEmpty(shipment.CanCancel()));

			shipment.AttachedOrders.Delete(order);

			Assert("Expected no attached orders on shipment", shipment.AttachedOrders.Count == 0);
			Assert("Expected not to cancel shipment without attached orders", string.IsNullOrEmpty(shipment.CanCancel()));
		}

		public void TestCanCancelForwardingShipmentWithAttachedWarehouseOrders()
		{
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();

			Assert("Expected no attached warehouse orders on shipment", shipment.AttachedWarehouseOrders.Count == 0);
			Assert("Expected not to cancel shipment without attached warehouse orders", string.IsNullOrEmpty(shipment.CanCancel()));

			var whsOrder = (BusinessObject)Factory.New<IWhsOrder>();
			shipment.AttachedWarehouseOrders.Add(whsOrder);

			Assert("Expected at least 1 attached warehouse orders to shipment", shipment.AttachedWarehouseOrders.Count > 0);
			Assert("Expected  to cancel shipment with attached warehouse orders", !string.IsNullOrEmpty(shipment.CanCancel()));

			shipment.AttachedWarehouseOrders.Delete(whsOrder);

			Assert("Expected no attached warehouse orders on shipment", shipment.AttachedWarehouseOrders.Count == 0);
			Assert("Expected not to cancel shipment without attached warehouse orders", string.IsNullOrEmpty(shipment.CanCancel()));
		}

		public void TestCanCancelForwardingShipmentWithActiveConsignments()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_ShipmentType = ShipmentTypes.HighVolumeLowValue;

			Assert("Expected no active consignment on shipment", !shipment.HVLVConsignments.Any());
			AssertNullOrEmpty("Expected to cancel shipment without active consignment", shipment.CanCancel());

			var header = Factory.LoadTop1<IHVLVConsignmentHeader>(new ZQuery(HVLVConsignmentHeaderSchema.HCH_JS_Shipment, shipment.PK)) as BusinessObject;
			header.FillWithValidTestData();
			var consignment = Factory.New<IHVLVConsignment>() as BusinessObject;
			consignment.FillWithValidTestData();
			consignment[HVLVConsignmentSchema.HVC_HCH_Header.Name] = header.PK;

			Factory.Save();

			Assert("Expected at least 1 active consignment on shipment", shipment.HVLVConsignments.Any());
			AssertNotNullOrEmpty("Expected not to cancel shipment with active consignment", shipment.CanCancel());
			AssertEquals(string.Format("You cannot deactivate {0} since it has active consignments.", shipment.HumanReadableName), shipment.CanCancel());

			var reloadedConsignment = Factory.Load<IHVLVConsignment>(consignment.PK) as BusinessObject;
			reloadedConsignment[HVLVConsignmentSchema.HVC_IsActive] = false;
			Factory.Save();

			Assert("Expected no active consignment on shipment", !shipment.HVLVConsignments.Any());
			AssertNullOrEmpty("Expected to cancel shipment without active consignment", shipment.CanCancel());
		}

