		public void TestReverse()
		{
			var consignor = Factory.NewWithValidTestData<OrgHeader>();
			var consignee = Factory.NewWithValidTestData<OrgHeader>();

			var exportBroker = Factory.NewWithValidTestData<OrgHeader>();
			var exportTransport = Factory.NewWithValidTestData<OrgHeader>();
			var exportCFS = Factory.NewWithValidTestData<OrgHeader>();

			var importBroker = Factory.NewWithValidTestData<OrgHeader>();
			var importTransport = Factory.NewWithValidTestData<OrgHeader>();
			var importCFS = Factory.NewWithValidTestData<OrgHeader>();
			var importDeliveryAgent = Factory.NewWithValidTestData<OrgHeader>();

			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Constants.TransportModes.Sea;
			shipment.JS_PackingMode = Constants.ContainerModes.FCL;
			shipment.JS_ShipmentType = Constants.ShipmentTypes.StandardHouse;
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "USCHI";
			shipment.ConsignorPK = consignor.PK;
			shipment.ConsigneePK = consignee.PK;

			// Pickup Tab (Export)
			shipment.JS_OH_ExportBroker = exportBroker.PK;
			shipment.DocsAndCartage.JP_OA_PickupCartageCoAddr = exportTransport.MainAddress.PK;
			shipment.JS_OA_ExportReceivingDepot = exportCFS.MainAddress.PK;

			shipment.JS_InterimReceipt = "InterimReceipt";
			shipment.JS_BookingReference = "BookingReference";
			shipment.DocsAndCartage.JP_PickupLabourCharge = 1;
			shipment.DocsAndCartage.JP_PickupTruckWaitCharge = 1;

			// Delivery Tab (Import)
			shipment.JS_OH_ImportBroker = importBroker.PK;
			shipment.DocsAndCartage.JP_OA_DeliveryCartageCoAddr = importTransport.MainAddress.PK;
			shipment.JS_OH_DeliveryAgent = importDeliveryAgent.PK;
			shipment.JS_OA_ImportReleaseDepot = importCFS.MainAddress.PK;

			shipment.DocsAndCartage.JP_DeliveryLabourCharge = 1;
			shipment.DocsAndCartage.JP_DeliveryTruckWaitCharge = 1;
			shipment.DocsAndCartage.JP_LCLAirStorageCharge = 1;
			shipment.DocsAndCartage.JP_LCLAirStorageDaysOrHours = 1;

			((ITemplateReversible)shipment).Reverse();

			AssertEquals("USCHI", shipment.JS_RL_NKOrigin);
			AssertEquals("AUSYD", shipment.JS_RL_NKDestination);

			AssertEquals("Consignor", consignee, shipment.Consignor);
			AssertEquals("Consignee", consignor, shipment.Consignee);

			// Delivery Tab (Import)
			AssertEquals(null, shipment.ExportBroker);
			AssertEquals(null, shipment.DocsAndCartage.PickupCartageCoAddr);
			AssertEquals(null, shipment.ExportReceivingDepot);

			AssertEquals(ZString.Empty, shipment.JS_InterimReceipt);
			AssertEquals(ZString.Empty, shipment.JS_BookingReference);
			AssertEquals(0m, shipment.DocsAndCartage.JP_PickupLabourCharge);
			AssertEquals(0m, shipment.DocsAndCartage.JP_PickupTruckWaitCharge);

			// Delivery Tab (Import)
			AssertEquals(null, shipment.ImportBroker);
			AssertEquals(null, shipment.DocsAndCartage.DeliveryCartageCoAddr);
			AssertEquals(null, shipment.DeliveryAgent);
			AssertEquals(null, shipment.ImportReleaseDepot);

			AssertEquals(0m, shipment.DocsAndCartage.JP_DeliveryLabourCharge);
			AssertEquals(0m, shipment.DocsAndCartage.JP_DeliveryTruckWaitCharge);
			AssertEquals(0m, shipment.DocsAndCartage.JP_LCLAirStorageCharge);
			AssertEquals(0, shipment.DocsAndCartage.JP_LCLAirStorageDaysOrHours.ToZInt());

			consignor.SetRelatedParty(exportBroker, RelatedPartyTypeList.Codes.CustomsAgentBroker, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.All, ZString.Empty);
			consignor.SetRelatedParty(exportTransport.MainAddress.PK, exportTransport, RelatedPartyTypeList.Codes.LocalTransport, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.All, ZString.Empty);
			consignor.SetRelatedParty(exportCFS, RelatedPartyTypeList.Codes.ClientCFS, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.All, ZString.Empty);

			consignee.SetRelatedParty(importBroker, RelatedPartyTypeList.Codes.CustomsAgentBroker, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.All, ZString.Empty);
			consignee.SetRelatedParty(importTransport.MainAddress.PK, importTransport, RelatedPartyTypeList.Codes.LocalTransport, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.All, ZString.Empty);
			consignee.SetRelatedParty(importDeliveryAgent, RelatedPartyTypeList.Codes.DeliveryAgent, RelatedPartyDirectionList.Codes.Delivery, Constants.TransportModes.All, ZString.Empty);
			consignee.SetRelatedParty(importCFS, RelatedPartyTypeList.Codes.ClientCFS, RelatedPartyDirectionList.Codes.PickupAndDelivery, Constants.TransportModes.All, ZString.Empty);

			((ITemplateReversible)shipment).Reverse();

			AssertEquals("AUSYD", shipment.JS_RL_NKOrigin);
			AssertEquals("USCHI", shipment.JS_RL_NKDestination);

			AssertEquals("Consignor", consignor, shipment.Consignor);
			AssertEquals("Consignee", consignee, shipment.Consignee);

			AssertEquals(exportBroker, shipment.ExportBroker);
			AssertEquals(exportTransport.MainAddress, shipment.DocsAndCartage.PickupCartageCoAddr);
			AssertEquals(exportCFS.MainAddress, shipment.ExportReceivingDepot);

			AssertEquals(null, shipment.ImportBroker);
			AssertEquals(importTransport.MainAddress, shipment.DocsAndCartage.DeliveryCartageCoAddr);
			AssertEquals(importDeliveryAgent, shipment.DeliveryAgent);
			AssertEquals(importCFS.MainAddress, shipment.ImportReleaseDepot);

			shipment.JS_InterimReceipt = "Blah";
			shipment.JS_BookingReference = "BlahBlah";
			shipment.DocsAndCartage.JP_PickupLabourCharge = 1;
			shipment.DocsAndCartage.JP_PickupTruckWaitCharge = 2;
			shipment.DocsAndCartage.JP_DeliveryLabourCharge = 3;
			shipment.DocsAndCartage.JP_DeliveryTruckWaitCharge = 4;
			shipment.DocsAndCartage.JP_LCLAirStorageCharge = 5;
			shipment.DocsAndCartage.JP_LCLAirStorageDaysOrHours = 6;

			((ITemplateReversible)shipment).Reverse();

			AssertEquals("USCHI", shipment.JS_RL_NKOrigin);
			AssertEquals("AUSYD", shipment.JS_RL_NKDestination);

			AssertEquals("Consignor", consignee, shipment.Consignor);
			AssertEquals("Consignee", consignor, shipment.Consignee);

			AssertEquals(null, shipment.ExportBroker);
			AssertEquals(importTransport.MainAddress, shipment.DocsAndCartage.PickupCartageCoAddr);
			AssertEquals(importCFS.MainAddress, shipment.ExportReceivingDepot);

			AssertEquals(exportBroker, shipment.ImportBroker);
			AssertEquals(exportTransport.MainAddress, shipment.DocsAndCartage.DeliveryCartageCoAddr);
			AssertEquals(null, shipment.DeliveryAgent);
			AssertEquals(exportCFS.MainAddress, shipment.ImportReleaseDepot);

			AssertEquals(ZString.Empty, shipment.JS_InterimReceipt);
			AssertEquals(ZString.Empty, shipment.JS_BookingReference);
			AssertEquals((ZDecimal)0, shipment.DocsAndCartage.JP_PickupLabourCharge);
			AssertEquals((ZDecimal)0, shipment.DocsAndCartage.JP_PickupTruckWaitCharge);
			AssertEquals((ZDecimal)0, shipment.DocsAndCartage.JP_DeliveryLabourCharge);
			AssertEquals((ZDecimal)0, shipment.DocsAndCartage.JP_DeliveryTruckWaitCharge);
			AssertEquals((ZDecimal)0, shipment.DocsAndCartage.JP_LCLAirStorageCharge);
			AssertEquals((ZByte)0, shipment.DocsAndCartage.JP_LCLAirStorageDaysOrHours);
		}

