		public void TestJS_SZB()
		{
			var shipment = Factory.New<ForwardingShipment>();

			CombineAssertions("By default there should be no SZB", () =>
			{
				AssertEquals(ZString.Empty, shipment.JS_SZB);
				AssertEquals(ZString.Empty, shipment.JS_SZBInformation);
				AssertEquals(ZDateTime.Empty, shipment.JS_SZBIssueDate);
				AssertNull(shipment.Numbers.OfType<CusEntryNumber>().FirstOrDefault(n => n.CE_EntryType == GermanyAdditionalReferenceNumberTypes.Codes.SZBNumber));
			});

			shipment.JS_SZB = "FOO";
			AssertEquals("SZB was added", "FOO", shipment.JS_SZB);
			AssertEquals("SZB was added", 1, shipment.Numbers.OfType<CusEntryNumber>().Count(n => n.CE_EntryType == GermanyAdditionalReferenceNumberTypes.Codes.SZBNumber));

			shipment.JS_SZBInformation = "BAR";
			AssertEquals("BAR", shipment.JS_SZBInformation);
			AssertEquals("Only one SZB", 1, shipment.Numbers.OfType<CusEntryNumber>().Count(n => n.CE_EntryType == GermanyAdditionalReferenceNumberTypes.Codes.SZBNumber));

			shipment.JS_SZBIssueDate = new ZDateTime(2013, 10, 31);
			AssertEquals(new ZDateTime(2013, 10, 31), shipment.JS_SZBIssueDate);
			AssertEquals("Only one SZB", 1, shipment.Numbers.OfType<CusEntryNumber>().Count(n => n.CE_EntryType == GermanyAdditionalReferenceNumberTypes.Codes.SZBNumber));

			var szbNumber = shipment.Numbers.OfType<CusEntryNumber>().FirstOrDefault(n => n.CE_EntryType == GermanyAdditionalReferenceNumberTypes.Codes.SZBNumber);
			CombineAssertions("SZB CusEntryNumber properties", () =>
			{
				AssertEquals(shipment.PK, szbNumber.CE_ParentID);
				AssertEquals(shipment.TableName, szbNumber.CE_ParentTable);
				AssertEquals(GermanyAdditionalReferenceNumberTypes.Codes.SZBNumber, szbNumber.CE_EntryType);
				AssertEquals(GlbCompany.CurrentCompany.GC_RN_NKCountryCode, szbNumber.CE_RN_NKCountryCode);
				AssertEquals(true, szbNumber.CE_EntryIsSystemGenerated);
			});

			Factory.Save();

			var shipmentReloaded = new BusinessObjectFactory().Load<ForwardingShipment>(shipment.PK);
			CombineAssertions("SZB persisted", () =>
			{
				AssertEquals("FOO", shipmentReloaded.JS_SZB);
				AssertEquals("BAR", shipmentReloaded.JS_SZBInformation);
				AssertEquals(new ZDateTime(2013, 10, 31), shipmentReloaded.JS_SZBIssueDate);
			});
		}

		public void TestJS_SZB_SystemSZBCouldNotBeModifiedOrDeleted()
		{
			var creationFactory = new BusinessObjectFactory();
			var shipment = creationFactory.NewWithValidTestData<ForwardingShipment>();

			var systemSZB = shipment.Numbers.AddNew();
			systemSZB.CE_EntryType = GermanyAdditionalReferenceNumberTypes.Codes.SZBNumber;
			systemSZB.CE_EntryNum = "111";
			systemSZB.CE_EntryIsSystemGenerated = true;

			var userSZB = shipment.Numbers.AddNew();
			userSZB.CE_EntryType = GermanyAdditionalReferenceNumberTypes.Codes.SZBNumber;
			userSZB.CE_EntryNum = "222";

			var usualNumber = shipment.Numbers.AddNew();
			usualNumber.CE_EntryType = "AAA";
			usualNumber.CE_EntryNum = "333";

			creationFactory.Save();
			shipment = Factory.Load<ForwardingShipment>(shipment.PK);

			systemSZB = shipment.Numbers.OfType<CusEntryNumber>().First(n => n.CE_EntryNum == "111");
			Assert("System SZB is readonly", systemSZB.ReadOnly);

			userSZB = shipment.Numbers.OfType<CusEntryNumber>().First(n => n.CE_EntryNum == "222");
			Assert("User SZB is not readonly", !userSZB.ReadOnly);

			usualNumber = shipment.Numbers.OfType<CusEntryNumber>().First(n => n.CE_EntryNum == "333");
			Assert("Usual number is not readonly", !usualNumber.ReadOnly);

			Assert("System SZB could not be deleted", !systemSZB.CanDelete);
			AssertEquals("This SZB number was received from DAKOSY, it could not be deleted.", systemSZB.ReasonForNotAbleToDelete);

			Assert("User SZB could be deleted", userSZB.CanDelete);
			Assert("Usual number could be deleted", usualNumber.CanDelete);
		}

