		public void TestReadOnlySecurity_Phase_Disabled()
		{
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			AssertEquals("Precondition: phase security", false, shipment.IsReadOnlyDueToPhase);
			AssertPropertiesAndChildrenAreReadonly("Not readonly by default", shipment, false);

			shipment.ReadOnly = true;
			AssertEquals("Forced to true when shipment set to readonly", true, shipment.IsReadOnlyDueToPhase);

			shipment.ReadOnly = false;
			AssertEquals("Not readonly due to phase", false, shipment.IsReadOnlyDueToPhase);
		}

		public void TestReadOnlySecurity_Phase_Enabled()
		{
			var resolver = new Mock<IPhaseSecurityResolver>();
			resolver.Setup(m => m.IsEditingAllowed).Returns(false);
			resolver.Setup(m => m.IsPropertyMandatory(It.IsAny<ZString>())).Returns(false);
			resolver
				.Setup(m => m.InitialisePhaseDependantMandatoryValidation(It.IsAny<IEnumerable<ZPropertyInfo>>(), It.IsAny<ZGuid?>()))
				.Returns(Enumerable.Empty<ZPropertyInfo>());

			var shipmentMock = Factory.NewMoq<ForwardingShipment>();
			shipmentMock.Protected().Setup<IPhaseSecurityResolver>("GetPhaseSecurityResolver").Returns(resolver.Object);

			AssertEquals("Precondition: phase security", true, shipmentMock.Object.IsReadOnlyDueToPhase);
			AssertPropertiesAndChildrenAreReadonly("Readonly because of phase security", shipmentMock.Object, true);

			Env.Security.ShipmentPhaseSecurityOverride.IsAllowed = true;
			AssertEquals("Phase security does not apply to phase if user have rights", false, shipmentMock.Object.JS_PhaseInfo.ReadOnly);

			shipmentMock.Object.ReadOnly = false;
			AssertEquals("Still readonly due to phase", true, shipmentMock.Object.IsReadOnlyDueToPhase);
		}

		void AssertPropertiesAndChildrenAreReadonly(string message, ForwardingShipment shipment, bool expectedReadonly)
		{
			CombineAssertions(delegate
			{
				AssertEquals(message, expectedReadonly, shipment.JS_PackingModeInfo.ReadOnly);
				AssertEquals(message, expectedReadonly, shipment.JS_TransportModeInfo.ReadOnly);
				AssertEquals(message, expectedReadonly, shipment.JS_RL_NKOriginInfo.ReadOnly);
			});

			CombineAssertions(delegate
			{
				AssertEquals(message, expectedReadonly, shipment.DocsAndCartage.ReadOnly);
				AssertEquals(message, expectedReadonly, shipment.OuterPackLines.ReadOnly);
				AssertEquals(message, expectedReadonly, shipment.Transports.ReadOnly);
			});

			CombineAssertions(delegate
			{
				string excludedMessage = "This child should be excluded from phase security";

				new JobHeader.Loader(shipment).TryCreate();
				AssertEquals(excludedMessage, false, shipment.Job.ReadOnly);
			});
		}

		public void TestReadOnlySecurity_PropertiesAreForcedToReadOnly()
		{
			var resolver = new Mock<IPhaseSecurityResolver>();
			resolver.Setup(m => m.IsEditingAllowed).Returns(true);
			resolver
				.Setup(m => m.InitialisePhaseDependantMandatoryValidation(It.IsAny<IEnumerable<ZPropertyInfo>>(), It.IsAny<ZGuid?>()))
				.Returns(Enumerable.Empty<ZPropertyInfo>());

			resolver.Setup(m => m.IsEditingAllowed).Returns(true);
			resolver.Setup(m => m.IsPropertyReadOnly((ZString)"JS_PackingMode")).Returns(true);
			resolver.Setup(m => m.IsPropertyReadOnly((ZString)"JS_TransportMode")).Returns(false);

			resolver.Setup(m => m.RegisterEditableChild(It.IsAny<IBusiness>(), It.IsAny<ZString>()));

			resolver.Setup(m => m.IsPropertyReadOnly((ZString)"DocsAndCartage")).Returns(true);
			resolver.Setup(m => m.IsPropertyReadOnly((ZString)"OuterPackLines")).Returns(false);
			resolver.Setup(m => m.IsPropertyReadOnly((ZString)"PickupConfirms")).Returns(true);

			var shipmentMock = Factory.NewMoq<ForwardingShipment>();
			shipmentMock.Protected().Setup<IPhaseSecurityResolver>("GetPhaseSecurityResolver").Returns(resolver.Object);

			ForwardingShipment shipment = shipmentMock.Object;
			AssertEquals("Precondition", false, shipment.IsReadOnlyDueToPhase);

			AssertEquals(true, shipment.JS_PackingModeInfo.ReadOnly);
			AssertEquals(false, shipment.JS_TransportModeInfo.ReadOnly);

			AssertEquals(true, shipment.DocsAndCartage.ReadOnly);
			AssertEquals(false, shipment.OuterPackLines.ReadOnly);
			AssertEquals(true, shipment.PickupConfirms.ReadOnly);

			resolver.VerifyAll();
		}

