			ForwardingShipment shipment = shipmentMock.Object;
			AssertEquals("Precondition", true, shipment.IsReadOnlyDueToPhase);
			AssertEquals("If shipment is readonly due to phase, all properties should be readonly", true, shipment.IsChildPropertyReadOnlyDueToPhase(ZGuid.NewZGuid(), "RandomProperty"));

			resolver.VerifyAll();

			ZGuid childPK = ZGuid.NewZGuid();
			ZString childPropertyName = "ChildProperty";

			resolver = new Mock<IPhaseSecurityResolver>();
			resolver.Setup(m => m.IsEditingAllowed).Returns(true);
			resolver.Setup(m => m.IsChildPropertyReadOnly(It.IsAny<ZGuid>(), It.IsAny<ZString>())).Returns(false);

			shipmentMock = Factory.NewMoq<ForwardingShipment>();
			shipmentMock.Protected().Setup<IPhaseSecurityResolver>("GetPhaseSecurityResolver").Returns(resolver.Object);

			shipment = shipmentMock.Object;
			AssertEquals("Precondition", false, shipment.IsReadOnlyDueToPhase);
			AssertEquals(false, shipment.IsChildPropertyReadOnlyDueToPhase(childPK, childPropertyName));

			resolver.Setup(m => m.IsChildPropertyReadOnly(It.IsAny<ZGuid>(), It.IsAny<ZString>())).Returns(true);
			AssertEquals(true, shipment.IsChildPropertyReadOnlyDueToPhase(childPK, childPropertyName));

			resolver.VerifyAll();
		}

		public void TestReadOnlySecurity_RegisterEditableChildObjectWithName()
		{
			ChildEditableService.SetState(Factory, ChildEditableServiceStates.Shipment);
			AssertEquals("Precondition", ChildEditableServiceStates.Shipment, ChildEditableService.GetState(Factory));

			ForwardingShipmentForReadOnlySecurityTesting shipment = Factory.New<ForwardingShipmentForReadOnlySecurityTesting>();
			shipment.JS_TransportMode = Constants.TransportModes.Air;

			foreach (PropertyInfo propertyInfo in typeof(ForwardingShipment).GetProperties())
			{
				if (typeof(IBusiness).IsAssignableFrom(propertyInfo.PropertyType))
				{
					propertyInfo.GetValue(shipment, null);
				}
			}

			// Some children are registered with names in CommonShipment
			ZString[] expectedRegisteredNames = new ZString[]
			{
				"DocsAndCartage",
				"InnerPackLines",
				"OuterPackLines",
				"PickupConfirms",
				"DeliveryConfirms"
			};

			AssertContainsExactElementsInAnyOrder("Expected registered children with names", expectedRegisteredNames, shipment.RegisteredChildrenNames);

			ShipmentPhaseDependantsProvider dependantsProvider = new ShipmentPhaseDependantsProvider();
			List<ZString> supportedChildrenNamesFromRegistry = new List<ZString>();
			supportedChildrenNamesFromRegistry.AddRange(dependantsProvider.GetChildDependants().Select(x => x.Name));
			supportedChildrenNamesFromRegistry.AddRange(dependantsProvider.GetChildExpandableDependants().Keys.Select(key => key.Name));

			string message = "\r\n\r\nRegistered children with names should be in sync with the following class:\r\n" +
				"Enterprise.Freight.Forwarding.Registry.ShipmentPhaseDependantsProvider";

			AssertContainsExactElementsInAnyOrder(message, shipment.RegisteredChildrenNames, supportedChildrenNamesFromRegistry);
		}

		public void TestPhaseSecurity_AllProperties_InitializationIsSafe()
		{
			Action<bool> setupAndAssert = (isReadonly) =>
			{
				var creationFactory = new BusinessObjectFactory();

				var shipment = creationFactory.New<ForwardingShipment>();
				shipment.JS_Phase = "XXX";

				creationFactory.Save();

				var security = PhaseSecurityTestHelper.Shipment.SetupAllowed("XXX");
				var rule = security.Phases[0].Rules[0];

				var allCustomizablePropertyNames = new ShipmentPhaseDependantsProvider()
					.GetIZTypeProperties()
					.Select(p => p.Name)
					.ToArray();

				foreach (var propertyName in allCustomizablePropertyNames)
				{
					var dependant = rule.Dependants.AddNew();
					dependant.Name = propertyName;
					dependant.IsReadOnly = isReadonly;
					dependant.IsMandatory = !isReadonly;
				}

				ForwardingConfigurationRegistry.Instance.ShipmentPhaseSecurity.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, security);

				AssertNoExceptionThrown(() =>
				{
					shipment = new BusinessObjectFactory().Load<ForwardingShipment>(shipment.PK);

					foreach (var propertyInfo in shipment.ZPropertyInfoHash.Cast<ZPropertyInfo>())
					{
						var touchAndGo = propertyInfo.Value;
					}
				});
			};

			setupAndAssert(true);
			setupAndAssert(false);
		}

