		public void TestHandleSaveException_Shipment_CustomField()
		{
			var shipment = new BusinessObjectFactory { RefreshEnabled = false }.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_HouseBill = "AAA";
			shipment.Factory.Save();

			var reloadedShipment = new BusinessObjectFactory { RefreshEnabled = false }.Load<ForwardingShipment>(shipment.PK);
			reloadedShipment.JS_HouseBill = "AAA2";
			reloadedShipment.Factory.Save();

			var customValue = new BusinessObjectFactory { RefreshEnabled = false }.New<GenCustomAddOnValue>();
			customValue.XV_ParentID = shipment.PK;
			customValue.XV_ParentTableCode = JobShipmentSchema.Constants.Prefix;
			customValue.XV_Name = "AAA";
			customValue.XV_Type = "STR";
			customValue.XV_Data = "111";
			customValue.Factory.Save();

			shipment.JS_HouseBill = "AAA3";

			var customValueNew = shipment.Factory.New<GenCustomAddOnValue>();
			customValueNew.XV_ParentID = shipment.PK;
			customValueNew.XV_ParentTableCode = JobShipmentSchema.Constants.Prefix;
			customValueNew.XV_Name = "AAA";
			customValueNew.XV_Type = "STR";
			customValueNew.XV_Data = "222";

			AssertNoExceptionThrown(() => ZExceptionReporting.ProcessWithSaveExceptionHandling(shipment.Factory.Save, null, true));

			var finalFactory = new BusinessObjectFactory();
			var finalShipment = finalFactory.Load<ForwardingShipment>(shipment.PK);
			AssertEquals("AAA2", finalShipment.JS_HouseBill);

			AssertNull("customValue is deleted", finalFactory.Load<GenCustomAddOnValue>(customValue.PK));

			var finalCustomValue = finalFactory.Load<GenCustomAddOnValue>(customValueNew.PK);
			AssertNotNull(finalCustomValue);
			AssertEquals("222", finalCustomValue.XV_Data);
		}

