			customField2.XC_Type = AddOnColumnDataType.Codes.String;

			var customField3 = workflowTemplate.GenCustomColumnDefinitions.AddNew();
			customField3.XC_Name = "TestJobNo1";
			customField3.XC_Type = AddOnColumnDataType.Codes.Integer;

			Factory.Save();

			var locationsList = PhaseConstants.GetShipmentLocationsList();
			var phaseSecurity = new PhaseSecurity(locationsList);
			phaseSecurity.IsEnabled = true;

			var phase = phaseSecurity.Phases.AddNew();
			phase.Code = "XXX";
			phase.Description = (NoResString)"XXX Phase Description";

			var rule = phase.Rules.AddNew();
			rule.Location = PhaseConstants.Locations.AnyLocation;
			rule.DepartmentPK = GlbDepartment.CurrentDepartment.PK;

			Action<string, bool> addDependant = (dependantName, readOnly) =>
			{
				var dependant = rule.Dependants.AddNew();
				dependant.DependantType = PhaseConstants.DependantType.Property;
				dependant.Name = dependantName;
				dependant.Description = dependantName;
				dependant.IsReadOnly = readOnly;
			};

			addDependant("__TESTJOBNO1__prop__ZString", true);
			addDependant("__TESTJOBNO2__prop__ZString", false);
			addDependant("__TESTJOBNO1__prop__ZInt", false);

			phaseSecurity.Phases.Add(phase);

			using (ForwardingConfigurationRegistry.Instance.ShipmentPhaseSecurity.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, phaseSecurity))
			{
				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
				shipment.JS_TransportMode = Constants.TransportModes.Sea;
				shipment.JS_Phase = "ALL";

				var customFields = ((ICustomFieldProvider)shipment).GetCustomBusinessObject();
				var propertyNames = ((IDynamicBusinessObject)customFields).PropertyNames;
				AssertContainsExactElementsInAnyOrder(new[] { "__TESTJOBNO1__prop__ZString", "__TESTJOBNO1__prop__ZStringInfo", "__TESTJOBNO2__prop__ZString", "__TESTJOBNO2__prop__ZStringInfo", "__TESTJOBNO1__prop__ZInt", "__TESTJOBNO1__prop__ZIntInfo" }, propertyNames);

				ZPropertyInfo customFieldInfo1 = customFields.FindPropertyInfo("__TESTJOBNO1__prop__ZString");
				ZPropertyInfo customFieldInfo2 = customFields.FindPropertyInfo("__TESTJOBNO2__prop__ZString");
				ZPropertyInfo customFieldInfo3 = customFields.FindPropertyInfo("__TESTJOBNO1__prop__ZInt");
				AssertNotNull(customFieldInfo1);
				AssertNotNull(customFieldInfo2);
				AssertNotNull(customFieldInfo3);

				AssertEquals("ALL", shipment.JS_Phase);
				AssertEquals("Phase: ALL, ReadOnly should be false", false, customFieldInfo1.ReadOnly);
				AssertEquals("Phase: ALL, ReadOnly should be false", false, customFieldInfo2.ReadOnly);
				AssertEquals("Phase: ALL, ReadOnly should be false", false, customFieldInfo3.ReadOnly);

				shipment.JS_Phase = "XXX";
				AssertEquals("Phase: XXX, ReadOnly should be true", true, customFieldInfo1.ReadOnly);
				AssertEquals("Phase: XXX, ReadOnly should be false", false, customFieldInfo2.ReadOnly);
				AssertEquals("Phase: XXX, ReadOnly should be false", false, customFieldInfo3.ReadOnly);
			}
		}

		public void TestCopyShipmentTemplate()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			var shipment2 = Factory.New<ForwardingShipment>();
			var templateRecord = Factory.New<StmTemplateRecord>();

			var templateRecordProvider = shipment as ITemplateRecordProvider;
			templateRecordProvider.TemplateRecord = templateRecord;

			using (((IDbConnected)Factory).Connection.BeginTransactionWithManager()) // Fountain GetNext() requires a transaction
			{
				templateRecordProvider.SaveToTemplateRecord();
			}

			var templateRecordProvider2 = shipment2 as ITemplateRecordProvider;
			templateRecordProvider2.LoadFromTemplateRecord(templateRecord);

			var copy = (ForwardingShipment)shipment2.TemplateCopy(Factory);
			Assert("Before save the copy doesn't have a consignref", string.IsNullOrEmpty(copy.JS_UniqueConsignRef));

			Factory.Save();
			Assert("After save the copy has a consignref", !string.IsNullOrEmpty(copy.JS_UniqueConsignRef));
		}

