		public void TestGetNameOfRelatedItem()
		{
			var shipment = Factory.New<ForwardingShipment>();
			var masterShipment = Factory.New<ForwardingShipment>();

			shipment.JS_JS_ColoadMasterShipment = masterShipment.PK;

			var consol1 = shipment.Consols.AddNew();
			var consol2 = shipment.Consols.AddNew();
			var consol3 = shipment.Consols.AddNew();
			var consol4 = masterShipment.Consols.AddNew();
			var consol5 = Factory.New<ForwardingConsol>();

			var transport = shipment.Transports.AddNew();
			transport.JW_ETD = ZDateTime.Now.AddDays(1);
			transport.JW_ETA = ZDateTime.Now.AddDays(2);

			var relatedItemsNameProvider = (IRelatedItemsNameProvider)shipment;

			AssertEquals(ZString.Empty, relatedItemsNameProvider.GetNameOfRelatedItem(shipment));
			AssertEquals("Master Shipment", relatedItemsNameProvider.GetNameOfRelatedItem(masterShipment));
			AssertEquals("Departure Consol", relatedItemsNameProvider.GetNameOfRelatedItem(consol1));
			AssertEquals("Transship. Consol", relatedItemsNameProvider.GetNameOfRelatedItem(consol2));
			AssertEquals("Arrival Consol", relatedItemsNameProvider.GetNameOfRelatedItem(consol3));
			AssertEquals("Master Shipment, Consol", relatedItemsNameProvider.GetNameOfRelatedItem(consol4));
			AssertEquals(ZString.Empty, relatedItemsNameProvider.GetNameOfRelatedItem(consol5));
			AssertEquals("No related item name for transport (for now)", ZString.Empty, relatedItemsNameProvider.GetNameOfRelatedItem(transport));
		}

