		public void TestAUCusHAWB()
		{
			ZGuid shipmentPK;
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.NewZealand))
			{
				var consol = Factory.New<ForwardingConsol>();
				consol.JK_RL_NKLoadPort = "NZAKL";
				consol.JK_RL_NKDischargePort = "AUSYD";
				consol.JK_TransportMode = "AIR";
				var shipment = consol.Shipments.AddNew();
				var masterBillNZ = Factory.New<NZ.ICusMAWB>() as BusinessObject;
				var houseBillNZ = Factory.New<ICusHAWB>() as BusinessObject;
				houseBillNZ[CusHAWBSchema.CS_CM] = masterBillNZ.PK;
				houseBillNZ[CusHAWBSchema.CS_JS] = shipmentPK = shipment.PK;
				houseBillNZ[CusHAWBSchema.CS_HAWB] = "HBNZ";
				Factory.Save();

				AssertEquals(Core.Constants.Customs.ExpressApplicationCodes.NZ.TSWWriteOff, masterBillNZ[CusMAWBSchema.CM_ApplicationCode]);
				AssertNull("No AU House Bill exists on this Shipment", shipment.AUCusHAWB);
			}

			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.Australia))
			{
				var otherFactory = new BusinessObjectFactory();
				var shipmentIOF = otherFactory.Load<ForwardingShipment>(shipmentPK);
				AssertNull("No AU House Bill exists on this Shipment", shipmentIOF.AUCusHAWB);

				var masterBillAU = otherFactory.New<IAUCusMAWB>() as BusinessObject;
				var houseBillAU = otherFactory.New<IAUCusHAWB>() as BusinessObject;
				houseBillAU[CusHAWBSchema.CS_CM] = masterBillAU.PK;
				houseBillAU[CusHAWBSchema.CS_JS] = shipmentPK;
				houseBillAU[CusHAWBSchema.CS_HAWB] = "HBAU";
				otherFactory.Save();

				AssertEquals(Core.Constants.AUCustoms.ImportMessagingMode.ForceCMRMessages, masterBillAU[CusMAWBSchema.CM_ApplicationCode]);
				AssertEquals("The AU House Bill was returned", "HBAU", shipmentIOF.AUCusHAWB.CS_HAWB);

				var consolIOF = shipmentIOF.Consols.Cast<ForwardingConsol>().First();
				consolIOF.JK_RL_NKDischargePort = "FJSUV";
				AssertNull("Should be null as Discharge is not Australia", shipmentIOF.AUCusHAWB);

				consolIOF.JK_RL_NKDischargePort = "AUSYD";
				AssertEquals("The AU House Bill was returned", "HBAU", shipmentIOF.AUCusHAWB.CS_HAWB);

				using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.NewZealand))
				{
					AssertNull("The AU House Bill on this Shipment is not visible from NZ Company", shipmentIOF.AUCusHAWB);
				}
			}
		}

