		public void TestBizOsWithRelatedEvents_WhenHVLType_ContainsAirCargoMasterBills()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = TransportModes.Air;
			shipment.JS_ShipmentType = ShipmentTypes.HighVolumeLowValue;

			var consol = shipment.Consols.AddNew();

			var leg = consol.Transports.AddNew();
			leg.JW_TransportMode = TransportModes.Air;
			leg.JW_RL_NKLoadPort = Env.CurrentCompany.Country.Code + "AAA";
			leg.JW_RL_NKDiscPort = "AUSYD";

			var mawb = Factory.New<ICusMAWB>();
			var hawb = Factory.New<ICusHAWB>();
			mawb.CM_MAWB = "12312341234";
			mawb.CM_MasterHouseBill = "HB111000";
			mawb.CM_ApplicationCode = Core.Constants.AUCustoms.ImportMessagingMode.ForceCMRMessages;

			hawb.CS_CM = mawb.PK;
			hawb.CS_MasterHouseBill = "HB111000";
			Factory.Save();

			AssertCollectionNotContains(mawb, shipment.BusinessObjectsWithRelatedEvents);

			shipment.JS_HouseBill = "HB111000";
			consol.JK_MasterBillNum = mawb.CM_MAWB;
			hawb.CS_JS = shipment.PK;
			mawb.CM_JK = consol.PK;
			Factory.Save();

			AssertCollectionContains("The master bill should be part of the shipment's BusinessObjectsWithRelatedEvents", mawb, shipment.BusinessObjectsWithRelatedEvents);
		}

