		public void TestCancellation()
		{
			var shipment = Factory.New<ForwardingShipment>();
			var declaration = Factory.New<IBaseJobDeclaration>();
			declaration.JE_JS = shipment.PK;
			var header1 = Factory.New<US.InBond.ICusInBondHeader>();
			header1.BH_ParentID = shipment.PK;
			header1.BH_ParentTableCode = shipment.TablePrefix;
			var header2 = Factory.New<US.InBond.ICusInBondHeader>();
			header2.BH_ParentID = shipment.PK;
			header2.BH_ParentTableCode = shipment.TablePrefix;

			shipment.IsCancelled = true;
			Assert(declaration.JE_IsCancelled);
			Assert(header1.IsCancelled);
			Assert(header2.IsCancelled);

			shipment.IsCancelled = false;
			Assert(!declaration.JE_IsCancelled);
			Assert(!header1.IsCancelled);
			Assert(!header2.IsCancelled);
		}

