		public void TestFreightSpotRates_ReadOnly()
		{
			var shipment = Factory.New<ForwardingShipment>();

			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentSellRate);
			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentCostRate);
			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentGatewaySellRate);

			var consol = shipment.Consols.AddNew();
			consol.JK_TransportMode = Constants.TransportModes.Sea;
			consol.JK_RL_NKLoadPort = "AUBNE";

			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentSellRate);
			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentCostRate);
			AssertFreightSpotRateReadOnly(shipment, true, SpotRateType.ShipmentGatewaySellRate);

			var org = Factory.NewWithValidTestData<OrgHeader>();

			consol.JK_OA_SendingForwarderAddress = org.MainAddress.PK;
			consol.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;

			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentSellRate);
			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentCostRate);
			AssertFreightSpotRateReadOnly(shipment, true, SpotRateType.ShipmentGatewaySellRate);

			consol.JK_OA_SendingForwarderAddress = GlbCompany.CurrentCompany.OrgProxy.MainAddress.PK;
			var orgAppointedAgentPorts = Factory.New<OrgAppointedAgentPorts>();
			orgAppointedAgentPorts.O5_PortOrCountry = "AUBNE";
			orgAppointedAgentPorts.O5_AgentDirection = AgentDirectionList.Codes.Both;
			orgAppointedAgentPorts.O5_SeaAgentStatus = AgentStatusList.Codes.GatewayAgent;
			consol.SendingForwarder.AppointedGatewayAgentPorts.Add(orgAppointedAgentPorts);

			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentSellRate);
			AssertFreightSpotRateReadOnly(shipment, true, SpotRateType.ShipmentCostRate);
			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentGatewaySellRate);

			shipment.JS_UnitFreightRate = 120.2516m;

			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentSellRate);
			AssertFreightSpotRateReadOnly(shipment, true, SpotRateType.ShipmentCostRate);
			AssertFreightSpotRateReadOnly(shipment, true, SpotRateType.ShipmentGatewaySellRate);

			var department = Factory.LoadTop1<GlbDepartment>(new ZQuery(GlbDepartmentSchema.GE_Code, "GEA"));
			using (Env.SetTemporaryUserContext(Env.CurrentUser.LoginName, Env.CurrentBranch.PK, department.PK.ToGuid()))
			{
				AssertEquals(true, GlbDepartment.CurrentDepartment.IsGatewayDepartment);

				AssertFreightSpotRateReadOnly(shipment, true, SpotRateType.ShipmentSellRate);
				AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentCostRate);
				AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentGatewaySellRate);

				consol.JK_OA_SendingForwarderAddress = org.MainAddress.PK;

				AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentSellRate);
				AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentCostRate);
				AssertFreightSpotRateReadOnly(shipment, true, SpotRateType.ShipmentGatewaySellRate);
			}
		}

		public void TestFreightSpotRates_ReadOnly_AnotherBranchOrCompanyActingAsGateway()
		{
			var shipment = Factory.New<ForwardingShipment>();
			var consol = shipment.Consols.AddNew();
			consol.JK_TransportMode = Constants.TransportModes.Sea;
			consol.JK_RL_NKLoadPort = "AUBNE";

			var anotherCompanyQuery = new ZQuery(GlbCompanySchema.GC_OH_OrgProxy, SQLComparisonOperator.NotEqual, GlbCompany.CurrentCompany.GC_OH_OrgProxy);
			var anotherCompany = Factory.LoadTop1<GlbCompany>(anotherCompanyQuery);

			Assert("Precondition: Another company exists", anotherCompany != null);

			var anotherBranch = anotherCompany.Branches.AddNew();
			var anotherBranchOrg = Factory.NewWithValidTestData<OrgHeader>();

			anotherBranch.GB_OH_OrgProxy = anotherBranchOrg.PK;

			Factory.Save();

			consol.JK_OA_SendingForwarderAddress = anotherBranchOrg.MainAddress.PK;
			consol.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			var orgAppointedAgentPorts1 = consol.SendingForwarder.AppointedGatewayAgentPorts.AddNew();
			orgAppointedAgentPorts1.O5_OA_AgentOfficeAddress = consol.JK_OA_SendingForwarderAddress;
			orgAppointedAgentPorts1.O5_PortOrCountry = "AUBNE";
			orgAppointedAgentPorts1.O5_AgentDirection = AgentDirectionList.Codes.Both;
			orgAppointedAgentPorts1.O5_SeaAgentStatus = AgentStatusList.Codes.GatewayAgent;

			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentSellRate);
			AssertFreightSpotRateReadOnly(shipment, true, SpotRateType.ShipmentCostRate);
			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentGatewaySellRate);

			shipment.JS_UnitFreightRate = 120.2516m;

			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentSellRate);
			AssertFreightSpotRateReadOnly(shipment, true, SpotRateType.ShipmentCostRate);
			AssertFreightSpotRateReadOnly(shipment, true, SpotRateType.ShipmentGatewaySellRate);

			consol.JK_OA_SendingForwarderAddress = anotherCompany.OrgProxy.MainAddress.PK;
			var orgAppointedAgentPorts2 = consol.SendingForwarder.AppointedGatewayAgentPorts.AddNew();
			orgAppointedAgentPorts2.O5_OA_AgentOfficeAddress = consol.JK_OA_SendingForwarderAddress;
			orgAppointedAgentPorts2.O5_PortOrCountry = "AUBNE";
			orgAppointedAgentPorts2.O5_AgentDirection = AgentDirectionList.Codes.Both;
			orgAppointedAgentPorts2.O5_SeaAgentStatus = AgentStatusList.Codes.GatewayAgent;

			shipment.JS_UnitFreightRate = 0m;

			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentSellRate);
			AssertFreightSpotRateReadOnly(shipment, true, SpotRateType.ShipmentCostRate);
			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentGatewaySellRate);

			shipment.JS_UnitFreightRate = 120.2516m;

			AssertFreightSpotRateReadOnly(shipment, false, SpotRateType.ShipmentSellRate);
			AssertFreightSpotRateReadOnly(shipment, true, SpotRateType.ShipmentCostRate);
			AssertFreightSpotRateReadOnly(shipment, true, SpotRateType.ShipmentGatewaySellRate);
		}

		void AssertFreightSpotRateReadOnly(ForwardingShipment shipment, bool readOnly, SpotRateType rateType)
		{
			switch (rateType)
			{
				case SpotRateType.ShipmentSellRate:
					AssertEquals(readOnly, shipment.JS_UnitFreightRateInfo.ReadOnly);
					AssertEquals(readOnly, shipment.JS_FreightSpotRateAutoratingModeInfo.ReadOnly);
					AssertEquals(readOnly, shipment.JS_RX_NKFrtRateCurrencyInfo.ReadOnly);
					break;

				case SpotRateType.ShipmentCostRate:
					AssertEquals(readOnly, shipment.JS_FreightCostRateInfo.ReadOnly);
					AssertEquals(readOnly, shipment.JS_FreightCostRateAutoratingModeInfo.ReadOnly);
					AssertEquals(readOnly, shipment.JS_RX_NKFreightCostRateCurrencyInfo.ReadOnly);
					break;

				case SpotRateType.ShipmentGatewaySellRate:
					AssertEquals(readOnly, shipment.JS_GatewayFreightSellRateInfo.ReadOnly);
					AssertEquals(readOnly, shipment.JS_FreightGatewaySellRateAutoratingModeInfo.ReadOnly);
					AssertEquals(readOnly, shipment.JS_RX_NKGatewayFreightSellRateCurrencyInfo.ReadOnly);
					break;
			}
		}

		public void TestHasConsolSendingAgentActingAsGatewayInAnyCompany_Cache()
		{
			var shipment = Factory.New<ForwardingShipment>();
			var consol = Factory.New<ForwardingConsol>();
			consol.JK_TransportMode = TransportModes.Sea;
			consol.JK_RL_NKLoadPort = "AUBNE";
			consol.JK_OA_SendingForwarderAddress = GlbCompany.CurrentCompany.OrgProxy.MainAddress.PK;
			Factory.Save();

			ForwardingConsolGatewayBillingSupporterTest.SetGatewayAgentPortOnConsolFromSendingAgent(consol, GlbCompany.CurrentCompany.OrgProxy);

			CombineAssertions("cache recalculation scenarios", () =>
			{
				AssertEquals("pre: should be false initially", false, shipment.HasConsolSendingAgentActingAsGatewayInAnyCompanyExposed);
				shipment.Consols.Add(consol);
				AssertEquals("consol is attached", true, shipment.HasConsolSendingAgentActingAsGatewayInAnyCompanyExposed);
				shipment.Consols.Remove(consol);
				AssertEquals("consol is removed", false, shipment.HasConsolSendingAgentActingAsGatewayInAnyCompanyExposed);
				shipment.Consols.Add(consol);
				AssertEquals("consol is added (2)", true, shipment.HasConsolSendingAgentActingAsGatewayInAnyCompanyExposed);
				consol.JK_OA_SendingForwarderAddress = Guid.Empty;
				AssertEquals("JK_OA_SendingForwarderAddress is set", false, shipment.HasConsolSendingAgentActingAsGatewayInAnyCompanyExposed);
			});
		}

