		public void TestUpdateInspectionTypeWhenShipmentDatesChange()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry("US"))
			{
				var usShipment = Factory.New<ForwardingShipment>();
				usShipment.JS_TransportMode = "AIR";
				usShipment.JS_RL_NKOrigin = "JPOSA";
				usShipment.JS_RL_NKDestination = "BRRIO";

				AssertEquals("Inspection type defaults to UNK", "UNK", usShipment.JS_InspectionTypeCode);

				usShipment.JS_InspectionTypeCode = "APP";
				usShipment.JS_E_DEP = ZDateTime.Now.AddDays(1);

				AssertEquals("Inspection type is not recalculated when JS_E_DEP changes", "APP", usShipment.JS_InspectionTypeCode);
			}

			using (GlbCompany.CurrentCompany.TemporarilySetCountry("JP"))
			{
				var jpShipment = Factory.New<ForwardingShipment>();
				jpShipment.JS_TransportMode = "AIR";
				jpShipment.JS_RL_NKOrigin = "JPOSA";
				jpShipment.JS_RL_NKDestination = "BRRIO";

				AssertEquals("Inspection type defaults to UNK", "UNK", jpShipment.JS_InspectionTypeCode);

				jpShipment.JS_InspectionTypeCode = "APP";
				jpShipment.JS_E_DEP = ZDateTime.Now.AddDays(1);

				AssertEquals("Inspection type is recalculated when JS_E_DEP changes", "UNK", jpShipment.JS_InspectionTypeCode);

				jpShipment.JS_InspectionTypeCode = "XRY";
				jpShipment.JS_E_DEP = ZDateTime.Now.AddDays(2);

				AssertEquals("Inspection type is not recalculated when it is a user entered value", "XRY", jpShipment.JS_InspectionTypeCode);
			}
		}

