		public void TestJS_InspectionTypeCode_LogSecurityModifiedEvent_AutomaticRecalculate()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.Jamaica))
			{
				using (FreightDataRegistry.Instance.ShipmentInspectionTypeDefault.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, string.Empty))
				{
					var shipment = Factory.New<ForwardingShipment>();
					shipment.GetReasonChangingSecurityInspectionStatusEventHandler += (sender, arg) => arg.Reason = "test reason";

					var consignor = Factory.NewWithValidTestData<OrgHeader>();
					consignor.CountryData.OV_EXApprovedOrMajorExporter = AviationSecuritySchemeMembershipEx.Codes.Yes;

					shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
					shipment.ConsignorDocumentaryAddress.E2_OA_Address = consignor.MainAddress.PK;
					shipment.JS_RL_NKOrigin = "JMKIN";
					AssertEquals(string.Empty, shipment.JS_InspectionTypeCode);

					shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
					shipment.ConsignorDocumentaryAddress.E2_OA_Address = ZGuid.Empty;
					shipment.ConsignorDocumentaryAddress.E2_OA_Address = consignor.MainAddress.PK;
					AssertEquals(BaseJobShipmentLookups.InspectionType_Approved, shipment.JS_InspectionTypeCode);

					Factory.Save();
					AssertEquals(1, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.SecurityModified.Code).Count());

					var secEvent = shipment.Logs.MostRecentLogByEventTime(Events.SecurityModified);
					AssertNotNull(secEvent);
					AssertEquals("|NEW=APP|RES=Automatically calculated", secEvent.SL_Reference);
				}
			}
		}

		public void TestJS_InspectionTypeCode_LogSecurityModifiedEvent_AutomaticRecalculateAfterManualChange()
		{
			var consignor = Factory.NewWithValidTestData<OrgHeader>();

			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.Jamaica))
			using (FreightDataRegistry.Instance.ShipmentInspectionTypeDefault.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, FreightDataRegistry.AviationSecurity_Unknown_Code))
			{
				var shipment = Factory.New<ForwardingShipment>();

				shipment.GetReasonChangingSecurityInspectionStatusEventHandler += (sender, arg) => arg.Reason = "test reason";

				consignor.OH_Code = "CONSIGNOR";
				consignor.OH_FullName = "Supplier";
				consignor.MainAddress.OA_Address1 = "Supplier Address";
				consignor.CountryData.OV_EXApprovedOrMajorExporter = AviationSecuritySchemeMembershipEx.Codes.Yes;

				shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
				shipment.ConsignorDocumentaryAddress.E2_OA_Address = consignor.MainAddress.PK;
				shipment.JS_RL_NKOrigin = "JMKIN";
				AssertEquals(FreightDataRegistry.AviationSecurity_Unknown_Code, shipment.JS_InspectionTypeCode);

				shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
				shipment.ConsignorDocumentaryAddress.E2_OA_Address = ZGuid.Empty;
				shipment.ConsignorDocumentaryAddress.E2_OA_Address = consignor.MainAddress.PK;
				AssertEquals(BaseJobShipmentLookups.InspectionType_Approved, shipment.JS_InspectionTypeCode);

				shipment.JS_InspectionTypeCode = ScreeningMethods.Codes.XRayEquipment;
				AssertEquals(ScreeningMethods.Codes.XRayEquipment, shipment.JS_InspectionTypeCode);

				shipment.SetApprovedShipperStatus("", true);

				Factory.Save();
				AssertEquals(1, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.SecurityModified.Code).Count());

				var secEvent = shipment.Logs.MostRecentLogByEventTime(Events.SecurityModified);
				AssertNotNull(secEvent);
				AssertEquals("|NEW=APP|OLD=UNK", secEvent.SL_Reference);
			}
		}

