				shipment.JS_InspectionTypeCode = ExemptionCodes.Codes.BiomedicalSamples;
				AssertEquals(ExemptionCodes.Codes.BiomedicalSamples, shipment.JS_InspectionTypeCode);

				Factory.Save();

				AssertEquals("Log is created for change from UNK to BIO", 1, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.SecurityModified.Code).Count());

				shipment.GetReasonChangingSecurityInspectionStatusEventHandler += (sender, arg) => arg.Reason = "test reason";
				shipment.JS_InspectionTypeCode = ExemptionCodes.Codes.NuclearMaterial;
				AssertEquals(ExemptionCodes.Codes.NuclearMaterial, shipment.JS_InspectionTypeCode);

				shipment.JS_InspectionTypeCode = ExemptionCodes.Codes.BiomedicalSamples;
				AssertEquals(ExemptionCodes.Codes.BiomedicalSamples, shipment.JS_InspectionTypeCode);

				Factory.Save();
				AssertEquals("No new log is created as Inspection Type has not changed", 1, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.SecurityModified.Code).Count());
