		public void AssertWriteAndReadTemplateRecord()
		{
			var shipment1 = Factory.New<ForwardingShipment>();
			shipment1.JS_TransportMode = "SEA";
			shipment1.JS_HouseBill = "H0000TST1";
			shipment1.JS_HouseBillOfLadingType = "FIA";

			var templateRecord = Factory.New<StmTemplateRecord>();
			var templateRecordProvider1 = shipment1 as ITemplateRecordProvider;
			templateRecordProvider1.TemplateRecord = templateRecord;

			using (((IDbConnected)Factory).Connection.BeginTransactionWithManager()) // Fountain GetNext() requires a transaction
			{
				templateRecordProvider1.SaveToTemplateRecord();
			}

			var shipment2 = Factory.New<ForwardingShipment>();
			var templateRecordProvider2 = shipment2 as ITemplateRecordProvider;

			AssertNotEquals(shipment1.JS_TransportMode, shipment2.JS_TransportMode);
			AssertNotEquals(shipment1.JS_HouseBill, shipment2.JS_HouseBill);
			AssertNotEquals(shipment1.JS_HouseBillOfLadingType, shipment2.JS_HouseBillOfLadingType);

			templateRecordProvider2.LoadFromTemplateRecord(templateRecord);

			AssertEquals(shipment1.JS_TransportMode, shipment2.JS_TransportMode);
			AssertEquals(shipment1.JS_HouseBill, shipment2.JS_HouseBill);
			AssertEquals(shipment1.JS_HouseBillOfLadingType, shipment2.JS_HouseBillOfLadingType);
		}

		public void TestLoadFromTemplateRecordHasNoChanges()
		{
			// Create a template record shipment and save it to db
			var templateRecordShipmentFactory = new TemplateRecordBusinessObjectFactory { RefreshEnabled = false };
			var shipment = templateRecordShipmentFactory.New<ForwardingShipment>();

			var templateRecord = templateRecordShipmentFactory.TemplateRecordFactory.New<StmTemplateRecord>();
			templateRecord.STR_ModuleID = "JobShipment";

			templateRecordShipmentFactory.TemplateRecordProvider = shipment;
			templateRecordShipmentFactory.TemplateRecordProvider.IsTemplateRecord = true;
			templateRecordShipmentFactory.TemplateRecordProvider.TemplateRecord = templateRecord;

			shipment.JS_TransportMode = "AIR";
			templateRecordShipmentFactory.Save();

			// Reload template record shipment from db
			var newFactory = new BusinessObjectFactory { RefreshEnabled = false };

			AssertEquals("No real shipment record should be saved in db", 0, newFactory.GetDatabaseCount(typeof(ForwardingShipment), new ZQuery(JobShipmentSchema.PK, shipment.PK)));
			AssertEquals("Tempalet record should be saved in db", 1, newFactory.GetDatabaseCount(typeof(StmTemplateRecord), new ZQuery(StmTemplateRecordSchema.PK, templateRecord.PK)));

			var localTemplateRecord = newFactory.Load<StmTemplateRecord>(templateRecord.PK);
			var localShipment = newFactory.New<ForwardingShipment>();
			((ITemplateRecordProvider)localShipment).LoadFromTemplateRecord(localTemplateRecord);

			Assert("Should be in db", localShipment.IsInDatabase);
			Assert("Should not have changes", !localShipment.HasChanges);
		}

