		public void TestDensity_AIR()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_UnitOfVolume = Constants.Volume.CubicMetres;
			shipment.JS_UnitOfWeight = Constants.Weight.Kilograms;
			shipment.JS_TransportMode = Constants.TransportModes.Air;

			var density = shipment.Density;
			CombineAssertions(() =>
			{
				AssertNotNull("Density should be initialized", density);
				AssertEquals("Density Factor should have default value", Density.DensityFactorForZeroDivision, density.DensityFactor);
				AssertEquals("Density Remark should have default value", Density.NAValueForZeroDivision, density.DensityRemark);
				AssertEquals("Volume Ratio should have default value", Density.NAValueForZeroDivision, density.VolumeRatio);
			});

			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "USLAX";
			shipment.JS_ActualVolume = 0.006m;
			shipment.JS_ActualWeight = 2m;
			CombineAssertions(() =>
			{
				AssertEquals("Density Factor should be re-calculated", 0.5m, density.DensityFactor);
				AssertEquals("Density Remark should be re-calculated", "Dense ++", density.DensityRemark);
				AssertEquals("Volume Ratio should be re-calculated", "1:3", density.VolumeRatio);
			});
		}

