		public void TestIsHazardous_HazardousCommodityCodePropagatesToShipment()
		{
			var shipment = Factory.New<ForwardingModuleShipment>();
			var packline = shipment.OuterPackLines.AddNew();

			var commodity_HAZ = Factory.LoadFromNaturalKey<RefCommodityCode>(RefCommodityCodeSchema.RH_Code, "HAZ");

			var commodity_NotHAZ = Factory.New<RefCommodityCode>();
			commodity_NotHAZ.RH_Code = "TES";

			packline.JL_RH_NKCommodityCode = commodity_HAZ.RH_Code;
			commodity_NotHAZ.RH_IsHazardous = false;

