		public void TestCommodityAttributesPropagatesToShipment()
		{
			var shipment = Factory.New<ForwardingShipment>();
			var packline = shipment.OuterPackLines.AddNew();
			var commodity = Factory.New<RefCommodityCode>();
			commodity.RH_Code = "TES";

			commodity.RH_IsTimber = false;
			commodity.RH_IsPerishable = true;
			commodity.RH_IsFlammable = false;
			commodity.RH_ContainerVentRequired = true;

			packline.JL_RH_NKCommodityCode = commodity.RH_Code;

			AssertEquals("Should be Timber", false, shipment.IsTimber);
			AssertEquals("Should be Perishable", true, shipment.IsPerishable);
			AssertEquals("Should be Flammable", false, shipment.IsFlammable);
			AssertEquals("Should require Container Vent", true, shipment.IsContainerVentRequired);

			commodity.RH_IsTimber = true;
			commodity.RH_IsPerishable = false;
			commodity.RH_IsFlammable = true;
			commodity.RH_ContainerVentRequired = false;

			AssertEquals("Should not be Timber", true, shipment.IsTimber);
			AssertEquals("Should not be Perishable", false, shipment.IsPerishable);
			AssertEquals("Should not be Flammable", true, shipment.IsFlammable);
			AssertEquals("Should not require Container Vent", false, shipment.IsContainerVentRequired);
		}

