		#region TestJS_Calc_LastKnownTransitWarehouseStatus

		public void TestJS_Calc_LastKnownTransitWarehouseStatus()
		{
			var shipment = Factory.New<ForwardingShipment>();
			var warehouse1 = CreateWarehouse("WHS01");

			var warehouse2 = CreateWarehouse("WHS02");
			var warehouse2NewAddress = warehouse2.Addresses.AddNew();
			warehouse2NewAddress.OA_Address1 = "Warehouse2 Address 2";

			CreatePackLineWithTWStatus(shipment, warehouse1.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Dispatched);

			var consol = shipment.Consols.AddNew();
			consol.JK_TransportMode = Constants.TransportModes.Sea;
			consol.JK_OA_PackDepotAddress = warehouse1.MainAddress.PK;
			consol.JK_OA_UnpackDepotAddress = warehouse2NewAddress.PK;

			AssertEquals("Only one status for one warehouse", "WHS01: DSP", shipment.JS_Calc_LastKnownTransitWarehouseStatus);

			CreatePackLineWithTWStatus(shipment, warehouse1.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Received);
			AssertEquals("Combine all status per warehouse", "WHS01: RCV, DSP", shipment.JS_Calc_LastKnownTransitWarehouseStatus);

			CreatePackLineWithTWStatus(shipment, warehouse1.MainAddress.PK, string.Empty);
			AssertEquals("Use 'UNK' instead of an empty TW status", "WHS01: UNK, RCV, DSP", shipment.JS_Calc_LastKnownTransitWarehouseStatus);

			CreatePackLineWithTWStatus(shipment, warehouse2.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Dispatched);
			CreatePackLineWithTWStatus(shipment, warehouse2NewAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Dispatched);
			CreatePackLineWithTWStatus(shipment, warehouse2.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Received);

			AssertEquals("Combine for different warehouses", "WHS01: UNK, RCV, DSP | WHS02: RCV, DSP", shipment.JS_Calc_LastKnownTransitWarehouseStatus);

			CreatePackLineWithTWStatus(shipment, ZGuid.Empty, string.Empty);
			AssertEquals("Leave warehouse org as empty and status as 'UNK' when both warehouse and status are empty", ": UNK | WHS01: UNK, RCV, DSP | WHS02: RCV, DSP", shipment.JS_Calc_LastKnownTransitWarehouseStatus);

			CreatePackLineWithTWStatus(shipment, ZGuid.Empty, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Received);
			CreatePackLineWithTWStatus(shipment, ZGuid.Empty, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Dispatched);
			AssertEquals("Combine for an empty warehouse", ": UNK, RCV, DSP | WHS01: UNK, RCV, DSP | WHS02: RCV, DSP", shipment.JS_Calc_LastKnownTransitWarehouseStatus);
		}

		public void TestJS_Calc_LastKnownTransitWarehouseStatus_OrderedByPickupAndDeliveryOrgs()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Constants.TransportModes.Sea;
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "CNSHA";

			ForwardingConsol CreateConsol(string loadPort, string dischargePort)
			{
				var consol = shipment.Consols.AddNew();
				consol.JK_TransportMode = Constants.TransportModes.Sea;
				consol.JK_RL_NKLoadPort = loadPort;
				consol.JK_RL_NKDischargePort = dischargePort;

				return consol;
			}

			var warehouse1 = CreateWarehouse("WHS01");
			var warehouse2 = CreateWarehouse("WHS02");
			var warehouse3 = CreateWarehouse("WHS03");
			var warehouse4 = CreateWarehouse("WHS04");
			var warehouse5 = CreateWarehouse("WHS05");
			var warehouse6 = CreateWarehouse("WHS06");
			var warehouse7 = CreateWarehouse("WHS07");
			var warehouse8 = CreateWarehouse("WHS08");
			var warehouse9 = CreateWarehouse("WHS09");

			var consol1 = CreateConsol("AUSYD", "SGSGP");
			var consol2 = CreateConsol("SGSGP", "HKHKG");
			var consol3 = CreateConsol("HKHKG", "CNSHA");

			shipment.ConsignorPickupAddress.E2_OA_Address = warehouse1.MainAddress.PK;
			shipment.ConsigneeDeliveryAddress.E2_OA_Address = warehouse2.MainAddress.PK;

			consol1.JK_OA_PackDepotAddress = warehouse3.MainAddress.PK;
			consol1.JK_OA_UnpackDepotAddress = warehouse4.MainAddress.PK;

			consol2.JK_OA_PackDepotAddress = warehouse5.MainAddress.PK;
			consol2.JK_OA_UnpackDepotAddress = warehouse6.MainAddress.PK;

			consol3.JK_OA_PackDepotAddress = warehouse7.MainAddress.PK;
			consol3.JK_OA_UnpackDepotAddress = warehouse8.MainAddress.PK;

			CreatePackLineWithTWStatus(shipment, warehouse1.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Received);
			CreatePackLineWithTWStatus(shipment, warehouse2.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Received);
			CreatePackLineWithTWStatus(shipment, warehouse3.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Received);
			CreatePackLineWithTWStatus(shipment, warehouse4.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Received);
			CreatePackLineWithTWStatus(shipment, warehouse5.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Received);
			CreatePackLineWithTWStatus(shipment, warehouse6.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Received);
			CreatePackLineWithTWStatus(shipment, warehouse7.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Received);
			CreatePackLineWithTWStatus(shipment, warehouse8.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Received);

			CreatePackLineWithTWStatus(shipment, ZGuid.Empty, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Dispatched);
			CreatePackLineWithTWStatus(shipment, warehouse9.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Dispatched);

			AssertEquals("Sort TW orgs in the order of the supply chain: firstly from empty TW and status, then shipment > pickup, 1st consol > departure, 1st consol > arrival, 2nd consol > departure, 2nd consol > arrival, etc. shipment > delivery",
				": DSP | WHS01: RCV | WHS03: RCV | WHS04: RCV | WHS05: RCV | WHS06: RCV | WHS07: RCV | WHS08: RCV | WHS02: RCV | WHS09: DSP",
				shipment.JS_Calc_LastKnownTransitWarehouseStatus);
		}

