			shipment2.SetCO2eStatus(CO2eStatusList.Codes.Current);
			consol.SetCO2eStatus(CO2eStatusList.Codes.Current);

			//Action
			packLine1.JL_JC = Guid.Empty;

			//Assert : unpack when shipment 1 and shipment 2 share common container
			AssertEquals(CO2eStatusList.Codes.Current, consol.GetCO2eStatus());
			CO2eBusinessTestHelper.AssertSTUEvent(shipment1, WarningMessageWhenPackLineContainerAllocationChanged);
			AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment1.GetCO2eStatus());
			CO2eBusinessTestHelper.AssertSTUEvent(shipment2, WarningMessageWhenPackLineContainerAllocationChanged);
			AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment2.GetCO2eStatus());
		}

		public void TestIfStatusIsChangedToNCU_When_RequireTEUChangesFromTrueToFalse()
		{
			//Arrange
			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.JK_ConsolMode = Constants.ContainerModes.FCL;

			var shipment = consol.Shipments.AddNew();
			var container = consol.Containers.AddNew();
			var packLine = shipment.OuterPackLines.AddNew();

			shipment.JS_TransportMode = TransportModes.Sea;

			packLine.SetContainer(consol, container);
			packLine.JL_ActualWeight = 100;

			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);
			consol.SetCO2eStatus(CO2eStatusList.Codes.Current);
			AssertEquals(true, (shipment as ICO2eCalculationSupporter).RequireTEU);

			//Action
			packLine.SetContainer(consol, null);

			//Assert : unpack when shipment has only one packline: RequireTEU changes from true to false
