			AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
			CO2eBusinessTestHelper.AssertSTUEvent(shipment, WarningMessageWhenPackLineContainerAllocationChanged);
		}

