		public void TestDoNotHandlePackLineUnpacked_WhenContainerDeleteByDataRefresh_AlreadyPacked()
		{
			//Arrange
			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.JK_ConsolMode = Constants.ContainerModes.FCL;

			var shipment = consol.Shipments.AddNew();
			shipment.JS_TransportMode = TransportModes.Sea;
			shipment.JS_PackingMode = Constants.ContainerModes.FCL;
			var container = consol.Containers.AddNew();
			container.JC_RC = RC_20GP_PK;
			var packLine = shipment.OuterPackLines.AddNew();
			packLine.JL_ActualWeight = 10;
			packLine.JL_ActualWeightUQ = "KG";
			packLine.SetContainer(consol, container);

			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);
			consol.SetCO2eStatus(CO2eStatusList.Codes.Current);
			var jobCO2eBO = (JobCO2e)shipment.FindJobCO2eByType(string.Empty);

			Factory.Save();

			var newFac = new BusinessObjectFactory();
			var consolInNewFac = newFac.Load<ForwardingConsol>(consol.PK);
			AssertEquals("pre-req", 1, consolInNewFac.Shipments.Count);
			AssertEquals("pre-req", 1, consolInNewFac.Containers.Count);
			AssertEquals("pre-req", 1, consolInNewFac.Containers[0].PackLines.Count);
			var containerInNewFac = consolInNewFac.Containers[0];
			var jobCO2eBOInNewFac = newFac.Load<JobCO2e>(jobCO2eBO.PK);

			var shipmentCO2eStatusAfterContainerDeletedByDataRefresh = string.Empty;
			containerInNewFac.DeletedByDataRefresh += (sender, args) =>
			{
				shipmentCO2eStatusAfterContainerDeletedByDataRefresh = jobCO2eBOInNewFac.JCO_Status;
			};

			//Action
			consol.Containers.RemoveAndDelete(container);
			Factory.Save();

			// Assert
			AssertEquals("shipment status in publisher factory", CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
			AssertEquals("shipment status remains unchanged in subscriber factory after container DeleteByDataRefresh", CO2eStatusList.Codes.Current, shipmentCO2eStatusAfterContainerDeletedByDataRefresh);
			AssertEquals("shipment status updated to NCU in subscriber factory at the end of Save", CO2eStatusList.Codes.NotCurrent, jobCO2eBOInNewFac.JCO_Status);
		}

