		public void TestCo2eStatusIsNCU_WhenPickUp_ForContainer_PickupFromIsChanged()
		{
			// Arrange
			var consignorPickupAddress1 = Factory.NewWithValidTestData<OrgHeader>().MainAddress;
			consignorPickupAddress1.OA_RL_NKRelatedPortCode = "AUADL";

			var consignorPickupAddress2 = Factory.NewWithValidTestData<OrgHeader>().MainAddress;
			consignorPickupAddress2.OA_RL_NKRelatedPortCode = "AUMEL";

			var consol = Factory.New<ForwardingConsol>();
			consol.JK_AgentType = Constants.AgentType.Direct;

			var container = Factory.NewWithValidTestData<ForwardingContainer>();
			container.GetOrCreateJobCO2e(CO2eTypes.EmptyPickup);
			container.SetCO2eStatus(CO2eStatusList.Codes.Current, CO2eTypes.EmptyPickup);
			consol.Containers.Add(container);

			var shipment = consol.Shipments.AddNew();
			var packLine = shipment.OuterPackLines.AddNew();
			container.AddPackLine(packLine);
			shipment.ConsignorPickupAddress.E2_OA_Address = consignorPickupAddress1.PK;
			shipment.JS_PackingMode = Constants.ContainerModes.FCL;
			shipment.JS_OA_ExportReceivingDepot = ZGuid.Empty;

			AssertEquals(CO2eStatusList.Codes.Current, container.GetCO2eStatus(CO2eTypes.EmptyPickup));

			// Act
			shipment.ConsignorPickupAddress.E2_OA_Address = consignorPickupAddress2.PK;

			// Assert
			AssertEquals(CO2eStatusList.Codes.NotCurrent, container.GetCO2eStatus(CO2eTypes.EmptyPickup));
			AssertHasWarning(container.TotalCO2eForEmptyPickupForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);
			CO2eBusinessTestHelper.AssertSTUEvent(container, "Shipment Consignor Pickup Address");

			// Act
			consol.JK_AgentType = Constants.AgentType.AWBCoload;
			container.SetCO2eStatus(CO2eStatusList.Codes.Current, CO2eTypes.EmptyPickup);
			shipment.ConsignorPickupAddress.E2_OA_Address = consignorPickupAddress1.PK;

			// Assert
			AssertEquals(CO2eStatusList.Codes.Current, container.GetCO2eStatus(CO2eTypes.EmptyPickup));
			AssertNoWarning(container.TotalCO2eForEmptyPickupForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);

			// Act
			consol.JK_AgentType = Constants.AgentType.Direct;
			shipment.JS_PackingMode = Constants.ContainerModes.FTL;
			container.SetCO2eStatus(CO2eStatusList.Codes.Current, CO2eTypes.EmptyPickup);
			shipment.ConsignorPickupAddress.E2_OA_Address = consignorPickupAddress2.PK;

			// Assert
			AssertEquals(CO2eStatusList.Codes.Current, container.GetCO2eStatus(CO2eTypes.EmptyPickup));
			AssertNoWarning(container.TotalCO2eForEmptyPickupForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);

			// Act
			consol.JK_AgentType = Constants.AgentType.Direct;
			shipment.JS_PackingMode = Constants.ContainerModes.FCL;
			shipment.JS_OA_ExportReceivingDepot = Factory.NewWithValidTestData<OrgHeader>().PK;
			container.SetCO2eStatus(CO2eStatusList.Codes.Current, CO2eTypes.EmptyPickup);
			shipment.ConsignorPickupAddress.E2_OA_Address = consignorPickupAddress1.PK;

			// Assert
			AssertEquals(CO2eStatusList.Codes.Current, container.GetCO2eStatus(CO2eTypes.EmptyPickup));
			AssertNoWarning(container.TotalCO2eForEmptyPickupForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);
		}

