		public void TestTotalCO2eForBinding_Sorting()
		{
			var shipment1 = Factory.New<ForwardingShipment>();
			shipment1.SetCO2eStatus(CO2eStatusList.Codes.Rejected);
			AssertEquals(ZString.Empty, shipment1.TotalCO2eForBinding);
			AssertEquals(0m, shipment1.TotalCO2eForSorting);

			var shipment2 = Factory.New<ForwardingShipment>();
			shipment2.SetCO2eStatus(CO2eStatusList.Codes.Pending);
			AssertEquals("Pending", shipment2.TotalCO2eForBinding);
			AssertEquals(0m, shipment2.TotalCO2eForSorting);

			var shipment3 = Factory.New<ForwardingShipment>();
			shipment3.JS_ActualWeight = 8m;
			shipment3.JS_UnitOfWeight = Weight.Tonnes;
			shipment3.SetCO2ePerTonneInKg(100.1111111m);
			shipment3.SetTotalCO2e(800.8888888m);
			AssertEquals("800.889", shipment3.TotalCO2eForBinding);
			AssertEquals(800.8888888m, shipment3.TotalCO2eForSorting);

			var shipment4 = Factory.New<ForwardingShipment>();
			shipment4.JS_ActualWeight = 200m;
			shipment4.JS_UnitOfWeight = Weight.Tonnes;
			shipment4.SetCO2ePerTonneInKg(100.1111111m);
			shipment4.SetTotalCO2e(20022.22222m);
			AssertEquals("20,022.222", shipment4.TotalCO2eForBinding);
			AssertEquals(20022.22222m, shipment4.TotalCO2eForSorting);

			var shipment5 = Factory.New<ForwardingShipment>();
			shipment5.JS_ActualWeight = 201m;
			shipment5.JS_UnitOfWeight = Weight.Tonnes;
			shipment5.SetCO2ePerTonneInKg(100.1111111m);
			shipment5.SetTotalCO2e(20122.3333311m);
			AssertEquals("20,122.333", shipment5.TotalCO2eForBinding);
			AssertEquals(20122.3333311m, shipment5.TotalCO2eForSorting);

			Assert("0 equals to 0", shipment1.TotalCO2eForSorting == shipment2.TotalCO2eForSorting);
			Assert("0 is smaller than 800.889", shipment2.TotalCO2eForSorting < shipment3.TotalCO2eForSorting);
			Assert("800.89 is smaller than 20022.222", shipment3.TotalCO2eForSorting < shipment4.TotalCO2eForSorting);
			Assert("20022.222 is smaller than 20122.333", shipment4.TotalCO2eForSorting < shipment5.TotalCO2eForSorting);
		}

