			AssertEquals("TotalCO2eForSorting should display using 3dp", 3, co2eForSortingDp.DecimalPlaces);
		}

		public void TestTotalCO2eForBinding_ByWeight()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_ActualWeight = 5m;
			shipment.JS_UnitOfWeight = Weight.Tonnes;
			shipment.SetCO2ePerTonneInKg(100.1111111m);
			shipment.SetTotalCO2e(500.5555555m);
			AssertEquals(CO2eStatusList.Codes.Current, shipment.GetCO2eStatus());
			AssertEquals("Weight = 5 T, CO2 Per Tonne = 100.1111111 Kg", "500.556", shipment.TotalCO2eForBinding);
			AssertEquals("Weight = 5 T, CO2 Per Tonne = 100.1111111 Kg", 500.5555555m, shipment.TotalCO2eForSorting);

			shipment.JS_ActualWeight = 10m;
			AssertEquals("Status should be not current", CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
			AssertEquals("Binding should not be changed", "500.556", shipment.TotalCO2eForBinding);
			AssertEquals("TotalCO2e should not be changed", 500.5555555m, shipment.GetTotalCO2e());
			AssertEquals("TotalCO2eForSorting should not be changed", 500.5555555m, shipment.TotalCO2eForSorting);

			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);
			shipment.JS_UnitOfWeight = Weight.Kilograms;
			AssertEquals("Status should be not current", CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
			AssertEquals("Binding should not be changed", "500.556", shipment.TotalCO2eForBinding);
			AssertEquals("TotalCO2e should not be changed", 500.5555555m, shipment.GetTotalCO2e());
			AssertEquals("TotalCO2eForSorting should not be changed", 500.5555555m, shipment.TotalCO2eForSorting);

			shipment.SetCO2eStatus(CO2eStatusList.Codes.Rejected);
			AssertEquals(ZString.Empty, shipment.TotalCO2eForBinding);
		}

		public void TestTotalCO2eForBinding_ByTEU()
		{
			// Arrange
