		public void TestRequireTEU()
		{
			var refContainerNoTEU = NewRefContainer("20GP111", "22G0", 0m, 2280m);
			void AssertRequireTEU(Action<ForwardingShipment> setup, bool expected = true)
			{
				// Arrange
				var shipment = Factory.New<ForwardingShipment>();
				setup(shipment);

				// Act & Assert
				AssertEquals(expected, (shipment as ICO2eCalculationSupporter).RequireTEU);
			}

			AssertRequireTEU((shipment) =>
			{
				shipment.JS_TransportMode = TransportModes.Sea;
				shipment.JS_PackingMode = ContainerModes.FCL;
				var consol = shipment.Consols.AddNew();
				var commonContainer = consol.Containers.AddNew();
				var packLine = shipment.OuterPackLines.AddNew();
				packLine.JL_ActualWeight = 100m;
				commonContainer.AddPackLine(packLine);
			});

			AssertRequireTEU((shipment) =>
			{
				shipment.JS_TransportMode = TransportModes.Road;
				shipment.JS_PackingMode = ContainerModes.FCL;
				shipment.JS_ActualWeight = 0;
				shipment.Consols.AddNew().Containers.AddNew();
			});

			AssertRequireTEU((shipment) =>
			{
				shipment.JS_TransportMode = TransportModes.Rail;
				shipment.JS_PackingMode = ContainerModes.FCL;
				shipment.JS_ActualWeight = 0;
				shipment.Consols.AddNew().Containers.AddNew();
			});

			AssertRequireTEU((shipment) =>
			{
				shipment.JS_TransportMode = TransportModes.Sea;
				shipment.JS_PackingMode = ContainerModes.FCL;
				var consol = shipment.Consols.AddNew();
				var commonContainer = consol.Containers.AddNew();
				commonContainer.JC_RC = refContainerNoTEU.PK;
				var packLine = shipment.OuterPackLines.AddNew();
				commonContainer.AddPackLine(packLine);
			}, false);
		}

		public void TestIncludeTEU()
		{
			// Arrange
			var shipment = CO2eTestHelper.CreateForwardingShipmentRequiringTEU(Factory) as ForwardingShipment;
			var supporter = (ICO2eLegBasedSupporter)shipment;
			Assert("Pre-condition", supporter.RequireTEU);
			Assert("Pre-condition", supporter.IncludeTEU);

			// Act & Assert
			shipment.JS_TransportMode = TransportModes.Road;
			Assert(!supporter.RequireTEU);
			Assert(supporter.IncludeTEU);

			shipment.JS_PackingMode = ContainerModes.LCL;
			Assert(!supporter.RequireTEU);
			Assert(!supporter.IncludeTEU);
		}

