			Factory.Save();

			shipment.SetCO2eStatus(CO2eStatusList.Codes.Pending);
			shipment.JS_TransportMode = TransportModes.Road;
			AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
			AssertHasWarning(shipment.TotalCO2eForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);
			CO2eBusinessTestHelper.AssertSTUEvent(shipment, "JS_TransportMode [AIR]->[ROA]", CO2eStatusList.Codes.Pending);

			TestDateAttribute.AddMinutes(1);
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Pending);
