		[TestDate(2024, 1, 1)]
		public void TestUpdateCO2eStatusToNotCurrent_WhenRelatedTransportIsNotCurrent()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_UniqueConsignRef = "S0123";
			shipment.JS_ActualWeight = 100m;
			shipment.JS_UnitOfWeight = "KG";
			shipment.JS_TransportMode = "SEA";
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "VNVNH";
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);
			AddTransportLeg(shipment, "SEA", "AUSYD", "SGSIN", "VOY001", "CARRIER1", CO2eStatusList.Codes.Current);
			AddTransportLeg(shipment, "SEA", "SGSIN", "VNVNH", "VOY002", "CARRIER2", CO2eStatusList.Codes.Current);
			AddTransportLeg(shipment, "SEA", "AUMEL", "VNVNH", "VOY003", "CARRIER3", CO2eStatusList.Codes.Current);
			AssertNoWarning(shipment.TotalCO2eForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);

			shipment.TransportsIncludingRelated[0].JW_TransportMode = TransportModes.Air;
			AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment.TransportsIncludingRelated[0].GetCO2eStatus());
			AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
			AssertHasWarning(shipment.TotalCO2eForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);
			CO2eBusinessTestHelper.AssertSTUEvent(shipment, "Transport");

			TestDateAttribute.AddMinutes(1);
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);
			AddTransportLeg(shipment, "SEA", "AUMEL", "NZAKL", "VOY004", "CARRIER4", CO2eStatusList.Codes.NotCalculated);
			AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
			AssertHasWarning(shipment.TotalCO2eForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);
			CO2eBusinessTestHelper.AssertSTUEvent(shipment, "Transport added");

			TestDateAttribute.AddMinutes(1);
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);
			shipment.TransportsIncludingRelated[3].SetCO2eStatus(CO2eStatusList.Codes.NotCurrent);
			AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
			AssertHasWarning(shipment.TotalCO2eForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);
			CO2eBusinessTestHelper.AssertSTUEvent(shipment, "Transport");

			TestDateAttribute.AddMinutes(1);
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);
			shipment.TransportsIncludingRelated.Remove(shipment.TransportsIncludingRelated[2]);
			AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
			AssertHasWarning(shipment.TotalCO2eForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);
			CO2eBusinessTestHelper.AssertSTUEvent(shipment, "Transport removed");

			TestDateAttribute.AddMinutes(1);
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);
			var consol = shipment.Consols.AddNew();
			var consolTransport = consol.Transports.AddNew();
			consolTransport.SetCO2eStatus(CO2eStatusList.Codes.NotCurrent);
			AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
			AssertHasWarning(shipment.TotalCO2eForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);
			CO2eBusinessTestHelper.AssertSTUEvent(shipment, "Transport");

			void AddTransportLeg(CommonShipment shipmentBO, string mode, string loadPort, string discPort, string voyageFlightNum, string carrierCode, ZString status)
			{
				Transport transport = shipmentBO.Transports.AddNew();
				transport.JW_TransportMode = mode;
				transport.JW_RL_NKLoadPort = loadPort;
				transport.JW_RL_NKDiscPort = discPort;
				transport.JW_VoyageFlight = voyageFlightNum;
				OrgHeader orgHeader = base.Factory.New<OrgHeader>();
				orgHeader.OH_Code = carrierCode;
				transport.JW_OA_CarrierAddress = orgHeader.MainAddress.PK;
				transport.SetCO2eStatus(status);
			}
		}

