		public void TestCO2ePerTonneInKg_WhenStatusIsCurrent()
		{
			ZString expectedWarning = "The greenhouse gas emissions for the input data on routing leg cannot be calculated.";

			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_UniqueConsignRef = "S0123";
			shipment.JS_ActualWeight = 100m;
			shipment.JS_UnitOfWeight = "KG";
			shipment.JS_TransportMode = "SEA";
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "VNVNH";
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);

			var transport = shipment.Transports.AddNew();
			var orgHeader = base.Factory.New<OrgHeader>();
			orgHeader.OH_Code = "CARRIER1";
			transport.JW_OA_CarrierAddress = orgHeader.MainAddress.PK;
			transport.JW_TransportMode = "SEA";
			transport.JW_VoyageFlight = "VOY001";
			transport.SetCO2eStatus(CO2eStatusList.Codes.Current);
			transport.SetCO2ePerTonneInKg(0);

			AssertEquals(CO2eStatusList.Codes.Current, shipment.GetCO2eStatus());
			AssertNoWarnings("No warning when load port and destination port are empty", transport.TotalCO2eForSortingInfo);

			transport.JW_RL_NKLoadPort = "AUSYD";
			transport.JW_RL_NKDiscPort = "SGSIN";
			transport.SetCO2eStatus(CO2eStatusList.Codes.Current);

			AssertEquals(CO2eStatusList.Codes.Current, shipment.GetCO2eStatus());
			AssertHasWarning(transport.TotalCO2eForSortingInfo, expectedWarning);

			transport.SetCO2ePerTonneInKg(2000);

			AssertEquals(CO2eStatusList.Codes.Current, shipment.GetCO2eStatus());
			transport.Validation.ValidateTotalCO2eForSorting();
			AssertNoWarnings("No warning with valid scenario", transport.TotalCO2eForSortingInfo);
		}

