		[TestDate(2024, 1, 1)]
		public void TestUpdateCO2eStatusToNotCurrent_WhenRequireTEUAndContainerChange()
		{
			// Arrange
			var consol1 = Factory.New<ForwardingConsol>();
			consol1.JK_TransportMode = TransportModes.Sea;
			consol1.JK_RL_NKLoadPort = "AUSYD";
			consol1.JK_RL_NKDischargePort = "CNSHA";
			consol1.JK_ConsolMode = ContainerModes.FCL;

			var shipmentBO = consol1.Shipments.AddNew();
			shipmentBO.JS_TransportMode = TransportModes.Sea;
			shipmentBO.JS_PackingMode = ContainerModes.FCL;
			shipmentBO.JS_RL_NKOrigin = "AUSYD";
			shipmentBO.JS_RL_NKDestination = "CNSHA";
			shipmentBO.JS_ActualWeight = 2000;
			shipmentBO.JS_UnitOfWeight = Weight.Kilograms;
			shipmentBO.SetCO2eStatus(CO2eStatusList.Codes.Current);

			consol1.Containers.RemoveAll();
			var container1 = consol1.Containers.AddNew();
			container1.JC_ContainerCount = 2;
			var refContainer1 = NewRefContainer("20GP111", "22G0", 1m, 2280m);
			container1.JC_RC = refContainer1.PK;

			var container2 = consol1.Containers.AddNew();
			container2.JC_ContainerCount = 1;
			var refContainer2 = NewRefContainer("40REHC111", "45R0", 2.3m, 4420m);
			container2.JC_RC = refContainer2.PK;

			var packline1 = shipmentBO.OuterPackLines[0];
			packline1.JL_ActualWeight = 1;
			packline1.JL_ActualWeightUQ = Weight.Tonnes;
			container2.AddPackLine(packline1);

			var packline2 = shipmentBO.OuterPackLines.AddNew();
			packline2.JL_ActualWeight = 1000;
			packline2.JL_ActualWeightUQ = Weight.Kilograms;
			container1.AddPackLine(packline2);

			Factory.Save();

			// Act & Assert
			AssertCO2eStatus(() => packline1.JL_ActualWeight = 2, "JL_ActualWeight [1]->[2]");
			AssertCO2eStatus(() => packline1.JL_ActualWeightUQ = Weight.Kilograms, "JL_ActualWeightUQ [T]->[KG]");
			AssertCO2eStatus(() => packline2.Delete(), "PackLine removed");
			AssertCO2eStatus(() => packline1.Delete(), "PackLine removed");

			void AssertCO2eStatus(Action action, string stuReason)
			{
				TestDateAttribute.AddMinutes(1);
				shipmentBO.SetCO2eStatus(CO2eStatusList.Codes.Current);
				Assert(!shipmentBO.SkipCO2eStatusCheck());
				action.Invoke();
				AssertEquals(CO2eStatusList.Codes.NotCurrent, shipmentBO.GetCO2eStatus());
				CO2eBusinessTestHelper.AssertSTUEvent(shipmentBO, stuReason);
			}
		}

		public void TestShouldNotCallRequireTEU_WhenSkipCO2eStatusCheck()
		{
			// Arrange
			var consol1 = Factory.New<ForwardingConsol>();
			consol1.JK_TransportMode = TransportModes.Sea;
			consol1.JK_ConsolMode = ContainerModes.FCL;

			var shipmentBO = consol1.Shipments.AddNew();
			shipmentBO.JS_TransportMode = TransportModes.Sea;
			shipmentBO.JS_PackingMode = ContainerModes.FCL;
			shipmentBO.JS_ActualWeight = 2000;
			shipmentBO.JS_UnitOfWeight = Weight.Kilograms;

			consol1.Containers.RemoveAll();
			var container1 = consol1.Containers.AddNew();
			container1.JC_ContainerCount = 2;
			var refContainer1 = NewRefContainer("20GP111", "22G0", 1m, 2280m);
			container1.JC_RC = refContainer1.PK;

			var container2 = consol1.Containers.AddNew();
			container2.JC_ContainerCount = 1;
			var refContainer2 = NewRefContainer("40REHC111", "45R0", 2.3m, 4420m);
			container2.JC_RC = refContainer2.PK;

			var packline1 = shipmentBO.OuterPackLines[0];
			packline1.JL_ActualWeight = 1;
			packline1.JL_ActualWeightUQ = Weight.Tonnes;
			container2.AddPackLine(packline1);

			var packline2 = shipmentBO.OuterPackLines.AddNew();
			packline2.JL_ActualWeight = 1000;
			packline2.JL_ActualWeightUQ = Weight.Kilograms;
			container1.AddPackLine(packline2);
			shipmentBO.SetCO2eStatus(CO2eStatusList.Codes.NotCurrent);

			Factory.Save();

			var requireTEUCalled = 0;
			shipmentBO.OnRequireTEUCalled += delegate { requireTEUCalled++; };

			// Act & Assert
			AssertRequireTEUNotCalled(() => packline1.JL_ActualWeight = 2);
			AssertRequireTEUNotCalled(() => packline1.JL_ActualWeightUQ = Weight.Kilograms);
			AssertRequireTEUNotCalled(() => packline2.Delete());
			AssertRequireTEUNotCalled(() => packline1.Delete());
			AssertRequireTEUNotCalled(() => packline1.Delete());

			void AssertRequireTEUNotCalled(Action action, int count = 0)
			{
				Assert(shipmentBO.SkipCO2eStatusCheck());
				action();
				AssertEquals(count, requireTEUCalled);
			}
		}

