		}

		RefContainer NewRefContainer(ZString code, ZString isoType, decimal teu, decimal tareWeight)
		{
			var refContainer = RefContainer.New(Factory);
			refContainer.RC_Code = code;
			refContainer.RC_ISOType = isoType;
			refContainer.RC_TEU = teu;
			refContainer.RC_TareWeight = tareWeight;

			return refContainer;
		}

		public void TestCO2IsCopiedForClonedShipment()
		{
			var shipment = (ForwardingShipment)GetShipment();
			shipment.JS_ActualWeight = 2000;
			shipment.SetCO2ePerTonneInKg(50m);
			shipment.SetTotalCO2e(100m);

			var clone = (ForwardingShipment)shipment.Clone();

			AssertEquals(50m, clone.GetCO2ePerTonneInKg());
			AssertEquals(100m, clone.GetTotalCO2e());
			AssertEquals(CO2eStatusList.Codes.Current, clone.GetCO2eStatus());
		}

		#region ICO2eCalculationSupporter members

		public void TestCO2eCalculationSupporterLoadPort()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_RL_NKOrigin = "AUSYD";

			var supporter = (ICO2eLegBasedSupporter)shipment;
			Assert(supporter.LoadPortForCO2eCalc.IsEmpty);

			shipment.JS_RL_NKOrigin = ZString.Empty;
			shipment.JS_RL_NKLoadPort = "AUMEL";
			AssertEquals("AUMEL", supporter.LoadPortForCO2eCalc.UNLOCO);
			AssertEquals(supporter.LoadPortForCO2eCalc.UNLOCO, supporter.AdditionalLoadPortForCO2eCalc.UNLOCO);

			var leg1 = shipment.Transports.AddNew();
			leg1.JW_RL_NKLoadPort = ZString.Empty;
			leg1.JW_RL_NKDiscPort = ZString.Empty;
			leg1.JW_ETD = ZDateTime.Today;
			AssertEquals("AUMEL", supporter.LoadPortForCO2eCalc.UNLOCO);
			AssertEquals(supporter.LoadPortForCO2eCalc.UNLOCO, supporter.AdditionalLoadPortForCO2eCalc.UNLOCO);

			var leg2 = shipment.Transports.AddNew();
			leg2.JW_RL_NKLoadPort = "";
