			leg1.JW_RL_NKLoadPort = "AUSYD";
			AssertEquals("AUSYD", supporter.LoadPortForCO2eCalc.UNLOCO);
			AssertEquals(supporter.LoadPortForCO2eCalc.UNLOCO, supporter.AdditionalLoadPortForCO2eCalc.UNLOCO);
