		public void TestCO2eCalculationSupporterEmptyContainers_ExcludeDepartureArrivalConsolWithDtbBooking()
		{
			// Arrange
			var shipment = CO2eTestHelper.CreateForwardingShipmentRequiringTEU(Factory);
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "CNSHA";
			var consol1 = shipment.Consols[0] as ForwardingConsol;
			consol1.JK_RL_NKLoadPort = "AUSYD";
			consol1.JK_RL_NKDischargePort = "SGSIN";

			var consol2 = shipment.Consols.AddNew() as ForwardingConsol;
			consol2.JK_TransportMode = TransportModes.Sea;
			consol2.JK_ConsolMode = ContainerModes.FCL;
			consol2.JK_RL_NKLoadPort = "SGSIN";
			consol2.JK_RL_NKDischargePort = "CNSHA";

			var consol2Container = consol2.Containers.AddNew();
			consol2Container.JC_ContainerCount = 1;
			consol2Container.JC_RC = NewRefContainer("60GP111", "33G0", 1m, 2280m).PK;
			consol2Container.AddPackLines(shipment.OuterPackLines.ToArray());

			var supporter = shipment as ICO2eLegBasedSupporter;
			AssertEquals("Pre-condition: 2 from consol1, 1 from consol2", 3, supporter.EmptyContainers.Count);
			AssertEmptyContainer(supporter, new[]
			{
				(consol1.Containers[0], true, true), (consol1.Containers[0], true, true), (consol2Container, true, true)
			});

			// Act & Assert
			CO2eTestHelper.CreateTransportBooking(consol1, nameof(DtbBookingDirection.DLV), Factory);
			AssertEmptyContainer(supporter, new[]
			{
				(consol1.Containers[0], true, true), (consol1.Containers[0], true, true), (consol2Container, true, true)
			});

			// Act & Assert
			CO2eTestHelper.CreateTransportBooking(consol2, nameof(DtbBookingDirection.PIC), Factory);
			AssertEmptyContainer(supporter, new[]
			{
				(consol1.Containers[0], true, true), (consol1.Containers[0], true, true), (consol2Container, true, true)
			});

			// Act & Assert
			CO2eTestHelper.CreateTransportBooking(consol1, nameof(DtbBookingDirection.PIC), Factory);
			AssertEmptyContainer(supporter, new[]
			{
				(consol1.Containers[0], false, true), (consol1.Containers[0], false, true), (consol2Container, true, true)
			});

			// Act & Assert
			CO2eTestHelper.CreateTransportBooking(consol2, nameof(DtbBookingDirection.DLV), Factory);
			AssertEmptyContainer(supporter, new[]
			{
				(consol1.Containers[0], false, true), (consol1.Containers[0], false, true), (consol2Container, true, false)
			});
		}

		public void TestCO2eCalculationSupporterEmptyContainers_UseHBLDeliveryMode()
		{
			// Arrange
			var shipment = CO2eTestHelper.CreateForwardingShipmentRequiringTEU(Factory);
			var consol = shipment.Consols[0] as ForwardingConsol;
			var notPackedContainer = consol.Containers.AddNew();
			notPackedContainer.JC_ContainerCount = 2;
			notPackedContainer.JC_RC = NewRefContainer("40RTT", "45AA", 2.3m, 4420m).PK;
			var supporter = (ICO2eLegBasedSupporter)shipment;

			using (FreightDataRegistry.Instance.UseHBLDeliveryModeForGHGCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				// Act & Assert: Empty HBL Delivery Mode
				AssertEmptyContainer(supporter, new[]
				{
					(consol.Containers[0], true, true), (consol.Containers[0], true, true)
				});

				// Act & Assert: DOOR_DOOR HBL Delivery Mode
				shipment.JS_HBLContainerPackModeOverride = Core.Constants.HBLDeliveryModes.Codes.DOOR_DOOR;
				AssertEmptyContainer(supporter, new[]
				{
					(consol.Containers[0], true, true), (consol.Containers[0], true, true)
				});

				// Act & Assert: CFS_CY HBL Delivery Mode
				shipment.JS_HBLContainerPackModeOverride = Core.Constants.HBLDeliveryModes.Codes.CFS_CY;
				AssertEmptyContainer(supporter, new[]
				{
					(consol.Containers[0], true, false), (consol.Containers[0], true, false)
				});

				// Act & Assert: CY_CFS HBL Delivery Mode
				shipment.JS_HBLContainerPackModeOverride = Core.Constants.HBLDeliveryModes.Codes.CY_CFS;
				AssertEmptyContainer(supporter, new[]
				{
					(consol.Containers[0], false, true), (consol.Containers[0], false, true)
				});

				// Act & Assert: ARPT_ARPT HBL Delivery Mode
				shipment.JS_HBLContainerPackModeOverride = Core.Constants.HBLDeliveryModes.Codes.ARPT_ARPT;
				AssertEmptyContainer(supporter, Array.Empty<(ForwardingContainer, bool, bool)>());
			}
		}

		void AssertEmptyContainer(ICO2eLegBasedSupporter supporter, (ForwardingContainer, bool, bool)[] expected)
		{
			AssertEquals("Count", expected.Length, supporter.EmptyContainers.Count);
			foreach (var (container, hasPickup, hasReturn) in expected)
			{
				var actual = supporter.EmptyContainers.FirstOrDefault(x => ((BusinessObject)x.Container).PK == container.PK);
				AssertNotNull(actual);
				AssertEquals(hasPickup, actual.HasPickup);
				AssertEquals(hasReturn, actual.HasReturn);
			}
		}

