			shipment.Consols[0].JK_OA_UnpackDepotAddress = addresses[5].PK;
			shipment.Consols[0].Containers[0].JC_OA_DepartureContainerYardAddress = addresses[6].PK;
			shipment.Consols[0].Containers[0].JC_OA_ArrivalContainerYardAddress = addresses[7].PK;
