		public void TestCO2eCalculationSupporterPreCarriageLegs()
		{
			var address1 = Factory.NewWithValidTestData<OrgHeader>().MainAddress;
			address1.OA_RL_NKRelatedPortCode = "AUADL";
			var address2 = Factory.NewWithValidTestData<OrgHeader>().MainAddress;
			address2.OA_RL_NKRelatedPortCode = "AUCBR";
			Factory.Save();
			using (FreightDataRegistry.Instance.EnablePrePostCarriageCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKLoadPort = "AUSYD";

				AssertCarriageLegs(shipment.GetPreCarriageLegs().ToArray());

				shipment.ConsignorPickupAddress.E2_OA_Address = address1.PK;
				AssertCarriageLegs(shipment.GetPreCarriageLegs().ToArray(),
					(("", address1.PK), ("AUSYD", ZGuid.Empty)));

				shipment.JS_OA_ExportReceivingDepot = address1.PK;
				AssertCarriageLegs(shipment.GetPreCarriageLegs().ToArray(),
					(("", address1.PK), ("AUSYD", ZGuid.Empty)));

				shipment.JS_OA_ExportReceivingDepot = address2.PK;
				AssertCarriageLegs(shipment.GetPreCarriageLegs().ToArray(),
					(("", address1.PK), ("", address2.PK)),
					(("", address2.PK), ("AUSYD", ZGuid.Empty)));

				shipment.JS_RL_NKLoadPort = "AUMEL";
				AssertCarriageLegs(shipment.GetPreCarriageLegs().ToArray(),
					(("", address1.PK), ("", address2.PK)),
					(("", address2.PK), ("AUMEL", ZGuid.Empty)));

				var transport = shipment.Transports.AddNew();
				transport.JW_RL_NKLoadPort = "AUBNE";

				AssertCarriageLegs(shipment.GetPreCarriageLegs().ToArray(),
					(("", address1.PK), ("", address2.PK)),
					(("", address2.PK), ("AUBNE", ZGuid.Empty)));
			}
		}

