		public void TestCO2eCalculationSupporterPreCarriageLegs_HBLDeliveryModes()
		{
			// Arrange
			var address1 = Factory.NewWithValidTestData<OrgHeader>().MainAddress;
			address1.OA_RL_NKRelatedPortCode = "AUADL";
			var address2 = Factory.NewWithValidTestData<OrgHeader>().MainAddress;
			address2.OA_RL_NKRelatedPortCode = "AUCBR";
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_RL_NKLoadPort = "AUSYD";
			shipment.ConsignorPickupAddress.E2_OA_Address = address1.PK;
			shipment.JS_OA_ExportReceivingDepot = address2.PK;

			// Assert DOOR_X
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.DOOR_DOOR).ToArray(),
				(("", address1.PK), ("", address2.PK)),
				(("", address2.PK), ("AUSYD", ZGuid.Empty)));
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.DOOR_CY).ToArray(),
				(("", address1.PK), ("", address2.PK)),
				(("", address2.PK), ("AUSYD", ZGuid.Empty)));
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.DOOR_CFS).ToArray(),
				(("", address1.PK), ("", address2.PK)),
				(("", address2.PK), ("AUSYD", ZGuid.Empty)));
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.DOOR_ARPT).ToArray(),
				(("", address1.PK), ("", address2.PK)),
				(("", address2.PK), ("AUSYD", ZGuid.Empty)));
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.DOOR_PORT).ToArray(),
				(("", address1.PK), ("", address2.PK)),
				(("", address2.PK), ("AUSYD", ZGuid.Empty)));

			// Assert CFS_X no Consol
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CFS_CY).ToArray(),
				(("", address2.PK), ("AUSYD", ZGuid.Empty)));
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CFS_CFS).ToArray(),
				(("", address2.PK), ("AUSYD", ZGuid.Empty)));
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CFS_ARPT).ToArray(),
				(("", address2.PK), ("AUSYD", ZGuid.Empty)));
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CFS_DOOR).ToArray(),
				(("", address2.PK), ("AUSYD", ZGuid.Empty)));

			// Assert CY_X, ARPT_X, PORT_X
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CY_CFS).ToArray());
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CY_CY).ToArray());
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CY_DOOR).ToArray());
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.ARPT_CFS).ToArray());
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.ARPT_ARPT).ToArray());
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.ARPT_DOOR).ToArray());
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.PORT_DOOR).ToArray());
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.PORT_PORT).ToArray());

			shipment.Consols.AddNew();
			// Assert CFS_X has Consol
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CFS_CY).ToArray());
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CFS_CFS).ToArray());
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CFS_ARPT).ToArray());
			AssertCarriageLegs(shipment.GetPreCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CFS_DOOR).ToArray());
		}

