					(("", address2.PK), ("", address1.PK)));

				CO2eTestHelper.CreateTransportBooking(shipment, nameof(DtbBookingDirection.PIC), Factory);
				AssertCarriageLegs(shipment.GetPostCarriageLegs().ToArray(),
					(("", address2.PK), ("", address1.PK)));

				CO2eTestHelper.CreateTransportBooking(consol, nameof(DtbBookingDirection.PIC), Factory);
				AssertCarriageLegs(shipment.GetPostCarriageLegs().ToArray(),
					(("", address2.PK), ("", address1.PK)));

				CO2eTestHelper.CreateTransportBooking(consol, nameof(DtbBookingDirection.DLV), Factory);
				AssertCarriageLegs(shipment.GetPostCarriageLegs().ToArray(),
					(("", address2.PK), ("", address1.PK)));
			}
		}

		public void TestCO2eCalculationSupporterPostCarriageLegs_HBLDeliveryModes()
		{
			// Arrange
			var address1 = Factory.NewWithValidTestData<OrgHeader>().MainAddress;
			address1.OA_RL_NKRelatedPortCode = "AUADL";
			var address2 = Factory.NewWithValidTestData<OrgHeader>().MainAddress;
			address2.OA_RL_NKRelatedPortCode = "AUCBR";
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_RL_NKDischargePort = "AUSYD";
			shipment.ConsigneeDeliveryAddress.E2_OA_Address = address1.PK;
			shipment.JS_OA_ImportReleaseDepot = address2.PK;

			// Assert X_DOOR
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CY_DOOR).ToArray(),
				(("AUSYD", ZGuid.Empty), ("", address2.PK)),
				(("", address2.PK), ("", address1.PK)));
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CFS_DOOR).ToArray(),
				(("AUSYD", ZGuid.Empty), ("", address2.PK)),
				(("", address2.PK), ("", address1.PK)));
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.ARPT_DOOR).ToArray(),
				(("AUSYD", ZGuid.Empty), ("", address2.PK)),
				(("", address2.PK), ("", address1.PK)));
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.DOOR_DOOR).ToArray(),
				(("AUSYD", ZGuid.Empty), ("", address2.PK)),
				(("", address2.PK), ("", address1.PK)));
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.PORT_DOOR).ToArray(),
				(("AUSYD", ZGuid.Empty), ("", address2.PK)),
				(("", address2.PK), ("", address1.PK)));

			// Assert X_CFS no Consol
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CY_CFS).ToArray(),
				(("AUSYD", ZGuid.Empty), ("", address2.PK)));
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CFS_CFS).ToArray(),
				(("AUSYD", ZGuid.Empty), ("", address2.PK)));
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.ARPT_CFS).ToArray(),
				(("AUSYD", ZGuid.Empty), ("", address2.PK)));
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.DOOR_CFS).ToArray(),
				(("AUSYD", ZGuid.Empty), ("", address2.PK)));

			// Assert X_CY, X_ARPT, X_PORT
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CY_CY).ToArray());
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CFS_CY).ToArray());
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.DOOR_CY).ToArray());
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CFS_ARPT).ToArray());
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.ARPT_ARPT).ToArray());
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.DOOR_ARPT).ToArray());
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.DOOR_PORT).ToArray());
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.PORT_PORT).ToArray());

			shipment.Consols.AddNew();
			// Assert X_CFS has Consol
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CY_CFS).ToArray());
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.CFS_CFS).ToArray());
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.ARPT_CFS).ToArray());
			AssertCarriageLegs(shipment.GetPostCarriageLegs(Core.Constants.HBLDeliveryModes.Codes.DOOR_CFS).ToArray());
		}

		void AssertCarriageLegs(PrePostCarriageLegWrapper[] actual, params ((ZString, ZGuid) From, (ZString, ZGuid) To)[] expected)
		{
			AssertEquals(expected.Length, actual.Length);
			for (var idx = 0; idx < actual.Length; idx++)
			{
				CombineAssertions($"Carriage leg {idx}", () =>
				{
					AssertEquals(false, actual[idx].From.IsEmpty);
					AssertEquals(false, actual[idx].To.IsEmpty);
					AssertEquals(expected[idx].From.Item1, actual[idx].From.UNLOCO);
					AssertEquals(expected[idx].From.Item2, (actual[idx].From.Address?.EntityPK ?? ZGuid.Empty));
					AssertEquals(expected[idx].To.Item1, actual[idx].To.UNLOCO);
					AssertEquals(expected[idx].To.Item2, (actual[idx].To.Address?.EntityPK ?? ZGuid.Empty));
				});
			}
		}

		public void TestCO2eCalculationSupporterAdditionalCalculationSupporters()
		{
			// Arrange
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "CNSHA";
			shipment.JS_ActualWeight = 100m;
			var consol1 = shipment.Consols.AddNew();
			consol1.JK_RL_NKLoadPort = "AUSYD";
			consol1.JK_RL_NKDischargePort = "SGSIN";
			var consol1AnotherShipment = consol1.Shipments.AddNew();
			consol1AnotherShipment.JS_ActualWeight = 300m;
			var consol2 = shipment.Consols.AddNew();
			consol2.JK_RL_NKLoadPort = "SGSIN";
			consol2.JK_RL_NKDischargePort = "CNSHA";
			var consol2AnotherShipment = consol2.Shipments.AddNew();
			consol2AnotherShipment.JS_ActualWeight = 400m;

			var supporter = (ICO2eCalculationSupporter)shipment;
			AssertEquals(0, supporter.AdditionalCalculationSupporters.Length);

			using (FreightDataRegistry.Instance.EnablePrePostCarriageCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var shipmentTransportBookingPIC = CO2eTestHelper.CreateTransportBooking(shipment, nameof(DtbBookingDirection.PIC), Factory);
				((ICO2eCalculationSupporter)shipmentTransportBookingPIC).SetTotalCO2e(10m);
				var shipmentTransportBookingDLV = CO2eTestHelper.CreateTransportBooking(shipment, nameof(DtbBookingDirection.DLV), Factory);
				((ICO2eCalculationSupporter)shipmentTransportBookingDLV).SetTotalCO2e(20m);
				AssertContainsExactElementsInAnyOrder(new[] { shipmentTransportBookingPIC, shipmentTransportBookingDLV }, supporter.AdditionalCalculationSupporters.Select(x => x.Supporter));

				var consol1TransportBookingPIC = CO2eTestHelper.CreateTransportBooking(consol1, nameof(DtbBookingDirection.PIC), Factory);
				((ICO2eCalculationSupporter)consol1TransportBookingPIC).SetTotalCO2e(40m);
				var consol1TransportBookingDLV = CO2eTestHelper.CreateTransportBooking(consol1, nameof(DtbBookingDirection.DLV), Factory);
				((ICO2eCalculationSupporter)consol1TransportBookingDLV).SetTotalCO2e(50m);
				AssertContainsExactElementsInAnyOrder(new[] { shipmentTransportBookingPIC, shipmentTransportBookingDLV, consol1TransportBookingPIC }, supporter.AdditionalCalculationSupporters.Select(x => x.Supporter));

				var consol2TransportBookingPIC = CO2eTestHelper.CreateTransportBooking(consol2, nameof(DtbBookingDirection.PIC), Factory);
				((ICO2eCalculationSupporter)consol2TransportBookingPIC).SetTotalCO2e(60m);
				var consol2TransportBookingDLV = CO2eTestHelper.CreateTransportBooking(consol2, nameof(DtbBookingDirection.DLV), Factory);
				((ICO2eCalculationSupporter)consol2TransportBookingDLV).SetTotalCO2e(70m);

				// Act & Assert
				AssertAdditionalSupporter(supporter, (ICO2eCalculationSupporter)shipmentTransportBookingPIC, 10m);
				AssertAdditionalSupporter(supporter, (ICO2eCalculationSupporter)shipmentTransportBookingDLV, 20m);
				AssertAdditionalSupporter(supporter, (ICO2eCalculationSupporter)consol1TransportBookingPIC, 40m * (100m / 400m));
				AssertAdditionalSupporter(supporter, (ICO2eCalculationSupporter)consol2TransportBookingDLV, 70m * (100m / 500m));
				Assert(!supporter.AdditionalCalculationSupporters.Any(x => ((BusinessObject)x.Supporter).PK == ((BusinessObject)consol1TransportBookingDLV).PK));
				Assert(!supporter.AdditionalCalculationSupporters.Any(x => ((BusinessObject)x.Supporter).PK == ((BusinessObject)consol2TransportBookingPIC).PK));
			}

			using (FreightDataRegistry.Instance.EnablePrePostCarriageCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
			{
				AssertEquals(0, supporter.AdditionalCalculationSupporters.Length);
			}
		}

		void AssertAdditionalSupporter(ICO2eCalculationSupporter hostSupporter, ICO2eCalculationSupporter additionalSupporter, ZDecimal apportionedValue)
		{
			var additionalCalculation = hostSupporter.AdditionalCalculationSupporters.FirstOrDefault(x => ((BusinessObject)x.Supporter).PK == ((BusinessObject)additionalSupporter).PK);
			AssertNotNull(additionalCalculation.Supporter);
			AssertEquals(apportionedValue, additionalCalculation.GetApportionedValue());
		}

		public void TestOnTransportBookingCalculated_WhenRegistryEnabled()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "CNSHA";
			shipment.JS_TransportMode = "AIR";
			shipment.JS_ActualWeight = 100m;

			var supporter = (ICO2eCalculationSupporter)shipment;
			var shipmentTransportBookingPIC = CO2eTestHelper.CreateTransportBooking(shipment, nameof(DtbBookingDirection.PIC), Factory);
			((ICO2eCalculationSupporter)shipmentTransportBookingPIC).SetTotalCO2e(10m);
			((ICO2eCalculationSupporter)shipmentTransportBookingPIC).SetCO2eStatus(CO2eStatusList.Codes.Current);
			var shipmentTransportBookingDLV = CO2eTestHelper.CreateTransportBooking(shipment, nameof(DtbBookingDirection.DLV), Factory);
			((ICO2eCalculationSupporter)shipmentTransportBookingDLV).SetTotalCO2e(20m);
			((ICO2eCalculationSupporter)shipmentTransportBookingDLV).SetCO2eStatus(CO2eStatusList.Codes.Current);

			using (FreightDataRegistry.Instance.EnablePrePostCarriageCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				AssertEquals("Pre-condition", 2, supporter.AdditionalCalculationSupporters.Length);

				// Arrange: Both TBs are Current, shipment is not pending
				shipment.SetTotalCO2e(1000m);
				shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);

				// Act
				((ICO2ePrePostCarriage)shipment).OnTransportBookingCalculated(shipmentTransportBookingDLV);

				// Assert
				AssertEquals("Shipment TotalCO2e remains", 1000m, shipment.GetTotalCO2e());

				// Arrange: One TB is pending, shipment is pending
				shipment.SetTotalCO2e(0m);
				shipment.SetCO2eStatus(CO2eStatusList.Codes.Pending);
				((ICO2eCalculationSupporter)shipmentTransportBookingPIC).SetCO2eStatus(CO2eStatusList.Codes.Pending);

				// Act
				((ICO2ePrePostCarriage)shipment).OnTransportBookingCalculated(shipmentTransportBookingDLV);

				// Assert
				AssertEquals("Shipment TotalCO2e remains", 0m, shipment.GetTotalCO2e());

				// Arrange: Both TBs are Current, shipment is pending with TotalCO2e = 0
				((ICO2eCalculationSupporter)shipmentTransportBookingPIC).SetCO2eStatus(CO2eStatusList.Codes.Current);

				// Act
				((ICO2ePrePostCarriage)shipment).OnTransportBookingCalculated(shipmentTransportBookingDLV);

				// Assert
				AssertEquals("Shipment TotalCO2e remains", 0m, shipment.GetTotalCO2e());

				// Arrange: Both TBs are Current, shipment is pending with TotalCO2e > 0
				shipment.SetTotalCO2e(1000m);

				// Act
				((ICO2ePrePostCarriage)shipment).OnTransportBookingCalculated(shipmentTransportBookingDLV);

				// Assert
				AssertEquals("Apply TBs emissions to Shipment TotalCO2e", 1030m, shipment.GetTotalCO2e());
				AssertEquals("Set Shipment CO2e status to current", CO2eStatusList.Codes.Current, shipment.GetCO2eStatus());
			}
		}

