		public void TestOnTransportBookingCO2eStatusChanged_SetCO2eStatusToNotCurrent_WhenRegistryEnabled()
		{
			// Arrange
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "CNSHA";
			var departureConsol = shipment.Consols.AddNew();
			departureConsol.JK_RL_NKLoadPort = "AUSYD";
			departureConsol.JK_RL_NKDischargePort = "SGSIN";
			var arrivalConsol = shipment.Consols.AddNew();
			arrivalConsol.JK_RL_NKLoadPort = "SGSIN";
			arrivalConsol.JK_RL_NKDischargePort = "CNSHA";

			var shipmentTransportBookingPIC = CO2eTestHelper.CreateTransportBooking(shipment, nameof(DtbBookingDirection.PIC), Factory);
			((ICO2eCalculationSupporter)shipmentTransportBookingPIC).SetCO2eStatus(CO2eStatusList.Codes.Current);

			var depConsolTransportBookingPIC = CO2eTestHelper.CreateTransportBooking(departureConsol, nameof(DtbBookingDirection.PIC), Factory);
			((ICO2eCalculationSupporter)depConsolTransportBookingPIC).SetCO2eStatus(CO2eStatusList.Codes.Current);
			var depConsolTransportBookingDLV = CO2eTestHelper.CreateTransportBooking(departureConsol, nameof(DtbBookingDirection.DLV), Factory);
			((ICO2eCalculationSupporter)depConsolTransportBookingDLV).SetCO2eStatus(CO2eStatusList.Codes.Current);

			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);

			using (FreightDataRegistry.Instance.EnablePrePostCarriageCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				AssertContainsExactElementsInAnyOrder("Pre-condition", new[] { shipmentTransportBookingPIC, depConsolTransportBookingPIC }, ((ICO2eCalculationSupporter)shipment).AdditionalCalculationSupporters.Select(x => x.Supporter));
				AssertEquals("Pre-condition", CO2eStatusList.Codes.Current, shipment.GetCO2eStatus());

				// Act
				((ICO2eCalculationSupporter)shipmentTransportBookingPIC).SetCO2eStatus(CO2eStatusList.Codes.NotCurrent);

				// Assert
				AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
				AssertHasWarning(shipment.TotalCO2eForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);

				// Arrange
				((ICO2eCalculationSupporter)shipmentTransportBookingPIC).SetCO2eStatus(CO2eStatusList.Codes.Current);
				shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);

				// Act
				((ICO2eCalculationSupporter)depConsolTransportBookingPIC).SetCO2eStatus(CO2eStatusList.Codes.NotCurrent);

				// Assert
				AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
				AssertHasWarning(shipment.TotalCO2eForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);

				// Arrange
				((ICO2eCalculationSupporter)depConsolTransportBookingPIC).SetCO2eStatus(CO2eStatusList.Codes.Current);
				shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);

				// Act
				((ICO2eCalculationSupporter)depConsolTransportBookingDLV).SetCO2eStatus(CO2eStatusList.Codes.NotCurrent);

				// Assert
				AssertEquals(CO2eStatusList.Codes.Current, shipment.GetCO2eStatus());
				AssertNoWarning(shipment.TotalCO2eForBindingInfo, CO2eBusinessTestHelper.CO2eStaleWarning);
			}
		}

