		public void TestJS_HBLContainerPackModeOverride_UpdateCO2eStatusToNCU()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);
			AssertEquals(CO2eStatusList.Codes.Current, shipment.GetCO2eStatus());

			using (FreightDataRegistry.Instance.EnablePrePostCarriageCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
			{
				shipment.JS_HBLContainerPackModeOverride = Core.Constants.HBLDeliveryModes.Codes.CFS_CFS;
				AssertEquals(CO2eStatusList.Codes.Current, shipment.GetCO2eStatus());
			}

			using (FreightDataRegistry.Instance.EnablePrePostCarriageCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				using (FreightDataRegistry.Instance.UseHBLDeliveryModeForGHGCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
				{
					shipment.JS_HBLContainerPackModeOverride = Core.Constants.HBLDeliveryModes.Codes.CY_CY;
					AssertEquals(CO2eStatusList.Codes.Current, shipment.GetCO2eStatus());
				}

				using (FreightDataRegistry.Instance.UseHBLDeliveryModeForGHGCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
				{
					Factory.Save();
					shipment.JS_HBLContainerPackModeOverride = Core.Constants.HBLDeliveryModes.Codes.DOOR_DOOR;
					AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
					CO2eBusinessTestHelper.AssertSTUEvent(shipment, "JS_HBLContainerPackModeOverride [CY/CY]->[DOOR/DOOR]");
				}
			}
		}

		[ExpectNoExceptions]
		public void TestCO2eCalculationSupporterGetTotalEmptyContainerEmissions()
		{
			// Arrange
			var shipment1 = (ForwardingShipment)CO2eTestHelper.CreateForwardingShipmentWithLegs(Factory);
			shipment1.JS_TransportMode = TransportModes.Sea;
			shipment1.JS_PackingMode = ContainerModes.FCL;
			var shipment2 = (ForwardingShipment)CO2eTestHelper.CreateForwardingShipmentWithLegs(Factory);
			shipment2.JS_TransportMode = TransportModes.Sea;
			shipment2.JS_PackingMode = ContainerModes.FCL;

			var consol = shipment1.Consols.AddNew();
			consol.JK_TransportMode = TransportModes.Sea;
			consol.JK_ConsolMode = ContainerModes.FCL;
			shipment2.Consols.Add(consol);

			var container = consol.Containers.AddNew();
			var refContainer = NewRefContainer("20GP111", "22G0", 1m, 2280m);
			container.JC_RC = refContainer.PK;

			shipment1.OuterPackLines.RemoveAndDeleteAll();
			shipment2.OuterPackLines.RemoveAndDeleteAll();

			using (FreightDataRegistry.Instance.EnablePrePostCarriageCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				// Act & Assert
				var supporter = shipment1 as ICO2eLegBasedSupporter;
				AssertEquals("Pre-requisite: no empty containers", 0, supporter.EmptyContainers.Count);
				AssertEmptyContainerEmissions("When there are no packed containers, should return no emissions.", supporter, 0m);

				// Act & Assert
				var packline1 = shipment1.OuterPackLines.AddNew();
				packline1.JL_ActualWeight = 100;
				packline1.JL_ActualWeightUQ = Weight.Kilograms;
				container.AddPackLine(packline1);
				AssertEquals("Pre-requisite: 1 empty container", 1, supporter.EmptyContainers.Count);
				AssertEmptyContainerEmissions("When there is a packed container on shipment1, empty containers emissions on shipment1 should factor in this weight and return an emission.", supporter, 35m);

				// Act & Assert
				var packline2 = shipment2.OuterPackLines.AddNew();
				packline2.JL_ActualWeight = 100;
				packline2.JL_ActualWeightUQ = Weight.Kilograms;
				container.AddPackLine(packline2);
				AssertEquals("Pre-requisite: 1 empty containers", 1, supporter.EmptyContainers.Count);
				AssertEmptyContainerEmissions("When there is also a packed container on shipment2, empty container emissions on shipment1 should not factor in this packline.", supporter, 17.5m);

				// Act & Assert
				var packline3 = shipment1.OuterPackLines.AddNew();
				packline3.JL_ActualWeight = 50;
				packline3.JL_ActualWeightUQ = Weight.Kilograms;
				container.AddPackLine(packline3);
				AssertEquals("Pre-requisite: 1 empty container", 1, supporter.EmptyContainers.Count);
				AssertEmptyContainerEmissions("When there is multiple packlines for a container, empty containers emissions on the shipment should factor in the weight of all packlines for a container on that shipment and return an emission.", supporter, 21m);
			}
			using (FreightDataRegistry.Instance.EnablePrePostCarriageCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
			{
				// Act & Assert
				var supporter = shipment1 as ICO2eLegBasedSupporter;
				AssertEquals("Pre-requisite: 1 empty container", 1, supporter.EmptyContainers.Count);
				AssertEmptyContainerEmissions("When PrePostCarriage registry is disabled, should return no emissions.", supporter, 0m);
			}

			void AssertEmptyContainerEmissions(ZString message, ICO2eLegBasedSupporter supporter, ZDecimal expectedEmissions)
			{
				supporter.EmptyContainers.ForEach(emptyContainer =>
				{
					emptyContainer.Container.SetTotalCO2e(10, CO2eTypes.EmptyPickup);
					emptyContainer.Container.SetCO2ePerTEUInKg(10, CO2eTypes.EmptyPickup);
					emptyContainer.Container.SetTotalCO2e(25, CO2eTypes.EmptyReturn);
					emptyContainer.Container.SetCO2ePerTEUInKg(25, CO2eTypes.EmptyReturn);
				});

				var emptyContainerEmissions = supporter.GetTotalEmptyContainerEmissions();
				AssertEquals(message, expectedEmissions, emptyContainerEmissions);
			}
		}

		public void TestICO2eCalculationSupporterOnCalculatedDeleteJobCO2eForUnlinkedLegsWhenConsolAttached()
		{
			// Arrange
			var shipment = Factory.New<ForwardingShipment>();

			var consol = shipment.Consols.AddNew();

			var unlinkedConsolTransport = consol.Transports.AddNew();
			unlinkedConsolTransport.JW_IsLinked = false;
			unlinkedConsolTransport.SetCO2eStatus(CO2eStatusList.Codes.Current);
			unlinkedConsolTransport.SetCO2ePerTonneInKg(250m);

			var linkedConsolTransport = consol.Transports.AddNew();
			linkedConsolTransport.JW_IsLinked = true;
			linkedConsolTransport.SetCO2eStatus(CO2eStatusList.Codes.Current);
			linkedConsolTransport.SetCO2ePerTonneInKg(250m);

			var unlinkedShipmentTransport = shipment.Transports.AddNew();
			unlinkedShipmentTransport.JW_IsLinked = false;
			unlinkedShipmentTransport.SetCO2eStatus(CO2eStatusList.Codes.Current);
			unlinkedShipmentTransport.SetCO2ePerTonneInKg(250m);

			var linkedShipmentTransport = shipment.Transports.AddNew();
			linkedShipmentTransport.JW_IsLinked = true;
			linkedShipmentTransport.SetCO2eStatus(CO2eStatusList.Codes.Current);
			linkedShipmentTransport.SetCO2ePerTonneInKg(250m);

			using (FreightDataRegistry.Instance.EnablePrePostCarriageCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
			{
				Assert(!((ICO2ePrePostCarriage)shipment).RequiresPrePostCarriageLegs);

				// Act
				(shipment as ICO2eCalculationSupporter).OnCalculated(true);

				// Assert
				AssertEquals(CO2eStatusList.Codes.Current, unlinkedConsolTransport.GetCO2eStatus());
				AssertEquals(250m, unlinkedConsolTransport.GetCO2ePerTonneInKg());

				AssertEquals(CO2eStatusList.Codes.Current, linkedConsolTransport.GetCO2eStatus());
				AssertEquals(250m, linkedConsolTransport.GetCO2ePerTonneInKg());

				AssertEquals(CO2eStatusList.Codes.Current, unlinkedShipmentTransport.GetCO2eStatus());
				AssertEquals(250m, unlinkedShipmentTransport.GetCO2ePerTonneInKg());

				AssertEquals(CO2eStatusList.Codes.Current, linkedShipmentTransport.GetCO2eStatus());
				AssertEquals(250m, linkedShipmentTransport.GetCO2ePerTonneInKg());
			}
			using (FreightDataRegistry.Instance.EnablePrePostCarriageCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				Assert(((ICO2ePrePostCarriage)shipment).RequiresPrePostCarriageLegs);

				// Act
				(shipment as ICO2eCalculationSupporter).OnCalculated(true);

				// Assert
				AssertEquals(CO2eStatusList.Codes.Current, unlinkedConsolTransport.GetCO2eStatus());
				AssertEquals(250m, unlinkedConsolTransport.GetCO2ePerTonneInKg());

				AssertEquals(CO2eStatusList.Codes.Current, linkedConsolTransport.GetCO2eStatus());
				AssertEquals(250m, linkedConsolTransport.GetCO2ePerTonneInKg());

				AssertEquals(CO2eStatusList.Codes.NotCalculated, unlinkedShipmentTransport.GetCO2eStatus());
				AssertEquals(0m, unlinkedShipmentTransport.GetCO2ePerTonneInKg());

				AssertEquals(CO2eStatusList.Codes.Current, linkedShipmentTransport.GetCO2eStatus());
				AssertEquals(250m, linkedShipmentTransport.GetCO2ePerTonneInKg());
			}
		}
