		void AssertHookAttachedToTransport(Transport transport, ForwardingShipment shipment)
		{
			// Arrange
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);

			// Trigger hook
			transport.SetCO2eStatus(CO2eStatusList.Codes.Current);
			transport.SetCO2eStatus(CO2eStatusList.Codes.NotCurrent);

			// Check side effect
			AssertEquals("Shipment status changed", CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
		}

		void AssertHookNotAttachedToTransport(Transport transport, ForwardingShipment shipment)
		{
			// Arrange
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);

			// Trigger hook
			transport.SetCO2eStatus(CO2eStatusList.Codes.Current);
			transport.SetCO2eStatus(CO2eStatusList.Codes.NotCurrent);

			// Check side effect
			AssertEquals("Shipment status not changed", CO2eStatusList.Codes.Current, shipment.GetCO2eStatus());
		}

		void AssertCountChangedEventAddingRemovingConsolTransportUpdatesStatus(ForwardingConsol consol, ForwardingShipment shipment)
		{
			// Arrange
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);

			// Trigger count changed event
			var consolTransport = consol.Transports.AddNew();

			// Check side effect
			AssertEquals("Shipment status changed", CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());

			// Arrange
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Current);

			// Trigger count changed event
			consol.Transports.RemoveAndDelete(consolTransport);

			// Check side effect
			AssertEquals("Shipment status changed", CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());
		}

