		public void TestOnTransportsIncludingRelatedCreatedHooksSubscribedToConsolsTransportsIfPrePostCarriageEnabledAndConsolAttached()
		{
			using (FreightDataRegistry.Instance.EnablePrePostCarriageCalculation.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				// Arrange
				var shipment = Factory.New<ForwardingShipment>();
				var consol = shipment.Consols.AddNew();
				var consolTransport1 = (Transport)consol.Transports.First();
				var shipmentTransport1 = shipment.Transports.AddNew();

				// Act
				AssertEquals("Load TransportsIncludingRelated collection", 2, shipment.TransportsIncludingRelated.Count);

				// Assert
				AssertCountChangedEventAddingRemovingConsolTransportDoesntUpdateStatus(consol, shipment);
				AssertCountChangedEventAddingRemovingShipmentTransportDoesntUpdateStatus(shipment);
				AssertHookAttachedToTransport(consolTransport1, shipment);
				AssertHookNotAttachedToTransport(shipmentTransport1, shipment);

				// Act
				var consolTransport2 = consol.Transports.AddNew();
				var shipmentTransport2 = shipment.Transports.AddNew();

				// Assert
				AssertHookAttachedToTransport(consolTransport2, shipment);
				AssertHookNotAttachedToTransport(shipmentTransport2, shipment);

				// Act
				consol.Transports.Remove(consolTransport2);
				shipment.Transports.Remove(shipmentTransport2);

				// Assert
				AssertHookNotAttachedToTransport(consolTransport2, shipment);
				AssertHookNotAttachedToTransport(shipmentTransport2, shipment);
			}
		}

