		public void TestCarteDePorteFilter()
		{
			var carteDePorteMenuItemPK = new ZGuid("5a7dbf65-2845-4c97-85db-a8c8405eff27");
			var carteDePorteMenuItem = Factory.Load<StmMenuItem>(carteDePorteMenuItemPK);

			AssertNotNull("Carte De Porte menu item has been found", carteDePorteMenuItem);

			var filter = carteDePorteMenuItem.SU_FilterList.ToString();

			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Road;
			shipment.JS_HouseBillOfLadingType = "CPT";

			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.Argentina))
			using (var scope = new MacroScope(shipment))
			{
				scope.SetVariable("env", new MasterFiles.Business.Macros.Environment());

				var expr = filter
					.With<StandardLibrary>()
					.CreateExpression();

				var res = expr.Evaluate(scope);

				AssertMultilineASCIIEquals("expect no errors",
					"",
					string.Join("\r\n", expr.Errors.Select(err => err.Message)));

				AssertEquals("Carte De Porte filter has been evaluated properly.", true, res);
			}
		}

