		public void TestSynchronizeShipmentGatewayFromConsols_AttachConsol()
		{
			#region test attach a consol when no exsit gateway on shipment. Order:SendingForwarder - ReceivingForwarder

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			var sendingForwarder = Factory.NewWithValidTestData<OrgHeader>();
			consol.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol.JK_OA_SendingForwarderAddress = sendingForwarder.MainAddress.PK;
			var receivingForwarder = Factory.NewWithValidTestData<OrgHeader>();
			consol.JK_ReceivingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol.JK_OA_ReceivingForwarderAddress = receivingForwarder.MainAddress.PK;
			Factory.Save();

			shipment.Consols.Add(consol);
			AssertEquals("Consol count", 1, shipment.Consols.Count);
			AssertEquals("Gateways count", 2, shipment.Gateways.Count);
			AssertEquals("Gateway shipment: SendingForwarder", shipment.PK, shipment.Gateways[0].JSG_JS_Shipment);
			AssertEquals("Gateway Sequence: SendingForwarder is in order before ReceivingForwarder", 1, shipment.Gateways[0].JSG_Sequence.ToZInt());
			AssertEquals("Gateway: SendingForwarderAddress", consol.SendingForwarderAddress.PK, shipment.Gateways[0].JSG_OA_ForwarderAddress);
			AssertEquals("Gateway Sequence: ReceivingForwarder is in order after SendingForwarder", 2, shipment.Gateways[1].JSG_Sequence.ToZInt());
			AssertEquals("Gateway: ReceivingForwarderAddress", consol.ReceivingForwarderAddress.PK, shipment.Gateways[1].JSG_OA_ForwarderAddress);

			#endregion

			#region test attach a consol when has exsit gateway on shipment. Order:SendingForwarder - ReceivingForwarder - manually added gateway

			var shipment2 = Factory.NewWithValidTestData<ForwardingShipment>();
			var gateway = shipment2.Gateways.AddNew();
			var gatewayOrg = Factory.NewWithValidTestData<OrgHeader>();
			gateway.JSG_OA_ForwarderAddress = gatewayOrg.MainAddress.PK;
			AssertEquals("Gateway Sequence: manually added gateway", 1, gateway.JSG_Sequence.ToZInt());

			var consol2 = Factory.NewWithValidTestData<ForwardingConsol>();
			consol2.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol2.JK_OA_SendingForwarderAddress = sendingForwarder.MainAddress.PK;
			consol2.JK_ReceivingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol2.JK_OA_ReceivingForwarderAddress = receivingForwarder.MainAddress.PK;
			Factory.Save();

			shipment2.Consols.Add(consol2);
			AssertEquals("Consol count", 1, shipment2.Consols.Count);
			AssertEquals("Gateways count", 3, shipment2.Gateways.Count);
			AssertEquals("Gateway Sequence: SendingForwarder is in order before ReceivingForwarder", 1, shipment2.Gateways[0].JSG_Sequence.ToZInt());
			AssertEquals("Gateway: SendingForwarder from consol", consol2.SendingForwarderAddress.PK, shipment2.Gateways[0].JSG_OA_ForwarderAddress);
			AssertEquals("Gateway: ReceivingForwarder from consol", consol2.ReceivingForwarderAddress.PK, shipment2.Gateways[1].JSG_OA_ForwarderAddress);
			AssertEquals("Gateway Sequence: manually added gateway is always behind the the default ones from consol", 3, shipment2.Gateways[2].JSG_Sequence.ToZInt());
			AssertEquals("Gateway: manually added gateway", gatewayOrg.MainAddress.PK, shipment2.Gateways[2].JSG_OA_ForwarderAddress);

			#endregion

			#region test no duplicate gateway added when attach a consol

			var consol3 = Factory.NewWithValidTestData<ForwardingConsol>();
			consol3.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol3.JK_OA_SendingForwarderAddress = sendingForwarder.MainAddress.PK;
			consol3.JK_ReceivingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol3.JK_OA_ReceivingForwarderAddress = receivingForwarder.MainAddress.PK;

			var shipment3 = Factory.NewWithValidTestData<ForwardingShipment>();
			var gateway3 = shipment3.Gateways.AddNew();
			gateway3.JSG_OA_ForwarderAddress = consol3.ReceivingForwarderAddress.PK;
			AssertEquals("Gateway Sequence: manually added gateway", 1, gateway3.JSG_Sequence.ToZInt());
			Factory.Save();

			shipment3.Consols.Add(consol3);
			AssertEquals("Gateways count: Not adding duplicate gateway", 2, shipment3.Gateways.Count);
			AssertEquals("Gateway: SendingForwarder from consol", consol3.SendingForwarderAddress.PK, shipment3.Gateways[0].JSG_OA_ForwarderAddress);
			AssertEquals("Gateway: ReceivingForwarder from consol", consol3.ReceivingForwarderAddress.PK, shipment3.Gateways[1].JSG_OA_ForwarderAddress);

			#endregion

			#region test no duplicate gateway added when attach muti consols

			var consol4 = Factory.NewWithValidTestData<ForwardingConsol>();
			consol4.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol4.JK_OA_SendingForwarderAddress = sendingForwarder.MainAddress.PK;
			consol4.JK_ReceivingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol4.JK_OA_ReceivingForwarderAddress = receivingForwarder.MainAddress.PK;

			var consol5 = Factory.NewWithValidTestData<ForwardingConsol>();
			consol5.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol5.JK_OA_SendingForwarderAddress = sendingForwarder.MainAddress.PK;
			consol5.JK_ReceivingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol5.JK_OA_ReceivingForwarderAddress = receivingForwarder.MainAddress.PK;

			var shipment4 = Factory.NewWithValidTestData<ForwardingShipment>();
			Factory.Save();

			shipment4.Consols.Add(consol4);
			shipment4.Consols.Add(consol5);
			AssertEquals("Gateways count: Not adding duplicate gateway", 2, shipment4.Gateways.Count);
			AssertEquals("Gateway: SendingForwarder from consol", consol4.SendingForwarderAddress.PK, shipment4.Gateways[0].JSG_OA_ForwarderAddress);
			AssertEquals("Gateway: ReceivingForwarder from consol", consol4.ReceivingForwarderAddress.PK, shipment4.Gateways[1].JSG_OA_ForwarderAddress);

			#endregion
		}

