			var consol5 = Factory.NewWithValidTestData<ForwardingConsol>();
			consol5.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol5.JK_OA_SendingForwarderAddress = sendingForwarder.MainAddress.PK;
			consol5.JK_ReceivingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol5.JK_OA_ReceivingForwarderAddress = receivingForwarder.MainAddress.PK;

			var shipment4 = Factory.NewWithValidTestData<ForwardingShipment>();
			Factory.Save();

			consol4.Shipments.Add(shipment4);
			consol5.Shipments.Add(shipment4);
			AssertEquals("Gateways count: Not adding duplicate gateway", 2, shipment4.Gateways.Count);
			AssertEquals("Gateway: SendingForwarder from consol", consol4.SendingForwarderAddress.PK, shipment4.Gateways[0].JSG_OA_ForwarderAddress);
			AssertEquals("Gateway: ReceivingForwarder from consol", consol4.ReceivingForwarderAddress.PK, shipment4.Gateways[1].JSG_OA_ForwarderAddress);

			#endregion
		}

		public void TestSynchronizeShipmentGatewayFromConsols_DetachShipment()
		{
			#region test detach a consol when no exsit gateway on shipment.

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			var sendingForwarder = Factory.NewWithValidTestData<OrgHeader>();
			consol.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol.JK_OA_SendingForwarderAddress = sendingForwarder.MainAddress.PK;
			var receivingForwarder = Factory.NewWithValidTestData<OrgHeader>();
			consol.JK_ReceivingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol.JK_OA_ReceivingForwarderAddress = receivingForwarder.MainAddress.PK;
			Factory.Save();

			consol.Shipments.Add(shipment);
			AssertEquals("Gateways count", 2, shipment.Gateways.Count);

			consol.Shipments.Remove(shipment);
			AssertEquals("Gateways count", 0, shipment.Gateways.Count);

			#endregion

			#region test detach a consol when has exsit gateway on shipment.

			var shipment2 = Factory.NewWithValidTestData<ForwardingShipment>();
			var gateway = shipment2.Gateways.AddNew();
			var gatewayOrg = Factory.NewWithValidTestData<OrgHeader>();
			gateway.JSG_OA_ForwarderAddress = gatewayOrg.MainAddress.PK;
			AssertEquals("Gateway Sequence: manually added gateway", 1, gateway.JSG_Sequence.ToZInt());

			var consol2 = Factory.NewWithValidTestData<ForwardingConsol>();
			consol2.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol2.JK_OA_SendingForwarderAddress = sendingForwarder.MainAddress.PK;
			consol2.JK_ReceivingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol2.JK_OA_ReceivingForwarderAddress = receivingForwarder.MainAddress.PK;
			Factory.Save();

			consol2.Shipments.Add(shipment2);
			AssertEquals("Gateways count", 3, shipment2.Gateways.Count);

			consol2.Shipments.Remove(shipment2);
			AssertEquals("Gateways count", 1, shipment2.Gateways.Count);
			AssertEquals("Gateway Sequence: manually added gateway is always behind the the default ones from consol", 1, shipment2.Gateways[0].JSG_Sequence.ToZInt());
			AssertEquals("Gateway: manually added gateway", gatewayOrg.MainAddress.PK, shipment2.Gateways[0].JSG_OA_ForwarderAddress);

			#endregion

			#region test detach a consol when the exsit gateway on shipment is same as the consol gataway agent.

			var consol3 = Factory.NewWithValidTestData<ForwardingConsol>();
			consol3.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol3.JK_OA_SendingForwarderAddress = sendingForwarder.MainAddress.PK;
			consol3.JK_ReceivingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol3.JK_OA_ReceivingForwarderAddress = receivingForwarder.MainAddress.PK;

			var shipment3 = Factory.NewWithValidTestData<ForwardingShipment>();
			var gateway3 = shipment3.Gateways.AddNew();
			gateway3.JSG_OA_ForwarderAddress = consol3.ReceivingForwarderAddress.PK;
			AssertEquals("Gateway Sequence: manually added gateway", 1, gateway3.JSG_Sequence.ToZInt());
			Factory.Save();

			consol3.Shipments.Add(shipment3);
			AssertEquals("Gateways count", 2, shipment3.Gateways.Count);

			consol3.Shipments.Remove(shipment3);
			AssertEquals("Gateways count: Gateway will be removed if it is including in removed consol regardless how it adding", 0, shipment3.Gateways.Count);

			#endregion
		}

		public void TestSynchronizeShipmentGatewayFromConsols_DataRefreshBus()
		{
			#region test DataRefreshBus doesn't cause consol to have changes when saving consol

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			var sendingForwarder = Factory.NewWithValidTestData<OrgHeader>();
			consol.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol.JK_OA_SendingForwarderAddress = sendingForwarder.MainAddress.PK;
			var receivingForwarder = Factory.NewWithValidTestData<OrgHeader>();
			consol.JK_ReceivingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol.JK_OA_ReceivingForwarderAddress = receivingForwarder.MainAddress.PK;
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			Factory.Save();

			var shipmentFactory = new BusinessObjectFactory();
			var newShipment = shipmentFactory.LoadTop1<ForwardingShipment>(new ZQuery(JobShipmentSchema.PK, shipment.PK));

			var consolFactory = new BusinessObjectFactory();
			var newConsol = consolFactory.LoadTop1<ForwardingConsol>(new ZQuery(JobConsolSchema.PK, consol.PK));

			newConsol.Shipments.Add(shipment);
			consolFactory.Save();

			AssertEquals("shipment shouldn't have changes on saving consol after attaching shipment to consol", false, newShipment.HasChanges);

			newConsol.Shipments.Remove(shipment);
			consolFactory.Save();

			AssertEquals("shipment shouldn't have changes on saving consol after detaching shipment from consol", false, newShipment.HasChanges);
			#endregion

			#region test DataRefreshBus doesn't cause shipment to have changes when saving shipment

			newShipment.Consols.Add(consol);
			shipmentFactory.Save();

			AssertEquals("consol shouldn't have changes on saving shipment after attaching consol to shipment", false, newConsol.HasChanges);

			newShipment.Consols.Remove(consol);
			shipmentFactory.Save();

			AssertEquals("consol shouldn't have changes on saving shipment after detaching consol from shipment", false, newConsol.HasChanges);

			#endregion
		}

