		#region SI Log Creation
		public void TestSIJLogCreated()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			var oldStatus = shipment.JS_ShipmentStatus;
			shipment.GenerateStatusEvent(ShipmentStatusList.Codes.SIRejected, "Yeet");

			var updEvent = shipment.Logs.GetAllLogs().OfType<StmALog>().FirstOrDefault(log => log.SL_SE_NKEvent == Events.StatusUpdated.Code);

			AssertNotNull("SEC event has been created on consolidation", updEvent);
			AssertEquals(oldStatus, updEvent.Parameters[EventConstants.EventReferenceParameters.Codes.Old]);
			AssertEquals(ShipmentStatusList.Codes.SIRejected, updEvent.Parameters[EventConstants.EventReferenceParameters.Codes.New]);
			AssertEquals("Shipping Instruction Rejected, Yeet", updEvent.Parameters[EventConstants.EventReferenceParameters.Codes.Reason]);
		}

		public void TestStatusChangeTriggersLogCreation()
		{
			ForwardingShipment shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			var oldStatus = shipment.JS_ShipmentStatus;
			shipment.JS_ShipmentStatus = ShipmentStatusList.Codes.SIRejected;

			AssertEquals(ShipmentStatusList.Codes.SIRejected, shipment.JS_ShipmentStatus);
			var updEvent = shipment.Logs.GetAllLogs().OfType<StmALog>().FirstOrDefault(log => log.SL_SE_NKEvent == Events.StatusUpdated.Code);

			AssertNotNull("SEC event has been created on consolidation", updEvent);
			AssertEquals(oldStatus, updEvent.Parameters[EventConstants.EventReferenceParameters.Codes.Old]);
			AssertEquals(ShipmentStatusList.Codes.SIRejected, updEvent.Parameters[EventConstants.EventReferenceParameters.Codes.New]);
			AssertEquals("Shipping Instruction Rejected", updEvent.Parameters[EventConstants.EventReferenceParameters.Codes.Reason]);
		}

