				airConsol.JK_RL_NKLoadPort = "DEHAM";
				airConsol.JK_RL_NKDischargePort = "SGSIN";

				shipment.JS_RL_NKOrigin = "ZACPT";
				shipment.JS_RL_NKDestination = "SGSIN";

				AssertEquals(false, shipment.JS_InspectionTypeCodeInfo.ReadOnly);
