		void AssertRequiresSecuredCargoFromWarehouse(ZString origin, bool isCheckingActivated, bool expected)
		{
			using (WarehouseDataRegistry.Instance.DriverSecurityCertificationCheckingActivated.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, isCheckingActivated))
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(origin.Left(2)))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = origin;
				shipment.JS_RL_NKDestination = "HKHKG";
				shipment.JS_TransportMode = "AIR";

				AssertEquals("Expect false when have no packlines", false, shipment.RequiresSecuredCargoFromWarehouse);

				shipment.OuterPackLines.AddNew();
				AssertEquals("Expect false when have packlines but no warehouse is linked", false, shipment.RequiresSecuredCargoFromWarehouse);

				var warehouse = CreateWarehouse("WHS01");
				CreatePackLineWithTWStatus(shipment, warehouse.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Dispatched);

				AssertEquals(expected, shipment.RequiresSecuredCargoFromWarehouse);
			}
		}

		#region TransitWarehouseParent Memebers

		public void TestITransitWarehouseParent_AttachPackages()
		{
			var shipment = Factory.New<ForwardingShipment>();
			var unMatching = shipment.OuterPackLines.AddNew();
			unMatching.JL_RefNumber = "UnMatching";
			unMatching.JL_F3_NKPackType = "ROL";
			unMatching.JL_Description = "UM";
			unMatching.JL_PackageCount = 4;
			unMatching.JL_UnitOfDimension = "D3";
			unMatching.JL_ActualWeightUQ = "G";
			unMatching.JL_ActualVolumeUQ = "M3";
			unMatching.JL_Height = 21;
			unMatching.JL_Length = 22;
			unMatching.JL_Width = 25;
			unMatching.JL_ActualVolume = 23;
			unMatching.JL_ActualWeight = 24;
			unMatching.JL_MarksAndNumbers = "MNS";
			AssertEquals(1, shipment.OuterPackLines.Count);
			AssertEquals(0, Factory.Load<StmALog>(new ZQuery(StmALogSchema.SL_Parent, shipment.PK)).Length);

			var packageJob = CreateTWPkgPackageJob("RC0001");
			var packageIDAlreadyExistsInPackline = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "AlreadyExists", "PLT", 1, 2, 5, 1, 3, 4, "M3", "KG", "M3", marksAndNumbers: "MN1", goodsDescription: "GD");
			var newPackageID = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "", "CTN", 2, 21, 51, 11, 31, 41, "M2", "KG", "M3", marksAndNumbers: "MN1", isDamaged: true, damagedReason: "LOS", goodsDescription: "GD1");
			((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { packageIDAlreadyExistsInPackline, newPackageID });

			var shipmentATCEventLogs = Factory.Load<StmALog>(new ZQuery(StmALogSchema.SL_Parent, shipment.PK));
			AssertEquals(1, shipmentATCEventLogs.Length);
			AssertEquals("|REF=2x Blind Transit Package(s) attached to Shipment.", shipmentATCEventLogs.First().SL_Reference);
			AssertEquals(3, shipment.OuterPackLines.Count);
			var alreadyExistsOuter = shipment.OuterPackLines.Cast<ForwardingPackLine>().Single(o => o.JL_Height == 1m);
			var newOuter = shipment.OuterPackLines.Cast<ForwardingPackLine>().Single(o => o.JL_Height == 11m);
			var unMatch = shipment.OuterPackLines.Cast<ForwardingPackLine>().Single(o => o.JL_Height == 21);
			AssertOuterPackline(alreadyExistsOuter, "PLT", "GD", 1m, 2m, 3m, 4m, 5m, 1, "M3", "KG", "M3", "MN1", 0, string.Empty, FreightConstants.PacklineOriginTransitWarehouseStatus.Codes.Surplus, true);
			AssertOuterPackline(newOuter, "CTN", "GD1", 11m, 21m, 31m, 41m, 51m, 2, "M2", "KG", "M3", "MN1", 2, "LOS", FreightConstants.PacklineOriginTransitWarehouseStatus.Codes.Surplus, true);
			AssertOuterPackline(unMatch, "ROL", "UM", 21m, 22m, 23m, 24m, 25m, 4, "D3", "G", "M3", "MNS", 0, string.Empty, FreightConstants.PacklineOriginTransitWarehouseStatus.Codes.Unknown, false);

			var newFactory = new BusinessObjectFactory();
			var shipmentInNewFactory = newFactory.New<ForwardingShipment>();
			shipmentInNewFactory.HasChanges = false;
			AssertEquals("Precondition", false, shipmentInNewFactory.HasChanges);

			((ITransitWarehouseParent)shipmentInNewFactory).AttachPackages(new ITransitPackage[] { packageIDAlreadyExistsInPackline });
			AssertEquals(true, shipmentInNewFactory.HasChanges);
			AssertEquals(0, Factory.Load<StmALog>(new ZQuery(StmALogSchema.SL_Parent, shipmentInNewFactory.PK)).Length);

			var shipmentInNewFactory2 = newFactory.New<ForwardingShipment>();
			shipmentInNewFactory2.HasChanges = false;
			AssertEquals("Precondition", false, shipmentInNewFactory2.HasChanges);
			((ITransitWarehouseParent)shipmentInNewFactory2).AttachPackages(Array.Empty<ITransitPackage>());
			AssertEquals(false, shipmentInNewFactory2.HasChanges);
			AssertEquals(0, Factory.Load<StmALog>(new ZQuery(StmALogSchema.SL_Parent, shipmentInNewFactory2.PK)).Length);
		}

