				var newPackageID = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "", "CTN", 2, 21, 51, 11, 31, 41, "M2", "KG", "M3", marksAndNumbers: "MN1", goodsDescription: "GD1", isDamaged: true);
				((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { packageIDAlreadyExistsInPackline, newPackageID });

				var shipmentATCEventLogs = Factory.Load<StmALog>(new ZQuery(StmALogSchema.SL_Parent, shipment.PK));
				AssertEquals(1, shipmentATCEventLogs.Length);
				AssertEquals("|REF=2x Blind Transit Package(s) attached to Shipment.", shipmentATCEventLogs.First().SL_Reference);
				AssertEquals(3, shipment.OuterPackLines.Count);
