				AssertEquals(newPackageID.Package.PK, newOuter.PkgPackageCollection[0].PK);
				AssertOuterPackline(unMatch, "ROL", "UM", 21m, 22m, 23m, 24m, 25m, 4, "D3", "G", "M3", "MNS", 0, String.Empty, FreightConstants.PacklineOriginTransitWarehouseStatus.Codes.Unknown, false);
				AssertEquals(FreightConstants.PacklineOriginTransitWarehouseStatus.Codes.Surplus, newOuter.JL_OriginTransitWarehouseStatus);
				AssertEquals(FreightConstants.PacklineOriginTransitWarehouseStatus.Codes.Surplus, alreadyExistsOuter.JL_OriginTransitWarehouseStatus);

				var newFactory = new BusinessObjectFactory();
