				((ITransitWarehouseParent)shipmentInNewFactory).AttachPackages(new ITransitPackage[] { packageIDAlreadyExistsInPackline });
				AssertEquals(true, shipmentInNewFactory.HasChanges);
				AssertEquals(0, newFactory.Load<StmALog>(new ZQuery(StmALogSchema.SL_Parent, shipmentInNewFactory.PK)).Length);

				var shipmentInNewFactory2 = newFactory.New<ForwardingShipment>();
