		public void TestITransitWarehouseParent_AttachPackagesATCEvent()
		{
			var shipment = Factory.New<ForwardingShipment>();
			AssertEquals(0, Factory.Load<StmALog>(new ZQuery(StmALogSchema.SL_Parent, shipment.PK)).Length);

			var packageJob = CreateTWPkgPackageJob("RC0001");
			var packageID = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "PackageID", "PLT", goodsDescription: "GD");
			var packageID2 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "PackageID2", "CTN", goodsDescription: "GD1");
			var packageID3 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "PackageID3", "GLC", goodsDescription: "GD2");

			((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { packageID });
			var shipmentATCEventLogs = Factory.Load<StmALog>(new ZQuery(StmALogSchema.SL_Parent, shipment.PK));
			AssertEquals(1, shipmentATCEventLogs.Length);
			AssertEquals("|REF=1x Blind Transit Package(s) attached to Shipment.", shipmentATCEventLogs.First().SL_Reference);

			((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { packageID, packageID2, packageID3 });
			var shipmentATCEventLogs2 = Factory.Load<StmALog>(new ZQuery(StmALogSchema.SL_Parent, shipment.PK));
			AssertEquals(2, shipmentATCEventLogs2.Length);
			AssertEquals("|REF=2x Blind Transit Package(s) attached to Shipment.", shipmentATCEventLogs2.Last().SL_Reference);

			((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { packageID, packageID2, packageID3 });
			var shipmentATCEventLogs3 = Factory.Load<StmALog>(new ZQuery(StmALogSchema.SL_Parent, shipment.PK));
			AssertEquals(2, shipmentATCEventLogs3.Length);
		}

		public void TestITransitWarehouseParent_DeletePacklinesForLink()
		{
			using (FreightConfigurationRegistry.Instance.EnableTWPackageLinking.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
				shipment.JS_TransportMode = TransportModes.Sea;
				var oldPackLine = shipment.OuterPackLines.AddNew();
				oldPackLine.JL_F3_NKPackType = "ROL";
				oldPackLine.JL_Description = "UM";
				oldPackLine.JL_PackageCount = 4;
				oldPackLine.JL_UnitOfDimension = "D3";
				oldPackLine.JL_ActualWeightUQ = "G";
				oldPackLine.JL_ActualVolumeUQ = "M3";
				oldPackLine.JL_Height = 21;
				oldPackLine.JL_Length = 22;
				oldPackLine.JL_Width = 25;
				oldPackLine.JL_ActualVolume = 23;
				oldPackLine.JL_ActualWeight = 24;
				oldPackLine.JL_MarksAndNumbers = "MNS";

				var shipmentPackageJob = Factory.New<PkgPackageJob>();
				shipmentPackageJob.KJ_JobID = "SH0001";
				shipmentPackageJob.KJ_ParentID = shipment.PK;
				shipmentPackageJob.KJ_ParentTableCode = shipment.TablePrefix;
				var pkg1 = shipmentPackageJob.Packages.AddNew();
				pkg1.KP_PackageID = "PKG1";
				pkg1.KP_F3_NKPackType = "PLT";
				pkg1.KP_PackageQty = 1;
				pkg1.KP_GoodsDescription = "GD";
				pkg1.KP_Height = 1m;
				pkg1.KP_Length = 2m;
				pkg1.KP_Weight = 4m;
				pkg1.KP_Width = 5m;
				pkg1.KP_DimensionUQ = "M";
				pkg1.KP_WeightUQ = "KG";
				pkg1.KP_VolumeUQ = "M3";
				pkg1.KP_Volume = 3m;
				pkg1.KP_MarksAndNumbers = "MN1";
				oldPackLine.PkgPackageCollection.Add(pkg1);

				var packageJob = CreateTWPkgPackageJob("RC0001");
				var pkg2 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "PKG2");

				Factory.Save();
				((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { pkg2 });
				AssertEquals(2, shipment.OuterPackLines.Count);
				Factory.Save();

				shipment.OuterPackLines.RemoveAndDeleteAll();
				Factory.Save();
				AssertEquals(0, shipment.OuterPackLines.Count);
				AssertEquals(true, shipmentPackageJob.IsDeleted);
				AssertEquals(true, pkg1.IsDeleted);

				AssertEquals(false, packageJob.IsDeleted);
				AssertEquals(false, pkg2.Package.IsDeleted);
			}
		}

