		public void TestITransitWarehouseParent_AttachPackagesIncludesScreenings()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry("AU"))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "AUSYD";
				shipment.JS_RL_NKDestination = "HKHKG";
				shipment.JS_TransportMode = "AIR";

				var packlineOnShipment = shipment.OuterPackLines.AddNew();
				packlineOnShipment.JL_RefNumber = "attachedShipment";
				packlineOnShipment.JL_F3_NKPackType = "ROL";
				packlineOnShipment.JL_Description = "UM";
				packlineOnShipment.JL_PackageCount = 4;
				packlineOnShipment.JL_RequiresTemperatureControl = true;
				packlineOnShipment.JL_RequiredTemperatureMinimum = 4m;
				packlineOnShipment.JL_RequiredTemperatureMaximum = 5m;
				packlineOnShipment.JL_RequiredTemperatureUnit = "C";
				packlineOnShipment.JL_MarksAndNumbers = "MNS";

				var packageScreening1 = Factory.New<PkgPackageScreening>();
				packageScreening1.KPS_GS_NKScreenedBy = "STF";
				packageScreening1.KPS_Passed = true;
				packageScreening1.KPS_Method = AdditionalScreeningMethods.Codes.PhysicalInspectionAndHandSearch;
				packageScreening1.KPS_Time = DateTimeOffset.Now.AddHours(-1);

				var packageScreening2 = Factory.New<PkgPackageScreening>();
				packageScreening2.KPS_GS_NKScreenedBy = "~BP";
				packageScreening2.KPS_Passed = true;
				packageScreening2.KPS_Method = AdditionalScreeningMethods.Codes.XRayEquipment;
				packageScreening2.KPS_Time = DateTimeOffset.Now;

				var packageScreening3 = Factory.New<PkgPackageScreening>();
				packageScreening3.KPS_GS_NKScreenedBy = "STF";
				packageScreening3.KPS_Passed = false;
				packageScreening3.KPS_Method = AdditionalScreeningMethods.Codes.PhysicalInspectionAndHandSearch;
				packageScreening3.KPS_Time = DateTimeOffset.Now;

				AssertEquals(1, shipment.OuterPackLines.Count);

				var packageJob = CreateTWPkgPackageJob("RC0001");
				var package1 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "package1", "PLT", 1, goodsDescription: "GD", requiresTemperatureControl: false, requiredTemperatureMaximum: 6, requiredTemperatureMinimum: 6, requiredTemperatureUnit: "C", screenings: new[] { packageScreening1, packageScreening2 }, isHighRisk: true);
				var package2 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "package2", "CTN", 1, goodsDescription: "GD1", requiresTemperatureControl: false, screenings: new[] { packageScreening3 });
				((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { package1, package2 });
				AssertEquals(3, shipment.OuterPackLines.Count);

				var packlineWithPackage1 = shipment.OuterPackLines.Cast<ForwardingPackLine>().Single(o => o.JL_F3_NKPackType == "PLT");
				var packlineWithPackage2 = shipment.OuterPackLines.Cast<ForwardingPackLine>().Single(o => o.JL_F3_NKPackType == "CTN");

				var innerPackage1 = packlineWithPackage1.PkgPackageCollection[0];
				var innerPackage2 = packlineWithPackage2.PkgPackageCollection[0];
				AssertEquals(AdditionalScreeningMethods.Codes.PhysicalInspectionAndHandSearch, innerPackage1.ScreeningMethod);
				AssertEquals(AdditionalScreeningMethods.Codes.XRayEquipment, innerPackage1.AdditionalScreeningMethod);
				AssertEquals(ZString.Empty, innerPackage2.ScreeningMethod);
				AssertEquals(ZString.Empty, innerPackage2.AdditionalScreeningMethod);
				AssertEquals(0, innerPackage1.Screenings.Count);
				AssertEquals(0, innerPackage2.Screenings.Count);
			}
		}

