				packLine2.JL_InspectionTypeCode = AdditionalScreeningMethods.Codes.XRayEquipment;

				AssertEquals(2, shipment.OuterPackLines.Count);
				AssertEquals(AdditionalScreeningMethods.Codes.XRayEquipment, shipment.JS_InspectionTypeCode);
				Factory.Save();

				AssertEquals(1, shipment.Logs.GetAllLogsByEventOrderByPostedTimeUtcDESC(Events.SecurityModified).Count());
				Assert(shipment.JS_InspectionTypeCodeHasChanges);

				var newFactory = new BusinessObjectFactory();
				var reloadedShipment = newFactory.Load<ForwardingShipment>(shipment.PK);
				Assert(!reloadedShipment.JS_InspectionTypeCodeHasChanges);

				var packageScreening1 = Factory.New<PkgPackageScreening>();
				packageScreening1.KPS_GS_NKScreenedBy = "~BP";
				packageScreening1.KPS_Passed = true;
				packageScreening1.KPS_Method = AdditionalScreeningMethods.Codes.XRayEquipment;
				packageScreening1.KPS_Time = DateTimeOffset.Now;

				var packageScreening2 = Factory.New<PkgPackageScreening>();
				packageScreening2.KPS_GS_NKScreenedBy = "~BP";
				packageScreening2.KPS_Passed = true;
				packageScreening2.KPS_Method = AdditionalScreeningMethods.Codes.XRayEquipment;
				packageScreening2.KPS_Time = DateTimeOffset.Now;

				var packageScreening3 = Factory.New<PkgPackageScreening>();
				packageScreening3.KPS_GS_NKScreenedBy = "~BP";
				packageScreening3.KPS_Passed = true;
				packageScreening3.KPS_Method = AdditionalScreeningMethods.Codes.XRayEquipment;
				packageScreening3.KPS_Time = DateTimeOffset.Now;

				var packageJob = CreateTWPkgPackageJob("RC0001");
				var package1 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "package1", "CTN", 1, goodsDescription: "GD1", requiresTemperatureControl: false, screenings: new[] { packageScreening1 }, externalReference: "001");
				var package2 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "package2", "CTN", 1, goodsDescription: "GD2", requiresTemperatureControl: false, screenings: new[] { packageScreening2 }, externalReference: "002");
				var package3 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "package3", "CTN", 1, goodsDescription: "GD3", requiresTemperatureControl: false, screenings: new[] { packageScreening3 }, externalReference: "002");
				using (reloadedShipment.SuspendRedefaultingInspectionTypeCodes())
				{
					((ITransitWarehouseParent)reloadedShipment).AttachPackages(new ITransitPackage[] { package1, package2, package3 });
				}
				reloadedShipment.UpdateInspectionTypeFromPackLines();
				Assert(!reloadedShipment.JS_InspectionTypeCodeHasChanges);
				AssertEquals(5, reloadedShipment.OuterPackLines.Count);
				Assert(reloadedShipment.OuterPackLines.Cast<ForwardingPackLine>().All(p => p.JL_InspectionTypeCode == AdditionalScreeningMethods.Codes.XRayEquipment));
			}
		}

