		public void TestITransitWarehouseParent_AttachPackagesIncludesUNDGs()
		{
			var shipment = Factory.New<ForwardingShipment>();

			var packlineOnShipment = shipment.OuterPackLines.AddNew();
			packlineOnShipment.JL_RefNumber = "attachedShipment";
			packlineOnShipment.JL_F3_NKPackType = "ROL";
			packlineOnShipment.JL_Description = "UM";
			packlineOnShipment.JL_PackageCount = 4;
			packlineOnShipment.JL_RequiresTemperatureControl = true;
			packlineOnShipment.JL_RequiredTemperatureMinimum = 4m;
			packlineOnShipment.JL_RequiredTemperatureMaximum = 5m;
			packlineOnShipment.JL_RequiredTemperatureUnit = "C";
			packlineOnShipment.JL_MarksAndNumbers = "MNS";

			var undg3 = packlineOnShipment.UNDGs.AddNew();
			var subs = Factory.New<UNDGSubstance>();
			subs.DG_Code = "0005";
			subs.DG_Standard = UNDGSubstanceLookups.UNDGSubstanceStandardTypes.IMO;
			undg3.DI_DG = subs.PK;
			undg3.LinkDefault(subs);
			undg3.DI_IMOClass = "1.1E";
			undg3.DI_TechnicalName = "CARTRIDGES FOR WEAPONS";

			var undg1 = Factory.NewWithValidTestData<UNDGDataItem>();
			var subs2 = Factory.New<UNDGSubstance>();
			subs2.DG_Code = "0037";
			subs2.DG_Standard = UNDGSubstanceLookups.UNDGSubstanceStandardTypes.IMO;
			undg1.DI_DG = subs2.PK;
			undg1.LinkDefault(subs2);
			undg1.DI_IMOClass = "1.1F";
			undg1.DI_TechnicalName = "BOMBS, PHOTO-FLASH";

			var undg2 = Factory.NewWithValidTestData<UNDGDataItem>();
			var subs3 = Factory.New<UNDGSubstance>();
			subs3.DG_Code = "0027b";
			subs3.DG_Standard = UNDGSubstanceLookups.UNDGSubstanceStandardTypes.IMO;
			undg2.DI_DG = subs3.PK;
			undg2.LinkDefault(subs3);
			undg2.DI_IMOClass = "1.1D";
			undg2.DI_TechnicalName = "GUNPOWDER";

			AssertEquals(1, shipment.OuterPackLines.Count);

			var packageJob = CreateTWPkgPackageJob("RC0001");
			var package1 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "package1", "PLT", 1, goodsDescription: "GD", requiresTemperatureControl: false, requiredTemperatureMaximum: 6, requiredTemperatureMinimum: 6, requiredTemperatureUnit: "C");
			var package2 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "", "CTN", 2, goodsDescription: "GD1", requiresTemperatureControl: false, undgs: new[] { undg1, undg2 });
			((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { package1, package2 });

			AssertEquals(3, shipment.OuterPackLines.Count);
			var packlineWithAttachedPackage = shipment.OuterPackLines.Cast<ForwardingPackLine>().Single(o => o.JL_PackageCount == 4);
			var packlineWithPackage1 = shipment.OuterPackLines.Cast<ForwardingPackLine>().Single(o => o.JL_PackageCount == 1);
			var packlineWithPackage2 = shipment.OuterPackLines.Cast<ForwardingPackLine>().Single(o => o.JL_PackageCount == 2);

			AssertEquals("packlineWithPackage1 should not have any UNDGs", 0, packlineWithPackage1.UNDGs.Count);

			var packlineWithPackage2_undg1 = packlineWithPackage2.UNDGs.Cast<UNDGDataItem>().Single(o => o.SubstanceCode == "0037");
			var packlineWithPackage2_undg2 = packlineWithPackage2.UNDGs.Cast<UNDGDataItem>().Single(o => o.SubstanceCode == "0027b");
			AssertEquals("0037", packlineWithPackage2_undg1.SubstanceCode);
			AssertEquals("BOMBS, PHOTO-FLASH", packlineWithPackage2_undg1.DI_TechnicalName);
			AssertEquals("1.1F", packlineWithPackage2_undg1.DI_IMOClass);
			AssertEquals("0027b", packlineWithPackage2_undg2.SubstanceCode);
			AssertEquals("GUNPOWDER", packlineWithPackage2_undg2.DI_TechnicalName);
			AssertEquals("1.1D", packlineWithPackage2_undg2.DI_IMOClass);

			var packlineWithAttachedPackage_undg3 = packlineOnShipment.UNDGs[0];
			AssertEquals("0005", packlineWithAttachedPackage_undg3.SubstanceCode);
			AssertEquals("CARTRIDGES FOR WEAPONS", packlineWithAttachedPackage_undg3.DI_TechnicalName);
			AssertEquals("1.1E", packlineWithAttachedPackage_undg3.DI_IMOClass);
		}

		public void TestITransitWarehouseParent_AttachPackagesIncludesRCN_FR()
		{
			var shipment = Factory.New<ForwardingShipment>();
			var exportDepot = Factory.NewWithValidTestData<OrgHeader>();
			exportDepot.MainAddress.OA_RN_NKCountryCode = Core.Constants.CountryCodes.France;
			shipment.JS_OA_ExportReceivingDepot = exportDepot.MainAddress.PK;

			var packlineOnShipment = shipment.OuterPackLines.AddNew();
			packlineOnShipment.JL_RefNumber = "attachedShipment";
			packlineOnShipment.JL_F3_NKPackType = "ROL";
			packlineOnShipment.JL_Description = "UM";
			packlineOnShipment.JL_PackageCount = 4;
			packlineOnShipment.JL_RequiresTemperatureControl = true;
			packlineOnShipment.JL_RequiredTemperatureMinimum = 4m;
			packlineOnShipment.JL_RequiredTemperatureMaximum = 5m;
			packlineOnShipment.JL_RequiredTemperatureUnit = "C";
			packlineOnShipment.JL_MarksAndNumbers = "MNS";

			AssertEquals(1, shipment.OuterPackLines.Count);

			var packageJob1 = CreateTWPkgPackageJob("RC0001");
			var package1 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob1, "package1", "PLT", 1, goodsDescription: "GD", requiresTemperatureControl: false, requiredTemperatureMaximum: 6, requiredTemperatureMinimum: 6, requiredTemperatureUnit: "C");
			package1.Numbers = new CusEntryNumber[] { CreatePANCusEntryNumber("PAN0001", Constants.CountryCodes.France, "CLR") };

			var packageJob2 = CreateTWPkgPackageJob("RC0002");
			var package2 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob2, "package2", "PLT", 1, goodsDescription: "GD", requiresTemperatureControl: false, requiredTemperatureMaximum: 6, requiredTemperatureMinimum: 6, requiredTemperatureUnit: "C");
			package2.Numbers = new CusEntryNumber[] { CreatePANCusEntryNumber("DEA0002", Constants.CountryCodes.Germany, "HLD") };

			((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { package1, package2 });

			AssertEquals(3, shipment.OuterPackLines.Count);
			AssertContainsExactElementsInAnyOrder("JL_ExportRefNumber is populated from PAN only for FR", new[] { string.Empty, string.Empty, "PAN0001" }, shipment.OuterPackLines.Cast<ForwardingPackLine>().Select(p => p.JL_ExportRefNumber));

			AssertContainsExactElementsInAnyOrder("ERC is populated from RCN", new[] { string.Empty, "ERC: RC0001/FR", "ERC: RC0002/FR" }, shipment.OuterPackLines.Cast<ForwardingPackLine>().Select(p => p.AdditionalReferenceNumbers.AllNumbersAsString));

			AssertContainsExactElementsInAnyOrder("PAN is from PAN number", new[] { string.Empty, "PAN: PAN0001/FR/PRT/CLR", "PAN: DEA0002/DE/PRT/HLD" }, shipment.OuterPackLines.Cast<ForwardingPackLine>().Select(p =>
			string.Join(", ", p.PortReferences.Cast<CusEntryNumber>().Select(c => $"{c.CE_EntryType}: {c.CE_EntryNum}/{c.CE_RN_NKCountryCode}/{c.CE_Category}/{c.CE_EntryStatus}"))));
		}

		public void TestITransitWarehouseParent_AttachPackages_PopulatePAN_UsePEN() => TestITransitWarehouseParent_AttachPackages_PopulatePANCore(hasPEN: true);

		public void TestITransitWarehouseParent_AttachPackages_PopulatePAN_UsePAN() => TestITransitWarehouseParent_AttachPackages_PopulatePANCore(hasPEN: false);

		void TestITransitWarehouseParent_AttachPackages_PopulatePANCore(bool hasPEN)
		{
			var shipment = Factory.New<ForwardingShipment>();
			var exportDepot = Factory.NewWithValidTestData<OrgHeader>();
			exportDepot.MainAddress.OA_RN_NKCountryCode = Core.Constants.CountryCodes.France;
			shipment.JS_OA_ExportReceivingDepot = exportDepot.MainAddress.PK;

			var packlineOnShipment = shipment.OuterPackLines.AddNew();
			packlineOnShipment.JL_RefNumber = "attachedShipment";
			packlineOnShipment.JL_F3_NKPackType = "ROL";
			packlineOnShipment.JL_Description = "UM";
			packlineOnShipment.JL_PackageCount = 4;
			packlineOnShipment.JL_RequiresTemperatureControl = true;
			packlineOnShipment.JL_RequiredTemperatureMinimum = 4m;
			packlineOnShipment.JL_RequiredTemperatureMaximum = 5m;
			packlineOnShipment.JL_RequiredTemperatureUnit = "C";
			packlineOnShipment.JL_MarksAndNumbers = "MNS";

			AssertEquals(1, shipment.OuterPackLines.Count);

			var packageJob1 = CreateTWPkgPackageJob("RC0001");
			var package = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob1, "package1", "PLT", 1, goodsDescription: "GD", requiresTemperatureControl: false, requiredTemperatureMaximum: 6, requiredTemperatureMinimum: 6, requiredTemperatureUnit: "C");

			if (hasPEN)
			{
				var portReference = CreatePANCusEntryNumber("BBE001", Constants.CountryCodes.France, "CLR");
				portReference.CE_EntryType = ForwardingPackingLineAdditionalReferenceNumberTypes.Codes.PEN;
				package.Numbers = new CusEntryNumber[] { portReference };
			}
			else
			{
				package.Numbers = new CusEntryNumber[] { CreatePANCusEntryNumber("BBE002", Constants.CountryCodes.France, "CLR") };
			}

			((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { package });
			AssertEquals(2, shipment.OuterPackLines.Count);
			var expectedReferenceNumber = hasPEN ? "BBE001" : "BBE002";
			AssertContainsExactElementsInAnyOrder("PAN is from PAN number", new[] { string.Empty, $"PAN: {expectedReferenceNumber}/FR/PRT/CLR" }, shipment.OuterPackLines.Cast<ForwardingPackLine>().Select(p =>
			string.Join(", ", p.PortReferences.Cast<CusEntryNumber>().Select(c => $"{c.CE_EntryType}: {c.CE_EntryNum}/{c.CE_RN_NKCountryCode}/{c.CE_Category}/{c.CE_EntryStatus}"))));
		}

		CusEntryNumber CreatePANCusEntryNumber(ZString number, ZString countryCode, ZString status)
		{
			var panNumber = Factory.New<CusEntryNumber>();
			panNumber.CE_EntryNum = number;
			panNumber.CE_EntryType = ForwardingPackingLineAdditionalReferenceNumberTypes.Codes.PAN;
			panNumber.CE_RN_NKCountryCode = countryCode;
			panNumber.CE_EntryStatus = status;

			return panNumber;
		}

