		public void TestITransitWarehouseParent_CanAttachPackages()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			foreach (var shipmentTypeCode in shipment.Lookups.JS_ShipmentType_List.GetAllCodes())
			{
				shipment.JS_ShipmentType = shipmentTypeCode;
				var canAttachPackages = (shipment as ITransitWarehouseParent).CanAttachPackages(out ZString errorMessage);
				if (shipmentTypeCode == Constants.ShipmentTypes.CoLoadMaster || shipmentTypeCode == Constants.ShipmentTypes.BlindCoLoadMaster || shipmentTypeCode == Constants.ShipmentTypes.AssemblyMaster)
				{
					Assert(!canAttachPackages);
					AssertEquals("Attaching blind packages to master shipments is not allowed.", errorMessage);
				}
				else
				{
					Assert(canAttachPackages);
					AssertEquals(ZString.Empty, errorMessage);
				}
			}
		}

		public void TestITransitWarehouseParent_CanAttachPackages_NotReceivedPackLines()
		{
			var expectedError = "Blind packages cannot be attached to a shipment when existing pack lines have not been received in Transit Warehouse.";
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			var canAttachPackages = (shipment as ITransitWarehouseParent).CanAttachPackages(out ZString errorMessage);
			Assert(canAttachPackages);
			AssertEquals(ZString.Empty, errorMessage);

			var packLine = shipment.OuterPackLines.AddNew();
			canAttachPackages = (shipment as ITransitWarehouseParent).CanAttachPackages(out errorMessage);
			Assert(!canAttachPackages);
			AssertEquals(expectedError, errorMessage);

			packLine.JL_LastKnownTransitWarehouseStatus = FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Received;
			canAttachPackages = (shipment as ITransitWarehouseParent).CanAttachPackages(out errorMessage);
			Assert(canAttachPackages);
			AssertEquals(ZString.Empty, errorMessage);

			packLine.JL_LastKnownTransitWarehouseStatus = FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Dispatched;
			canAttachPackages = (shipment as ITransitWarehouseParent).CanAttachPackages(out errorMessage);
			Assert(!canAttachPackages);
			AssertEquals(expectedError, errorMessage);
		}

		public void TestITransitWarehouseParent_CanDetachPackages()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;

			var packLine = shipment.OuterPackLines.AddNew();
			var canDetachPackages = (shipment as ITransitWarehouseParent).CanDetachPackages(out ZString errorMessage);
			Assert(canDetachPackages);
			AssertEquals(ZString.Empty, errorMessage);

			packLine.JL_LastKnownTransitWarehouseStatus = FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Received;
			canDetachPackages = (shipment as ITransitWarehouseParent).CanDetachPackages(out errorMessage);
			Assert(canDetachPackages);
			AssertEquals(ZString.Empty, errorMessage);

			packLine.JL_LastKnownTransitWarehouseStatus = FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Dispatched;
			canDetachPackages = (shipment as ITransitWarehouseParent).CanDetachPackages(out errorMessage);
			Assert(!canDetachPackages);
			AssertEquals("Packages cannot be detached when existing pack lines have been dispatched from Transit Warehouse.", errorMessage);
		}

		[TestDate(2021, 1, 1)]
		public void TestITransitWarehouseParent_AttachPackages_PackageState()
		{
			var shipment = Factory.New<ForwardingShipment>();
			var packageJob = CreateTWPkgPackageJob("RC0001");
			var package = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "package1", "PLT", 1, volumn: 1.1m, weight: 10.1m);
			package.IsHighRisk = true;

			var latestScreening = package.Package.Screenings.AddNew();
			latestScreening.KPS_GS_NKScreenedBy = GlbStaff.CurrentUser?.GS_Code ?? ZString.Empty;
			latestScreening.KPS_Time = DateTimeOffset.Now;
			latestScreening.KPS_Method = "VCK";
			latestScreening.KPS_Passed = true;

			var lastSecondScreening = package.Package.Screenings.AddNew();
			lastSecondScreening.KPS_GS_NKScreenedBy = GlbStaff.CurrentUser?.GS_Code ?? ZString.Empty;
			lastSecondScreening.KPS_Time = DateTimeOffset.Now.AddDays(-1);
			lastSecondScreening.KPS_Method = "XRY";
			lastSecondScreening.KPS_Passed = true;
			Factory.Save();
			((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { package });
			var packline = shipment.OuterPackLines[0];
			AssertEquals("Packline has PkgPackage attached", 1, packline.PkgPackageCollection.Count);
