		public void TestITransitWarehouseParent_RemovePackages()
		{
			var shipment = Factory.New<ForwardingShipment>();
			var packageJob = CreateTWPkgPackageJob("RC0001");
			var package1 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "package1", isDamaged: true);
			var package2 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "package2");

			((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { package1, package2 });
			Factory.Save();
			AssertEquals("precondition: 1 packline", 1, shipment.OuterPackLines.Count);
			var packline = shipment.OuterPackLines.Cast<ForwardingPackLine>().ElementAt(0);
			AssertEquals(1, packline.JL_Damaged);
			var pkgPackageCollection = shipment.OuterPackLines.Cast<ForwardingPackLine>().ElementAt(0).PkgPackageCollection;
			AssertEquals("precondition: 2 packages", 2, pkgPackageCollection.Count);
			var package1PK = pkgPackageCollection.ElementAt(0).PK;
			var package2PK = pkgPackageCollection.ElementAt(1).PK;

			((ITransitWarehouseParent)shipment).RemovePackages(new ITransitPackage[] { package1 });
			Assert("shipment has changes because package1 was deleted", shipment.HasChanges);
			Factory.Save();
			AssertEquals(1, shipment.OuterPackLines.Count);
			CombineAssertions("package1 was deleted", () =>
			{
				AssertEquals(1, packline.PkgPackageCollection.Count);
				AssertEquals((ZString)"package2", packline.PkgPackageCollection.ElementAt(0).KP_PackageID);
				AssertNull(Factory.LoadTop1<PkgPackage>(new ZQuery(PkgPackageSchema.PK, package1PK)));
				AssertEquals(0, packline.JL_Damaged);
			});

			shipment.HasChanges = false;
			Assert(!shipment.HasChanges);
			((ITransitWarehouseParent)shipment).RemovePackages(new ITransitPackage[] { package1 });
			Assert("nothing was removed, so HasChanges should be false", !shipment.HasChanges);
			Factory.Save();

			((ITransitWarehouseParent)shipment).RemovePackages(new ITransitPackage[] { package2 });
			Assert("shipment has changes because package2 was deleted", shipment.HasChanges);
			Factory.Save();
			AssertEquals("packline was removed", 0, shipment.OuterPackLines.Count);
			AssertNull("package2 was removed", Factory.LoadTop1<PkgPackage>(new ZQuery(PkgPackageSchema.PK, package2PK)));
		}

		public void TestITransitWarehouseParent_RemovePackagesForLinking()
		{
			using (FreightConfigurationRegistry.Instance.EnableTWPackageLinking.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var shipment = Factory.New<ForwardingShipment>();

				var packageJob = CreateTWPkgPackageJob("RC0001");
				var package1 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "package1", isDamaged: true);
				var package2 = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, "package2");

				((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { package1, package2 });
				Factory.Save();
				AssertEquals("precondition: 1 packline", 1, shipment.OuterPackLines.Count);
				var packline = shipment.OuterPackLines.Cast<ForwardingPackLine>().ElementAt(0);
				var pkgPackageCollection = shipment.OuterPackLines.Cast<ForwardingPackLine>().ElementAt(0).PkgPackageCollection;
				AssertEquals(1, packline.JL_Damaged);
				AssertEquals("precondition: 2 packages", 2, pkgPackageCollection.Count);
				var package1PK = pkgPackageCollection.ElementAt(0).PK;
				var package2PK = pkgPackageCollection.ElementAt(1).PK;

				((ITransitWarehouseParent)shipment).RemovePackages(new ITransitPackage[] { package1 });
				Assert("shipment has changes because package1 was deleted", shipment.HasChanges);
				Factory.Save();
				AssertEquals(1, shipment.OuterPackLines.Count);
				CombineAssertions("package1 was deleted", () =>
				{
					AssertEquals(1, packline.PkgPackageCollection.Count);
					AssertEquals((ZString)"package2", packline.PkgPackageCollection.ElementAt(0).KP_PackageID);
					AssertNotNull(Factory.LoadTop1<PkgPackage>(new ZQuery(PkgPackageSchema.PK, package1PK)));
					AssertEquals(0, packline.JL_Damaged);
				});

				shipment.HasChanges = false;
				Assert(!shipment.HasChanges);
				((ITransitWarehouseParent)shipment).RemovePackages(new ITransitPackage[] { package1 });
				Assert("nothing was removed, so HasChanges should be false", !shipment.HasChanges);
				Factory.Save();

				((ITransitWarehouseParent)shipment).RemovePackages(new ITransitPackage[] { package2 });
				Assert("shipment has changes because package2 was deleted", shipment.HasChanges);
				Factory.Save();
				AssertEquals("packline was removed", 0, shipment.OuterPackLines.Count);
				AssertNotNull("package2 was removed", Factory.LoadTop1<PkgPackage>(new ZQuery(PkgPackageSchema.PK, package2PK)));

				var shipmentPackageJob = Factory.New<PkgPackageJob>();
				shipmentPackageJob.KJ_JobID = "RC0002";
				shipmentPackageJob.KJ_ParentID = shipment.PK;
				shipmentPackageJob.KJ_ParentTableCode = shipment.TablePrefix;
				var packLine3 = shipment.OuterPackLines.AddNew();
				var package31 = packLine3.PkgPackageCollection.AddNew();
				package31.KP_F3_NKPackType = "PLT";
				package31.KP_PackageQty = 1;
				package31.KP_KJ_ParentPackageJob = shipmentPackageJob.PK;
				package31.KP_PackageID = "PKG1";
				var package32 = packLine3.PkgPackageCollection.AddNew();
				package32.KP_F3_NKPackType = "PLT";
				package32.KP_PackageQty = 1;
				package32.KP_KJ_ParentPackageJob = shipmentPackageJob.PK;
				package32.KP_PackageID = "PKG2";
				packLine3.JL_F3_NKPackType = "PLT";
				packLine3.JL_PackageCount = 2;
				Factory.Save();

				var shipmentPackageJobPK = shipmentPackageJob.PK;
				var package31PK = package31.PK;
				var package32PK = package32.PK;

				((ITransitWarehouseParent)shipment).RemovePackages(new ITransitPackage[] { new ReadOnlyPackageForLink(package31) });
				Assert("shipment has changes because package31 was deleted", shipment.HasChanges);
				Factory.Save();
				AssertEquals("packline was not removed", 1, shipment.OuterPackLines.Count);
				AssertNull("package31 was removed", Factory.LoadTop1<PkgPackage>(new ZQuery(PkgPackageSchema.PK, package31PK)));
				AssertNotNull("package job for package31 was not removed", Factory.LoadTop1<PkgPackageJob>(new ZQuery(PkgPackageJobSchema.PK, shipmentPackageJobPK)));

				((ITransitWarehouseParent)shipment).RemovePackages(new ITransitPackage[] { new ReadOnlyPackageForLink(package32) });
				Assert("shipment has changes because package32 was deleted", shipment.HasChanges);
				Factory.Save();
				AssertEquals("packline was removed", 0, shipment.OuterPackLines.Count);
				AssertNull("package32 was removed", Factory.LoadTop1<PkgPackage>(new ZQuery(PkgPackageSchema.PK, package32PK)));
				AssertNull("package job for package32 was not removed", Factory.LoadTop1<PkgPackageJob>(new ZQuery(PkgPackageJobSchema.PK, shipmentPackageJobPK)));
			}
		}

