			var shipment = Factory.New<ForwardingShipment>();
			AssertEquals("Precondition: shipment.HasChanges", false, shipment.HasChanges);
			((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { overpack1 });
			AssertEquals("Only one packline added", 1, shipment.OuterPackLines.Count);
			AssertEquals("Only one package exists", 1, shipment.OuterPackLines.Cast<ForwardingPackLine>().First().PkgPackageCollection.Count);
