		public void TestITransitWarehouseParent_RemovePacklines()
		{
			var packageJob = CreateTWPkgPackageJob("RC0001");
			var shipment = Factory.New<ForwardingShipment>();
			var packlineFromTWH = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, string.Empty, packageQty: 10, unitType: "PKL", externalReference: "PKL1");
			var packageWithoutID = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, string.Empty, packageQty: 1, unitType: "PKG", externalReference: "PKG1");

			((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { packlineFromTWH, packageWithoutID });
			Factory.Save();
			AssertEquals("precondition: 2 packlines", 2, shipment.OuterPackLines.Count);
			var packlines = shipment.OuterPackLines.Cast<ForwardingPackLine>();
			var pkgPackageCollection1 = packlines.First(p => p.JL_PackLineId == "PKL1").PkgPackageCollection;
			AssertEquals("precondition: 1 package", 1, pkgPackageCollection1.Count);
			var pkgPackageCollection2 = packlines.First(p => p.JL_PackLineId == "PKG1").PkgPackageCollection;
			AssertEquals("precondition: 1 package", 1, pkgPackageCollection2.Count);
			var packlineFromTWHPK = pkgPackageCollection1.First().PK;
			var packageWithoutIDPK = pkgPackageCollection2.First().PK;

			((ITransitWarehouseParent)shipment).RemovePackages(new ITransitPackage[] { packlineFromTWH });
			Assert("shipment has changes because package1 was deleted", shipment.HasChanges);
			Factory.Save();
			AssertEquals(1, shipment.OuterPackLines.Count);
			CombineAssertions("package1 was deleted", () =>
			{
				AssertEquals(1, packlines.Count());
				AssertEquals((ZString)"PKG1", packlines.First().PkgPackageCollection.First().KP_ExternalReference);
				AssertNull(Factory.LoadTop1<PkgPackage>(new ZQuery(PkgPackageSchema.PK, packlineFromTWHPK)));
			});

			shipment.HasChanges = false;
			Assert(!shipment.HasChanges);
			((ITransitWarehouseParent)shipment).RemovePackages(new ITransitPackage[] { packlineFromTWH });
			Assert("nothing was removed, so HasChanges should be false", !shipment.HasChanges);
			Factory.Save();

			((ITransitWarehouseParent)shipment).RemovePackages(new ITransitPackage[] { packageWithoutID });
			Assert("shipment has changes because package2 was deleted", shipment.HasChanges);
			Factory.Save();
			AssertEquals("packline was removed", 0, shipment.OuterPackLines.Count);
			AssertNull("package2 was removed", Factory.LoadTop1<PkgPackage>(new ZQuery(PkgPackageSchema.PK, packageWithoutIDPK)));
		}

