		public void TestITransitWarehouseParent_AttachPacklines_ThenRemovePackageFromPacklinePkgPackageCollection_OnSaving()
		{
			var shipment = Factory.New<ForwardingShipment>();
			AssertEquals("Pre-condition", 0, shipment.OuterPackLines.Count);

			var packageJob = CreateTWPkgPackageJob("RC0001");
			var packLine = ReadOnlyPackageForLink.CreatePkgPackageSample(packageJob, string.Empty, "PLT", 10, unitType: "PKL", externalReference: "PKL1");
			((ITransitWarehouseParent)shipment).AttachPackages(new ITransitPackage[] { packLine });
			AssertEquals("Outer packline is created", 1, shipment.OuterPackLines.Count);
			var outterPackline = shipment.OuterPackLines[0];
			Assert(outterPackline.BlindPackageAttached);

			var package1 = outterPackline.PkgPackageCollection.AddNew();
			package1.KP_F3_NKPackType = "PLT";
			package1.KP_PackageQty = 1;
			package1.KP_KJ_ParentPackageJob = packageJob.PK;
			package1.KP_PackageID = "PKG1";
			var package2 = outterPackline.PkgPackageCollection.AddNew();
			package2.KP_F3_NKPackType = "PLT";
			package2.KP_PackageQty = 1;
			package2.KP_KJ_ParentPackageJob = packageJob.PK;
			package2.KP_PackageID = "PKG2";
			Factory.Save();

			AssertEquals("Outer packline should have 3 packages", 3, outterPackline.PkgPackageCollection.Count);
			AssertEquals(true, shipment.RequireSendingPrepareDispatchTWInstructionForBlindPackages);

			var anotherFactory = new BusinessObjectFactory();
			var shipmentInAnotherFactory = anotherFactory.Load<ForwardingShipment>(shipment.PK);
			shipmentInAnotherFactory.JS_ActualVolume = 20;

			((ITransitWarehouseParent)shipmentInAnotherFactory).RemovePackages(new ITransitPackage[] { new ReadOnlyPackageForLink(package1) });

			AssertEquals("Outer packline should have 2 packages", 2, shipmentInAnotherFactory.OuterPackLines[0].PkgPackageCollection.Count);
			AssertEquals("Outer packline is not removed", 1, shipmentInAnotherFactory.OuterPackLines.Count);
			anotherFactory.Save();
			AssertEquals(true, shipmentInAnotherFactory.RequireSendingPrepareDispatchTWInstructionForBlindPackages);
			AssertEquals(TransitWarehouseInstructionHelper.Direction.Pickup, shipmentInAnotherFactory.PrepareDispatchTWInstructionForBlindPackagesDirection);
		}

