			AssertOrderAndExpectedDepotAddress(2, importDepotOnConsol.MainAddress, listOfCFSsWithShipmentImportCFS);
			AssertOrderAndExpectedDepotAddress(3, importDepotOnShipment.MainAddress, listOfCFSsWithShipmentImportCFS);

			shipment.JS_OA_ExportReceivingDepot = exportDepotOnShipment.MainAddress.PK;
			var listOfCFSsWithShipmentExportCFS = transitParent.GetOrderedCFSOrgAddressPKs();
			AssertEquals(4, listOfCFSsWithShipmentExportCFS.Count);
