			AssertOrderAndExpectedDepotAddress(2, exportDepotOnConsol.MainAddress, listOfCFSsWithShipmentExportCFS);
			AssertOrderAndExpectedDepotAddress(3, importDepotOnConsol.MainAddress, listOfCFSsWithShipmentExportCFS);
			AssertOrderAndExpectedDepotAddress(4, importDepotOnShipment.MainAddress, listOfCFSsWithShipmentExportCFS);
		}

