			AssertCollectionContains(importDepotOnConsol3.MainAddress.PK, orgAddresses);
			AssertCollectionContains(exportDepotOnConsol2.MainAddress.PK, orgAddresses);
			AssertCollectionContains(importDepotOnConsol2.MainAddress.PK, orgAddresses);
