		public void TestForwardingShipmentDoesNotImplementISupportMultipleResourceStringData()
		{
			const string assertionMessage =
				$"ForwardingShipment must not implement {nameof(ISupportMultipleResourceStringData)}.\r\n" +
				$"If you need to provide {nameof(ISupportMultipleResourceStringData.MultipleKeysToUse)} for a PlugIn, let the top-level control of the PlugIn itself to implement it.\r\n" +
				$"This ensures that the {nameof(ISupportMultipleResourceStringData.MultipleKeysToUse)} for a specific context do not interfere with those of another context.";

			var forwardingShipment = Factory.New<ForwardingShipment>();
			if (forwardingShipment is ISupportMultipleResourceStringData)
