		public void TestShippingLineOrgCodeFallbackToBookedShippingLine()
		{
			var shipment = Factory.New<ForwardingShipment>();

			AssertEquals(ZGuid.Empty, shipment.BookedShippingLinePK);
			Assert(shipment.Consols.OfType<ForwardingConsol>().All(x => x.ShippingLinePK.IsEmpty));
			AssertEquals(ZString.Empty, shipment.ShippingLineOrgCodeFallbackToBookedShippingLine);

			var shipmentOrgHeader = Factory.NewWithValidTestData<OrgHeader>();
			var consolOrgAddress = Factory.NewWithValidTestData<OrgAddress>();

			shipment.BookedShippingLinePK = shipmentOrgHeader.PK;
			Factory.Save();

			AssertEquals(shipmentOrgHeader.PK, shipment.BookedShippingLinePK);
			Assert(shipment.Consols.OfType<ForwardingConsol>().All(x => x.ShippingLinePK.IsEmpty));
			AssertEquals("Fallback to BookedShippingLine when no consols attached", shipmentOrgHeader.OH_Code, shipment.ShippingLineOrgCodeFallbackToBookedShippingLine);

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.JK_MasterBillNum = "MASTERBILL";
			consol.JK_TransportMode = Core.Constants.TransportModes.Sea;
			consol.JK_OA_ShippingLineAddress = ZGuid.Empty;

			shipment.Consols.Add(consol);
			Factory.Save();

			AssertEquals(shipmentOrgHeader.PK, shipment.BookedShippingLinePK);
			Assert(shipment.Consols.OfType<ForwardingConsol>().All(x => x.ShippingLinePK.IsEmpty));
			AssertEquals("Fallback to BookedShippingLine when consol attached does not have ShippingLine", shipmentOrgHeader.OH_Code, shipment.ShippingLineOrgCodeFallbackToBookedShippingLine);

			consol.JK_OA_ShippingLineAddress = consolOrgAddress.PK;
			Factory.Save();

			AssertEquals(shipmentOrgHeader.PK, shipment.BookedShippingLinePK);
			Assert(shipment.Consols.OfType<ForwardingConsol>().Any(x => !x.ShippingLinePK.IsEmpty));
			AssertEquals(consolOrgAddress.Header.OH_Code, shipment.ShippingLineOrgCodeFallbackToBookedShippingLine);

			var consol2 = Factory.NewWithValidTestData<ForwardingConsol>();
			consol2.JK_MasterBillNum = "MASTERBILL2";
			consol2.JK_TransportMode = Core.Constants.TransportModes.Sea;
			consol2.JK_OA_ShippingLineAddress = consolOrgAddress.PK;

			shipment.Consols.Add(consol2);

			shipment.JS_RL_NKDestination = "AUSYD";
			consol.JK_RL_NKDischargePort = "AUSYD";
			consol2.JK_RL_NKDischargePort = "CNNJG";
			consol.JK_OA_ShippingLineAddress = ZGuid.Empty;
			Factory.Save();

			AssertEquals(ZString.Empty, shipment.ShippingLineOrgCodeFallbackToBookedShippingLine);
		}

