		public void TestRecalculateRelatedParties_ShouldSetDefaultValueForPickupDeliveryProperties()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.Namibia))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "AUSYD";
				shipment.JS_RL_NKDestination = "CNSHA";

				var result = shipment.RecalculateRelatedParties();
				Assert("When login company is not origin nor destination", !result.WasSuccessful);
				AssertEquals("When login company is not origin nor destination", "You cannot Recalculate Related Parties for this company because the company you are logged in does not match Pickup or Delivery directions of this job.", result.Log);

				shipment.JS_RL_NKOrigin = "NASWP";

				shipment.AttemptToUpdateExistingValueInRecalculation += Shipment_AttempToUpdateExistingValueInRecalculation;

				AssertProperty(shipment,
					value => shipment.ConsignorDocumentaryAddress.OrganisationPK = value,
					RelatedPartyTypeList.Codes.CustomsAgentBroker,
					RelatedPartyDirectionList.Codes.Pickup,
					"Export Broker",
					() => shipment.JS_OH_ExportBroker,
					value => shipment.JS_OH_ExportBroker = value);

				shipment.JS_OH_ExportBroker = ZGuid.Empty;

				AssertProperty(shipment,
					value => shipment.ConsignorDocumentaryAddress.OrganisationPK = value,
					RelatedPartyTypeList.Codes.LocalTransport,
					RelatedPartyDirectionList.Codes.Pickup,
					"Pickup Company",
					() => shipment.DocsAndCartage.JP_OA_PickupCartageCoAddr_ZAddress.OrgPK,
					value => shipment.DocsAndCartage.JP_OA_PickupCartageCoAddr_ZAddress.OrgPK = value);

				shipment.DocsAndCartage.JP_OA_PickupCartageCoAddr_ZAddress.OrgPK = ZGuid.Empty;

				AssertProperty(shipment,
					value => shipment.ConsignorDocumentaryAddress.OrganisationPK = value,
					RelatedPartyTypeList.Codes.PickupAgent,
					RelatedPartyDirectionList.Codes.Pickup,
					"Pickup Agent",
					() => shipment.PickupAgentDocumentaryAddress.OrganisationPK,
					value => shipment.PickupAgentDocumentaryAddress.OrganisationPK = value);

				shipment.PickupAgentDocumentaryAddress.OrganisationPK = ZGuid.Empty;

				AssertProperty(shipment,
					value => shipment.ConsignorDocumentaryAddress.OrganisationPK = value,
					RelatedPartyTypeList.Codes.ClientCFS,
					RelatedPartyDirectionList.Codes.Pickup,
					"Pickup CFS",
					() => shipment.ExportReceivingDepot.OA_OH,
					value => shipment.JS_OA_ExportReceivingDepot = value == ZGuid.Empty ? ZGuid.Empty : Factory.Load<OrgHeader>(value).MainAddress.PK);

				shipment.JS_RL_NKOrigin = "CNSHA";
				shipment.JS_RL_NKDestination = "NASWP";

				AssertProperty(shipment,
					value => shipment.ConsigneeDocumentaryAddress.OrganisationPK = value,
					RelatedPartyTypeList.Codes.CustomsAgentBroker,
					RelatedPartyDirectionList.Codes.Delivery,
					"Import Broker",
					() => shipment.JS_OH_ImportBroker,
					value => shipment.JS_OH_ImportBroker = value);

				shipment.JS_OH_ImportBroker = ZGuid.Empty;

				AssertProperty(shipment,
					value => shipment.ConsigneeDocumentaryAddress.OrganisationPK = value,
					RelatedPartyTypeList.Codes.LocalTransport,
					RelatedPartyDirectionList.Codes.Delivery,
					"Delivery Company",
					() => shipment.DocsAndCartage.JP_OA_DeliveryCartageCoAddr_ZAddress.OrgPK,
					value => shipment.DocsAndCartage.JP_OA_DeliveryCartageCoAddr_ZAddress.OrgPK = value);

				shipment.DocsAndCartage.JP_OA_DeliveryCartageCoAddr_ZAddress.OrgPK = ZGuid.Empty;

				AssertProperty(shipment,
					value => shipment.ConsigneeDocumentaryAddress.OrganisationPK = value,
					RelatedPartyTypeList.Codes.DeliveryAgent,
					RelatedPartyDirectionList.Codes.Delivery,
					"Delivery Agent",
					() => shipment.JS_OH_DeliveryAgent,
					value => shipment.JS_OH_DeliveryAgent = value);

				shipment.JS_OH_DeliveryAgent = ZGuid.Empty;

				AssertProperty(shipment,
					value => shipment.ConsigneeDocumentaryAddress.OrganisationPK = value,
					RelatedPartyTypeList.Codes.ClientCFS,
					RelatedPartyDirectionList.Codes.Delivery,
					"Delivery CFS",
					() => shipment.ImportReleaseDepot.OA_OH,
					value => shipment.JS_OA_ImportReleaseDepot = value == ZGuid.Empty ? ZGuid.Empty : Factory.Load<OrgHeader>(value).MainAddress.PK);
			}
		}

		void AssertProperty(ForwardingShipment shipment,
				Action<ZGuid> shipperConsigneeSetter,
				ZString partyType, ZString direction,
				string propertyName, Func<ZGuid> propertyGetter, Action<ZGuid> propertySetter)
		{
			var oldValue = Factory.NewWithValidTestData<OrgHeader>();
			var newValue = Factory.NewWithValidTestData<OrgHeader>();

			AddRelatedPartyAndAssignOrg(shipperConsigneeSetter, partyType, direction, newValue);

			propertySetter(oldValue.PK);

			attemptToUpdateEventRaised = false;
			attemptToUpdateUsersAnswer = true;
			var result = shipment.RecalculateRelatedParties();
			Assert("Attempt to update event should be raised", attemptToUpdateEventRaised);
			AssertEquals($"{propertyName} shouldn't be changed", oldValue.PK, propertyGetter());
			Assert("When login company is shipment's origin", result.WasSuccessful);
			AssertEquals("When login company is not origin nor destination", ZString.Empty, result.Log);

			attemptToUpdateEventRaised = false;
			attemptToUpdateUsersAnswer = false;
			result = shipment.RecalculateRelatedParties();
			Assert("Attempt to update event should be raised", attemptToUpdateEventRaised);
			AssertEquals($"{propertyName} should be changed", newValue.PK, propertyGetter());
			Assert("When login company is shipment's origin", result.WasSuccessful);
			AssertEquals("When login company is not origin nor destination", ZString.Empty, result.Log);

			propertySetter(ZGuid.Empty);
			attemptToUpdateEventRaised = false;
			attemptToUpdateUsersAnswer = false;
			result = shipment.RecalculateRelatedParties();
			Assert("Attempt to update event should not be raised", !attemptToUpdateEventRaised);
			AssertEquals($"{propertyName} should be changed", newValue.PK, propertyGetter());
			Assert("When login company is shipment's origin", result.WasSuccessful);
			AssertEquals("When login company is not origin nor destination", ZString.Empty, result.Log);
		}

		void AddRelatedPartyAndAssignOrg(
				Action<ZGuid> shipperConsigneeSetter,
				ZString partyType,
				ZString direction,
				OrgHeader newValue)
		{
			var org = Factory.NewWithValidTestData<OrgHeader>();
			org.AddRelatedParty(newValue.PK, partyType, direction, Constants.TransportModes.All, ZString.Empty, GlbCompany.CurrentCompany);
			shipperConsigneeSetter(org.PK);
		}

