		public void TestShouldNotUpdateCO2eStatusToNotCurrentWhenCopyingShipment()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Pending);
			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());

			var shipment2 = Factory.New<ForwardingShipment>();
			shipment2.JS_TransportMode = Constants.TransportModes.Sea;
			shipment2.JS_RL_NKOrigin = "JMKIN";
			shipment2.SetCO2eStatus(CO2eStatusList.Codes.Pending);

			((IBusinessObjectInternals)shipment2).IsCopying = true;
