		public void TestCO2eStatusWhenReversingShipment()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.SetCO2eStatus(CO2eStatusList.Codes.Pending);
			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "CNSHA";

			((IBusinessObjectInternals)shipment).IsCopying = false;
			AssertEquals(CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());

			((ITemplateReversible)shipment).Reverse();
			AssertEquals("shipment reversed", shipment.JS_RL_NKOrigin, "CNSHA");
			AssertEquals("shipment reversed", shipment.JS_RL_NKDestination, "AUSYD");
			AssertEquals("shipment reversed", CO2eStatusList.Codes.NotCurrent, shipment.GetCO2eStatus());

			var shipment2 = Factory.New<ForwardingShipment>();
			shipment2.JS_TransportMode = Constants.TransportModes.Sea;
			shipment2.SetCO2eStatus(CO2eStatusList.Codes.Pending);
			shipment2.JS_RL_NKOrigin = "AUSYD";
			shipment2.JS_RL_NKDestination = "CNSHA";

			((IBusinessObjectInternals)shipment2).IsCopying = true;
			((ITemplateReversible)shipment2).Reverse();

			AssertEquals("shipment reversed", shipment2.JS_RL_NKOrigin, "CNSHA");
			AssertEquals("shipment reversed", shipment2.JS_RL_NKDestination, "AUSYD");
			AssertEquals("shipment reversed", CO2eStatusList.Codes.NotCurrent, shipment2.GetCO2eStatus());
		}

