			using (FreightDataRegistry.Instance.CalculateDeliveryDueDateByTransportMode.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new CalculateDeliveryDueDateOptions { IsActive = true, TransportModes = ActiveTransportModesForCalculateDeliveryDateOption() }))
			{
				var shipment = DeliveryDueDateWithExceptionsTestHelper.CreateShipmentForTest(Factory, newDeliveryDueDate);
				var consol = shipment.Consols.AddNew();
				var container = consol.Containers.AddNew();
				Factory.Save();

				var trigger = shipment.WorkflowItems.Triggers.AddNew();
				trigger.P9_Description = "Trigger";
				trigger.TriggerConditions.TriggerEventCode = Events.CalculateDeliveryDateWithExceptionsRequested.Code;

				var action = trigger.ProcessTaskNotifications.AddNew();
				action.PQ_TriggerType = WorkflowTriggerActionTypeConstants.Codes.ImmediateFieldChange;
				action.PQ_FieldName = "<JS_RevisedDeliveryDueDate>";
				action.PQ_FieldValue = "<GetCalculatedDeliveryDueDateWithExceptions>";

				DeliveryDueDateWithExceptionsTestHelper.AddException(container, 12, "AOG");
				Factory.Save();
