				DeliveryDueDateWithExceptionsTestHelper.AddException(container, 12, "AOG");
				Factory.Save();
				AssertEquals("RDD is updated when shipment is packed", newDeliveryDueDate.AddHours(24), shipment.JS_RevisedDeliveryDueDate.ToZDateTime());
			}
		}

		public void TestCFSTransitWarehouseAddressNotMatchDeliveryZone()
		{
			var auZoneOwner = CreateTestTransportZoneSet("AUZONE", CountryCodes.Australia, "1000", "1999");
			var nzZoneOwner = CreateTestTransportZoneSet("NZZONE", CountryCodes.NewZealand, "2000", "2999");

			using (FreightDataRegistry.Instance.CalculateDeliveryDueDateByTransportMode.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new CalculateDeliveryDueDateOptions { IsActive = true, TransportModes = ActiveTransportModesForCalculateDeliveryDateOption() }))
			{
				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();

				var consignee = Factory.NewWithValidTestData<OrgHeader>();
				consignee.MainAddress.OA_RN_NKCountryCode = CountryCodes.Australia;
				consignee.MainAddress.OA_PostCode = "1001";

				var deliveryCFS = nzZoneOwner;
				deliveryCFS.MainAddress.OA_RN_NKCountryCode = CountryCodes.NewZealand;
				deliveryCFS.MainAddress.OA_PostCode = "2002";

				shipment.JS_TransportMode = Constants.TransportModes.Sea;
				shipment.ConsigneeDocumentaryAddress.OrganisationPK = consignee.PK;
				shipment.JS_OA_ImportReleaseDepot = deliveryCFS.MainAddress.PK;

				var warningMesage = "Pickup or Delivery CFS is not a Zone Owner. Zone Owner is configured in the Transport Zone Set applicable to the pickup/delivery postcode.";
				AssertEquals(true, shipment.JS_OA_ImportReleaseDepotInfo.HasWarning(warningMesage));

				deliveryCFS = auZoneOwner;
				deliveryCFS.MainAddress.OA_RN_NKCountryCode = CountryCodes.Australia;
				deliveryCFS.MainAddress.OA_PostCode = "1002";
				shipment.JS_OA_ImportReleaseDepot = deliveryCFS.MainAddress.PK;

				AssertEquals(false, shipment.JS_OA_ImportReleaseDepotInfo.HasWarning(warningMesage));

				shipment.JS_OA_ImportReleaseDepot = ZGuid.Empty;

				AssertEquals(false, shipment.JS_OA_ImportReleaseDepotInfo.HasWarning(warningMesage));
			}
		}

