				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
				var consignor = Factory.NewWithValidTestData<OrgHeader>();
				consignor.MainAddress.OA_RN_NKCountryCode = CountryCodes.Australia;
				consignor.MainAddress.OA_PostCode = "1001";

				var pickupCFS = nzZoneOwner;
				pickupCFS.MainAddress.OA_RN_NKCountryCode = CountryCodes.NewZealand;
				pickupCFS.MainAddress.OA_PostCode = "2001";

				shipment.JS_TransportMode = Constants.TransportModes.Sea;
				shipment.ConsignorDocumentaryAddress.OrganisationPK = consignor.PK;
				shipment.JS_OA_ExportReceivingDepot = pickupCFS.MainAddress.PK;

				var warningMesage = "Pickup or Delivery CFS is not a Zone Owner. Zone Owner is configured in the Transport Zone Set applicable to the pickup/delivery postcode.";
				AssertEquals(true, shipment.JS_OA_ExportReceivingDepotInfo.HasWarning(warningMesage));

				pickupCFS = auZoneOwner;
				pickupCFS.MainAddress.OA_RN_NKCountryCode = CountryCodes.Australia;
				pickupCFS.MainAddress.OA_PostCode = "1002";
				shipment.JS_OA_ExportReceivingDepot = pickupCFS.MainAddress.PK;

				AssertEquals(false, shipment.JS_OA_ExportReceivingDepotInfo.HasWarning(warningMesage));

				shipment.JS_OA_ExportReceivingDepot = ZGuid.Empty;

				AssertEquals(false, shipment.JS_OA_ExportReceivingDepotInfo.HasWarning(warningMesage));
			}
		}

		OrgHeader CreateTestTransportZoneSet(ZString orgCode, ZString countryCode, ZString fromPostCode, ZString toPostCode)
		{
			var zoneOwner = Factory.NewWithValidTestData<OrgHeader>();
			zoneOwner.OH_Code = orgCode;

			var zoneSet = Factory.NewWithValidTestData<RateTransportProvider>();
			zoneSet.TP_ZoneType = RatingConstants.RatingZoneTypes.All;
			zoneSet.TP_ZoneMode = RateMode.ALL;
			zoneSet.TP_RN_NKCountry = countryCode;
			zoneSet.TP_OH_RelatedParty = zoneOwner.PK;

			var zone = zoneSet.Zones.AddNew();
			zone.TZ_ZoneName = "Zone 1";
			var zoneItem = zone.Items.AddNew();
			zoneItem.TQ_FromPostCode = fromPostCode;
			zoneItem.TQ_ToPostCode = toPostCode;

			Factory.Save();

			return zoneOwner;
		}

		CalculateDeliveryDueDateTransportModeCollection ActiveTransportModesForCalculateDeliveryDateOption()
		{
			var activeTransportModes = new CalculateDeliveryDueDateTransportModeCollection();
			activeTransportModes.Add(Core.Constants.TransportModes.Air, Core.Constants.TransportModeDescriptions.Air, true);
			activeTransportModes.Add(Core.Constants.TransportModes.Sea, Core.Constants.TransportModeDescriptions.Sea, true);
			activeTransportModes.Add(Core.Constants.TransportModes.Road, Core.Constants.TransportModeDescriptions.Road, true);
			activeTransportModes.Add(Core.Constants.TransportModes.Rail, Core.Constants.TransportModeDescriptions.Rail, true);
			return activeTransportModes;
		}

