		[TestDate(2023, 11, 18)]
		public void TestDefaultPackLineInspectionTypeWhenShipmentInspectionTypeChangesFromAPP()
		{
			using (WarehouseDataRegistry.Instance.DriverSecurityCertificationCheckingActivated.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.Germany))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "DEHAM";
				shipment.JS_RL_NKDestination = "HKHKG";
				shipment.JS_TransportMode = "AIR";

				var warehouse = CreateWarehouse("WHS01");
				CreatePackLineWithTWStatus(shipment, warehouse.MainAddress.PK, FreightConstants.PacklineLastKnownTransitWarehouseStatus.Codes.Dispatched);

				AssertEquals(true, shipment.RequiresSecuredCargoFromWarehouse);

				var packLine1 = shipment.OuterPackLines.AddNew();
				packLine1.JL_InspectionTypeCode = "APP";
				var packLine2 = shipment.OuterPackLines.AddNew();
				packLine2.JL_InspectionTypeCode = "APP";
				shipment.JS_InspectionTypeCode = "APP";

				AssertEquals("pre-condition", "APP", packLine1.JL_InspectionTypeCode);
				AssertEquals("pre-condition", "APP", packLine2.JL_InspectionTypeCode);
				AssertEquals("pre-condition", "APP", shipment.JS_InspectionTypeCode);

				shipment.JS_InspectionTypeCode = "UNK";
				AssertEquals("UNK", packLine1.JL_InspectionTypeCode);
				AssertEquals("UNK", packLine2.JL_InspectionTypeCode);
			}
		}

