		#region Earliest Last Free Day

		public void TestEarliestLastFreeDay_Import_DetentionPenalties()
		{
			var date = new ZDateTime(2009, 1, 2, 3, 4, 6);
			var (detention, consol, container1, container2) = SetupImportCarrierDetentionOrDemurrage(ContainerDetentionPenaltyType.DET);
			var penalty1 = container1.ImportPenalties.AddNew();
			penalty1.CPY_PenaltyType = ContainerDetentionPenaltyType.DET;
			penalty1.CPY_CreditorType = ContainerPenaltyCreditorType.Codes.Carrier;

			var penalty2 = container2.ImportPenalties.AddNew();
			penalty2.CPY_PenaltyType = ContainerDetentionPenaltyType.DET;
			penalty2.CPY_CreditorType = ContainerPenaltyCreditorType.Codes.Carrier;

			AssertEquals("EarliestLastFreeDayImportDetentionForBinding", ZDateTime.Empty, consol.Shipments[0].EarliestLastFreeDayImportDetentionForBinding);

			container1.JC_EmptyReturnedBy = ZDateTime.Empty;
			container1.JC_FCLUnloadFromVessel = date.AddDays(-4);

			container2.JC_EmptyReturnedBy = ZDateTime.Empty;
			container2.JC_FCLUnloadFromVessel = date.AddDays(-3);

			detention.PD_FreeDays = 10;
			detention.PD_FreeDayType = ContainerDetentionFreeDayType.FCLUnload;
			Factory.Save();

			AssertEquals(penalty1.FirstFreeDay.AddDays(penalty1.FreeTimeAsDays - 1), penalty1.LastFreeDay);
			AssertEquals(penalty2.FirstFreeDay.AddDays(penalty2.FreeTimeAsDays - 1), penalty2.LastFreeDay);

			AssertEquals("EarliestLastFreeDayImportDetentionForBinding", new ZDateTime(2009, 1, 7, 3, 4, 6), consol.Shipments[0].EarliestLastFreeDayImportDetentionForBinding);
		}

