			AssertEquals(penalty1.FirstFreeDay.AddDays(penalty1.FreeTimeAsDays - 1), penalty1.LastFreeDay);
			AssertEquals(penalty2.FirstFreeDay.AddDays(penalty2.FreeTimeAsDays - 1), penalty2.LastFreeDay);

			AssertEquals("EarliestLastFreeDayExportDemurrageForBinding", new ZDateTime(2009, 1, 1, 3, 4, 6), consol.Shipments[0].EarliestLastFreeDayExportDemurrageForBinding);
		}

		(OrgContainerDetention detention, ForwardingConsol consol, ForwardingContainer container1, ForwardingContainer container2) SetupImportCarrierDetentionOrDemurrage(string penaltyType)
		{
			var consol = SetupConsolForPenalties();
			var consignee = consol.Shipments[0].Consignee;
			var container1 = consol.Containers[0];
			var container2 = consol.Containers[1];

			var detention1 = consignee.ConsigneeContainerPenalties.AddNew();
