			detention1.PD_FreeDays = 3;
			detention1.PD_CreditorType = "CAR";
			detention1.PD_DetentionPortOrCountry = "USLAX";
			detention1.PD_OH_Carrier = consol.ShippingLinePK;

			return (detention1, consol, container1, container2);
		}

