		#region TestJS_Calc_ElectronicBillOfLadingDate

		public void TestJS_Calc_ElectronicBillOfLadingDate()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			shipment.JS_ElectronicBillOfLadingReference = "BOL123";
			Factory.Save();

			AssertEquals(ZDate.Empty, shipment.JS_Calc_ElectronicBillOfLadingDate);

			var documentData = Factory.NewWithValidTestData<VisualizerDocumentData>();
			documentData[JobDocumentDataSchema.JDD_ParentTableCode] = shipment.TablePrefix;
			documentData[JobDocumentDataSchema.JDD_ParentID] = shipment.PK;
			documentData[JobDocumentDataSchema.JDD_Name] = ShipmentDocumentDataStoreNames.BillOfLading;
			Factory.Save();

			AssertEquals(ZDate.Empty, shipment.JS_Calc_ElectronicBillOfLadingDate);

			documentData.Logs.CreateOrRecreateEventLog(Events.MessageSent, EstimateActual.Actual, new ZDateTimeOffset(2024, 09, 30, 0, 0, 1));
			Factory.Save();
			Thread.Sleep(10);

			AssertEquals(ZDate.Empty, shipment.JS_Calc_ElectronicBillOfLadingDate);

			var parameters = new KeyValuePair<string, string>[]
			{
				new KeyValuePair<string, string>(Params.Type, Core.Constants.BillStatusUpdatedTypes.OriginalBillSentForPublication),
				new KeyValuePair<string, string>(Params.Department, ElectronicBOLConstants.EHBLEventDepartments.TitleRegistry)
			};

			documentData.Logs.CreateOrRecreateEventLog(Events.MessageSent, EstimateActual.Actual, new ZDateTimeOffset(2024, 10, 01, 0, 0, 1), string.Empty, parameters);
			Factory.Save();
			Thread.Sleep(10);

			var log = documentData.Logs.MostRecentLogByPostedTime(Events.MessageSent);

			AssertEquals(log.PostedLocalBranchTime, shipment.JS_Calc_ElectronicBillOfLadingDate);

			documentData.Logs.CreateOrRecreateEventLog(Events.MessageSent, EstimateActual.Actual, new ZDateTimeOffset(2024, 10, 02, 0, 0, 1), string.Empty, parameters);
			Factory.Save();
			Thread.Sleep(10);

			log = documentData.Logs.MostRecentLogByPostedTime(Events.MessageSent);

			AssertEquals(log.PostedLocalBranchTime, shipment.JS_Calc_ElectronicBillOfLadingDate);

			shipment.Logs.CreateOrRecreateEventLog(Events.BillStatusUpdated, EstimateActual.Actual, new ZDateTimeOffset(2024, 10, 03, 0, 0, 1));
			Factory.Save();
			Thread.Sleep(10);

			AssertEquals(log.PostedLocalBranchTime, shipment.JS_Calc_ElectronicBillOfLadingDate);

			parameters = new KeyValuePair<string, string>[]
			{
				new KeyValuePair<string, string>(Params.Type, Core.Constants.BillStatusUpdatedTypes.AmendmentRequested),
				new KeyValuePair<string, string>(Params.Department, ElectronicBOLConstants.EHBLEventDepartments.TitleRegistry)
			};

			shipment.Logs.CreateOrRecreateEventLog(Events.BillStatusUpdated, EstimateActual.Actual, new ZDateTimeOffset(2024, 10, 04, 0, 0, 1), string.Empty, parameters);
			Factory.Save();
			Thread.Sleep(10);

			var cancelledLog = shipment.Logs.MostRecentLogByPostedTime(Events.BillStatusUpdated);
			cancelledLog.Cancel();
			Factory.Save();
			Thread.Sleep(10);

			AssertEquals(log.PostedLocalBranchTime, shipment.JS_Calc_ElectronicBillOfLadingDate);

			shipment.Logs.CreateOrRecreateEventLog(Events.BillStatusUpdated, EstimateActual.Actual, new ZDateTimeOffset(2024, 10, 05, 0, 0, 1), string.Empty, parameters);
			Factory.Save();
			Thread.Sleep(10);

			log = shipment.Logs.MostRecentLogByPostedTime(Events.BillStatusUpdated);

			AssertEquals(log.PostedLocalBranchTime, shipment.JS_Calc_ElectronicBillOfLadingDate);

			parameters = new KeyValuePair<string, string>[]
			{
				new KeyValuePair<string, string>(Params.Type, Core.Constants.BillStatusUpdatedTypes.SwitchedToPaper),
				new KeyValuePair<string, string>(Params.Department, ElectronicBOLConstants.EHBLEventDepartments.TitleRegistry)
			};
			shipment.JS_ElectronicBillOfLadingStatus = FreightConstants.BillOfLadingBillStatus.Codes.SwitchedToPaper;

			shipment.Logs.CreateOrRecreateEventLog(Events.BillStatusUpdated, EstimateActual.Actual, new ZDateTimeOffset(2024, 10, 04, 0, 0, 1), string.Empty, parameters);
			Factory.Save();
			Thread.Sleep(10);

			log = shipment.Logs.MostRecentLogByPostedTime(Events.BillStatusUpdated);

			AssertEquals(log.PostedLocalBranchTime, shipment.JS_Calc_ElectronicBillOfLadingDate);

			foreach (var type in new[] {
						BillStatusUpdatedTypes.SwitchedToPaper,
						BillStatusUpdatedTypes.Surrendered,
						BillStatusUpdatedTypes.AmendmentRequested,
						BillStatusUpdatedTypes.OriginalBillPublished,
						BillStatusUpdatedTypes.OriginalBillNotPublished,
						BillStatusUpdatedTypes.OriginalBillTransferred,
						BillStatusUpdatedTypes.DenyAmendmentAccepted,
						BillStatusUpdatedTypes.DenyAmendmentRejected,
			})
			{
				parameters = new KeyValuePair<string, string>[]
				{
					new KeyValuePair<string, string>(Params.Type, type),
					new KeyValuePair<string, string>(Params.Department, ElectronicBOLConstants.EHBLEventDepartments.TitleRegistry)
				};

				shipment.Logs.CreateOrRecreateEventLog(Events.BillStatusUpdated, EstimateActual.Actual, new ZDateTimeOffset(2024, 10, 04, 0, 0, 1), string.Empty, parameters);
				Factory.Save();
				Thread.Sleep(10);

				log = shipment.Logs.MostRecentLogByPostedTime(Events.BillStatusUpdated);

				AssertEquals(log.PostedLocalBranchTime, shipment.JS_Calc_ElectronicBillOfLadingDate);
			}
		}

		public void TestJS_Calc_ElectronicBillOfLadingDateOnSurrenderedStatus()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_TransportMode = "SEA";
