			var boleroEBLConfiguration = new BoleroEBLConfiguration()
			{
				EnableEBLIntegration = true,
				GalileoEndPointUrl = "http://test.test",
				GalileoAudience = Guid.NewGuid().ToString(),
				GalileoTestEndPointUrl = "http://test.test",
				GalileoTestAudience = Guid.NewGuid().ToString()
			};

			using (FreightDataRegistry.Instance.EnableBoleroEHBLIntegration.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, boleroEBLConfiguration))
			{
				var parameters = new KeyValuePair<string, string>[]
				{
					new KeyValuePair<string, string>(Params.Type, Core.Constants.BillStatusUpdatedTypes.OriginalBillSentForPublication),
					new KeyValuePair<string, string>(Params.Department, ElectronicBOLConstants.EHBLEventDepartments.TitleRegistry)
				};

				documentData.Logs.CreateOrRecreateEventLog(Events.MessageSent, EstimateActual.Actual, new ZDateTimeOffset(2024, 10, 01, 0, 0, 1), string.Empty, parameters);
				Factory.Save();

				parameters = new KeyValuePair<string, string>[]
				{
					new KeyValuePair<string, string>(Params.Type, Core.Constants.BillStatusUpdatedTypes.Surrendered),
					new KeyValuePair<string, string>(Params.Department, ElectronicBOLConstants.EHBLEventDepartments.TitleRegistry)
				};
				shipment.Logs.CreateOrRecreateEventLog(Events.BillStatusUpdated, EstimateActual.Actual, new ZDateTimeOffset(2024, 11, 11, 0, 0, 1), string.Empty, parameters);
				Factory.Save();
				Thread.Sleep(10);

				var log = shipment.Logs.MostRecentLogByPostedTime(Events.BillStatusUpdated);
				AssertEquals(log.PostedLocalBranchTime, shipment.JS_Calc_ElectronicBillOfLadingDate);
			}
		}

