				consol2.JK_AgentType = AgentType.Agent;
				consol2.JK_IsNeutralMaster = ZBool.False;
				consol2.JK_MasterBillNum = "17610000002";
				consol2.JK_RL_NKLoadPort = "CNSHA";
				consol2.JK_RL_NKDischargePort = "BDDAC";
				consol2.ReceivingForwarderWithContact.OrgPK = orgHeader2.PK;

				shipment.Consols.Add(consol);
				Factory.Save();

				AssertEquals(orgHeader1.PK, shipment.SurrenderPartyDocAddress.OrganisationPK);
				AssertEquals(orgHeader1.MainAddress.PK, shipment.SurrenderPartyDocAddress.E2_OA_Address);
				AssertEquals("ContactName", shipment.SurrenderPartyDocAddress.E2_Contact);

				shipment.Consols.Add(consol2);
				Factory.Save();
				AssertEquals(orgHeader1.PK, shipment.SurrenderPartyDocAddress.OrganisationPK);
				AssertEquals(orgHeader1.MainAddress.PK, shipment.SurrenderPartyDocAddress.E2_OA_Address);
				AssertEquals("ContactName", shipment.SurrenderPartyDocAddress.E2_Contact);

				shipment.Consols.Remove(consol2);
				Factory.Save();
				AssertEquals(orgHeader1.PK, shipment.SurrenderPartyDocAddress.OrganisationPK);
				AssertEquals(orgHeader1.MainAddress.PK, shipment.SurrenderPartyDocAddress.E2_OA_Address);
				AssertEquals("ContactName", shipment.SurrenderPartyDocAddress.E2_Contact);
			});
