		#region Test_UpdateOriginalBillNotes_WhenMSNOccurs

		[TestDate(2024, 10, 31, 9, 32, 21)]
		[TestTimeZoneUNLOCO("AUSYD")]
		public void Test_UpdateOriginalBillNotes_WhenMSNOccurs()
		{
			TestDateAttribute.UseUNLOCO = true;
			AssertTRIValidation(delegate ()
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_HouseBill = "S00001001";
				shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;

				var orgHeader = Factory.New<OrgHeader>();
				orgHeader.OH_Code = "TEST002";
				orgHeader.OH_FullName = "Test Organization2";
				orgHeader.OH_IsConsignee = true;
				orgHeader.MainAddress.OA_RL_NKRelatedPortCode = "AUSYD";
				orgHeader.MainAddress.Address1 = "Address1";
				orgHeader.MainAddress.Address2 = "Address2";
				orgHeader.MainAddress.City = "City";
				orgHeader.MainAddress.State = "State";
				orgHeader.MainAddress.Postcode = "Postcode";

				shipment.ConsignorDocumentaryAddress.OrganisationPK = orgHeader.PK;

				Factory.Save();

				var originalBillNote = shipment.Notes.FindByDescription(PredefinedNoteTypes.Instance.OriginalBillNotes.ToString()).FirstOrDefault();

				AssertNull("Should be null.", originalBillNote);

				AddMSNLog(BillStatusUpdatedTypes.AmendmentGranted);
				originalBillNote = shipment.Notes.FindByDescription(PredefinedNoteTypes.Instance.OriginalBillNotes.ToString()).FirstOrDefault();

				AssertEquals(@$"31-Oct-24 09:32:21 +00:00 WayBill S00001001/0 {BillStatusUpdatedTypes.AmendmentGranted}
First Holder : Test Organization2, Address1, Address2, City State Postcode, Australia", originalBillNote.ST_NoteText);

				AddMSNLog(BillStatusUpdatedTypes.OriginalBillSentForPublication);
				originalBillNote = shipment.Notes.FindByDescription(PredefinedNoteTypes.Instance.OriginalBillNotes.ToString()).FirstOrDefault();

				AssertEquals(@$"31-Oct-24 09:32:21 +00:00 WayBill S00001001/0 {BillStatusUpdatedTypes.OriginalBillSentForPublication}
First Holder : Test Organization2, Address1, Address2, City State Postcode, Australia

31-Oct-24 09:32:21 +00:00 WayBill S00001001/0 {BillStatusUpdatedTypes.AmendmentGranted}
First Holder : Test Organization2, Address1, Address2, City State Postcode, Australia", originalBillNote.ST_NoteText);

				void AddMSNLog(string messageType)
				{
					var eventParameters = new[]
					{
						new KeyValuePair<string, string>(EventConstants.EventReferenceParameters.Codes.Department, ElectronicBOLConstants.EHBLEventDepartments.TitleRegistry),
						new KeyValuePair<string, string>(EventConstants.EventReferenceParameters.Codes.MessageType, "Bill Of Lading"),
						new KeyValuePair<string, string>(EventConstants.EventReferenceParameters.Codes.Type, messageType)
					};
					var log = shipment.Logs.AddNew(Events.MessageSent, eventParameters);
				}
			});
		}

