		public void TestExitReport()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.Germany))
			{
				var shipment = Factory.New<ForwardingShipment>();
				var exitHeader = Factory.New<ICusExitHeader>();
				exitHeader.CXH_ParentTableCode = shipment.TablePrefix;
				exitHeader.CXH_ParentID = shipment.PK;
				var exitReport = Factory.New<ICusExitReport>();
				exitReport.CER_CXH_Header = exitHeader.PK;

				CombineAssertions(() =>
				{
					shipment.JS_RL_NKOrigin = "CNSHA";
					shipment.JS_RL_NKDestination = "DEWIB";
					AssertCollectionNotContains("is not Export", exitReport, shipment.ExitReports);

					shipment.JS_RL_NKOrigin = "DEWIB";
					shipment.JS_RL_NKDestination = "CNSHA";
					AssertCollectionContains("is Export", exitReport, shipment.ExitReports);
				});
			}
		}

		public void TestExitStatus()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.Germany))
			{
				var shipment = Factory.New<ForwardingShipment>();
				var exitHeader = Factory.New<ICusExitHeader>();

				shipment.JS_RL_NKOrigin = "DEWIB";
				shipment.JS_RL_NKDestination = "CNSHA";

				AssertEquals("No reports", "", shipment.ExitStatus);

				exitHeader.CXH_ParentTableCode = shipment.TablePrefix;
				exitHeader.CXH_ParentID = shipment.PK;
				var exitReport1 = Factory.New<ICusExitReport>();
				exitReport1.CER_CXH_Header = exitHeader.PK;
				exitReport1.CER_Status = "A1";
				var exitReport2 = Factory.New<ICusExitReport>();
				exitReport2.CER_CXH_Header = exitHeader.PK;
				exitReport2.CER_Status = "A1";

				AssertEquals("All same", "A1", shipment.ExitStatus);

				var exitReport3 = Factory.New<ICusExitReport>();
				exitReport3.CER_CXH_Header = exitHeader.PK;
				exitReport3.CER_Status = "";

				AssertEquals("All same with empty", CommonEntryStatusList.Codes.MultipleEntryStatus, shipment.ExitStatus);

				exitReport3.CER_Status = "B1";

				AssertEquals("Multiple", CommonEntryStatusList.Codes.MultipleEntryStatus, shipment.ExitStatus);
			}
		}

		public void TestExitStatusDescription()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.Germany))
			{
				var helper = new UniversalReferenceTestDataHelper(Factory);
				var eunZZZ = helper.CreateNewOrGetExistingDataGrouping("EUN");
				helper.CreateNewOrGetExistingDataGrouping(Core.Constants.CountryCodes.Germany, parent: eunZZZ);
				helper.CreateNewOrGetExistingCusCodeType(Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.ExportCustomsStatus, "CSTEX");
				helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.Germany, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.ExportCustomsStatus, "130", "Customs Status 130", ZDateTime.MinSmallDateTimeValue, ZDateTime.MaxSmallDateTimeValue);
				helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.Germany, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.ExportCustomsStatus, "131", "Customs Status 130", ZDateTime.MinSmallDateTimeValue, ZDateTime.MaxSmallDateTimeValue);
				helper.CreateNewOrGetExistingCusCodeList(Core.Constants.Customs.Universal.RefDataGrouping.Codes.EuropeanUnionEUN, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.ExportCustomsStatus, "200", "Customs Status 200", ZDateTime.MinSmallDateTimeValue.Date, ZDateTime.MaxSmallDateTimeValue.Date);
				Factory.Save();

				var shipment = Factory.New<ForwardingShipment>();
				var exitHeader = Factory.New<ICusExitHeader>();

				shipment.JS_RL_NKOrigin = "DEWIB";
				shipment.JS_RL_NKDestination = "CNSHA";

				AssertEquals("No reports", "", shipment.ExitStatusDescription);

				exitHeader.CXH_ParentTableCode = shipment.TablePrefix;
				exitHeader.CXH_ParentID = shipment.PK;
				var exitReport1 = Factory.New<ICusExitReport>();
				exitReport1.CER_CXH_Header = exitHeader.PK;
				exitReport1.CER_Status = "130";
				var exitReport2 = Factory.New<ICusExitReport>();
				exitReport2.CER_CXH_Header = exitHeader.PK;
				exitReport2.CER_Status = "130";

				AssertEquals("All same", "Customs Status 130", shipment.ExitStatusDescription);

				var exitReport3 = Factory.New<ICusExitReport>();
				exitReport3.CER_CXH_Header = exitHeader.PK;
				exitReport3.CER_Status = "";

				AssertEquals("All same with empty", CommonEntryStatusList.Descriptions.MultipleEntryStatus, shipment.ExitStatusDescription);

				exitReport3.CER_Status = "200";

				AssertEquals("All same with unknown", CommonEntryStatusList.Descriptions.MultipleEntryStatus, shipment.ExitStatusDescription);

				exitReport3.CER_Status = "131";

				AssertEquals("Multiple", CommonEntryStatusList.Descriptions.MultipleEntryStatus, shipment.ExitStatusDescription);
			}
		}

		public void TestIsLinkedDCNSplitted()
		{
			var shipment = Factory.New<ForwardingShipment>();
			shipment.PrepareDispatchTWInstructionForBlindPackagesDirection = TransitWarehouseInstructionHelper.Direction.Pickup;
			var depot = Factory.LoadTop1<OrgAddress>(new ZQuery());
			shipment.JS_OA_ExportReceivingDepot = depot.PK;

			var warehouse = (BusinessObject)Factory.New<IWhsWarehouse>();
			warehouse[WhsWarehouseSchema.WW_WarehouseType] = "TRW";
			warehouse[WhsWarehouseSchema.WW_IsActive] = true;
			warehouse[WhsWarehouseSchema.WW_OA_WarehouseAddress] = depot.PK;

			var dispatchConsignment1 = (BusinessObject)Factory.New<IWhsItemDispatchConsignment>();
			dispatchConsignment1[WhsItemDispatchConsignmentSchema.WDC_ConsignmentID] = "DCN1";
			dispatchConsignment1[WhsItemDispatchConsignmentSchema.WDC_ParentID] = shipment.PK;
			dispatchConsignment1[WhsItemDispatchConsignmentSchema.WDC_ParentTableCode] = shipment.TablePrefix;
			dispatchConsignment1[WhsItemDispatchConsignmentSchema.WDC_WW_Warehouse] = warehouse.PK;

			var dispatchConsignment2 = (BusinessObject)Factory.New<IWhsItemDispatchConsignment>();
			dispatchConsignment2[WhsItemDispatchConsignmentSchema.WDC_ConsignmentID] = "DCN2";
			dispatchConsignment2[WhsItemDispatchConsignmentSchema.WDC_ParentID] = shipment.PK;
			dispatchConsignment2[WhsItemDispatchConsignmentSchema.WDC_ParentTableCode] = shipment.TablePrefix;
			dispatchConsignment2[WhsItemDispatchConsignmentSchema.WDC_WW_Warehouse] = warehouse.PK;

			Assert(shipment.IsLinkedDCNSplitted);
		}

