		void AssertSendAmendmentDeniedEventToBolero(Func<ForwardingShipment, ZString> assertAction)
		{
			Env.Security.MaintainShipmentAllowPublisheHBL.IsAllowed = true;

			var boleroEBLConfiguration = new BoleroEBLConfiguration()
			{
				EnableEBLIntegration = true,
				GalileoEndPointUrl = "http://test.test",
				GalileoAudience = Guid.NewGuid().ToString(),
				GalileoTestEndPointUrl = "http://test.test",
				GalileoTestAudience = Guid.NewGuid().ToString()
			};

			GlbBranch.CurrentBranch.OrgProxy.CustomsCodes.AddNew(OrgCusCode.CodeTypes.BoleroTitleRegisterID, "123456789");

			using (FreightDataRegistry.Instance.EnableBoleroEHBLIntegration.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, boleroEBLConfiguration))
			{
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
				shipment.JS_UniqueConsignRef = "S00001234";
				shipment.JS_HouseBill = "1234";
				shipment.JS_ElectronicBillOfLadingStatus = "OBP";

				var exceptStatus = assertAction(shipment);

				var parameters = new KeyValuePair<string, string>[]
				{
					new KeyValuePair<string, string>(Params.Type, Core.Constants.BillStatusUpdatedTypes.AmendmentRequested),
					new KeyValuePair<string, string>(Params.Department, ElectronicBOLConstants.EHBLEventDepartments.TitleRegistry)
				};
				shipment.Logs.CreateOrRecreateEventLog(Events.BillStatusUpdated, EstimateActual.Actual, new ZDateTimeOffset(2024, 11, 19, 22, 59, 58), string.Empty, parameters);
				Factory.Save();
				Thread.Sleep(10);
				AssertEquals("OBA", shipment.JS_ElectronicBillOfLadingStatus);

				parameters = new KeyValuePair<string, string>[]
				{
					new KeyValuePair<string, string>(Params.Type, Core.Constants.BillStatusUpdatedTypes.AmendmentDenied),
					new KeyValuePair<string, string>(Params.Department, ElectronicBOLConstants.EHBLEventDepartments.Carrier)
				};
				shipment.Logs.CreateOrRecreateEventLog(Events.MessageSent, EstimateActual.Actual, new ZDateTimeOffset(2024, 11, 19, 23, 59, 59), string.Empty, parameters);
				shipment.RevertToPreviousEHBLStatus();
				AssertEquals("The Bill Status reverts to the previous Bill Status, before the Amendment Request was received.", exceptStatus, shipment.JS_ElectronicBillOfLadingStatus);
			}
		}

