				shipment.Logs.CreateOrRecreateEventLog(Events.BillStatusUpdated, EstimateActual.Actual, new ZDateTimeOffset(2024, 12, 04, 17, 0, 2), string.Empty, parameters);

				AssertEquals("WTLDAUILA_S00001001_2", shipment.JS_ElectronicBillOfLadingReference);
			});
		}

