		public void TestILMessagesLoad()
		{
			var shipment = Factory.New<ForwardingShipment>();
			var message1 = CreateMessage(shipment.TableName, shipment.PK, "GPM");
			var message2 = CreateMessage(shipment.TableName, shipment.PK, "DLO");
			var message3 = CreateMessage(shipment.TableName, shipment.PK, "UCI");
			Factory.Save();

			AssertEquals("Expected 1 EDI ILMessages", 1, shipment.ExportReleaseMessages.Count);
		}

		EDIMessage CreateMessage(ZString tableName, ZGuid tablePK, ZString messageType)
		{
			EDIMessage message = Factory.New<EDIMessage>();
			message.EM_MessageText = "MessageText";
			message.EM_MessageType = messageType;
			message.EM_ReceiveTransmit = EDIMessage.Direction.Receive;
			message.EM_ApplicationReference = "AppRef";
			message.EM_LinkTable = tableName;
			message.EM_LinkUniqueID = tablePK;
			message.EM_ApplicationCode = "ILC";
			return message;
		}

		public void TestLogRevisedDeliveryDateUpdatedEvent_CurrentDeliveryDueDateCalculationModeIsAddedToTheParameters()
		{
			var newDeliveryDueDate = new ZDateTimeOffset(2022, 10, 04, 09, 30, 0);
			using (FreightDataRegistry.Instance.CalculateDeliveryDueDateByTransportMode.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new CalculateDeliveryDueDateOptions { IsActive = true, TransportModes = ActiveTransportModesForCalculateDeliveryDateOption() }))
			{
				Env.Security.MaintainShipmentDeliveryDueDateOverride.IsAllowed = true;
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
				shipment.GetReasonForChangingDeliveryDueDateEventHandler += (sender, arg) => arg.Reason = "I want to override";
				AssertEquals("Pre-condition: Revised Delivery Due Date is empty", ZDateTimeOffset.Empty, shipment.JS_RevisedDeliveryDueDate);

				shipment.JS_RevisedDeliveryDueDate = newDeliveryDueDate;
				AssertEquals("Revised Delivery Due Date is overriden", newDeliveryDueDate, shipment.JS_RevisedDeliveryDueDate);
				AssertEquals("DDE event will not be logged until shipment is saved, DDE event count = 0", 0, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.DeliveryDateUpdatedCode).Count());

				Factory.Save();
				AssertEquals("DDE event is logged, DDE event count = 1", 1, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.DeliveryDateUpdatedCode).Count());
				var ddeEvent = shipment.Logs.MostRecentLogByEventTime(Events.DeliveryDateUpdated);
				AssertNotNull(ddeEvent);
				AssertEquals("|ACT=Override|NEW=04-Oct-22 09:30|RES=I want to override|TYP=Revised", ddeEvent.SL_Reference);
			}
		}

		public void TestLogDeliveryDateUpdatedEvent_CurrentDeliveryDueDateCalculationModeIsAddedToTheParameters()
		{
			var newDeliveryDueDate = new ZDateTime(2022, 10, 04, 09, 30, 0);
			DeliveryDueDateCalculationTestHelper.SetupDeliveryDueDateCalculatorManagerMock(newDeliveryDueDate);
			using (FreightDataRegistry.Instance.CalculateDeliveryDueDateByTransportMode.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, new CalculateDeliveryDueDateOptions { IsActive = true, TransportModes = ActiveTransportModesForCalculateDeliveryDateOption() }))
			{
				Env.Security.MaintainShipmentDeliveryDueDateOverride.IsAllowed = true;
				var shipment = Factory.New<ForwardingShipment>();
				shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
				AssertEquals("Pre-condition: Delivery Due Date is empty", ZDateTime.Empty, shipment.JS_DeliveryDueDate);

				shipment.CalculateDeliveryDueDate(ForwardingShipment.DeliveryDueDateCalculationMode.Automatic);
				AssertEquals("Delivery Due Date is auto-calculated", newDeliveryDueDate, shipment.JS_DeliveryDueDate);
				AssertEquals("DDE event will not be logged until shipment is saved, DDE event count = 0", 0, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.DeliveryDateUpdatedCode).Count());

				Factory.Save();
				AssertEquals("DDE event is logged, DDE event count = 1", 1, shipment.Logs.Find(x => x.SL_SE_NKEvent == Events.DeliveryDateUpdatedCode).Count());
				var ddeEvent = shipment.Logs.MostRecentLogByEventTime(Events.DeliveryDateUpdated);
				AssertNotNull(ddeEvent);
				AssertEquals("|ACT=Automatic|NEW=04-Oct-22 09:30|RES=Automatically calculated for new shipment|TYP=Original", ddeEvent.SL_Reference);
			}
		}

		public void TestRunPreSaveValidation_JK_IsHazardous()
		{
			using (FreightConfigurationRegistry.Instance.IsConsolDangerousGoodsValidationEnabled.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var consol = Factory.New<ForwardingConsol>();
				consol.JK_IsHazardous = false;
				var shipment = consol.Shipments.AddNew();
				shipment.JS_UniqueConsignRef = "S1";
				var packline = shipment.OuterPackLines.AddNew();

				packline.JL_RH_NKCommodityCode = "HAZ";
				shipment.RunPreSaveValidation();
				AssertHasError("Expected warning.", consol.JK_IsHazardousInfo, @"Is Hazardous Flag should be set when there are shipments with dangerous goods attached.
The following Shipment(s) attached to this consol have dangerous cargo: Shipment S1");

				packline.JL_RH_NKCommodityCode = "GEN";
				shipment.RunPreSaveValidation();
				AssertNoErrors(consol.JK_IsHazardousInfo);

				packline.JL_RH_NKCommodityCode = "HAZ";
				shipment.RunPreSaveValidation();
				AssertHasError("Expected warning.", consol.JK_IsHazardousInfo, @"Is Hazardous Flag should be set when there are shipments with dangerous goods attached.
The following Shipment(s) attached to this consol have dangerous cargo: Shipment S1");
			}
		}

		#region Commodity Cache

		public void TestShipmentCommodities_LightCommoditiesLoadedIfNotCached()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.UnitedStates))
			{
				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
				var declaration = Factory.New<US.IJobDeclaration>();
				declaration.JE_JS = shipment.PK;
				var invoice = declaration.Invoices.AddNew();
				var invoiceLine1 = invoice.AddNewInvoiceLine();
				invoiceLine1.JI_Tariff = "33333333";
				Factory.Save();

				var factory1 = new BusinessObjectFactory();
				var shipment1 = factory1.Load<ForwardingShipment>(shipment.PK);
				var commodities = ((IComplianceCommodityRiskStatusProvider)shipment1).Commodities;
				CombineAssertions(() =>
				{
					AssertEquals("33333333", commodities.First().HarmonizedCode);
					AssertNotSame(invoiceLine1, shipment1.Declarations[0].InvoiceLines[0]); // Different objects i.e. loaded from the DB
				});
			}
		}

		public void TestShipmentCommodities_LightCommoditiesLoadedFromCacheDictionary()
		{
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.UnitedStates))
			{
				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
				var declaration = Factory.New<US.IJobDeclaration>();
				declaration.JE_JS = shipment.PK;
				var invoice = declaration.Invoices.AddNew();
				var invoiceLine1 = invoice.AddNewInvoiceLine();
				invoiceLine1.JI_Tariff = "33333333";
				Factory.Save();

				var factory1 = new BusinessObjectFactory();
				var shipment1 = factory1.Load<ForwardingShipment>(shipment.PK);
				var commodities1 = ((IComplianceCommodityRiskStatusProvider)shipment1).Commodities;
				var shipment2 = factory1.Load<ForwardingShipment>(shipment.PK);
				var commodities2 = ((IComplianceCommodityRiskStatusProvider)shipment2).Commodities;
				CombineAssertions(() =>
				{
					AssertNotSame(commodities1, commodities2); // Shipment creates a new List
					AssertSame(commodities1.First(), commodities2.First()); // but the commodity is the same, i.e. loaded from cache
					AssertSame(shipment1.Declarations[0].InvoiceLines[0], shipment2.Declarations[0].InvoiceLines[0]); // Same objects i.e. loaded from cache
				});
			}
		}

