		public void TestGetRequestSupportedAddressInfo()
		{
			GlbCompany.CurrentCompany.SetCountry("JM");

			FreightDataRegistry.Instance.ShipmentInspectionTypeDefault.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, ZString.Empty);
			FreightDataRegistry.Instance.ShipmentInspectionOrganisationToUse.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, SupplyChainSecurityOrganisationTypes.Consignor);

			var client = Factory.NewWithValidTestData<OrgHeader>();
			client.CountryData.OV_EXApprovedOrMajorExporter = AviationSecuritySchemeMembershipEx.Codes.Yes;

			var assigneeOrg = Factory.NewWithValidTestData<OrgHeader>();
			assigneeOrg.Contacts.Add(Factory.NewWithValidTestData<OrgContact>());
			var reviewerOrg = Factory.NewWithValidTestData<OrgHeader>();
			reviewerOrg.Contacts.Add(Factory.NewWithValidTestData<OrgContact>());
			reviewerOrg.CountryData.OV_EXApprovedOrMajorExporter = AviationSecuritySchemeMembershipEx.Codes.Yes;
			var controllingCustomerOrg = Factory.NewWithValidTestData<OrgHeader>();
			controllingCustomerOrg.Contacts.Add(Factory.NewWithValidTestData<OrgContact>());
			Factory.Save();

			var shipment = CreateShipmentWithJob("JMKIN");

			shipment.ShipmentJobHeader.JH_OA_LocalChargesAddr = client.MainAddress.PK;
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = assigneeOrg.PK;
			shipment.ConsigneeDocumentaryAddress.E2_OA_Address = assigneeOrg.MainAddress.PK;
			shipment.ConsigneeDocumentaryAddress.E2_Contact = assigneeOrg.Contacts[0].OC_ContactName;

			shipment.ConsignorDocumentaryAddress.OrganisationPK = reviewerOrg.PK;
			shipment.ConsignorDocumentaryAddress.E2_OA_Address = reviewerOrg.MainAddress.PK;
			shipment.ConsignorDocumentaryAddress.E2_Contact = reviewerOrg.Contacts[0].OC_ContactName;

			shipment.ControllingCustomerAddress.OrganisationPK = controllingCustomerOrg.PK;
			shipment.ControllingCustomerAddress.E2_OA_Address = controllingCustomerOrg.MainAddress.PK;
			shipment.ControllingCustomerAddress.E2_Contact = controllingCustomerOrg.Contacts[0].OC_ContactName;

			AssertEquals(assigneeOrg.PK, shipment.GetRequestSupportedAddressInfo(DocAddressTypes.Codes.ConsigneeDocumentaryAddress).OrginzationPK);
			AssertEquals(assigneeOrg.Contacts[0].PK, shipment.GetRequestSupportedAddressInfo(DocAddressTypes.Codes.ConsigneeDocumentaryAddress).ContactPK);
			AssertEquals(reviewerOrg.PK, shipment.GetRequestSupportedAddressInfo(DocAddressTypes.Codes.ConsignorDocumentaryAddress).OrginzationPK);
			AssertEquals(reviewerOrg.Contacts[0].PK, shipment.GetRequestSupportedAddressInfo(DocAddressTypes.Codes.ConsignorDocumentaryAddress).ContactPK);
			AssertEquals(controllingCustomerOrg.PK, shipment.GetRequestSupportedAddressInfo(DocAddressTypes.Codes.ControllingCustomer).OrginzationPK);
			AssertEquals(controllingCustomerOrg.Contacts[0].PK, shipment.GetRequestSupportedAddressInfo(DocAddressTypes.Codes.ControllingCustomer).ContactPK);
			AssertEquals(client.PK, shipment.GetRequestSupportedAddressInfo(DocAddressTypes.Codes.LocalClient).OrginzationPK);
			AssertEquals(ZGuid.Empty, shipment.GetRequestSupportedAddressInfo(DocAddressTypes.Codes.LocalClient).ContactPK);
		}

